P.entries["quest:93746"] = {n="Reação firme",s="\"Reação firme\" é uma missão da Horda na Ilha de Zefras oferecida por Ayessa Dawnsinger. As tensões estão fervilhando enquanto a misteriosa Alta Ordem se intromete no território e nos negócios dos Moldavento locais. Ayessa ordena um ataque preventivo contra Belathaan Brightwish na estrada para o Santuário de Akir a fim de estabelecer limites claros pela força.",h="\"Reação firme\" é uma missão da Horda na Ilha de Zefras oferecida por Ayessa Dawnsinger.",kw={"reação firme","ayessa dawnsinger","belathaan brightwish","alta ordem","tempestades vivas","santuário de akir","moldavento","ilha de zefras"},ang={["class:Shaman"]="O confronto com Tempestades Vivas na estrada destaca a turbulenta e indomada magia elemental do ar disseminada por toda a Ilha de Zefras.",["faction:Horde"]="A presença da Horda na Ilha de Zefras depende do estabelecimento de posições seguras e de impedir que facções rivais como a Alta Ordem invadam interesses aliados."},sec={{t="Traçando o limite",b="Os Moldavento da Ilha de Zefras não toleram olhares não convidados, especialmente de uma organização tão secreta e calculista quanto a Alta Ordem. Avisos anteriores foram ignorados, forçando Ayessa Dawnsinger a intensificar a situação. Para proteger seus interesses, ela decide interceptar Belathaan Brightwish no trecho isolado da estrada que segue para o norte em direção ao Santuário de Akir, garantindo que o confronto fique longe dos olhares curiosos na cidade."},{t="Tempestades na estrada",b="A ida de Belathaan para o norte em direção ao antigo Santuário de Akir levanta suspeitas imediatas, embora suas reais motivações permaneçam incertas. Ao ser confrontado na estrada isolada, o encontro rapidamente se torna hostil, atraindo Tempestades Vivas para o combate. Derrotar esses elementais turbulentos e humilhar Belathaan envia uma mensagem inequívoca de volta à Alta Ordem: qualquer interferência com os Moldavento será respondida com força."}},faq={{q="Quem é Ayessa Dawnsinger?",a="Ayessa Dawnsinger é uma concedente de missões alinhada à Horda e aos Moldavento na Ilha de Zefras. Ela é protetora do domínio deles e implacável ao lidar com intrusos que se intrometem em seus assuntos.",al={"ayessa dawnsinger","quem dá reação firme","ayessa"}},{q="Quem é Belathaan Brightwish?",a="Belathaan Brightwish é um operativo ligado à Alta Ordem. Ele é visto indo sozinho em direção ao Santuário de Akir e se torna o alvo da tentativa de Ayessa Dawnsinger de intimidar sua organização.",al={"belathaan brightwish","belthaan","quem é belathaan"}},{q="O que é a Alta Ordem?",a="A Alta Ordem é uma facção que opera na Ilha de Zefras cujas atividades vão contra os Moldavento locais. Apesar dos avisos explícitos, eles continuam investigando assuntos que não lhes dizem respeito.",al={"alta ordem","história da alta ordem","o que é a alta ordem"}},{q="Onde fica o Santuário de Akir?",a="O Santuário de Akir fica ao norte da cidade na Ilha de Zefras. Belathaan é interceptado ao longo da estrada isolada que leva a esse marco.",al={"santuário de akir","onde fica o santuário de akir","santuário de akir zefras"}},{q="Por que Ayessa quer que Belathaan seja espancado em vez de morto?",a="Ayessa visa explicitamente enviar uma mensagem em vez de iniciar uma guerra total. Ao castigar Belathaan e permitir que ele retorne aos seus superiores, ela espera incutir medo e respeito pelos limites dos Moldavento.",al={"matar belathaan","por que poupar belathaan","por que apenas machucados"}},{q="O que são as Tempestades Vivas encontradas durante esta tarefa?",a="Tempestades Vivas são entidades elementais que se manifestam durante o confronto com Belathaan na estrada, refletindo as energias elementais voláteis que definem a Ilha de Zefras.",al={"tempestades vivas","o que são tempestades vivas"}}},fx={["3180a0eb"]={q="Por que Ayessa Dawnsinger quer que Belathaan seja confrontado?",a="A Alta Ordem interferiu repetidamente nos assuntos dos Moldavento, ignorando avisos anteriores para respeitar seu território e práticas. Ayessa acredita que palavras diplomáticas não são mais suficientes. Ao interceptar Belathaan na estrada e dar a ele uma surra severa, ela espera enviar uma mensagem inconfundível de volta aos seus superiores de que os Moldavento aplicarão seus limites pela força, se necessário.",al={"por que confrontar belathaan","motivação de ayessa","por que enviar mensagem para a alta ordem"}}},fp="15,209,16.292.0,18.327.1,25.168.0,28.169.0,23.169.0,36.118.0,57.176.0,56.160.0"}
P.entries["quest:93786"] = {n="A Message in Blood",s="Krom’rosh envia você contra a fazenda humana em Meadowsbrook. Ele quer que os trabalhadores da fazenda sejam mortos para responder à reivindicação dos desertores sobre as terras.",h="Krom’rosh envia você contra a fazenda humana em Meadowsbrook.",kw={"uma mensagem em sangue","farholde","fazenda","desertores humanos","krom'rosh","meadowsbrook farm","meadowsbrook farmhands","escaramuças"},ang={["faction:Horde"]="Como membro da Horda, você cumpre a ordem de Krom’rosh contra os desertores humanos que reivindicaram a fazenda."},sec={{t="Os trabalhadores da fazenda",b="Krom’rosh aponta Meadowsbrook Farm, a sudoeste, do outro lado do rio. Desertores humanos reivindicaram a fazenda alguns anos atrás e depois avançaram em direção a Farholde, a fortaleza na margem leste. Krom’rosh diz que as escaramuças anteriores não tinham combatentes suficientes para vencer. Agora, ele quer que você interrompa o trabalho na fazenda e não deixe prisioneiros."}},faq={{q="Quem me pede para ir a Meadowsbrook?",a="Krom’rosh pede que você ataque Meadowsbrook Farm e interrompa o trabalho na fazenda.",al={"quem me enviou","tarefa de krom'rosh","quem está pedindo"}},{q="Por que Krom’rosh quer que a fazenda seja atacada?",a="Desertores humanos reivindicaram a fazenda e avançaram em direção a Farholde. Krom’rosh quer lembrá-los de que seu povo está presente.",al={"por que atacar a fazenda","por que meadowsbrook","por que lutar contra humanos"}},{q="Onde fica Meadowsbrook Farm?",a="Meadowsbrook Farm fica a sudoeste, do outro lado do rio.",al={"onde fica a fazenda","localização de meadowsbrook","fazenda a sudoeste"}},{q="Quem são os trabalhadores da fazenda?",a="Os Meadowsbrook Farmhands são as pessoas que Krom’rosh manda você matar.",al={"quem são os trabalhadores da fazenda","pessoas de meadowsbrook","humanos na fazenda"}},{q="O que aconteceu nas escaramuças anteriores?",a="Krom’rosh diz que as escaramuças anteriores teriam favorecido seu lado se tivessem mais combatentes.",al={"lutas anteriores","por que as escaramuças falharam","escaramuças de kromrosh"}}},fp="18,136,13.314.0,34.73.0,44.119.0,27.50.0,22.72.0,40.98.0"}
P.entries["quest:93787"] = {n="Food for the Taking",s="Krom'rosh envia você a uma fazenda da Aliança em Meadowsbrook para buscar ração. Levar os suprimentos prejudicará os humanos e dará tempo para planejar o próximo passo.",h="Krom'rosh envia você a uma fazenda da Aliança em Meadowsbrook para buscar ração.",kw={"fazenda da aliança","feed satchels","comida para levar","humanos","krom'rosh","meadowsbrook","suprimentos"},ang={["faction:Horde"]="Como membro da Horda, você recebe a tarefa de privar os humanos da Aliança do conforto e do sustento proporcionados pelos suprimentos da fazenda."},sec={{t="Os estoques da fazenda",b="A fazenda da Aliança em Meadowsbrook guarda ração que Krom'rosh quer que seja tomada. Você é enviado ao sudoeste para pegar o que encontrar, privando os humanos de suprimentos e ganhando tempo para outro plano."}},faq={{q="Quem quer que a ração seja levada?",a="Krom'rosh quer que você pegue ração na fazenda da Aliança em Meadowsbrook.",al={"quem me enviou","pedido de kromrosh","quem quer os suprimentos"}},{q="Onde fica a fazenda?",a="A fazenda da Aliança fica em Meadowsbrook, a sudoeste.",al={"onde fica a fazenda da aliança","fazenda de meadowsbrook","local da fazenda"}},{q="Por que levar os suprimentos?",a="Levar os suprimentos privará os humanos de provisões e dará tempo para planejar o próximo passo.",al={"por que roubar ração","por que privar de comida","qual é o objetivo"}},{q="Quais suprimentos serão levados?",a="Os suprimentos são Feed Satchels da fazenda da Aliança.",al={"qual ração","feed satchels","o que roubar"}}},fp="19,148,17.188.0,25.72.0,18.55.0,22.93.0,30.54.0"}
P.entries["quest:93788"] = {n="Borrowed Blades",s="Kreza Darkthorn pede que você busque os machados dos lenhadores no acampamento madeireiro de Turner's Logging Camp. As lâminas fornecerão materiais para armas em Rog'mar.",h="Kreza Darkthorn pede que você busque os machados dos lenhadores no acampamento madeireiro de Turner's Logging...",kw={"lâminas emprestadas","forja","gur'dok","kreza darkthorn","lenhadores","rog'mar","turner's logging camp","armas","machado de carpinteiro"},sec={{t="No acampamento madeireiro",b="Kreza Darkthorn mantém a forja de Rog'mar em funcionamento enquanto Gur'dok desmonta as lâminas. A presença humana ao sul e Twilight a oeste dificultam a coleta de recursos. Pedem que você traga os machados dos lenhadores de Turner's Logging Camp, para que seus materiais sejam transformados em armas."}},faq={{q="Quem quer os machados?",a="Kreza Darkthorn, em Rog'mar, pede que você recupere os machados de Turner's Logging Camp.",al={"quem me enviou","machados de kreza","quem precisa de lâminas"}},{q="Por que Kreza quer os machados dos lenhadores?",a="Gur'dok vai desmontar as lâminas, e Kreza usará os materiais para fabricar armas.",al={"por que machados","para que servem os machados","materiais para armas"}},{q="Onde fica Turner's Logging Camp?",a="Turner's Logging Camp fica ao sul, seguindo o rio, perto do moinho.",al={"localização do acampamento madeireiro","onde estão os lenhadores","acampamento de turner"}},{q="O que dificulta a coleta de recursos?",a="A presença humana ao sul e Twilight a oeste dificultam a disputa por recursos.",al={"por que é difícil obter recursos","presença humana","twilight por perto"}}},fp="15,143,19.304.0,19.84.0,42.87.0,31.60.0,41.96.0"}
P.entries["quest:93791"] = {n="Speak with Belann",s="Speak with Belann direciona conjuradores aspirantes a Valanaar para encontrar o mestre artesão Belann Windwood. À medida que o domínio mágico de um iniciado se expande, criar um foco de feitiço pessoal marca um rito de passagem essencial sob as consagradas tradições da Alta Ordem.",h="Speak with Belann direciona conjuradores aspirantes a Valanaar para encontrar o mestre artesão Belann...",kw={"belann","belann windwood","alta ordem","foco de feitiço","cajados","valanaar","varinhas"},ang={["class:Mage"]="Criar um foco de feitiço pessoal marca um rito de passagem vital para conjuradores aspirantes que honram as antigas tradições da Alta Ordem."},sec={{t="Um Rito de Poder Crescente",b="À medida que o domínio da magia de um praticante aspirante floresce, a Alta Ordem recorre a um antigo costume para testar e elevar seus talentos. Criar um foco de feitiço personalizado — seja na forma de uma varinha ou cajado — é considerado uma das tradições mais duradouras da ordem para estudantes que buscam vincular seu poder crescente a um instrumento de sua própria autoria."},{t="O Artesão de Valanaar",b="Para realizar essa criação sagrada, os iniciados são direcionados a Valanaar para procurar Belann Windwood. Renomado por dedicar mais de um século à forja de cajados e varinhas excepcionais para a Alta Ordem, Belann atua como um mentor de confiança, ansioso para acolher estudantes dedicados e guiá-los pelo ofício intrincado e pela história de suas ferramentas mágicas."}},faq={{q="Quem é Belann Windwood?",a="Belann Windwood é um mestre artesão que reside em Valanaar. Ele dedicou mais de um século de seu ofício à criação de cajados e varinhas para membros da Alta Ordem.",al={"quem é belann","belann windwood","belann"}},{q="O que é a Alta Ordem?",a="A Alta Ordem é uma organização antiga de praticantes cujas tradições de longa data incluem guiar jovens conjuradores na construção e no domínio de seus próprios focos de feitiço.",al={"o que é a alta ordem","história da alta ordem"}},{q="O que é um foco de feitiço?",a="Um foco de feitiço, como uma varinha ou um cajado, canaliza energias mágicas. Criar um foco individual é considerado um dos ritos de passagem mais antigos para conjuradores em desenvolvimento na Alta Ordem.",al={"o que é um foco de feitiço","propósito do foco de feitiço"}},{q="Onde Valanaar pode ser encontrada?",a="Valanaar é o assentamento onde Belann Windwood mantém sua oficina e auxilia estudantes da Alta Ordem na criação de focos.",al={"onde fica valanaar","localização de valanaar"}},{q="Por que você é enviado para falar com Belann?",a="Como um usuário de magia aspirante cujos poderes estão florescendo, você é enviado a Belann para estudar sob seu século de perícia e iniciar o processo de moldar seu próprio instrumento mágico.",al={"por que visitar belann","por que criar um foco"}},{q="O que acontece depois de você conhecer Belann?",a="Ao se apresentar a Belann em Valanaar, o artesão dá as boas-vindas a você e se prepara para explicar os próximos estágios envolvidos na montagem de seu foco de feitiço.",al={"o que acontece a seguir","após falar com belann"}}},fp="17,153,23.326.0,25.270.0,23.145.0,23.158.0,22.162.0,28.112.0,38.157.0,35.138.0"}
P.entries["quest:93797"] = {n="Boughs in the Wind",s="Boughs in the Wind é um rito de passagem tradicional no qual um aprendiz recolhe um galho infuso com vento perto de Falaath Village para confeccionar um foco de feitiço. Orientada por Belann Windwood em Valanaar, a prática homenageia um antigo costume em uma época em que o talento mágico em Zephras diminui continuamente.",h="Boughs in the Wind é um rito de passagem tradicional no qual um aprendiz recolhe um galho infuso com vento...",kw={"belann windwood","boughs in the wind","falaath village","foco de feitiço","valanaar","santuário do vento","ramo infuso com vento","zephras"},ang={["class:Mage"]="Confeccionar um foco de feitiço a partir de ramos infusos com vento marca um rito de passagem inicial para conjuradores que aprendem a canalizar a ressonância elemental.",["race:Skyborne"]="À medida que menos jovens demonstram afinidade com a magia a cada ano que passa, participar da confecção de um foco de feitiço tradicional ajuda a preservar a cultura ancestral do seu povo em Zephras."},sec={{t="Um Rito de Passagem",b="Nas terras de Zephras, jovens conjuradores que demonstram um talento mágico nascente passam por um rito de passagem tradicional: confeccionar seu próprio foco de feitiço. Mentores como Belann Windwood em Valanaar orientam aprendizes através dessa prática ancestral, encarregando-os de coletar um galho caído das árvores mais antigas da região. Esses ramos veneráveis guardam vestígios elementais remanescentes do vento, tornando-os condutores ideais para canalizar feitiços."},{t="Sussurros no Santuário do Vento",b="Os ramos mais potentes são colhidos perto do santuário do vento localizado logo ao sul de Falaath Village, onde correntes elementais se concentram naturalmente. A tradição dita que o galho frequentemente escolhe o conjurador, dizendo-se por vezes que sussurra uma canção para aqueles sensíveis o suficiente para controlar seu poder. Para anciãos como Belann, cada estudante que completa o ritual representa uma continuação vital de sua cultura, especialmente porque cada vez menos indivíduos em Zephras nascem com o dom da magia a cada ano que passa."}},faq={{q="O que é a missão Boughs in the Wind?",a="Boughs in the Wind é uma missão de rito de passagem em que um aspirante a conjurador coleta um galho caído infuso com vento para criar seu próprio foco de feitiço. Ela representa um antigo costume praticado para preservar a herança mágica de Zephras.",al={"o que é boughs in the wind","missão boughs in the wind","missão foco de feitiço"}},{q="Quem é Belann Windwood?",a="Belann Windwood é um mentor localizado em Valanaar que orienta jovens conjuradores na criação tradicional de seus focos de feitiço. Ele observa com preocupação que cada vez menos pessoas demonstram o dom da magia a cada ano que passa.",al={"quem é belann windwood","belann concedente da missão","belann valanaar"}},{q="Onde você encontra o Ramo Infuso com Vento?",a="Os ramos infusos com vento caem das árvores mais antigas localizadas perto do santuário do vento, situado logo ao sul de Falaath Village. Belann orienta os aprendizes a irem até este santuário porque sua madeira ancestral retém vestígios de correntes elementais.",al={"onde encontrar ramo do vento","onde fica ramo infuso com vento","localização do ramo"}},{q="Por que os jovens conjuradores criam um foco de feitiço?",a="Na tradição local, os aprendizes confeccionam seu próprio foco de feitiço assim que demonstram proficiência mágica. O foco canaliza energias elementais, servindo tanto como um condutor funcional para conjuração quanto como uma iniciação aos ritos culturais.",al={"por que criar foco de feitiço","objetivo do foco de feitiço","história do foco de feitiço"}},{q="Por que Belann pergunta se o galho cantou para você?",a="Belann Windwood observa que a tradição dita que o galho frequentemente escolhe o conjurador, em vez do contrário. Ele comenta que um ramo apropriado parece cantar para alguém que possua a sensibilidade necessária para empunhar os ventos elementais.",al={"o ramo escolhe o conjurador","ramo cantante","o ramo escolhe você"}},{q="O que está acontecendo com a magia em Zephras?",a="Zephras é a terra onde essa tradição acontece. De acordo com Belann Windwood, a cada ano que passa em Zephras, menos indivíduos nascem com um talento natural para a magia, tornando vital a continuidade dos ritos ancestrais.",al={"onde fica zephras","magia desaparecendo em zephras","história da magia de zephras"}}},fp="18,207,17.262.0,27.396.0,37.130.0,23.174.0,41.181.0,47.153.0,46.155.0,38.147.0"}
P.entries["quest:938"] = {n="Bruma",s="Mist é uma missão de escolta nos galhos sombreados de Teldrassil. Após descobrir uma sabre-de-gelo cinzenta ferida e abandonada no fundo da floresta, os viajantes devem conduzi-la em segurança de volta à Sentinela Arynia Rasganimbus em um poço da lua próximo.",h="Mist é uma missão de escolta nos galhos sombreados de Teldrassil.",kw={"arynia rasganimbus","mist","poço da lua","oracle tree","sabre-de-gelo","sentinela","teldrassil"},ang={["class:Hunter"]="Qualquer mestre das feras reconhecerá a devoção feroz e o olhar inteligente nos olhos de Mist, tornando o seu retorno seguro à sua parceira uma questão de orgulho profissional.",["faction:Alliance"]="Ajudar as Sentinelas em Teldrassil consolida uma boa vontade vital entre a recém-formada Aliança e os defensores kaldorei da árvore do mundo.",["race:NightElf"]="O vínculo entre Sentinela e sabre-de-gelo é uma pedra angular da guerra e das tradições florestais dos elfos noturnos; resgatar Mist honra esse companheirismo antigo e sagrado."},sec={{t="Uma Companheira Ferida",b="Escondida em meio à vegetação rasteira e selvagem de Teldrassil está Mist, uma distinta sabre-de-gelo cinzenta marcada por lacerações graves e profundas nas costas e no ventre. Em vez de agir como uma fera selvagem da natureza, Mist exibe uma calma notável e uma inteligência brilhante em seus olhos azuis, buscando imediatamente a orientação e a proteção de viajantes amigáveis."},{t="O Preço da Emboscada",b="Mist é a amada companheira da Sentinela Arynia Rasganimbus. Enquanto patrulhava os grandes galhos perto de Oracle Tree, Arynia foi pega de surpresa por bruxas perversas que emboscaram a dupla e as separaram. Acreditando que sua leal mascote havia encontrado um fim sangrento, Arynia recolheu-se em luto à tranquilidade de um poço da lua local, onde esperava desesperadamente contra todas as probabilidades pela sobrevivência de Mist."}},faq={{q="Quem é Mist?",a="Mist é uma leal companheira sabre-de-gelo cinzenta que pertence à Sentinela Arynia Rasganimbus. Ela é encontrada ferida nas florestas de Teldrassil após se separar de sua mestra durante uma violenta emboscada.",al={"gato mist","o que é mist","quem é o sabre-de-gelo"}},{q="Quem feriu Mist?",a="Mist e sua mestra foram emboscadas por bruxas locais que espreitavam nas florestas de Teldrassil. As atacantes conseguiram separar a dupla e causaram lacerações profundas nas costas e no estômago da felina.",al={"quem feriu mist","por que mist está sangrando","bruxas emboscam mist"}},{q="Para onde Mist deve ser escoltada?",a="Mist precisa ser levada em segurança até a Sentinela Arynia Rasganimbus, que está posicionada ao lado do poço da lua perto de Oracle Tree.",al={"onde levar mist","entrega de mist","destino de mist"}},{q="Quem é a Sentinela Arynia Rasganimbus?",a="Arynia Rasganimbus é uma Sentinela elfo noturno e companheira de Mist. Ela está posicionada no poço da lua perto de Oracle Tree.",al={"arynia rasganimbus","rasganimbus","dona de mist"}},{q="Por que as Sentinelas elfos noturnos têm vínculos com sabres-de-gelo?",a="As Sentinelas elfos noturnos lutam ao lado dos grandes felinos de Kalimdor há milênios, contando com eles como parceiros ferozes em escaramuças, batedores nos galhos sombrios e companheiros confiáveis por toda a vida.",al={"felinos companheiros de elfos noturnos","sabres-de-gelo de sentinela","por que sabres-de-gelo"}},{q="Onde fica Oracle Tree em relação a este resgate?",a="Oracle Tree fica no noroeste de Teldrassil, com um poço da lua próximo provendo águas sagradas onde a Sentinela Arynia Rasganimbus cuida de seus deveres.",al={"localização de oracle tree","poço da lua mist"}}},fx={["1795c253"]={q="Por que Mist precisa da sua ajuda?",a="Mist está gravemente ferida com lacerações profundas em suas costas e estômago, separada de sua companheira Sentinela Arynia Rasganimbus. Enfraquecida e presa sozinha na floresta, ela não consegue navegar com segurança pelos perigos de Teldrassil sozinha para alcançar a segurança do poço lunar sem sua proteção.",al={"por que ajudar mist","motivação de mist","por que mist precisa de escolta"}},["94db0917"]={q="Por que Mist confia em você em vez de salvar a si mesma?",a="Mist está ferida demais para lutar pela floresta hostil ou fazer a longa jornada de volta sem assistência. Sendo uma fera separada de sua Sentinela, ela não tem aliados próximos ou guardas a quem recorrer; quando você a encontra, ela o reconhece como uma presença amigável e coloca sua confiança em sua capacidade de guiá-la e protegê-la.",al={"por que eu mist","por que mist não pode escapar sozinha","por que mist segue você"}}},fp="4,154,19.257.0,19.238.1,12.145.0,17.135.0,30.101.0,35.120.0,50.191.0,52.150.0"}
P.entries["quest:93835"] = {n="Confront Lorthuna",s="Um Mago ferido pede que você siga Ayessa e Elaadrin pelo portal até os Pináculos Rohashi. Eles precisam de ajuda para enfrentar a Alta Sacerdotisa Lorthuna.",h="Um Mago ferido pede que você siga Ayessa e Elaadrin pelo portal até os Pináculos Rohashi.",kw={"ayessa dawnsinger","elaadrin evengale","alta ordem","lorthuna","portal","pináculos rohashi","valennia","zephras"},sec={{t="Pelo portal",b="Lorthuna fugiu pelo portal para os Pináculos Rohashi, acima, e Ayessa Dawnsinger e Elaadrin Evengale foram atrás dela há poucos instantes. A companheira deles está ferida demais para seguir. Atravesse o portal e junte-se a eles para enfrentar a Alta Sacerdotisa."},{t="Depois do confronto",b="Os Magos restantes foram enviados para ajudar Valennia e suas forças a escapar, e Valennia está descansando na residência do Alto Ancião Shadowsong. Ansirem voltou a Azeroth depois de discutir os próximos passos da Alta Ordem. Zephras sobreviveu ao dia, mas está perigosamente vulnerável, e é preciso planejar o que vem a seguir."}},faq={{q="Quem está pedindo que eu vá atrás de Lorthuna?",a="Um Mago ferido pede que você siga Ayessa Dawnsinger e Elaadrin Evengale pelo portal e os ajude a enfrentar a Alta Sacerdotisa Lorthuna.",al={"quem me enviou","mago ferido","quem precisa de ajuda"}},{q="Para onde Lorthuna foi?",a="Lorthuna fugiu pelo portal para os Pináculos Rohashi, acima.",al={"onde está lorthuna","lorthuna portal","para onde ela fugiu"}},{q="Quem foi atrás de Lorthuna?",a="Ayessa Dawnsinger e Elaadrin Evengale atravessaram o portal atrás de Lorthuna.",al={"ayessa e elaadrin","quem foi atrás dela","quem está lá em cima"}},{q="Por que o Mago ferido não pode ir com eles?",a="O Mago sofreu golpes demais e precisa ficar para trás.",al={"por que vou sozinho","mago ferido demais","por que ficar para trás"}},{q="Onde está Valennia?",a="Valennia está descansando na residência do Alto Ancião Shadowsong, depois que os Magos restantes ajudaram ela e suas forças a escapar.",al={"localização de valennia","para onde ela foi","valennia está segura"}},{q="O que está em risco agora?",a="Zephras está perigosamente vulnerável, e a Alta Ordem precisa planejar o que vem a seguir.",al={"zephras vulnerável","o que aconteceu com zephras","próximos passos da alta ordem"}}},fp="17,176,18.239.0,15.311.1,38.137.0,22.62.0,24.79.0,40.49.0,18.116.0,20.84.0"}
P.entries["quest:93836"] = {n="The Fate of Zephras",s="The Fate of Zephras é uma missão crucial que se segue à derrota da líder do culto Lorthuna na Ilha de Zefras. Com a queda das proteções de camuflagem da ilha, o jogador leva a notícia da iminente ameaça elemental de Al'Akir e da proposta de missão de Ayessa a Azeroth ao Alto-ancião Talaanis Shadowsong em Valanaar.",h="The Fate of Zephras é uma missão crucial que se segue à derrota da líder do culto Lorthuna na Ilha de Zefras.",kw={"al'akir","ayessa","the fate of zephras","lorthuna","muln","santuário de akir","talaanis shadowsong","valanaar","ilha de zefras"},ang={["class:Shaman"]="Xamãs reconhecem a grave ameaça representada pelo Senhor do Vento Al'Akir, cujo domínio elemental cerca diretamente Zefras assim que as antigas proteções caem.",["race:Skyborne"]="A missão marca um ponto de virada para os Celestes da Ilha de Zefras, ponderando a perda das proteções e a ameaça de Al'Akir contra a sua nova missão além do seu lar flutuante."},sec={{t="Uma vitória precária",b="The Fate of Zephras marca um acerto de contas crítico para os habitantes da Ilha de Zefras. Após o confronto culminante acima do Santuário de Akir, a líder do culto Lorthuna foi eliminada, mas a vitória cobra um preço alto. As antigas proteções que ocultavam a ilha dos olhos de Al'Akir ruíram, deixando o santuário flutuante indefeso no coração do domínio do Senhor do Vento. Em resposta, um mensageiro é enviado através da ilha para levar notícias a Valanaar."},{t="A notícia para Valanaar",b="A missão exige falar diretamente com o Alto-ancião Talaanis Shadowsong em Valanaar. O ancião é informado não apenas sobre a morte de Lorthuna e as proteções rompidas, mas também sobre a firme determinação de Ayessa de liderar uma expedição a Azeroth. Com a perda do véu mágico, os ilhéus decidem aventurar-se para fora a fim de encontrar meios de proteger seu lar. Shadowsong contempla o equilíbrio entre o pavor e o triunfo, observando que, embora Al'Akir seja uma ameaça terrível, os deuses elementais operam em escalas de tempo vastas que podem lhes conceder um tempo precioso para agir."}},faq={{q="Sobre o que é a missão The Fate of Zephras?",a="The Fate of Zephras é uma missão crucial que se segue à derrota de Lorthuna no Santuário de Akir. Com as proteções que mascaravam a Ilha de Zefras destruídas, o jogador leva a notícia da iminente ameaça elemental e da proposta de expedição de Ayessa a Azeroth diretamente ao Alto-ancião Talaanis Shadowsong em Valanaar.",al={"missão the fate of zephras","o que é the fate of zephras","o que acontece em the fate of zephras"}},{q="Por que a Ilha de Zefras está em perigo por causa de Al'Akir?",a="A Ilha de Zefras existe dentro do domínio elemental do Senhor do Vento Al'Akir. Antigas proteções ocultavam anteriormente o santuário de sua vista, mas com a queda dessas defesas, a ilha se encontra exposta e vulnerável caso o senhor elemental direcione sua ira contra ela.",al={"por que zephras está em perigo","por que atacar zephras","ameaça elemental de zephras"}},{q="Quem é Talaanis Shadowsong?",a="Talaanis Shadowsong é o Alto-ancião da comunidade dos Celestes na Ilha de Zefras, estabelecido no assentamento de Valanaar. Ele supervisiona o governo e a sobrevivência de seu povo, recebendo relatórios sobre ameaças elementais e decisões cruciais para o seu lar.",al={"quem é talaanis shadowsong","alto-ancião shadowsong","onde fica talaanis shadowsong"}},{q="Qual é o plano de Ayessa?",a="Ayessa é uma figura importante na Ilha de Zefras que planeja uma expedição a Azeroth. Reconhecendo que a ilha não pode resistir a um ataque de Al'Akir sem defesas, ela busca soluções e aliados fora de seu domínio para assegurar a sobrevivência de seu povo a longo prazo.",al={"quem é ayessa","plano de ayessa","o que ayessa está fazendo"}},{q="Quem foi Lorthuna e o que aconteceu com ela?",a="Lorthuna era a líder do culto que operava na Ilha de Zefras. Antes desta missão, ela foi morta sobre o Santuário de Akir, desmantelando a liderança de sua organização, ao mesmo tempo em que o conflito derrubou as proteções mágicas que resguardavam a ilha.",al={"quem é lorthuna","líder de seita lorthuna","o que aconteceu com lorthuna"}},{q="Quem é Muln?",a="Muln é um conselheiro ou erudito versado sobre os senhores elementais que alertou os defensores de Zefras sobre o imenso poder e perigo de Al'Akir, confirmando a vulnerabilidade deles sem a ocultação mágica.",al={"quem é muln","história de muln"}}},fp="19,190,20.293.0,20.417.1,44.222.0,43.209.0,27.189.0,22.154.0,42.148.0,12.196.0"}
P.entries["quest:93926"] = {n="The Western Watch",s="The Western Watch é uma missão urgente para convocar de volta o Peacekeeper Vaaniel e a guarnição de um posto avançado isolado a sudoeste, sob cerco de sectários. Reconhecendo que manter a fortificação não vale as vidas que ela custa, a liderança local procura recuar os defensores para proteger o assentamento principal.",h="The Western Watch é uma missão urgente para convocar de volta o Peacekeeper Vaaniel e a guarnição de um posto...",kw={"seita","peacekeeper vaaniel","peacekeepers","conjuradores da tempestade","the western watch","torre de vigia","torre de vigia ocidental"},sec={{t="Um Posto Avançado Dispendioso",b="A torre de vigia ocidental fica a sudoeste do assentamento como um posto avançado que guarda a fronteira. Enfrentando uma pressão renovada de sectários hostis, os líderes locais julgaram que a estrutura isolada custava caro demais para ser defendida. Em vez de sacrificar mais vidas tentando manter uma posição exposta, ordens foram redigidas para convocar de volta os peacekeepers e concentrar todas as forças militares disponíveis na proteção do vilarejo e de seus cidadãos."},{t="Tarde Demais para Recuar",b="O Peacekeeper Vaaniel liderava a guarnição designada para proteger a vigília ocidental contra as ameaças que se aproximavam. Infelizmente, a ordem de retirada chegou tarde demais. No momento em que os mensageiros alcançaram a fortificação, os conjuradores da seita manipuladores de tempestades já haviam invadido a torre, deixando o Peacekeeper Vaaniel e seu pelotão mortos em meio a pedras chamuscadas e queimaduras de relâmpagos."}},faq={{q="Quem é o Peacekeeper Vaaniel?",a="O Peacekeeper Vaaniel é o oficial encarregado dos pacificadores que guardam a torre de vigia ocidental. Com cultistas atacando a torre, você é enviado para encontrá-lo e dizer-lhe para trazer sua guarnição de volta à vila o mais rápido possível.",al={"quem é vaaniel","história de vaaniel","peacekeeper vaaniel"}},{q="Por que os peacekeepers receberam ordens de abandonar a torre de vigia?",a="A liderança local reconheceu que manter a torre de vigia ocidental periférica estava custando vidas demais contra os incessantes ataques da seita. A decisão foi tomada para retirar a guarnição, permitindo que os defensores se consolidassem no vilarejo e protegessem sua população civil.",al={"por que abandonar a torre","por que deixar a torre de vigia","ordem de the western watch"}},{q="O que matou o Peacekeeper Vaaniel?",a="O Peacekeeper Vaaniel foi morto por conjuradores da seita que dominavam tempestades. Marcas recentes de queimaduras e chamuscos em seu corpo revelam que relâmpagos e magia elemental pura foram usados para abater os defensores da torre.",al={"como vaaniel morreu","quem matou vaaniel","peacekeeper morto pelo que"}},{q="Quem atacou a torre de vigia ocidental?",a="O ataque foi realizado por uma seita hostil que utilizava magia destrutiva de tempestade. Seus motivos exatos para tomar a torre de vigia permanecem incertos para os comandantes locais, mas sua ofensiva agressiva representava um perigo imediato para os assentamentos próximos.",al={"quem está atacando a torre","seita ataca torre ocidental","que seita é essa"}},{q="Onde fica localizada a torre de vigia ocidental?",a="A torre de vigia fica a sudoeste do assentamento local. Ela serve como um posto avançado que protege os acessos a oeste, embora sua posição isolada a tornasse vulnerável a ataques coordenados da seita.",al={"onde fica a torre de vigia","localização da torre de vigia ocidental"}},{q="O que aconteceu com a guarnição na torre?",a="Quando os mensageiros chegaram com ordens de evacuação de volta ao assentamento, a torre de vigia já havia caído. O Peacekeeper Vaaniel e os defensores de seu posto avançado foram subjugados e mortos pelos conjuradores da seita pouco antes de o socorro poder chegar.",al={"o que acontece na torre","desfecho da torre de vigia","algum peacekeeper sobreviveu"}}},fp="17,183,16.329.0,19.264.1,27.189.0,60.173.0,32.152.0,36.180.0,40.148.0,43.184.0"}
P.entries["quest:93927"] = {n="A Last Request",s="A Last Request começa ao descobrir o cadáver de um pacificador caído no campo. Preso nas mãos do guarda morto está um bilhete manchado de sangue contendo pistas vitais sobre seus momentos finais. Ler suas últimas palavras oferece a única maneira de cumprir seu dever inacabado e dar um desfecho ao seu destino.",h="A Last Request começa ao descobrir o cadáver de um pacificador caído no campo.",kw={"a last request","bilhete ensanguentado","pacificador morto","pacificador","bilhete do pacificador"},sec={{t="Uma Descoberta Sinistra",b="A Last Request começa com uma descoberta sombria no campo: o corpo sem vida de um pacificador caído. Caído na morte, o guardião ainda segura um bilhete manchado de sangue que se solta após inspeção. Nestes dias turbulentos em Zephras, os pacificadores frequentemente pagam o preço supremo tentando manter a ordem, e recuperar suas últimas palavras é frequentemente a única maneira de descobrir o que aconteceu com eles."},{t="A Mensagem Final",b="O pergaminho ensanguentado retirado das mãos do pacificador contém seu apelo ou instruções finais. Quem quer que tenha tirado a vida do guarda deixou seu dever inacabado, cabendo a quem encontrar o corpo interpretar as pistas e ver sua missão final concluída. Ler o bilhete fornece a direção essencial necessária para prosseguir e responder ao chamado final da sentinela caída."}},faq={{q="Quem é o pacificador morto?",a="A identidade exata do pacificador caído não é declarada na descoberta inicial. O que é evidente é seu papel como mantenedor da ordem cujo dever terminou violentamente, deixando para trás apenas a Mensagem Urgente presa em suas mãos.",al={"quem é o pacificador morto","pacificador morto","identidade do pacificador"}},{q="O que está escrito no bilhete ensanguentado?",a="O bilhete ensanguentado é o último relato do pacificador. O culto atacou seu posto de surpresa: Raani não viu o ataque chegando, Arvensus levou um golpe de espada na barriga e ele próprio foi derrubado por um raio e deixado para morrer, esperando que seus ferimentos terminassem o que o culto começou.",al={"o que é o bilhete ensanguentado","o que diz o bilhete","bilhete do pacificador"}},{q="Como este pedido é descoberto?",a="Esta tarefa começa diretamente ao descobrir e examinar o corpo sem vida de um pacificador. Vasculhar o defensor caído revela o bilhete ensanguentado preso em suas mãos sem vida, delineando seu apelo final.",al={"como começar a last request","onde encontrar a last request"}},{q="O que aconteceu com o pacificador?",a="O culto emboscou seu posto sem aviso. Seus companheiros pacificadores caíram, e ele foi atingido por um raio e deixado para morrer. Ele viveu apenas o suficiente para registrar o que aconteceu no bilhete encontrado preso em suas mãos.",al={"por que o pacificador foi morto","quem matou o pacificador"}},{q="Qual é o último pedido do pacificador?",a="O pacificador morreu antes que pudesse concluir sua missão ou entregar sua mensagem pessoalmente. Ao recuperar e inspecionar seu bilhete manchado de sangue, um aventureiro pode decifrar suas instruções finais e ver seu último desejo realizado.",al={"qual é o pedido do pacificador","objetivo de a last request"}},{q="Qual é a função dos pacificadores?",a="Os pacificadores atuam como protetores encarregados de manter a ordem e defender povoados e estradas de perigos. Cair em combate deixa seus deveres inacabados e seus aliados sem aviso, a menos que alguém recupere seus relatórios finais.",al={"quem são os pacificadores","história dos pacificadores"}}},fp="14,146,16.225.0,17.216.0,28.153.0,35.249.0,31.111.0,33.207.0,39.189.0,32.219.0"}
P.entries["quest:93948"] = {n="Deliver the Signet",s="Deliver the Signet é uma missão na qual um viajante leva um anel de família recuperado ao Grão-Ancião Talaanis Shadowsong em Valanaar. A entrega traz a trágica confirmação do falecimento de seu sobrinho na Ilha de Zefras, enquanto abre novas oportunidades para ajudar os pacificadores locais.",h="Deliver the Signet é uma missão na qual um viajante leva um anel de família recuperado ao Grão-Ancião...",kw={"deliver the signet","sinete da família cantonegro","shen'dorei","talaanis shadowsong","valanaar","valennia stormfist","ilha de zefras"},ang={["race:NightElf"]="O proeminente nome de família Shadowsong evoca uma história profunda entre as linhagens élficas, embora aqui na Ilha de Zefras, o Grão-Ancião Talaanis e os shen'dorei locais enfrentem suas próprias lutas distintas."},sec={{t="Uma Tarefa Sombria",b="Quando um aventureiro viaja em direção ao assentamento de Valanaar, ele carrega consigo o Sinete da Família Cantonegro recuperado de uma torre isolada. Encarregados desse símbolo sombrio, os viajantes procuram por Talaanis Shadowsong, o Grão-Ancião da Ilha de Zefras. Amado por seu povo apesar das adversidades locais generalizadas, Talaanis precisa enfrentar a dolorosa confirmação de que seu sobrinho pereceu, recebendo condolências junto com a relíquia de família recuperada."},{t="Luto e Dever em Valanaar",b="Ao receber o anel de sinete em Valanaar, o Grão-Ancião Talaanis expressa sincera gratidão apesar de seu profundo luto. Reconhecendo a habilidade do viajante que recuperou a relíquia, Talaanis o direciona à Capitã Valennia Stormfist, líder dos pacificadores de Valanaar. Enfrentando circunstâncias difíceis e pressões crescentes, o assentamento acolhe qualquer ajuda que protetores capazes possam oferecer."}},faq={{q="Quem é Talaanis Shadowsong?",a="Talaanis Shadowsong atua como o Grão-Ancião da Ilha de Zefras. Amplamente respeitado e amado por sua comunidade, ele guia seu povo em tempos turbulentos e suporta uma tragédia pessoal ao receber o anel de sinete que confirma a morte de seu sobrinho.",al={"quem é talaanis","grão-ancião talaanis","história de talaanis shadowsong"}},{q="O que é o Sinete da Família Cantonegro?",a="O sinete é o Sinete da Família Cantonegro, recuperado de uma torre. Ele serve como a sombria confirmação de que o sobrinho de Talaanis Shadowsong pereceu, devolvendo uma relíquia de família ao enlutado Grão-Ancião.",al={"o que é o anel de sinete","anel do sobrinho","sinete dos cantonegro"}},{q="Onde fica Valanaar?",a="Valanaar é um assentamento localizado na Ilha de Zefras onde o Grão-Ancião Talaanis Shadowsong reside e onde a Capitã Valennia Stormfist supervisiona os pacificadores locais.",al={"onde fica valanaar","assentamento de valanaar","localização de talaanis"}},{q="Quem é Valennia Stormfist?",a="Valennia Stormfist é a capitã dos pacificadores destacados em Valanaar. O Grão-Ancião Talaanis recomenda falar com ela para obter trabalho, ressaltando que o assentamento necessita urgentemente de pessoas capazes.",al={"quem é valennia stormfist","capitã valennia","capitã dos pacificadores de valanaar"}},{q="Quem são os shen'dorei mencionados por Talaanis?",a="Talaanis se refere aos jovens viajantes capazes que descem das terras altas como shen'dorei, destacando a presença e a herança élfica que perduram na Ilha de Zefras.",al={"quem são os shen'dorei","terras altas dos shen'dorei"}},{q="O que aconteceu com o sobrinho de Talaanis Shadowsong?",a="O sobrinho de Talaanis morreu em uma torre onde o sinete de sua família foi perdido. Levar o sinete a Valanaar informa o Grão-Ancião sobre o falecimento de seu sobrinho, trazendo um desfecho a uma perda dolorosa.",al={"o que aconteceu com o sobrinho de talaanis","como o sobrinho morreu"}}},fp="18,224,15.334.0,26.329.0,27.145.0,37.142.0,26.140.0,26.153.0,45.151.0,46.143.0"}
P.entries["quest:93949"] = {n="Bugged",s="Bugged é uma missão em Valanaar onde um influxo sazonal de insetos das terras baixas se revela uma trama de espionagem. Magos da Alta Ordem descobriram que cultistas locais estão tecendo amuletos de escuta em skyhoppers para espionar o assentamento, exigindo um esforço de extermínio para eliminar as pragas encantadas.",h="Bugged é uma missão em Valanaar onde um influxo sazonal de insetos das terras baixas se revela uma trama de...",kw={"bugged","culto","skyhoppers encantados","alta ordem","feitiço de escuta","skyhoppers","valanaar"},ang={["class:Mage"]="Magos da Alta Ordem descobriram as proteções mágicas de espionagem tecidas em pragas comuns, transformando a análise arcana em contraespionagem."},sec={{t="Espiões no Enxame",b="Durante a temporada de skyhoppers nas terras baixas, enxames de insetos nativos surgem ao redor da cidade de Valanaar. Embora geralmente considerados apenas um incômodo sazonal, uma inspeção realizada por magos da Alta Ordem revelou que vários espécimes abatidos carregavam encantamentos sofisticados de escuta. Um culto local transformou o enxame de insetos em arma, convertendo pragas comuns das terras baixas em ferramentas discretas de vigilância para espionar a cidade."},{t="Limpando os Ares",b="Como os skyhoppers encantados parecem indistinguíveis de seus semelhantes normais, os protetores de Valanaar são forçados a abater os enxames indiscriminadamente. Erradicar esses insetos nega ao culto hostil o acesso a informações cruciais, interrompendo a vigilância mágica e reforçando as defesas da cidade contra a subversão interna."}},faq={{q="O que são skyhoppers?",a="Skyhoppers são pragas aladas nativas das terras baixas que cercam Valanaar e que surgem em grandes enxames durante sua alta sazonal.",al={"o que são skyhoppers","inseto skyhopper"}},{q="Quem encantou os insetos?",a="Suspeita-se que cultistas locais capturam skyhoppers e colocam feitiços mágicos de escuta neles para espionar o assentamento.",al={"quem encantou os insetos","insetos espiões do culto","quem está espionando em valanaar"}},{q="Como você sabe quais skyhoppers estão encantados?",a="A olho nu, os skyhoppers encantados parecem idênticos a insetos comuns. Apenas exterminando os enxames é possível descobrir e eliminar os espiões imbuídos de magia.",al={"como identificar skyhoppers encantados","quais insetos estão encantados"}},{q="Onde isso acontece?",a="A infestação e a espionagem ocorrem ao redor de Valanaar, uma cidade aérea onde enxames sazonais sobem das terras baixas adjacentes.",al={"onde fica a missão bugged","insetos de valanaar"}},{q="Que tipo de encantamento foi colocado nos skyhoppers?",a="Magos da Alta Ordem inspecionaram insetos abatidos e detectaram um feitiço especializado de escuta vinculado a eles, convertendo as criaturas de forma eficaz em ferramentas de vigilância móveis.",al={"qual feitiço está nos insetos","encantamento de skyhopper"}},{q="Por que todos os skyhoppers precisam ser exterminados?",a="Como os skyhoppers encantados não podem ser distinguidos visualmente de pragas comuns, eliminar o enxame é necessário para purgar a rede de postos de escuta mágica do culto e proteger Valanaar.",al={"por que matar skyhoppers","objetivo da missão bugged"}}},fp="6,188,26.244.0,16.206.0,20.124.0,26.96.0,47.121.0,27.115.0,54.115.0,50.165.0"}
P.entries["quest:93951"] = {n="A Little Beauty",s="A Little Beauty é uma tarefa local no Planalto de Shen'dar onde viajantes recolhem plumas macias de hipogrifo perto de Zephras. As plumas coloridas são usadas pelos Skyborne para adornar seus cabelos, trazendo um toque de beleza e alegria simples à aldeia durante tempos difíceis.",h="A Little Beauty é uma tarefa local no Planalto de Shen'dar onde viajantes recolhem plumas macias de hipogrifo...",kw={"a little beauty","plumas de penugem","penas","hipogrifo","plumas","planalto de shen'dar","skyborne","zephras"},ang={["race:Skyborne"]="Coletar vibrantes plumas de penugem de hipogrifo permite que os Skyborne de Zephras adornem seus cabelos com plumas suaves, mantendo seus costumes culturais e encontrando pequenas alegrias apesar das adversidades."},sec={{t="Plumas do Planalto",b="Na Ilha de Zefras, a sudoeste da aldeia, hipogrifos selvagens estabeleceram locais de nidificação no Planalto de Shen'dar. Embora essas feras territoriais possam ser um incômodo indisciplinado para os viajantes próximos, elas soltam plumas excepcionalmente vibrantes e suaves como seda. Para os Skyborne locais, coletar essas plumas descartadas apresenta uma oportunidade de criar ornamentos requintados trançados diretamente em seus cabelos."},{t="Encontrando Alegria nas Pequenas Coisas",b="Embora coletar penas decorativas para o cabelo possa parecer nada mais do que vaidade, o artesão em Zephras vê isso como uma busca essencial. Mesmo quando as circunstâncias são difíceis, encontrar e compartilhar pequenas alegrias cotidianas ajuda a sustentar o espírito da comunidade. Trazer beleza à vida dos aldeões garante que cada dia reserve algo que valha a pena celebrar."}},faq={{q="Por que as penas de hipogrifo estão sendo coletadas?",a="As plumas de penugem de hipogrifos selvagens são coletadas para criar adornos de cabelo decorativos para os Skyborne locais. Embora os hipogrifos perto do povoado possam ser um incômodo, suas plumas caídas são valorizadas por serem notavelmente suaves como seda e vibrantes.",al={"por que coletar penas","para que servem as penas","objetivo das penas"}},{q="O que é Zephras?",a="Zephras é a Ilha de Zefras, o lar insular dos Skyborne onde esta missão acontece. O artesão local confecciona adornos de cabelo a partir da plumagem recolhida em um esforço para trazer momentos de leveza e felicidade aos moradores que vivem ali.",al={"quem é zephras","que vila é esta","onde isso acontece"}},{q="Onde os hipogrifos nidificam?",a="Os hipogrifos selvagens nidificam a sudoeste da aldeia, no Planalto de Shen'dar. Como os hipogrifos selvagens são extremamente territoriais e não toleram visitas indesejadas, recolher penas caídas ao redor de seus locais de nidificação exige cautela.",al={"onde estão os ninhos","onde estão os hipogrifos","localização do planalto de shen'dar"}},{q="Por que pequenos luxos como adornos de cabelo são importantes em tempos como estes?",a="Embora adornar o cabelo com penas possa parecer uma futilidade vã, quem oferece a missão explica que abraçar pequenas alegrias e a beleza é vital, especialmente durante tempos difíceis. Trazer um momento de felicidade aos outros faz o esforço valer a pena.",al={"as penas são importantes","por que enfeites de cabelo","futilidade vã"}},{q="Os hipogrifos são hostis aos visitantes?",a="Os hipogrifos que vivem a sudoeste da aldeia são criaturas selvagens. Eles consideram seus locais de nidificação como seu território e não toleram intrusos, tornando a coleta de suas plumas caídas perigosa para viajantes desavisados.",al={"por que os hipogrifos são perigosos","os hipogrifos são selvagens"}},{q="Enfeitar o cabelo com penas é comum entre os Skyborne?",a="Sim, muitos Skyborne gostam de trançar plumas vibrantes em seus cabelos como adornos pessoais. As plumas de penugem excepcionalmente suaves dos hipogrifos são materiais ideais para esses ornamentos decorativos.",al={"penas dos skyborne","os skyborne usam penas"}}},fp="15,157,23.241.0,27.222.0,44.173.0,16.159.0,30.152.0,74.139.0,40.161.0,59.131.0"}
P.entries["quest:93958"] = {n="The Inner Sanctum",s="The Inner Sanctum se concentra em um perigoso reconhecimento na câmara mais profunda do Santuário de Akir. Após Valennia Stormfist e sua força de ataque invadirem o sacrário em meio a um combate intenso, um silêncio inquietante recaiu sobre a área, motivando uma missão urgente para descobrir se ainda restam sobreviventes.",h="The Inner Sanctum se concentra em um perigoso reconhecimento na câmara mais profunda do Santuário de Akir.",kw={"the inner sanctum","santuário de akir","stormfist","valennia","valennia stormfist"},sec={{t="Um Silêncio Repentino",b="Após um ataque intenso, Valennia Stormfist liderou seu destacamento para invadir o sacrário interior no Santuário de Akir. O confronto inicial gerou sons de combate denso e desesperado vindo do fundo das câmaras, mas o barulho logo deu lugar a um silêncio abrupto e inquietante que deixou os aliados do lado de fora preparados para o pior."},{t="O Custo da Invasão",b="Aventurar-se pelo sacrário silenciado revela o preço terrível do ataque. Em vez de uma vanguarda vitoriosa assegurando a posição, Valennia Stormfist é encontrada gravemente ferida após a batalha, com o destino de sua vanguarda permanecendo em situação precária."}},faq={{q="Quem é Valennia Stormfist?",a="Valennia Stormfist é uma comandante que lidera um ataque às profundezas do Santuário de Akir. Ela liderou a invasão do sacrário interior com suas forças, embora o confronto feroz em seu interior tenha cessado abruptamente em um silêncio sinistro.",al={"quem é valennia","quem é valennia stormfist","valennia"}},{q="O que é o Santuário de Akir?",a="O Santuário de Akir abriga um sacrário interior atualmente sob ataque. As tropas de Valennia romperam suas defesas em meio a combates intensos, transformando-o no centro de um confronto tenso e mortal.",al={"o que é o santuário de akir","história do santuário de akir","santuário de akir"}},{q="O que aconteceu com as forças de Valennia lá dentro?",a="Combates pesados ecoaram de dentro logo após a invasão, mas os sons da batalha cessaram de repente. Uma calmaria perturbadora instalou-se sobre o sacrário interior, levando os aliados do lado de fora a temerem que a vanguarda de Valennia possa ter sido dominada ou aniquilada.",al={"por que está silêncio","o que aconteceu com as forças de valennia","soldados de valennia"}},{q="Valennia Stormfist ainda está viva?",a="Valennia sobrevive ao ataque, mas é encontrada gravemente ferida dentro do sacrário interior do Santuário de Akir após o término dos combates.",al={"valennia está viva","valennia morreu","destino de valennia"}},{q="Qual é o objetivo dentro do sacrário interior?",a="O sacrário interior é a câmara mais profunda do Santuário de Akir. A missão orienta um aliado a entrar na câmara sozinho, avaliar as consequências da invasão e fazer contato com Valennia e quaisquer combatentes sobreviventes.",al={"o que é the inner sanctum","objetivo da missão the inner sanctum"}},{q="Quem envia você para o sacrário interior?",a="Um aliado que protege a retaguarda do lado de fora do sacrário interior envia você. Enquanto mantém o perímetro para cobrir suas costas, ele envia você à frente para fazer contato com a vanguarda de Valennia.",al={"quem envia você até valennia","iniciador da missão the inner sanctum"}}},fp="17,175,16.262.0,22.139.1,26.177.0,27.173.0,42.173.0,34.123.0,47.158.0,37.156.0"}
P.entries["quest:93963"] = {n="Exploring the Alliance",s="Exploring the Alliance é uma jornada diplomática que orienta aventureiros recém-chegados à Bastilha Ventobravo a visitar as capitais soberanas da Aliança. Ao se encontrarem com os governantes de Altaforja e Darnassus, os viajantes adquirem uma compreensão vital das nações aliadas de Azeroth antes de pegarem em armas em terras próximas, como Cerro Oeste.",h="Exploring the Alliance é uma jornada diplomática que orienta aventureiros recém-chegados à Bastilha...",kw={"dalaran","darnassus","exploring the alliance","grão-mecânico mekkatorque","altaforja","magni barbabronze","randal emerson","bastilha ventobravo","tyrande murmuréolo","cerro oeste"},ang={["faction:Alliance"]="Esta jornada diplomática apresenta os recém-chegados aos principais bastiões da Aliança e aos líderes fundamentais que sustentam o pacto.",["race:Skyborne"]="Como convidados em Azeroth que se preparam para a presença de sua ordem em Dalaran, os Skyborne são instados a compreender as nações aliadas que os acolhem."},sec={{t="Uma Excursão pelas Terras Aliadas",b="Para os visitantes recém-chegados a Azeroth, a Aliança estende um convite aberto para testemunhar sua grandiosidade em primeira mão. Em vez de permanecerem isolados na Bastilha Ventobravo, os viajantes recebem a incumbência de se aventurar além da capital dos humanos para observar as distintas culturas, tradições e a determinação que definem os grandes povos aliados. Guiados inicialmente por Randal Emerson na antecâmara sul da fortaleza, os aventureiros partem em uma excursão que abrange o continente."},{t="Audiências com as Altas Sedes",b="A peregrinação diplomática leva os aventureiros por terra e mar até a presença dos líderes governantes da Aliança: o Rei Magni Barbabronze nos salões subterrâneos da montanha de Altaforja, o Grão-mecânico Gelbin Mekkatorque dos gnomos desabrigados e a Alta-sacerdotisa Tyrande Murmuréolo no topo de Darnassus, em Teldrassil. Encontrar esses governantes oferece um vislumbre raro da delicada rede de união que vincula humanos, anões, gnomos e elfos noturnos."},{t="Um Mundo que Precisa de Ajuda",b="Ao concluir a longa viagem e retornar a Ventobravo, os viajantes são recebidos com o lembrete de que o conhecimento de Azeroth é vital para ajudar seu próprio povo. Com sua ordem ainda preparando seus alicerces em Dalaran, o foco imediato se volta para fora, em direção aos territórios conturbados vizinhos à capital, começando pelas combalidas terras agrícolas de Cerro Oeste."}},faq={{q="O que é a missão Exploring the Alliance?",a="Exploring the Alliance é uma jornada diplomática que apresenta um recém-chegado às principais sedes do poder da Aliança por toda Azeroth. Na condição de convidado de honra, o aventureiro fica encarregado de viajar pelo mundo para conhecer os líderes de Altaforja, Gnomeregan no exílio e Darnassus.",al={"missão exploring the alliance","o que é esta missão"}},{q="Quem é Randal Emerson?",a="Randal Emerson é um atendente instalado na antecâmara sul da Bastilha Ventobravo. Ele fornece orientações e instruções iniciais de viagem para encaminhar os viajantes rumo às outras capitais.",al={"randal emerson","quem dá instruções"}},{q="Quais líderes devem ser visitados durante esta jornada?",a="A jornada exige apresentar-se ao Rei Magni Barbabronze de Altaforja, ao Grão-mecânico Gelbin Mekkatorque e à Alta-sacerdotisa Tyrande Murmuréolo em Darnassus. Cada um representa uma raça principal e uma sede de autoridade dentro da Aliança.",al={"líderes visitados","com quem falar"}},{q="Por que Dalaran é mencionada ao concluir a missão?",a="A ordem do aventureiro está em processo de estabelecer sua presença em Dalaran. Enquanto aguardam a consolidação desses preparativos, os viajantes são incentivados a se familiarizar com Azeroth e prestar ajuda aos territórios vizinhos.",al={"por que dalaran é mencionada","ordem em dalaran"}},{q="Para onde o caminho leva após concluir esta jornada?",a="Ao retornar à Bastilha Ventobravo, os aventureiros são direcionados ao interior que cerca a capital, especificamente a Cerro Oeste, onde comunidades locais enfrentam problemas e precisam urgentemente de defensores capacitados.",al={"para onde ir em seguida","após exploring the alliance"}},{q="Por que o aventureiro é tratado como um convidado da Aliança?",a="O texto da missão trata o aventureiro como um forasteiro que chega a Azeroth e precisa compreender o mundo mais amplo para proteger e ajudar seu próprio povo, conhecendo as variadas culturas da Aliança.",al={"convidado da aliança","por que convidado"}}},fp="22,167,22.330.0,29.363.0,22.273.0,41.223.0,22.133.0,50.195.0,51.170.0,55.165.0,57.211.0"}
P.entries["quest:93976"] = {n="The Goblin Trader",s="Kreza envia você para entregar uma lâmina a uma conhecida nas docas a leste de Rog'mar. A destinatária é conhecida por todos os Reinos e além.",h="Kreza envia você para entregar uma lâmina a uma conhecida nas docas a leste de Rog'mar.",kw={"conhecida","lâmina","docas","comerciante goblin","gur'dok","kreza darkthorn","rog'mar"},ang={["faction:Horde"]="A destinatária diz que a entrega foi feita em nome da Horda."},sec={{t="Uma lâmina para as docas",b="Kreza Darkthorn forjou uma lâmina com Gur'dok e pede que você a leve para leste de Rog'mar. Sua conhecida espera nas docas e é conhecida muito além dos Reinos. Kreza diz que as duas estão quites."}},faq={{q="Quem está me enviando com a lâmina?",a="Kreza Darkthorn envia você com uma lâmina que forjou com Gur'dok.",al={"quem me enviou","entrega da lâmina de kreza"}},{q="Para quem é a lâmina?",a="É para uma conhecida de Kreza Darkthorn nas docas a leste de Rog'mar.",al={"destinatária da lâmina","quem recebe a espada"}},{q="Onde devo entregar a lâmina?",a="Você a entrega à conhecida de Kreza Darkthorn nas docas a leste de Rog'mar.",al={"onde ficam as docas","entrega nas docas"}},{q="O que Kreza diz sobre a dívida?",a="Kreza pede que você diga que ela e sua conhecida estão quites.",al={"o que kreza quer dizer com quites","kreza, estamos quites"}}},fp="17,138,21.197.0,33.66.0,21.70.0,29.78.0,35.62.0"}
P.entries["quest:94"] = {n="Olho vigilante",s="Olho vigilante é uma missão da Aliança oferecida pelo mago Teócrito na Torre de Azora, na Floresta de Elwynn. Depois de estabelecer um vínculo básico de vidência para observar seu rival Morganth, Teócrito envia aventureiros para leste, rumo às Montanhas Cristarrubra, a fim de instalar um foco encantado numa antiga estátua de leão voltada para a Torre de Ilgalar.",h="Olho vigilante é uma missão da Aliança oferecida pelo mago Teócrito na Torre de Azora, na Floresta de Elwynn.",kw={"elwynn","glifo de azora","morganth","estátua de leão","cristarrubra","teócrito","torre de azora","torre de ilgalar"},ang={["class:Mage"]="Para os praticantes das artes arcanas, essa missão demonstra a adivinhação à distância e os canais de vidência, contrapondo os métodos acadêmicos estruturados de Teócrito aos feitiços ilícitos de Morganth.",["faction:Alliance"]="Neutralizar conjuradores humanos renegados como Morganth é fundamental para proteger a fronteira entre a Floresta de Elwynn e os povoados sitiados das Montanhas Cristarrubra."},sec={{t="Uma rivalidade além da fronteira",b="Da torre na região leste da Floresta de Elwynn, o mago Teócrito observa atentamente a magia sombria que se desenvolve nas colinas próximas. Seu principal inimigo é Morganth, um feiticeiro cruel e poderoso que tomou a Torre de Ilgalar, nos rochedos das Montanhas Cristarrubra. Para descobrir as ambições sinistras de Morganth antes que ultrapassem a fronteira, Teócrito criou o Olho de Azora, permitindo-lhe espionar o mago renegado à distância."},{t="A vigília do leão",b="Embora a vidência ofereça algumas informações, ela não basta para revelar os planos mais profundos de Morganth. Teócrito confia aos viajantes o Glifo de Azora e ordena que sigam até os arredores da Torre de Ilgalar. Ali, solitária e vigilante há décadas, fica uma antiga Estátua de Leão. Colocar o glifo numa cavidade desgastada em sua base ativa um canal arcano que liga a pedra à Torre de Azora, permitindo que Teócrito investigue diretamente a mente do rival."}},faq={{q="Quem é Teócrito?",a="Teócrito é um mago poderoso da Aliança que reside no alto da Torre de Azora, no leste da Floresta de Elwynn. Ele dedica seus estudos arcanos a proteger a região contra ameaças mágicas rebeldes, sobretudo o feiticeiro renegado Morganth.",al={"teócrito","mago da torre de azora","quem concede olho vigilante"}},{q="Quem é Morganth?",a="Morganth é um mago humano maligno e renegado que estabeleceu sua fortaleza na Torre de Ilgalar, nas Montanhas Cristarrubra. Ele é o grande rival de Teócrito, que teme os planos sombrios tramados por Morganth contra os territórios vizinhos.",al={"morganth","quem é morganth","mago rival"}},{q="Onde fica a antiga Estátua de Leão?",a="A antiga Estátua de Leão está desgastada pelo tempo nas elevações voltadas para a Torre de Ilgalar, nas colinas orientais das Montanhas Cristarrubra. Uma cavidade rasa em sua base serve para receber focos mágicos como o Glifo de Azora.",al={"localização da estátua de leão","onde fica a estátua","onde colocar o glifo de azora"}},{q="O que faz o Glifo de Azora?",a="O Glifo de Azora é uma pedra encantada criada por Teócrito. Encaixado na estátua de leão próxima à Torre de Ilgalar, ele funciona como posto arcano de escuta e canal de sondagem mental, permitindo que Teócrito se comunique pela pedra e examine os pensamentos de Morganth.",al={"glifo de azora","o que é o glifo"}},{q="O que é a Torre de Ilgalar?",a="A Torre de Ilgalar é uma torre alta e isolada de pedra, erguida entre os rochedos do leste das Montanhas Cristarrubra. Atualmente, ela é ocupada e defendida pelo mago Morganth e seus servos.",al={"torre de ilgalar","ilgalar"}},{q="O que acontece depois de colocar o glifo?",a="Assim que o Glifo de Azora é fixado na estátua, Teócrito fala através da pedra e oferece imediatamente a missão seguinte, Vendo Além, enquanto começa a desvendar as maquinações de Morganth.",al={"próxima missão","o que vem depois de olho vigilante"}}},fx={["0c307b8a"]={q="Por que Teócrito quer que isso seja feito?",a="Morganth é um mago implacável de poder formidável escondido na Torre de Ilgalar. Embora Teócrito possa visualizar seu rival usando a magia de vidência do Olho de Azora, vê-lo não é mais suficiente. Ao fixar o Glifo de Azora na estátua de leão próxima, Teócrito espera penetrar na mente de Morganth e descobrir o que o bruxo das trevas está planejando antes que ele o desencadeie sobre a região.",al={"motivação de teócrito","por que colocar o glifo de azora","por que espionar morganth"}}},fp="14,186,27.296.0,16.348.0,18.173.0,16.201.0,37.175.0,32.188.0,29.144.0,35.150.0"}
P.entries["quest:940"] = {n="Teldrassil",s="Depois de expulsar as harpias rebeldes nas proximidades da Árvore dos Oráculos, a Sentinela Arynia Cloudsbreak confia a você a entrega de um relatório a Darnassus. A casca de árvore inscrita é endereçada ao Arquidruida Fandral Guenelmo e traz notícias sobre o estado dos galhos e a corrupção que continua assolando a Árvore do Mundo.",h="Depois de expulsar as harpias rebeldes nas proximidades da Árvore dos Oráculos, a Sentinela Arynia...",kw={"arynia cloudsbreak","enclave cenariano","darnassus","fandral guenelmo","imortalidade","casca de árvore inscrita","kaldorei","árvore dos oráculos","teldrassil"},ang={["class:Druid"]="Levar notícias da antiga Árvore dos Oráculos diretamente ao líder do Círculo Cenariano evidencia a luta constante para restaurar o equilíbrio natural de Teldrassil.",["faction:Alliance"]="Para os campeões da Aliança que concluem suas primeiras tarefas na ilha, essa missão oferece uma apresentação formal à capital dos elfos noturnos e à sua liderança severa.",["race:NightElf"]="Entregar esse relatório coloca você frente a frente com o Arquidruida Guenelmo, revelando sua obsessão pessoal por restaurar a imortalidade dos kaldorei através dos galhos conturbados de Teldrassil."},sec={{t="Um mensageiro para a cidade de pedra",b="Nas profundezas dos galhos de Teldrassil, a Árvore dos Oráculos vigia a floresta. Depois de expulsar as harpias de seus ninhos no Bosque do Oráculo, a Sentinela Arynia Cloudsbreak decide que finalmente é seguro enviar notícias à liderança kaldorei. Confiando a você um pedaço de casca de árvore inscrita, ela o envia através das terras selvagens até Darnassus — a grande \"floresta de pedra\" — para entregar o relatório da Árvore dos Oráculos diretamente ao Arquidruida Fandral Guenelmo."},{t="A ambição e a frustração de Guenelmo",b="Ao receber o relatório, Fandral Guenelmo demonstra sentimentos contraditórios. Embora grato pelas notícias de que as harpias foram repelidas, o documento revela uma verdade mais profunda: sempre que uma ameaça diminui em Teldrassil, outra surge em seu lugar. Para Guenelmo, que defendeu o plantio da nova Árvore do Mundo para recuperar a imortalidade perdida dos elfos noturnos, os males constantes que afetam os galhos são um lembrete amargo de que sua grande obra está longe de terminar."}},faq={{q="Qual é o objetivo da missão Teldrassil?",a="Essa missão liga narrativamente suas aventuras na floresta próxima à Árvore dos Oráculos à capital. A Sentinela Arynia Cloudsbreak encarrega você de levar uma Casca de Árvore Inscrita, contendo o relatório da Árvore dos Oráculos, ao Arquidruida Fandral Guenelmo em Darnassus.",al={"objetivo da missão teldrassil","para que serve essa missão","entrega em teldrassil"}},{q="Quem é a Sentinela Arynia Cloudsbreak?",a="Arynia Cloudsbreak é uma sentinela elfa noturna que atua perto da Árvore dos Oráculos nas terras selvagens de Teldrassil. Ela vigia ameaças locais, como as harpias Pena Sangrenta, e coordena a defesa da floresta com Darnassus.",al={"história de arynia cloudsbreak","quem inicia a missão teldrassil"}},{q="Por que Arynia chama Darnassus de \"floresta de pedra\"?",a="Embora os elfos noturnos vivam sob a copa da Árvore do Mundo, Darnassus foi construída com grandes templos, pontes e pavilhões de mármore e pedra. Em comparação com as florestas intocadas próximas à Árvore dos Oráculos, a capital é uma floresta construída de pedra.",al={"significado de floresta de pedra","por que floresta de pedra"}},{q="Por que Fandral Guenelmo se preocupa tanto com o relatório da Árvore dos Oráculos?",a="Guenelmo liderou a criação de Teldrassil na esperança de recuperar a imortalidade dos kaldorei após os danos sofridos por Nordrassil na Terceira Guerra. As notícias da Árvore dos Oráculos confirmam que Teldrassil continua sofrendo com a corrupção e a agitação da vida selvagem, ameaçando suas ambições.",al={"reação de fandral guenelmo","por que guenelmo está preocupado"}},{q="Qual missão vem antes e qual vem depois desta?",a="Essa missão vem logo depois de O Bosque Encantado, em que você enfrenta as harpias que ameaçam a Árvore dos Oráculos. Depois de entregar o relatório ao Arquidruida Guenelmo, ele envia você a Costa Negra na missão seguinte, Bosque dos Antigos.",al={"série de missões teldrassil","qual é a próxima missão"}},{q="Onde encontro o Arquidruida Fandral Guenelmo?",a="O Arquidruida Fandral Guenelmo reside em Darnassus, no alto do Enclave Cenariano, onde supervisiona os druidas do Círculo Cenariano e ajuda a governar os kaldorei.",al={"onde fica fandral","localização de fandral guenelmo"}}},fx={d4229979={q="Por que a Sentinela Arynia Rasganimbus quer que este relatório seja entregue?",a="Arynia precisa que o Arquidruida Fandral Guenelmo receba o relatório da Árvore do Oráculo para que Darnassus permaneça informada sobre a condição do galho. Os bosques sofreram com infestações de harpias e corrupção não natural, e mensageiros anteriores não conseguiram fazer a viagem em segurança. Com a calma restaurada à Clareira do Oráculo, as notícias devem chegar ao Arquidruida para que a liderança possa avaliar o estado da árvore do mundo.",al={"por que enviar relatório a fandral","motivo de arynia rasganimbus","por que arynia quer o relatório entregue"}},["174bd7d2"]={q="Por que Arynia Rasganimbus envia você em vez de outro mensageiro?",a="Mensageiros anteriores enviados pelas trilhas da floresta não conseguiram chegar a Darnassus ou perderam-se no caminho, deixando Arynia hesitante em arriscar outro corredor comum. Tendo provado sua coragem e proeza em batalha ao limpar as harpias da Clareira do Oráculo, você conquistou o favor da floresta e demonstrou que pode se defender e proteger a mensagem ao longo das estradas perigosas até a cidade.",al={"por que me enviar a darnassus","por que não enviar outro mensageiro","por que arynia precisa de você"}}},fp="10,203,29.359.0,35.336.0,46.188.0,35.219.0,51.210.0,68.276.0,48.200.0,47.172.0"}
P.entries["quest:94003"] = {n="The Skybreaker Bulwark",s="O Baluarte do Rompe-céus é uma missão na Ilha de Zefras sobre a trágica queda da linhagem dos Skybreaker. Aventureiros são incumbidos de viajar até o Santuário de Akir para recuperar um escudo ancestral sagrado das mãos do sectário Zaal Stormshield.",h="O Baluarte do Rompe-céus é uma missão na Ilha de Zefras sobre a trágica queda da linhagem dos Skybreaker.",kw={"al'aketh","santuário de akir","skybreaker","baluarte do rompe-céus","skybreaker defense","o baluarte do rompe-céus","zaal stormshield","ilha de zefras"},ang={["class:Paladin"]="Defensores portadores de escudos que veneram relíquias sagradas apreciarão recuperar uma relíquia abençoada das garras de um sectário corrupto.",["class:Warrior"]="Guerreiros que valorizam o domínio defensivo encontrarão um propósito afim aqui, já que recuperar o escudo ancestral recompensa com instruções na técnica Skybreaker Defense."},sec={{t="Uma Linhagem Decaída",b="Na Ilha de Zefras, a linhagem ancestral dos Skybreaker teve um fim trágico nas mãos dos Al'Aketh. A família foi brutalmente assassinada, restando apenas um único sobrevivente sobrecarregado por uma profunda tristeza e pela amarga vergonha de ver sua maior relíquia de família perdida. Essa estimada relíquia, o Baluarte do Rompe-céus, foi levada por um sectário chamado Zaal Stormshield, que atualmente espreita no Santuário de Akir."},{t="O Escudo Sagrado",b="A tradição familiar sustenta que o Baluarte do Rompe-céus possui uma bênção protetora: nenhum mal pode atingir qualquer um que seja verdadeiramente digno de empunhá-lo. Convencido de que o sectário Zaal não é digno de seu favor divino, o último Skybreaker busca um aventureiro para viajar ao Santuário de Akir, abater o ladrão e recuperar o escudo ancestral em troca de treinamento na técnica Skybreaker Defense."}},faq={{q="Quem são os Skybreakers?",a="Os Skybreakers são uma linhagem antiga na Ilha de Zefras cujos membros foram quase inteiramente aniquilados. O concedente da missão é o único membro sobrevivente desta linha familiar após o restante ser morto pelos Al'Aketh.",al={"quem são os skybreakers","família skybreaker"}},{q="O que é o Baluarte do Rompe-céus?",a="O Baluarte do Rompe-céus é um escudo ancestral pertencente à linhagem dos Skybreaker na Ilha de Zefras. De acordo com a tradição e as lendas da família, nenhum mal pode acometer aquele que for considerado um portador digno do escudo.",al={"o que é o baluarte do rompe-céus","o escudo","história do escudo dos skybreaker"}},{q="Quem são os Al'Aketh?",a="Os Al'Aketh são a força hostil responsável pelo massacre da família Skybreaker na Ilha de Zefras, restando apenas um sobrevivente solitário para lamentar sua perda.",al={"quem matou os skybreakers","o que são os al'aketh","al'aketh"}},{q="Quem é Zaal Stormshield?",a="Zaal Stormshield é um sectário que roubou o Baluarte do Rompe-céus após a ruína da família Skybreaker. Ele pode ser encontrado carregando a relíquia no Santuário de Akir, na Ilha de Zefras.",al={"quem está com o escudo","zaal","stormshield"}},{q="Onde fica o Santuário de Akir?",a="O Santuário de Akir é um local na Ilha de Zefras onde o sectário Zaal Stormshield se refugiou com o roubado Baluarte do Rompe-céus.",al={"onde está zaal","localização do santuário de akir","onde encontrar o escudo"}},{q="Por que o Baluarte deve ser recuperado?",a="Recuperar a relíquia corrige a vergonha da família e remove a relíquia sagrada de mãos indignas. Em troca de sua recuperação, o último Skybreaker transmite o conhecimento de Skybreaker Defense.",al={"por que recuperar o escudo","o que é skybreaker defense","recompensa do escudo"}}},fp="22,144,16.273.0,17.345.0,24.143.0,31.153.0,21.98.0,24.166.0,28.103.0,34.187.0"}
P.entries["quest:94004"] = {n="Craftsman's Writ: Elixir of Ogre's Strength",s="Uma ordem transferível solicita um Elixir of Ogre's Strength e informa o local de entrega e as condições de pagamento. Sos'mol recebe o elixir e se lembra da sua ajuda.",h="Uma ordem transferível solicita um Elixir of Ogre's Strength e informa o local de entrega e as condições de...",kw={"ordem do artesão","entrega","elixir of ogre's strength","força de ogro","pagamento","sos'mol","ordem transferível"},sec={{t="Uma ordem de cliente",b="O bilhete desbotado pede que você traga um Elixir of Ogre's Strength. Ele pode ser transferido e informa o local de entrega e os detalhes do pagamento. Guarde a ordem para a troca."},{t="Os agradecimentos de Sos'mol",b="Sos'mol agradece por você ter trazido o elixir e diz que nenhum ogro o ajudou assim antes. Ele promete se lembrar da sua gentileza e retribuir algum dia."}},faq={{q="O que a ordem solicita?",a="A ordem solicita um Elixir of Ogre's Strength.",al={"o que esta ordem solicita","ordem do elixir of ogre's strength"}},{q="Quem é o cliente?",a="Sos'mol é o cliente que recebe o elixir.",al={"quem quer o elixir","quem é sos'mol"}},{q="Outra pessoa pode levar a ordem?",a="Sim. O bilhete diz que a ordem pode ser transferida.",al={"a ordem pode ser transferida","posso passar a ordem adiante"}},{q="O que preciso para fazer a troca?",a="Traga o elixir solicitado e mantenha a ordem com você durante a transação.",al={"o que devo trazer","requisitos da ordem"}},{q="O que Sos'mol diz depois de receber o elixir?",a="Sos'mol diz que se lembrará da sua ajuda e promete retribuir algum dia.",al={"agradecimentos de sos'mol","o que sos'mol promete"}}},fp="43,156,17.182.0,16.152.0,27.48.0,20.48.0,32.44.0,32.84.0,41.74.0"}
P.entries["quest:94006"] = {n="The Great Ursera Spirit",s="Um druida envia você para conhecer Urs'endris, um espírito de Zephras que há gerações ensina druidas a assumir a forma ursera. O domínio dele está definhando, e Urs'endris pode orientar você a avançar nos estudos.",h="Um druida envia você para conhecer Urs'endris, um espírito de Zephras que há gerações ensina druidas a...",kw={"druida","cachoeiras","santuário de akir","espírito","urs'endris","ursera","valanaar","zephras"},ang={["class:Druid"]="Como druida, seus estudos levaram você até Urs'endris, que há gerações ensina druidas a assumir a forma ursera."},sec={{t="O Grande Espírito",b="Um druida envia você até Urs'endris, perto das cachoeiras a nordeste de Valanaar. Seus estudos druídicos levaram você a um encontro com um dos grandes espíritos de Zephras. Urs'endris ensina druidas a assumir a forma ursera há gerações, e o domínio dele está definhando e caindo no céu."}},faq={{q="Quem é Urs'endris?",a="Urs'endris é um espírito sábio de Zephras que há gerações ensina druidas a assumir a forma ursera.",al={"quem é urs'endris","grande espírito urs","espírito ursera"}},{q="Onde posso encontrar Urs'endris?",a="Urs'endris fica perto das cachoeiras a nordeste de Valanaar, próximo ao Santuário de Akir.",al={"localização de urs'endris","onde está urs'endris","conhecer o espírito"}},{q="Por que estão me enviando até Urs'endris?",a="Seus estudos druídicos avançaram o suficiente para você conhecer um dos grandes espíritos de Zephras, e Urs'endris pode ensinar mais a você.",al={"por que conhecer urs'endris","missão de espírito druídico","estudos ursera"}},{q="O que está acontecendo com o domínio de Urs'endris?",a="O domínio de Urs'endris começou a definhar e cair no céu.",al={"domínio definhando","zephras caindo","o que há de errado lá"}},{q="O que é a forma ursera?",a="A forma ursera é uma forma que Urs'endris ensina druidas a assumir há gerações.",al={"forma ursera","caminho da garra","ursera"}}},fp="23,185,16.270.0,18.102.0,28.76.0,34.132.0,41.62.0,25.80.0"}
P.entries["quest:94007"] = {n="Taming the Beast",s="Quel'ana Quickgale em Valanaar pode ensinar você a domar uma fera. Seu tempo nas Terras Altas preparou você para buscar um companheiro animal.",h="Quel'ana Quickgale em Valanaar pode ensinar você a domar uma fera.",kw={"companheiro animal","domar feras","terras altas","quel'ana quickgale","taming the beast","valanaar"},sec={{t="Um novo companheiro",b="Você se sente mais à vontade nas Terras Altas, e seu anfitrião acredita que está pronto para buscar um companheiro animal. Vá a Valanaar e fale com Quel'ana Quickgale; ele começará a ensinar a arte de domar feras."}},faq={{q="Quem ensina a domar feras?",a="Quel'ana Quickgale ensina você a arte de domar feras em Valanaar.",al={"quem é quel'ana quickgale","instrutor de doma de feras"}},{q="Onde encontro Quel'ana Quickgale?",a="Quel'ana Quickgale está em Valanaar, o porto a sudeste.",al={"onde fica quel'ana","doma em valanaar"}},{q="Por que estou indo a Valanaar?",a="Você está sendo enviado a Valanaar para falar com Quel'ana Quickgale e começar a aprender a domar feras.",al={"por que valanaar","missão de domar feras"}},{q="O que estou aprendendo?",a="Quel'ana Quickgale ensinará você a domar uma fera para que possa buscar um companheiro animal.",al={"o que é domar feras","companheiro animal"}}},fp="16,135,15.187.0,25.58.0,35.61.0,27.92.0,19.86.0"}
P.entries["quest:94013"] = {n="Taming the Beast",s="Quel'ana Quickgale propõe um último desafio: domar um Vuldren Alpha. Ao dominá-lo, você estará pronto para aprender os ensinamentos mais profundos da sua classe.",h="Quel'ana Quickgale propõe um último desafio: domar um Vuldren Alpha.",kw={"companheiro animal","baixios dos lufopomos","quel'ana quickgale","bastão de adestramento","taming the beast","valanaar","vuldren alpha","ilha de zefras"},sec={{t="O Último Desafio",b="Quel'ana entrega a você um Bastão de Adestramento e envia você aos Baixios dos Lufopomos. Lá, você deve adestrar um Vuldren Alpha e depois devolver o bastão a ele em Valanaar. A lição deve provar seu domínio e preparar você para ensinamentos mais avançados da sua classe."},{t="Uma Nova Lição",b="Depois que você retorna, Quel'ana diz que você aprendeu o básico e se oferece para ensinar como criar um vínculo duradouro com um companheiro animal. Ele pede que você leve esse conhecimento adiante, como a classe precisa na Ilha de Zefras."}},faq={{q="O que Quel'ana me pede para domar?",a="Quel'ana pede que você dome um Vuldren Alpha nos Baixios dos Lufopomos com o Bastão de Adestramento.",al={"domar vuldren alpha","qual fera","domar alpha"}},{q="Onde encontro o Vuldren Alpha?",a="O Vuldren Alpha fica nos Baixios dos Lufopomos.",al={"localização do alpha","baixios dos lufopomos","onde domar fera"}},{q="Para que serve o Bastão de Adestramento?",a="Quel'ana lhe entrega o Bastão de Adestramento para domar um Vuldren Alpha.",al={"utilidade do bastão","missão do bastão de adestramento","como usar o bastão"}},{q="Onde devo devolver o Bastão de Adestramento?",a="Devolva o Bastão de Adestramento a Quel'ana Quickgale em Valanaar.",al={"devolver bastão","localização de quel'ana","onde devolver o bastão de adestramento"}},{q="O que vou aprender depois disso?",a="Quel'ana diz que pode ensinar você a criar um vínculo duradouro com um companheiro animal.",al={"próxima lição","vínculo com companheiro animal","o que vem depois"}}},fp="16,136,15.228.0,12.223.1,34.88.0,34.47.0,27.58.0,33.56.0,29.79.0"}
P.entries["quest:94050"] = {n="Training the Beast",s="Uma Caçadora manda você procurar Quel'dora Quickgale em Valanaar para aprender a treinar seu mascote. Os ensinamentos dela ampliam as formas de cuidar dele e orientá-lo.",h="Uma Caçadora manda você procurar Quel'dora Quickgale em Valanaar para aprender a treinar seu mascote.",kw={"alimentar mascote","caçador","treinamento de mascote","quel'dora quickgale","reanimar mascote","domar mascote","training the beast","valanaar"},ang={["class:Hunter"]="Como Caçador, você está aprendendo a treinar e orientar um mascote que já consegue domar."},sec={{t="Os ensinamentos de Quel'dora",b="Seu companheiro Caçador indica a irmã dele, Quel'dora Quickgale, em Valanaar. Você já pode domar um mascote, mas aprender a treiná-lo é o próximo passo para guiá-lo. Quel'dora pode ensinar você a treinar seu companheiro."},{t="O dever de um Caçador",b="Quel'dora pode ensinar você a orientar seu mascote, ensiná-lo novas habilidades, alimentá-lo e reanimá-lo se ele cair em batalha. Ela pede que você respeite o equilíbrio e contemple com admiração a natureza ao seu redor."}},faq={{q="Quem é Quel'dora Quickgale?",a="Quel'dora Quickgale é irmã da Caçadora que manda você aprender a treinar mascotes.",al={"quem é quel'dora","quel'dora","quickgale"}},{q="Onde posso encontrar Quel'dora?",a="Quel'dora Quickgale está em Valanaar.",al={"onde fica quel'dora","localização de quel'dora","treinadora em valanaar"}},{q="O que Quel'dora ensina?",a="Quel'dora ensina você a treinar e orientar seu mascote, incluindo ensinar habilidades a ele, alimentá-lo e reanimá-lo se cair em batalha.",al={"treinamento de mascote","treinar meu mascote","o que uma treinadora de mascotes ensina"}},{q="Já posso domar um mascote?",a="A Caçadora que manda você procurar Quel'dora diz que você já tem o poder de domar um mascote.",al={"domar mascote","domesticação de mascotes","caçador pode domar mascote"}},{q="O que a Caçadora me pede para fazer?",a="A Caçadora pede que você converse com Quel'dora Quickgale em Valanaar.",al={"training the beast","missão da treinadora de mascotes","falar com quel'dora"}},{q="O que Quel'dora diz sobre a natureza?",a="Quel'dora pede que você respeite o equilíbrio e viva em admiração pela natureza ao seu redor.",al={"respeitar a natureza","equilíbrio","conselho de quel'dora"}}},fp="18,119,20.166.0,17.191.0,27.84.0,27.35.0,26.116.0,25.84.0,34.66.0,37.84.0"}
P.entries["quest:941"] = {n="Plantando coração",s="Plantando coração é uma tarefa realizada para o herborista Denalan às margens do Lago Al'Ameth em Teldrassil. Após retirar o musgo sufocante de um estranho coração de madeira retirado de um timberling corrompido, Denalan testa se seu solo especialmente enriquecido pode purificar e curar a mácula persistente em seu interior.",h="Plantando coração é uma tarefa realizada para o herborista Denalan às margens do Lago Al'Ameth em Teldrassil.",kw={"blackmoss the fetid","coração purificado","denalan","lago al'ameth","jardineira","coração maculado","teldrassil","timberling"},ang={["class:Druid"]="Para um druida, testemunhar o núcleo de um timberling corrompido ser purificado por meio da terra rica oferece um sinal reconfortante de que a mácula não natural que aflige os galhos da Árvore do Mundo ainda pode ser revertida por meio do cuidado natural.",["profession:Herbalism"]="O domínio de Denalan sobre o solo rico em nutrientes e o rejuvenescimento botânico destaca o elo vital entre o estudo da terra e a recuperação da vida vegetal danificada.",["race:NightElf"]="Restaurar madeira viva e extrair vida de espíritos da floresta caídos reflete o compromisso dos kaldorei em cuidar da natureza, mesmo diante dos males perturbadores de Teldrassil."},sec={{t="Uma Segunda Chance de Viver",b="Ao examinar o estranho órgão de madeira recuperado do timberling corrompido conhecido como Blackmoss the Fetid, Denalan consegue raspar o musgo imundo que sufocava sua superfície. No entanto, apesar de seus esforços, uma mácula mais profunda e não natural ainda pulsa dentro da madeira. Em vez de queimar ou descartar o objeto, Denalan recorre ao seu ofício de toda a vida: a botânica e o cultivo do solo. Ele instrui os viajantes a enterrarem o coração diretamente em sua jardineira pessoal, confiando nos ricos nutrientes que misturou para estimular a vitalidade natural remanescente de volta à saúde."},{t="O Milagre da Terra Enriquecida",b="Colocar o coração de madeira enegrecido na jardineira de Denalan gera uma reação inesperada. No momento em que toca o solo fértil, o coração se enterra na terra como se guiado por um instinto primordial. Momentos depois, ele ressurge na superfície, purificado de sua corrupção imunda e pulsando com um calor suave e amigável. Ao purificar a semente de uma criatura caída e corrompida, Denalan demonstra que, mesmo quando os habitantes selvagens de Teldrassil são vítimas de pragas não naturais, o cuidado atento e a terra sagrada ainda podem restaurar a harmonia."}},faq={{q="De onde vem este coração corrompido?",a="O coração originalmente veio de Blackmoss the Fetid, um timberling corrompido à espreita pelas margens do Lago Al'Ameth. Ele foi recuperado sufocado por um musgo emaranhado e imundo antes de Denalan raspá-lo até ficar limpo.",al={"origem do coração","de onde veio o coração","coração de blackmoss"}},{q="Quem é Denalan?",a="Denalan é um botânico e herborista Elfo Noturno que cuida de um acampamento isolado na margem leste do Lago Al'Ameth. Ele passa seus dias estudando a flora de Teldrassil, investigando a estranha corrupção que se espalha pelos galhos e misturando solos enriquecidos.",al={"quem é denalan","história de denalan"}},{q="Por que colocar o coração em uma jardineira em vez de destruí-lo?",a="Denalan acredita em compreender e curar a natureza em vez de apenas destruir seres corrompidos. Ele espera que o solo nutritivo que preparou possa expurgar a mácula e restaurar a vitalidade pura e original do coração.",al={"por que plantar o coração","por que curar o coração"}},{q="O que acontece quando você enterra o coração?",a="O coração se enterra imediatamente no solo ao fazer contato. Segundos depois, ele se remexe de volta à superfície completamente purificado de sua mácula imunda, pulsando suavemente como um companheiro animado.",al={"o que acontece na jardineira","coração se enterra"}},{q="Isso cura a corrupção dos timberlings?",a="Isso cura apenas este único coração resgatado. Embora prove que espíritos botânicos individuais podem ser purificados com cuidado e solo rico, a corrupção abrangente que se espalha por Teldrassil continua sendo um perigo ativo.",al={"timberlings são curados","curar timberlings"}},{q="Por que o solo na jardineira de Denalan é especial?",a="Denalan dedicou um tempo considerável experimentando compostos e misturas de solos nutritivos ao redor do Lago Al'Ameth, criando uma terra potente o suficiente para revitalizar a flora doente e expurgar a decadência rastejante.",al={"solo de denalan","terra da jardineira"}}},fp="18,188,23.366.0,29.383.1,40.167.0,15.228.0,56.176.0,37.167.1,49.183.0,45.184.0"}
P.entries["quest:942"] = {n="O prospector distraído",s="Esta missão conecta o mistério de uma escavação de Costa Negra através do Grande Oceano até o Pantanal. O Arqueólogo-chefe Suiçagris confia a você um estranho fóssil de Kalimdor, enviando você ao Arqueólogo Pançacheia no Porto de Menethil para desvendar seus segredos.",h="Esta missão conecta o mistério de uma escavação de Costa Negra através do Grande Oceano até o Pantanal.",kw={"o prospector distraído","arqueólogo pançacheia","arqueólogo-chefe suiçagris","costa negra","taberna aguafunda","liga dos exploradores","porto de menethil","fóssil misterioso"},ang={["faction:Alliance"]="Esta tarefa exige utilizar as rotas de navegação da Aliança, fazendo viagens marítimas a partir de Kalimdor até o Porto de Menethil para manter as filiais da Liga conectadas.",["race:Dwarf"]="Para aventureiros anões, essa incumbência demonstra o alcance da Liga dos Exploradores, conectando o trabalho de campo na remota Kalimdor aos colegas acadêmicos sediados em Khaz Modan."},sec={{t="Uma Descoberta Curiosa",b="Ao examinar o estranho fóssil desenterrado em Costa Negra, o Arqueólogo-chefe Suiçagris nota uma impressionante semelhança com uma relíquia exibida em uma conferência da Liga dos Exploradores em Altaforja. Aquela peça anterior havia sido apresentada pelo Arqueólogo Pançacheia, que estava convencido de que tais fósseis guardavam poderes latentes à espera de serem revelados. Suiçagris acredita que Pançacheia é o único anão capaz de discernir o que torna este achado de Kalimdor tão extraordinário."},{t="Uma Viagem Através do Mar",b="Carregar a Relíquia Misteriosa significa empreender uma longa jornada para fora de Kalimdor rumo aos Reinos do Leste. Pançacheia foi visto pela última vez esperando por uma escolta armada para o Whelgar Excavation Site enquanto se hospedava na Taberna Aguafunda, no Porto de Menethil. Entregar o fóssil em suas mãos marca a reviravolta em que um levantamento local em Costa Negra se conecta a uma investigação arqueológica que abrange todo o continente."}},faq={{q="Por que Suiçagris me manda até o Porto de Menethil?",a="O Arqueólogo-chefe Suiçagris se lembra de que o Arqueólogo Pançacheia exibiu uma relíquia idêntica em uma conferência anual da Liga dos Exploradores em Altaforja. Acreditando que Pançacheia possui o conhecimento necessário para desbloquear seu poder oculto, Suiçagris envia você para encontrá-lo em sua última localização conhecida no Porto de Menethil.",al={"por que ir a menethil","recado de fóssil de suiçagris","por que pantanal"}},{q="Quem é o Arqueólogo Pançacheia?",a="O Arqueólogo Pançacheia é um pesquisador da Liga dos Exploradores destacado no Pantanal. Aguardando o fim dos atrasos na Taberna Aguafunda, no Porto de Menethil, ele está se preparando para uma expedição ao perigoso Whelgar Excavation Site.",al={"quem é pançacheia","história do arqueólogo pançacheia"}},{q="O que é o fóssil misterioso?",a="É um espécime antigo e curioso recuperado em Costa Negra. Pançacheia afirmou anteriormente que um espécime idêntico estudado por ele possuía um poder mágico ou histórico latente aguardando para ser desbloqueado.",al={"o que é o fóssil","origem do fóssil misterioso","fóssil do trilheiro"}},{q="O que Pançacheia diz quando você entrega o fóssil?",a="Pançacheia fica surpreso ao descobrir que uma relíquia idêntica à sua própria amostra de pesquisa se originou no distante continente de Kalimdor, confirmando que a história antiga une as duas massas terrestres.",al={"reação de pançacheia","entregando o fóssil"}},{q="Para onde Pançacheia quer ir a seguir?",a="Pançacheia tem esperado no Porto de Menethil por uma escolta para viajar terra adentro em direção ao Whelgar Excavation Site, um importante local de escavação situado no Pantanal.",al={"para onde pançacheia está indo","escavação de pançacheia"}},{q="Como essa missão se encaixa na história de O prospector distraído?",a="Ela atua como a etapa de trânsito da cadeia de missões. Depois de escoltar e resgatar o Prospector Trilheiro em Costa Negra e analisar sua relíquia escavada com Suiçagris, a investigação se desloca do norte de Kalimdor diretamente para os especialistas da Liga nos Reinos do Leste.",al={"o prospector distraído parte 4","contexto da cadeia de missões"}}},fx={["5b36a0d8"]={q="Por que o Arqueólogo-chefe Suiçagris quer que isso seja feito?",a="O Arqueólogo-chefe Suiçagris reconhece que o Fóssil Misterioso que Trilheiro descobriu tem uma semelhança impressionante com uma relíquia peculiar apresentada em uma conferência da Liga dos Exploradores em Altaforja. Seu descobridor, o Arqueólogo Pançacheia, acreditava que a relíquia possuía um poder latente esperando para ser desbloqueado. Suiçagris espera que Pançacheia possa estudar este novo espécime e desbloquear segredos antigos do passado.",al={"por que enviar fóssil","motivo de suiçagris","por que suiçagris quer o fóssil examinado"}}},fp="28,201,19.374.0,23.327.0,60.282.0,31.217.0,30.195.0,52.171.0,37.121.0,68.212.0"}
P.entries["quest:94212"] = {n="Craftsman's Writ: Elixir of Wisdom",s="Um Craftsman's Writ transferível solicita um Elixir of Wisdom e informa os detalhes de entrega e pagamento. O documento é necessário para concluir a troca.",h="Um Craftsman's Writ transferível solicita um Elixir of Wisdom e informa os detalhes de entrega e pagamento.",kw={"documento do artesão","entrega","elixir of wisdom","pagamento","transferível","documento"},sec={{t="Uma solicitação por escrito",b="Um bilhete desbotado chamado Craftsman's Writ: Elixir of Wisdom pede que você leve um Elixir of Wisdom. Ele informa o local de entrega e os detalhes do pagamento, e pode passar de mão em mão. Você precisa estar com o documento ao concluir a troca."}},faq={{q="O que o documento solicita?",a="Ele solicita um Elixir of Wisdom.",al={"documento de elixir","qual item é solicitado"}},{q="Posso passar o documento para outra pessoa?",a="Sim. O bilhete diz que o documento é transferível.",al={"o documento é transferível","outra pessoa pode carregá-lo"}},{q="Do que preciso para concluir a troca?",a="Você precisa ter o item solicitado e o documento em sua posse. O bilhete informa o local de entrega e os detalhes do pagamento.",al={"do que preciso para a entrega","como concluir o documento"}}},fp="34,149,17.246.0,27.33.0,36.44.0,40.118.0"}
P.entries["quest:94214"] = {n="Craftsman's Writ: Shadow Protection Potion",s="Uma requisição transferível solicita uma Shadow Protection Potion e traz detalhes sobre a entrega e o pagamento. A transação depende de você levar a requisição consigo.",h="Uma requisição transferível solicita uma Shadow Protection Potion e traz detalhes sobre a entrega e o...",kw={"craftsman's writ","entrega","pagamento","poção","shadow protection potion","transferível","requisição"},sec={{t="Um pedido por escrito",b="Uma nota desbotada pede que você forneça uma Shadow Protection Potion. Ela também informa o local de entrega e os detalhes do pagamento, e diz que a requisição pode passar de mão em mão. Você precisa estar com a requisição para concluir a troca."}},faq={{q="O que a requisição solicita?",a="A requisição solicita uma Shadow Protection Potion.",al={"o que querem","pedido de poção","item da requisição"}},{q="Onde faço a entrega?",a="O local de entrega está marcado no seu mapa.",al={"local de entrega","onde levar a poção","local marcado"}},{q="A requisição diz como vou receber o pagamento?",a="A requisição inclui informações sobre o pagamento.",al={"detalhes do pagamento","quanto pagam","pagamento da requisição"}},{q="Posso dar a requisição a outra pessoa?",a="Sim. A nota diz que a requisição é transferível.",al={"é transferível","repassar a requisição","transferir requisição"}},{q="Preciso manter a requisição comigo?",a="Sim. Você precisa estar com a requisição para concluir a transação.",al={"precisa da requisição para entregar","preciso levar comigo","requisição necessária"}}},fp="42,156,17.215.0,27.47.0,22.44.0,37.44.0,36.44.0,35.65.0"}
P.entries["quest:94215"] = {n="Craftsman's Writ: Free Action Potion",s="Um documento transferível pede que você entregue uma Free Action Potion em um local indicado. Lá, aguardam uma criatura presa e moedas espalhadas.",h="Um documento transferível pede que você entregue uma Free Action Potion em um local indicado.",kw={"casulo","moedas","craftsman's writ","entrega","free action potion","poção","seda de aranha","documento"},sec={{t="O Documento",b="Um bilhete desbotado solicita uma Free Action Potion e informa o local da entrega e o pagamento. O documento pode passar de mão em mão, mas você precisa estar com ele para concluir a troca."},{t="No Local Indicado",b="No local indicado, você encontra uma criatura se debatendo dentro de um casulo de seda de aranha. Ela não parece conseguir tomar a poção, e há um punhado de moedas ao lado dela."}},faq={{q="O que o documento pede?",a="O documento solicita uma Free Action Potion e informa o local da entrega e o pagamento.",al={"documento da free action potion","qual poção estão pedindo"}},{q="Posso passar o documento para outra pessoa?",a="Sim. O bilhete diz que o documento pode ser transferido.",al={"o documento é transferível","posso passar o documento adiante"}},{q="O que encontro no local indicado?",a="Há uma criatura presa em seda de aranha no local indicado, com moedas espalhadas ao lado.",al={"o que há no local de entrega","para onde o documento leva"}},{q="Por que preciso estar com o documento?",a="Você precisa estar com o documento para concluir a transação.",al={"precisa do documento para entregar","posso concluir sem o documento"}}},fp="36,134,8.170.0,19.159.0,27.85.0,36.47.0,38.92.0,31.64.0"}
P.entries["quest:94216"] = {n="Craftsman's Writ: Elixir of Lesser Agility",s="Uma ordem transferível pede que você obtenha um Elixir of Lesser Agility para um cliente. Ela informa o local de entrega e os detalhes do pagamento.",h="Uma ordem transferível pede que você obtenha um Elixir of Lesser Agility para um cliente.",kw={"agilidade","craftsman's writ","entrega","elixir","elixir of lesser agility","pagamento","transferível"},sec={{t="Pedido de um cliente",b="Um cliente procura um Elixir of Lesser Agility por meio desta ordem escrita com tinta desbotada. Você deve conseguir o item solicitado e levá-lo ao local indicado; é preciso estar com a ordem para concluir a transação."}},faq={{q="O que a ordem pede?",a="O cliente solicita um Elixir of Lesser Agility.",al={"qual item","pedido de elixir","o que querem"}},{q="Onde devo entregar?",a="A ordem indica no seu mapa um local de entrega.",al={"local de entrega","onde levar","local indicado"}},{q="A ordem diz como funciona o pagamento?",a="A ordem inclui informações sobre o pagamento.",al={"detalhes do pagamento","quanto pagam","qual é o pagamento"}},{q="Outra pessoa pode levar a ordem?",a="Sim. O texto na parte inferior diz que a ordem é transferível.",al={"é transferível","passar adiante","trocar a ordem"}},{q="Preciso da ordem para concluir a entrega?",a="Sim. Você precisa estar com a ordem para concluir a transação.",al={"preciso da ordem","guardar o papel","ordem necessária"}}},fp="42,132,20.209.0,27.51.0,22.58.0,36.44.0,32.54.0,44.68.0"}
P.entries["quest:94218"] = {n="Craftsman's Writ: Elixir of Defense",s="Uma ordem transferível solicita um Elixir of Defense e informa o local de entrega e os detalhes do pagamento. Você precisa da ordem para concluir a troca.",h="Uma ordem transferível solicita um Elixir of Defense e informa o local de entrega e os detalhes do pagamento.",kw={"craftsman's writ","entrega","elixir","elixir of defense","pagamento","transferível","ordem"},sec={{t="A solicitação por escrito",b="A nota foi escrita com tinta desbotada, e a ordem pode passar de mão em mão. Ela solicita um Elixir of Defense e informa os detalhes da entrega e do pagamento. Para concluir a troca, você precisa estar com a ordem e levar o item solicitado ao local indicado."}},faq={{q="O que a ordem solicita?",a="A ordem solicita um Elixir of Defense.",al={"qual item","ordem do elixir","elixir de defesa"}},{q="Onde devo entregar o elixir?",a="O local indicado na ordem informa o destino da entrega.",al={"local de entrega","onde entregar","local da ordem"}},{q="Preciso da ordem para concluir a troca?",a="Sim. Você precisa estar com a ordem para concluir a troca.",al={"preciso da ordem","ordem necessária","posso entregar sem ela"}},{q="A ordem pode ser transferida?",a="Sim. A nota diz que a ordem é transferível.",al={"ordem transferível","posso passar adiante","entregar a ordem"}},{q="A ordem informa como funciona o pagamento?",a="A ordem inclui informações sobre o pagamento.",al={"detalhes do pagamento","valor do pagamento","pagamento da ordem"}}},fp="35,145,19.272.0,27.40.0,30.58.0,44.72.0,28.44.0,36.44.0"}
P.entries["quest:94219"] = {n="Craftsman's Writ: Draught of Water Breathing",s="Uma requisição transferível solicita um Draught of Water Breathing e traz detalhes da entrega e do pagamento. Você precisa da requisição para concluir a troca.",h="Uma requisição transferível solicita um Draught of Water Breathing e traz detalhes da entrega e do pagamento.",kw={"craftsman's writ","entrega","draught of water breathing","pagamento","respiração aquática","requisição"},sec={{t="Um pedido por escrito",b="O bilhete desbotado pede a você um Draught of Water Breathing. Ele também informa o local de entrega e o pagamento, e pode passar de um portador a outro."}},faq={{q="O que a requisição solicita?",a="Ela solicita um Draught of Water Breathing.",al={"o que querem","pedido de draught","item da requisição"}},{q="Onde devo entregá-lo?",a="A requisição informa um local de entrega, marcado no seu mapa.",al={"local de entrega","onde levar","local da requisição"}},{q="Qual é o pagamento oferecido?",a="A requisição inclui informações sobre o pagamento.",al={"quanto pagam","pagamento da requisição","o que recebo"}},{q="A requisição pode ser transferida?",a="Sim. O bilhete diz que a requisição pode ser transferida.",al={"requisição transferível","outra pessoa pode levar","passar a requisição"}},{q="Preciso da requisição para concluir a troca?",a="Sim. Você precisa ter a requisição em mãos para concluir a transação.",al={"precisa do bilhete","requisição obrigatória","posso entregar sem ela"}}},fp="44,143,17.146.0,27.43.0,22.55.0,24.44.0,28.47.0,44.65.0"}
P.entries["quest:94220"] = {n="Craftsman's Writ: Pearl-Handled Dagger",s="Uma requisição transferível solicita uma Pearl-Handled Dagger e informa as condições de entrega e pagamento. Você precisa da requisição para concluir a troca.",h="Uma requisição transferível solicita uma Pearl-Handled Dagger e informa as condições de entrega e pagamento.",kw={"requisição de artesão","adaga","entrega","pagamento","pearl-handled dagger","requisição"},sec={{t="A requisição",b="O bilhete está escrito com tinta desbotada e menciona uma Pearl-Handled Dagger entre os itens solicitados. As linhas inferiores informam o local de entrega e as condições de pagamento. A requisição pode passar de mão em mão, mas você precisa estar com ela ao concluir a troca."}},faq={{q="O que a requisição pede?",a="A requisição solicita uma Pearl-Handled Dagger.",al={"requisição de adaga de pérola","qual item é solicitado"}},{q="Onde entrego o item?",a="O local de entrega está marcado no seu mapa.",al={"local de entrega","onde levar"}},{q="O que o cliente oferece?",a="A requisição inclui informações sobre o pagamento.",al={"condições de pagamento","valor do pagamento"}},{q="Posso transferir esta requisição?",a="Sim. A requisição diz que pode ser transferida.",al={"repassar requisição","o bilhete é transferível"}},{q="Preciso guardar a requisição?",a="Sim. Você precisa estar com a requisição em sua posse para concluir a transação.",al={"precisa da requisição para concluir","precisa estar com o bilhete"}}},fp="38,141,8.243.0,27.41.0,28.44.0,29.44.0,25.41.0,27.70.0"}
P.entries["quest:94222"] = {n="Craftsman's Writ: Iridescent Hammer",s="Uma ordem desbotada solicita um Martelo Iridescente e fornece detalhes sobre entrega e pagamento. Sua marca transferível permite que o portador conclua a troca.",h="Uma ordem desbotada solicita um Martelo Iridescente e fornece detalhes sobre entrega e pagamento.",kw={"ordem do artesão","entrega","martelo","martelo iridescente","pagamento","transferível","ordem"},sec={{t="A ordem",b="O cliente solicita um Martelo Iridescente. Você precisa estar com a ordem para concluir a transação no local indicado."}},faq={{q="O que o cliente quer?",a="O cliente solicita um Martelo Iridescente.",al={"ordem de martelo iridescente","qual item foi solicitado"}},{q="Onde devo entregá-lo?",a="A ordem informa os detalhes da entrega, e o local está marcado no seu mapa.",al={"local de entrega da ordem","onde levar o martelo"}},{q="Preciso estar com a ordem?",a="Sim. Você precisa estar com a ordem em sua posse para concluir a transação.",al={"precisa da ordem para entregar","ordem necessária"}},{q="Outra pessoa pode usar a ordem?",a="Sim. A ordem está marcada como transferível.",al={"ordem transferível","passar a ordem adiante"}},{q="A ordem informa como funciona o pagamento?",a="A ordem inclui informações sobre o pagamento.",al={"pagamento do martelo","valor do pagamento"}}},fp="35,147,8.123.0,28.44.0,22.72.0,33.75.0,30.40.0,36.44.0"}
P.entries["quest:94223"] = {n="Craftsman's Writ: Silver Skeleton Key",s="Uma ordem transferível pede uma Chave-mestra de prata e indica onde entregá-la. A cripta guarda um bilhete do zelador e um baú ligado à chave.",h="Uma ordem transferível pede uma Chave-mestra de prata e indica onde entregá-la.",kw={"zelador","craftsman's writ","cripta","cemitério de monte corvo","chave-mestra de prata","baú","morto-vivo"},sec={{t="A Ordem",b="A tinta desbotada menciona uma Chave-mestra de prata, indica onde entregá-la e informa o pagamento. A ordem pode passar de mão em mão, mas você precisa carregá-la para concluir a troca."},{t="Na Cripta",b="Um bilhete sobre um baú informa que o zelador do Cemitério de Monte Corvo morreu. Ele diz que os empregadores de Vila Sombria quase se esqueceram dele e que deixou sua fortuna no baú para quem conseguir abri-lo. Com mortos-vivos se reunindo por perto e sem mais ninguém à vista, você usa a chave. O baú contém pouca coisa, mas o suficiente para cobrir parte do custo."}},faq={{q="O que a ordem pede?",a="A ordem pede uma Chave-mestra de prata e informa onde entregá-la e qual será o pagamento.",al={"ordem da chave de prata","que chave querem"}},{q="Outra pessoa pode carregar a ordem?",a="Sim. A ordem diz que pode ser transferida, mas você precisa carregá-la para concluir a troca.",al={"ordem transferível","posso passar adiante"}},{q="Para onde a ordem me envia?",a="A ordem indica o local marcado no seu mapa.",al={"local de entrega","onde levar a chave"}},{q="Quem deixou o bilhete na cripta?",a="O bilhete foi deixado por um zelador do Cemitério de Monte Corvo, que diz ter morrido.",al={"bilhete do zelador","quem morreu"}},{q="O que havia no baú?",a="O baú está quase vazio, mas contém o suficiente para cobrir parte do custo.",al={"baú vazio","tesouro do zelador"}}},fp="37,165,8.165.0,12.334.1,27.81.0,32.97.0,28.56.0,31.77.0,22.72.0"}
P.entries["quest:94224"] = {n="Craftsman's Writ: Heavy Bronze Mace",s="Uma ordem desbotada solicita uma Heavy Bronze Mace e informa as condições de entrega e pagamento. Você precisa da ordem para concluir a troca.",h="Uma ordem desbotada solicita uma Heavy Bronze Mace e informa as condições de entrega e pagamento.",kw={"ordem do artesão","entrega","heavy bronze mace","maça","pagamento","ordem transferível"},sec={{t="Um pedido por escrito",b="O bilhete está escrito com tinta desbotada, e o cliente pede uma Heavy Bronze Mace. Você deve levar o item solicitado ao local marcado no mapa. Fique com a ordem, pois ela é necessária para concluir a troca."}},faq={{q="O que a ordem solicita?",a="O cliente solicita uma Heavy Bronze Mace.",al={"ordem heavy bronze mace","qual item é solicitado"}},{q="Onde devo entregar a maça?",a="O local de entrega está marcado no mapa.",al={"local de entrega da maça","onde levar o item"}},{q="Preciso ficar com a ordem?",a="Sim. Você precisa estar com a ordem para concluir a transação.",al={"precisa da ordem","ordem necessária"}},{q="O que o bilhete diz sobre o pagamento?",a="O bilhete inclui informações sobre o pagamento, mas o texto fornecido não informa o valor.",al={"pagamento da maça","qual é o valor do pagamento"}},{q="Outra pessoa pode usar a ordem?",a="O texto no rodapé diz que a ordem é transferível.",al={"ordem transferível","passar a ordem para alguém"}}},fp="35,133,17.218.0,27.44.0,28.44.0,27.69.0,37.92.0,30.56.0"}
P.entries["quest:94226"] = {n="Craftsman's Writ: Green Iron Gauntlets",s="A requisição de MacKinley pede que você leve Green Iron Gauntlets a ele. O documento transferível inclui detalhes de entrega e pagamento.",h="A requisição de MacKinley pede que você leve Green Iron Gauntlets a ele.",kw={"craftsman's writ","entrega","green iron gauntlets","soqueiras de ferro verde","mackinley","pagamento","transferível"},sec={{t="Uma ordem por escrito",b="A requisição desbotada menciona Green Iron Gauntlets e informa o local de entrega e o pagamento. Você precisa estar com a requisição para concluir a troca. MacKinley aguarda as mercadorias, embora sua saudação sugira que algo está errado."},{t="Na hora da troca",b="MacKinley diz que queria soqueiras de ferro verde, não manoplas. Ele aceita as manoplas enquanto espera por uma substituição, mas paga menos do que você esperava."}},faq={{q="O que MacKinley pede?",a="A requisição pede um par de Green Iron Gauntlets, embora MacKinley diga que pretendia pedir soqueiras de ferro verde.",al={"o que mckinley quer","requisição de ferro verde"}},{q="Onde entrego as manoplas?",a="A requisição informa um local de entrega, marcado no seu mapa.",al={"onde entregar","local da requisição"}},{q="Preciso estar com a requisição?",a="Sim. Você precisa ter a requisição em sua posse para concluir a troca.",al={"precisa da requisição","esqueci a requisição"}},{q="O que a requisição diz sobre o pagamento?",a="O documento inclui informações sobre o pagamento, mas não especifica nenhum valor no texto.",al={"quanto paga","detalhes do pagamento"}},{q="Outra pessoa pode levar a requisição?",a="Sim. O documento diz que a requisição é transferível.",al={"requisição transferível","posso dar a requisição"}}},fp="38,123,15.216.0,15.157.1,28.114.0,33.55.0,27.66.0,37.77.0,32.44.0"}
P.entries["quest:94228"] = {n="Craftsman's Writ: Green Iron Boots",s="Uma ordem transferível de artesão pede um par de green iron boots. Os detalhes da entrega e o pagamento aguardam quem levar o calçado ao local indicado.",h="Uma ordem transferível de artesão pede um par de green iron boots.",kw={"ferraria","ordem de artesão","pedido do cliente","entrega","green iron boots","ordem"},ang={["profession:Blacksmithing"]="Forjar um par de botas resistentes de green iron atende ao cliente e cumpre a ordem no pergaminho."},sec={{t="Uma ordem em pergaminho",b="Um cliente precisa de calçados resistentes e registrou o pedido em pergaminho, com tinta desbotada. Você deve levar as botas prontas ao destino indicado para acertar a conta. Tenha o comprovante de troca em mãos, pois o pagamento depende da apresentação do documento na chegada."}},faq={{q="O que a ordem solicita?",a="A ordem solicita um par de green iron boots para atender ao pedido do cliente.",al={"o que é necessário","pedido de botas","qual item"}},{q="Onde as botas devem ser entregues?",a="O pergaminho orienta você a entregar o calçado pronto no destino marcado no seu mapa.",al={"para onde vão as botas","local de entrega","lugar de entrega"}},{q="Outra pessoa pode cumprir esta ordem?",a="Uma linha no fim do pergaminho informa que o documento pode ser transferido para outra pessoa.",al={"posso passar a ordem adiante","a ordem é transferível","ordem de troca"}},{q="Por que manter a ordem em mãos?",a="Você deve manter a própria ordem em mãos para concluir a transação e receber o pagamento.",al={"preciso da ordem para concluir","levar a ordem","carregar a ordem"}}},fp="34,156,21.263.0,27.82.0,34.98.0,35.94.0,26.86.0"}
P.entries["quest:94229"] = {n="Craftsman's Writ: Ornate Spyglass",s="Uma ordem transferível solicita um Ornate Spyglass e informa os detalhes de entrega e pagamento. O cliente que aguarda diz que um engenheiro ainda não entregou o pedido.",h="Uma ordem transferível solicita um Ornate Spyglass e informa os detalhes de entrega e pagamento.",kw={"ordem do artesão","entrega","engenheiro","ornate spyglass","pagamento","telescópio","ordem"},ang={["profession:Engineering"]="Como engenheiro, você está ligado ao pedido: o cliente que aguarda diz que um engenheiro ainda não entregou o telescópio."},sec={{t="Um cliente à espera",b="Um cliente aguarda que um engenheiro entregue um Ornate Spyglass. A ordem desbotada identifica o item solicitado e informa onde entregá-lo e como será o pagamento. Você precisa estar com a ordem para concluir a troca."}},faq={{q="O que a ordem solicita?",a="A ordem solicita um Ornate Spyglass.",al={"ordem ornate spyglass","qual item é desejado"}},{q="Onde entrego o telescópio?",a="A ordem informa o local de entrega, marcado no seu mapa.",al={"local de entrega do ornate spyglass","onde levar o item"}},{q="A ordem informa como será o pagamento?",a="A ordem contém informações sobre o pagamento, mas o texto aqui não informa nenhum valor.",al={"pagamento do ornate spyglass","quanto vão pagar"}},{q="Por que preciso guardar a ordem?",a="Você precisa estar com a ordem para concluir a transação.",al={"precisa da ordem?","esqueci a ordem"}},{q="Quem está aguardando o pedido?",a="Um cliente aguarda que um engenheiro entregue o Ornate Spyglass.",al={"quem quer o ornate spyglass","cliente à espera"}}},fp="33,163,18.217.0,27.38.0,32.55.0,36.79.0,31.60.0,29.69.0"}
P.entries["quest:94231"] = {n="Craftsman's Writ: Moonsight Rifle",s="Uma ordem transferível solicita um Moonsight Rifle e indica o local de entrega e o pagamento. O comprador quer manter a troca em segredo.",h="Uma ordem transferível solicita um Moonsight Rifle e indica o local de entrega e o pagamento.",kw={"disfarce","ordem do artesão","fogo cruzado","entrega","moonsight rifle","pagamento","rifle","sátiro"},sec={{t="Uma Troca Discreta",b="Um bilhete desbotado pede que você leve um Moonsight Rifle ao local marcado, onde o pagamento será feito. A ordem pode passar de mão em mão, mas você precisa estar com ela para concluir a troca. O comprador avisa que sua aproximação está chamando atenção e pode comprometer seu disfarce."},{t="O Rifle",b="Assim que o Moonsight Rifle é apresentado, o comprador elogia seu poder contra sátiros. Ele manda você se afastar antes que o fogo cruzado comece."}},faq={{q="O que a ordem solicita?",a="A ordem solicita um Moonsight Rifle, que deve ser entregue no local marcado no seu mapa.",al={"ordem de moonsight rifle","qual rifle querem"}},{q="Posso passar a ordem para outra pessoa?",a="Sim. O bilhete diz que a ordem pode ser transferida, mas você precisa estar com ela para concluir a troca.",al={"a ordem é transferível","passar a ordem adiante"}},{q="Por que o comprador quer discrição?",a="O comprador diz que sua aproximação está chamando atenção e ameaça expor seu disfarce.",al={"por que tanto segredo","comprometer o disfarce"}},{q="Contra quem o rifle deve ser usado?",a="O comprador diz que o rifle pode arrancar a cabeça de um sátiro num tiro só.",al={"rifle contra sátiros","alvo do moonsight rifle"}}},fp="33,127,16.270.0,9.139.1,27.87.0,36.107.0,33.86.0,42.62.0"}
P.entries["quest:94232"] = {n="Craftsman's Writ: Minor Recombobulator",s="Um documento desbotado solicita um Minor Recombobulator e informa detalhes de entrega e pagamento. Ele pode ser transferido para outra pessoa.",h="Um documento desbotado solicita um Minor Recombobulator e informa detalhes de entrega e pagamento.",kw={"documento do artesão","entrega","minor recombobulator","pagamento","transferível","documento"},sec={{t="Uma solicitação por escrito",b="A nota desbotada de um cliente pede que você forneça um Minor Recombobulator. Ela também informa o local de entrega e os detalhes do pagamento, e diz que o documento pode ser transferido. Você precisa estar com o documento em mãos para concluir a troca."}},faq={{q="O que o documento solicita?",a="O documento solicita um Minor Recombobulator.",al={"qual item é solicitado","documento de recombobulador","item do documento do artesão"}},{q="Posso passar este documento para outra pessoa?",a="Sim. A nota diz que o documento é transferível.",al={"o documento é transferível","passar o documento adiante","documento transferível"}},{q="Do que preciso para concluir a troca?",a="Você precisa do Minor Recombobulator solicitado e do documento em sua posse. A nota informa o local de entrega e os detalhes do pagamento.",al={"do que preciso para a entrega","como concluir a transação","requisitos do documento"}}},fp="38,129,17.216.0,27.43.0,37.44.0,40.134.0"}
P.entries["quest:94233"] = {n="Craftsman's Writ: Practice Lock",s="Uma ordem transferível pede que você forneça um Practice Lock. O local de entrega e as condições de pagamento estão indicados no bilhete.",h="Uma ordem transferível pede que você forneça um Practice Lock.",kw={"craftsman's writ","entrega","lock","pagamento","practice lock","transferível","ordem"},sec={{t="Uma solicitação por escrito",b="Um cliente solicita um Practice Lock por meio de uma ordem desbotada e transferível. Você deve entregar o item solicitado no local indicado no mapa e estar com a ordem para concluir a transação."}},faq={{q="O que a ordem solicita?",a="A ordem solicita um Practice Lock.",al={"pedido de practice lock","qual item","ordem de lock"}},{q="Onde devo entregar o Practice Lock?",a="O local de entrega está indicado no mapa.",al={"local de entrega","onde levar","onde entregar"}},{q="Preciso ficar com a ordem?",a="Sim. Você precisa estar com a ordem para concluir a transação.",al={"preciso da ordem","levar o bilhete","ordem necessária"}},{q="A ordem é transferível?",a="Sim. A ordem informa que é transferível.",al={"posso transferir","bilhete transferível","passar a ordem"}},{q="O bilhete menciona pagamento?",a="A ordem menciona pagamento, mas o texto fornecido não informa o valor.",al={"condições de pagamento","quanto paga","pagamento"}}},fp="31,122,17.215.0,27.36.0,37.44.0,27.69.0,25.38.0,30.68.0"}
P.entries["quest:94234"] = {n="Craftsman's Writ: Shadow Goggles",s="Uma ordem comercial em tinta desbotada pede um par de Shadow Goggles em um local indicado. Ao levar esse documento transferível, você pode concluir a troca e receber o pagamento do cliente.",h="Uma ordem comercial em tinta desbotada pede um par de Shadow Goggles em um local indicado.",kw={"requisição do artesão","engenharia","shadow goggles","ordem comercial","ordem de serviço","requisição"},ang={["profession:Engineering"]="É preciso ter habilidade em engenharia para fabricar Shadow Goggles, mas qualquer viajante que tenha a encomenda pode fazer a entrega se conseguir um par."},sec={{t="Uma encomenda de óculos",b="Um cliente encomendou um trabalho de engenharia e deixou instruções e condições de pagamento em uma caligrafia desbotada. Para receber o pagamento prometido, você precisa levar os óculos ao destino indicado com o documento em mãos. Como o documento é transferível, qualquer pessoa que o tenha pode entregar os produtos."}},faq={{q="O que esta requisição solicita?",a="O documento solicita um único par de Shadow Goggles, além de instruções de entrega e pagamento.",al={"o que a requisição solicita","encomenda de shadow goggles"}},{q="Outra pessoa pode atender a esta encomenda?",a="O texto na parte inferior informa que a encomenda é transferível, então quem estiver com a requisição pode concluir a troca.",al={"qualquer pessoa pode entregar","requisição transferível"}},{q="O que é necessário para concluir a transação?",a="Você precisa levar a requisição para entregar os óculos e receber o pagamento no destino indicado.",al={"como atender à requisição","requisitos da requisição"}}},fp="32,209,20.319.0,31.103.0,38.115.0,41.108.0"}
P.entries["quest:94236"] = {n="Craftsman's Writ: Big Bronze Bomb",s="Uma ordem transferível solicita uma Big Bronze Bomb e informa o local de entrega e o pagamento. Você precisa estar com a ordem para concluir a troca.",h="Uma ordem transferível solicita uma Big Bronze Bomb e informa o local de entrega e o pagamento.",kw={"big bronze bomb","bomba","craftsman's writ","entrega","pagamento","ordem transferível"},sec={{t="Um Pedido por Escrito",b="A nota desbotada pede que você traga uma Big Bronze Bomb. Também informa o local de entrega e o pagamento, e diz que a ordem pode passar de mão em mão. Fique com ela para fazer a troca."}},faq={{q="O que a ordem solicita?",a="A ordem solicita uma Big Bronze Bomb.",al={"qual item foi solicitado","ordem da big bronze bomb"}},{q="Onde entrego a bomba?",a="A ordem indica o local de entrega marcado no seu mapa.",al={"local de entrega","onde levar"}},{q="O que o cliente oferece?",a="A ordem contém informações sobre o pagamento.",al={"qual é o valor do pagamento","detalhes do pagamento"}},{q="Posso passar a ordem para outra pessoa?",a="Sim. A nota diz que a ordem é transferível.",al={"a ordem é transferível","passar a nota adiante"}},{q="Preciso da ordem para fazer a troca?",a="Sim. Você precisa estar com a ordem para concluir a transação.",al={"precisa da ordem para concluir","preciso levar a nota"}}},fp="33,141,17.181.0,27.38.0,28.60.0,29.44.0,36.44.0,36.70.0"}
P.entries["quest:94238"] = {n="Craftsman's Writ: Heavy Leather Ball",s="Um Craftsman's Writ transferível solicita uma Bola de Couro Pesado e identifica um cliente. O desejo de Sos'mol pela bola faz essa entrega ser importante para ele.",h="Um Craftsman's Writ transferível solicita uma Bola de Couro Pesado e identifica um cliente.",kw={"craftsman's writ","entrega","bola de couro pesado","ogro","pagamento","sos'mol","transferível"},sec={{t="Pedido de um cliente",b="O bilhete desbotado solicita uma Bola de Couro Pesado e informa detalhes sobre a entrega e o pagamento. Você leva o bilhete consigo para concluir a troca. Sos'mol cantarolava uma melodia desafinada sobre o tédio quando você chega. Ele continua cantarolando, mas mais baixo, e parece um pouco envergonhado."},{t="A alegria de Sos'mol",b="Sos'mol pergunta se você trouxe a bola. Quando a recebe, seus olhos se enchem de lágrimas, e ele diz que aquele é o dia mais feliz da vida de um ogro. A bola importa mais para ele do que qualquer outra coisa que quisesse, embora não consiga se lembrar do que era."}},faq={{q="O que o bilhete solicita?",a="O bilhete solicita uma Bola de Couro Pesado, além de informar detalhes sobre a entrega e o pagamento.",al={"bilhete de bola de couro pesado","qual item é solicitado"}},{q="Quem é o cliente?",a="Sos'mol é o cliente indicado para a entrega.",al={"quem quer a bola","bilhete de sos'mol"}},{q="Por que Sos'mol quer uma bola?",a="Sos'mol diz que sonhava com a bola.",al={"por que quer uma bola","sos'mol quer uma bola"}},{q="O que Sos'mol está fazendo quando chego?",a="Sos'mol estava cantarolando uma canção desafinada sobre o tédio e continua mais baixo quando você se aproxima.",al={"o que sos'mol está fazendo","sos'mol cantando"}},{q="Outra pessoa pode usar o bilhete?",a="Sim. O bilhete diz que o Craftsman's Writ é transferível.",al={"bilhete transferível","posso passar o bilhete adiante"}}},fp="36,151,20.284.0,17.252.1,27.88.0,20.46.0,29.60.0,36.99.0,30.44.0"}
P.entries["quest:94241"] = {n="Craftsman's Writ: Dark Leather Tunic",s="Uma ordem desbotada e transferível solicita uma Dark Leather Tunic e informa os detalhes de entrega e pagamento. Você precisa da ordem para concluir a troca.",h="Uma ordem desbotada e transferível solicita uma Dark Leather Tunic e informa os detalhes de entrega e...",kw={"craftsman's writ","cliente","dark leather tunic","entrega","pagamento","ordem transferível","túnica"},sec={{t="A ordem",b="Um bilhete desbotado de um cliente pede uma Dark Leather Tunic. Ele informa onde entregar a peça e como será feito o pagamento. A ordem pode passar de mão em mão, mas você precisa estar com ela para concluir a transação."}},faq={{q="O que a ordem solicita?",a="O cliente solicita uma Dark Leather Tunic.",al={"qual item querem","pedido de túnica escura","item da ordem"}},{q="Onde devo entregar a túnica?",a="A ordem informa o local de entrega, marcado no seu mapa.",al={"local de entrega","onde levar","local da ordem"}},{q="Preciso guardar a ordem?",a="Sim. Você precisa estar com a ordem para concluir a transação.",al={"precisa do bilhete","precisa estar com a ordem","ordem necessária"}},{q="Posso passar a ordem para outra pessoa?",a="Sim. O bilhete diz que a ordem é transferível.",al={"bilhete transferível","pode ser trocado","passar a ordem adiante"}},{q="A ordem informa o pagamento?",a="O bilhete inclui informações sobre o pagamento.",al={"valor do pagamento","detalhes do pagamento","qual é o pagamento"}}},fp="36,144,8.229.0,27.45.0,29.55.0,27.70.0,36.44.0,30.44.0"}
P.entries["quest:94242"] = {n="Craftsman's Writ: Pilferer's Gloves",s="Uma requisição transferível solicita Pilferer's Gloves e traz os detalhes de entrega e pagamento. Você precisa da requisição para concluir a transação.",h="Uma requisição transferível solicita Pilferer's Gloves e traz os detalhes de entrega e pagamento.",kw={"craftsman's writ","entrega","luvas","pagamento","pilferer's gloves","transferível","requisição"},sec={{t="Um Pedido por Escrito",b="Um bilhete desbotado solicita um par de Pilferer's Gloves. Ele informa onde entregá-las e como será feito o pagamento, e a requisição pode passar de mão em mão."},{t="A Transação",b="Você precisa estar com a requisição ao levar as luvas solicitadas ao local marcado. O bilhete vincula os detalhes de entrega e pagamento a esse pedido por escrito."}},faq={{q="O que a requisição solicita?",a="A requisição solicita um par de Pilferer's Gloves.",al={"requisição de pilferer's gloves","pedido de luvas","qual item"}},{q="Onde entrego as luvas?",a="O local de entrega está marcado no seu mapa.",al={"local de entrega","onde levar as luvas","local marcado"}},{q="Do que preciso para concluir a transação?",a="Você precisa ter a requisição em sua posse para concluir a transação.",al={"precisar da requisição","exigência da requisição","concluir transação"}},{q="A requisição informa como funciona o pagamento?",a="A requisição inclui informações sobre o pagamento.",al={"detalhes do pagamento","valor do pagamento","pagamento pelas luvas"}},{q="Outra pessoa pode levar a requisição?",a="Sim. A requisição é transferível.",al={"requisição transferível","passar o bilhete","é possível dar a outra pessoa"}}},fp="35,141,15.156.0,15.156.0,27.48.0,30.44.0,43.65.0,36.44.0,32.30.0"}
P.entries["quest:94243"] = {n="Craftsman's Writ: Heavy Quiver",s="Uma ordem desbotada solicita uma Aljava Pesada e informa os detalhes da entrega e do pagamento. Ela pode ser transferida, mas você precisa carregá-la para concluir a troca.",h="Uma ordem desbotada solicita uma Aljava Pesada e informa os detalhes da entrega e do pagamento.",kw={"ordem do artesão","entrega","aljava pesada","pagamento","aljava","transferível"},sec={{t="A ordem",b="O bilhete pede que você obtenha o item solicitado e o leve ao local marcado no seu mapa. Você precisa estar com a ordem para concluir a transação."}},faq={{q="O que a ordem solicita?",a="O cliente solicita uma Aljava Pesada.",al={"pedido de aljava pesada","qual item é solicitado"}},{q="Onde devo entregá-la?",a="O local da entrega está marcado no seu mapa.",al={"local de entrega","onde levar a aljava"}},{q="Preciso carregar a ordem?",a="Sim. Você precisa estar com a ordem para concluir a transação.",al={"precisa da ordem","ordem necessária"}},{q="Posso dar esta ordem a outra pessoa?",a="Sim. O bilhete diz que a ordem é transferível.",al={"transferir ordem","outra pessoa pode usar"}},{q="A ordem menciona pagamento?",a="O bilhete inclui informações sobre o pagamento, mas não informa nenhum valor no texto.",al={"qual o valor do pagamento","pagamento da aljava"}}},fp="30,121,8.140.0,27.39.0,22.41.0,28.54.0,37.49.0,30.56.0"}
P.entries["quest:94245"] = {n="Craftsman's Writ: Barbaric Gloves",s="Uma ordem transferível solicita Barbaric Gloves e informa o local de entrega e os detalhes do pagamento. Você precisa estar com a ordem para concluir a transação.",h="Uma ordem transferível solicita Barbaric Gloves e informa o local de entrega e os detalhes do pagamento.",kw={"barbaric gloves","craftsman's writ","entrega","luvas","pagamento","transferível","ordem"},sec={{t="Um pedido de cliente",b="Um cliente solicita um par de Barbaric Gloves por meio desta ordem desbotada. O bilhete informa o local de entrega e os detalhes do pagamento, e pode passar de mão em mão. Você precisa estar com a ordem ao entregar o item solicitado."}},faq={{q="O que a ordem solicita?",a="O cliente solicita um par de Barbaric Gloves.",al={"ordem de barbaric gloves","quais luvas","ordem do artesão"}},{q="Onde entrego as luvas?",a="O local de entrega está marcado no seu mapa.",al={"local de entrega","onde levar as luvas"}},{q="Preciso levar a ordem comigo?",a="Sim. Você precisa estar com a ordem para concluir a transação.",al={"preciso estar com a ordem","ordem necessária"}},{q="A ordem pode ser transferida?",a="Sim. O bilhete diz que a ordem pode ser transferida.",al={"transferir ordem","passar a ordem adiante"}},{q="O que a ordem diz sobre o pagamento?",a="A ordem inclui informações sobre o pagamento.",al={"detalhes do pagamento","valor do pagamento"}}},fp="33,151,20.237.0,27.50.0,30.44.0,28.70.0,28.44.0,37.44.0"}
P.entries["quest:94246"] = {n="Craftsman's Writ: Red Whelp Gloves",s="Uma requisição transferível solicita um par de Red Whelp Gloves. Ela indica um local de entrega e o pagamento pela troca.",h="Uma requisição transferível solicita um par de Red Whelp Gloves.",kw={"craftsman's writ","entrega","pagamento","red whelp gloves","transferível","requisição"},sec={{t="Um pedido por escrito",b="Um bilhete desbotado solicita um par de Red Whelp Gloves e informa o local de entrega e o pagamento. Você precisa estar com a requisição para concluir a troca."}},faq={{q="O que a requisição solicita?",a="A requisição solicita um par de Red Whelp Gloves.",al={"requisição de red whelp gloves","qual item é solicitado"}},{q="Onde entrego as luvas?",a="A requisição informa um local de entrega marcado no seu mapa.",al={"local de entrega","onde levar as luvas"}},{q="Do que preciso para concluir a troca?",a="Você precisa ter a requisição em sua posse para concluir a troca.",al={"do que preciso","exigência da requisição"}},{q="A requisição pode ser transferida?",a="Sim. O bilhete diz que a requisição é transferível.",al={"requisição transferível","outra pessoa pode levar"}},{q="A requisição menciona o pagamento?",a="Sim. A requisição inclui informações sobre o pagamento.",al={"qual o valor do pagamento","pagamento pelas luvas"}}},fp="34,114,17.145.0,27.47.0,30.57.0,40.62.0,28.44.0,30.49.0"}
P.entries["quest:94247"] = {n="Craftsman's Writ: Lesser Wizard's Robe",s="Uma Craftsman's Writ pede a entrega de uma única Lesser Wizard's Robe a um contato com vista para Dalaran. O documento desbotado pode ser transferido, permitindo que qualquer viajante com o pergaminho e a vestimenta receba o pagamento prometido.",h="Uma Craftsman's Writ pede a entrega de uma única Lesser Wizard's Robe a um contato com vista para Dalaran.",kw={"alan","craftsman's writ","dalaran","kirin tor","lesser wizard's robe","alfaiataria"},ang={["profession:Tailoring"]="Como alfaiate, seu trabalho com a agulha fornece a Lesser Wizard's Robe exigida por este contrato transferível."},sec={{t="Uma entrega nas montanhas",b="Um pedaço de pergaminho desbotado pede uma única Lesser Wizard's Robe e promete moedas pela entrega. O contrato pode mudar de mãos livremente, deixando a quem carregar o documento e a vestimenta pronta a tarefa de concluir o negócio. As instruções no pergaminho apontam para as montanhas com vista para Dalaran."},{t="Encontro nas alturas",b="No alto da encosta está Alan, vestido com roupas de couro escuras e observando a cidade abaixo. Embora sua aparência clandestina pareça deslocada para receber vestimentas mágicas delicadas, ele insiste que age em nome do Kirin Tor. Ele recebe o robe sob um sussurro discreto e entrega o pagamento prometido."}},faq={{q="Quem fez o pedido da Lesser Wizard's Robe?",a="O contrato não identifica o comprador, mas um homem chamado Alan reivindica a vestimenta em nome do Kirin Tor de Dalaran.",al={"quem escreveu a ordem","quem pediu o robe","cliente do robe"}},{q="Para onde a ordem de entrega manda você ir?",a="A ordem direciona a entrega para uma encosta com vista para Dalaran, onde aguarda um contato vestido com roupas de couro escuras.",al={"onde fazer a entrega","onde levar a ordem","onde fica alan"}},{q="A Craftsman's Writ pode ser negociada com outro alfaiate?",a="Sim. A escrita desbotada na parte inferior indica que a ordem pode ser totalmente transferida, permitindo que qualquer pessoa que a tenha entregue o robe e receba o pagamento.",al={"posso negociar a ordem","contrato transferível"}}},fp="38,246,25.317.0,20.311.1,42.122.0,44.129.0,57.175.0"}
P.entries["quest:94249"] = {n="Craftsman's Writ: Azure Silk Hood",s="Um Craftsman’s Writ desbotado solicita um Azure Silk Hood e informa as condições de entrega e pagamento. Você precisa da requisição para concluir a troca.",h="Um Craftsman’s Writ desbotado solicita um Azure Silk Hood e informa as condições de entrega e pagamento.",kw={"azure silk hood","craftsman's writ","entrega","pagamento","capuz de seda","transferível","requisição"},sec={{t="As condições por escrito",b="O bilhete foi escrito com tinta desbotada e indica um item: um Azure Silk Hood. Também informa o local de entrega e o pagamento. A requisição pode passar de um portador para outro, mas você precisa estar com ela para concluir a transação."}},faq={{q="O que a requisição pede?",a="O cliente solicita um Azure Silk Hood.",al={"requisição de capuz azul","qual item é solicitado","craftsman writ"}},{q="Onde devo entregar o capuz?",a="O local de entrega está marcado no seu mapa.",al={"local de entrega","onde entregar","local marcado"}},{q="Do que preciso para a transação?",a="Você precisa ter o item solicitado e a requisição em sua posse.",al={"o que levar","precisa da requisição?","concluir a troca"}},{q="A requisição diz como funciona o pagamento?",a="O bilhete inclui informações sobre o pagamento, mas o texto aqui não especifica o valor.",al={"valor do pagamento","condições de pagamento","o que se recebe"}},{q="Outra pessoa pode levar a requisição?",a="Sim. A requisição está marcada como transferível.",al={"requisição transferível","pode passar adiante","quem pode portar"}}},fp="33,144,17.225.0,27.42.0,28.44.0,35.60.0,36.91.0,32.40.0"}
P.entries["quest:94250"] = {n="Craftsman's Writ: Small Silk Pack",s="Uma ordem transferível solicita um Small Silk Pack e informa como entregá-lo e receber o pagamento. Você precisa da ordem para concluir a troca.",h="Uma ordem transferível solicita um Small Silk Pack e informa como entregá-lo e receber o pagamento.",kw={"craftsman's writ","entrega","pagamento","seda","small silk pack","transferível","ordem"},sec={{t="A ordem",b="Um bilhete desbotado de um cliente pede um Small Silk Pack. Ele informa onde entregar o pacote e como será feito o pagamento. A ordem pode passar de mão em mão, mas você precisa estar com ela quando a troca for concluída."}},faq={{q="O que a ordem pede?",a="O cliente solicita um Small Silk Pack.",al={"ordem de small silk pack","qual item foi pedido","pedido de pacote de seda"}},{q="Onde devo entregar o pacote?",a="A ordem informa os detalhes da entrega, e o local está marcado no seu mapa.",al={"local de entrega","onde levar","onde fica o local de entrega"}},{q="Como será feito o pagamento?",a="A ordem inclui informações sobre o pagamento.",al={"quanto vou receber","detalhes do pagamento","qual é o pagamento"}},{q="Posso transferir a ordem para outra pessoa?",a="Sim. O bilhete diz que a ordem é transferível.",al={"a ordem é transferível","passar a ordem adiante","repassar"}},{q="Preciso da ordem para concluir a troca?",a="Sim. Você precisa estar com a ordem para concluir a transação.",al={"precisa da ordem para entregar","preciso guardar o bilhete","ordem necessária"}}},fp="33,141,8.220.0,27.42.0,28.79.0,23.44.0,40.44.0,44.70.0"}
P.entries["quest:94252"] = {n="Craftsman's Writ: Red Woolen Boots",s="Uma ordem transferível solicita um par de Red Woolen Boots e informa os detalhes da entrega e do pagamento. Você precisa da ordem para concluir a troca.",h="Uma ordem transferível solicita um par de Red Woolen Boots e informa os detalhes da entrega e do pagamento.",kw={"botas","ordem do artesão","entrega","pagamento","red woolen boots","transferível","ordem"},sec={{t="O Pedido por Escrito",b="Um bilhete desbotado pede que você forneça um par de Red Woolen Boots. Ele informa onde entregá-las e como o pagamento será feito. A ordem pode ser transferida, mas você precisa tê-la consigo ao concluir a troca."}},faq={{q="O que a ordem solicita?",a="A ordem solicita um par de Red Woolen Boots.",al={"ordem de botas vermelhas","quais botas foram solicitadas"}},{q="Onde devo entregar as botas?",a="A ordem informa os detalhes da entrega, e o local marcado aparece no seu mapa.",al={"local de entrega","onde levar as botas vermelhas"}},{q="Como será feito o pagamento?",a="A ordem inclui informações sobre o pagamento.",al={"pagamento pelas botas","quanto vão pagar"}},{q="Posso transferir esta ordem?",a="Sim. O bilhete diz que a ordem é transferível.",al={"ordem transferível","outra pessoa pode carregá-la"}},{q="Preciso da ordem para concluir a troca?",a="Sim. Você precisa estar com a ordem para concluir a transação.",al={"preciso estar com a ordem","concluir a transação"}}},fp="34,143,19.213.0,27.47.0,29.81.0,24.44.0,25.44.0,44.75.0"}
P.entries["quest:94253"] = {n="Craftsman's Writ: Colorful Kilt",s="Um cliente pede um Kilt Colorido por meio de uma ordem transferível. A peça deve ajudar o cliente a se misturar em Zul'Gurub.",h="Um cliente pede um Kilt Colorido por meio de uma ordem transferível.",kw={"kilt colorido","ordem do artesão","entrega","disfarce","ritualista","zul'gurub"},sec={{t="Um disfarce",b="A ordem pede que você providencie um Kilt Colorido e o leve ao local marcado. O cliente planeja passar pelos portões de Zul'Gurub sem ser notado, vestido como um de seus ritualistas, e diz que o kilt combina com o disfarce."}},faq={{q="O que a ordem pede?",a="A ordem solicita um Kilt Colorido, que deve ser entregue no local marcado no seu mapa.",al={"ordem de kilt colorido","qual item é necessário"}},{q="Por que o cliente quer um kilt colorido?",a="O cliente planeja entrar em Zul'Gurub sem ser notado, vestido como um de seus ritualistas, e diz que o kilt vai ajudar.",al={"por que kilt","disfarce de kilt"}},{q="Posso transferir esta ordem?",a="Sim. A ordem diz que é transferível.",al={"transferir ordem","passar ordem adiante"}},{q="Onde devo entregar o kilt?",a="A ordem indica o local marcado no seu mapa.",al={"local de entrega","onde levar"}}},fp="31,121,10.206.0,27.88.0,43.104.0,25.38.0,32.56.0"}
P.entries["quest:94255"] = {n="Craftsman's Writ: Spider Silk Slippers",s="Uma ordem transferível solicita um par de Spider Silk Slippers e informa os detalhes de entrega e pagamento. Guarde a ordem para concluir a troca.",h="Uma ordem transferível solicita um par de Spider Silk Slippers e informa os detalhes de entrega e pagamento.",kw={"craftsman's writ","entrega","pagamento","pantufas","spider silk slippers","transferível","ordem"},sec={{t="Um pedido por escrito",b="A ordem do cliente, escrita com tinta desbotada, pede que você obtenha Spider Silk Slippers. Ela informa onde entregá-las e como será feito o pagamento. A ordem pode passar de um portador para outro, mas você precisa tê-la em mãos para concluir a transação."}},faq={{q="O que a ordem solicita?",a="O cliente solicita Spider Silk Slippers.",al={"quais pantufas","pedido de seda de aranha"}},{q="Onde devo entregar as pantufas?",a="A ordem informa o local de entrega, marcado no seu mapa.",al={"local de entrega","onde levá-las"}},{q="Como será feito o pagamento?",a="A ordem contém informações sobre o pagamento.",al={"quanto pagar","detalhes do pagamento"}},{q="Posso entregar a ordem a outra pessoa?",a="Sim. A ordem informa que é transferível.",al={"é transferível","passar a ordem adiante"}},{q="Preciso guardar a ordem?",a="Sim. Você precisa estar com a ordem em sua posse para concluir a transação.",al={"preciso da ordem","concluir sem ela"}}},fp="38,148,17.224.0,27.43.0,32.57.0,23.44.0,36.38.0,27.75.0"}
P.entries["quest:94259"] = {n="Craftsman's Writ: Nature Protection Potion",s="Uma ordem de trabalho transferível solicita que uma única Nature Protection Potion seja levada a um destino marcado. Você tem em mãos os termos do cliente, que promete pagar quando a poção chegar junto com o pergaminho.",h="Uma ordem de trabalho transferível solicita que uma única Nature Protection Potion seja levada a um destino...",kw={"ordem de trabalho do artesão","entrega","nature protection potion","encomenda","poção","ordem de trabalho"},sec={{t="Uma ordem aberta",b="Um bilhete desbotado encomenda uma única Nature Protection Potion, indicando para onde a poção deve ser levada e quanto o comprador pagará. O pergaminho informa que o acordo pode ser transferido a quem estiver com ele, desde que o papel acompanhe a entrega."}},faq={{q="O que a ordem solicita?",a="O bilhete solicita uma única Nature Protection Potion e informa os detalhes da entrega e as condições de pagamento.",al={"o que a ordem solicita","encomenda de nature protection potion","qual item é necessário"}},{q="Outra pessoa pode cumprir esta ordem?",a="O texto informa que o acordo é transferível, permitindo que qualquer pessoa com o documento entregue a poção e receba o pagamento.",al={"qualquer pessoa pode entregar","quem pode cumprir a ordem","a encomenda é transferível"}},{q="Por que é preciso guardar a ordem?",a="Você precisa levar o documento para comprovar a transação ao entregar a poção solicitada.",al={"o que é necessário para a troca","preciso guardar o bilhete"}}},fp="42,215,13.254.0,27.97.0,35.129.0,26.102.0"}
P.entries["quest:94260"] = {n="Craftsman's Writ: Catseye Draught",s="Uma requisição transferível solicita uma Catseye Draught e informa os detalhes de entrega e pagamento. Você precisa estar com a requisição para concluir a troca.",h="Uma requisição transferível solicita uma Catseye Draught e informa os detalhes de entrega e pagamento.",kw={"catseye draught","craftsman's writ","entrega","pagamento","transferível","requisição"},sec={{t="A solicitação por escrito",b="A nota desbotada registra o pedido de um cliente por uma Catseye Draught. Ela também informa o local de entrega e os detalhes do pagamento, e a requisição pode passar de uma pessoa para outra. Você precisa estar com ela ao entregar o item solicitado para concluir a troca."}},faq={{q="O que a requisição solicita?",a="O cliente solicita uma Catseye Draught.",al={"requisição de catseye draught","qual item foi solicitado"}},{q="Onde devo entregar a poção?",a="A nota informa o local de entrega, marcado no seu mapa.",al={"local de entrega","onde levar"}},{q="Preciso da requisição para concluir a troca?",a="Sim. Você precisa estar com a requisição para concluir a transação.",al={"preciso da requisição","requisição necessária"}},{q="A requisição pode ser transferida?",a="Sim. A nota diz que a requisição é transferível.",al={"requisição transferível","outra pessoa pode carregá-la"}},{q="A nota explica como funciona o pagamento?",a="A nota inclui informações sobre o pagamento.",al={"detalhes do pagamento","qual é o valor do pagamento"}}},fp="33,144,19.253.0,27.42.0,31.58.0,44.69.0,28.44.0,36.44.0"}
P.entries["quest:94261"] = {n="Craftsman's Writ: Great Rage Potion",s="Uma ordem transferível na Clareira da Lua solicita uma Great Rage Potion. O cliente diz que a poção é necessária para rituais reservados entre druidas experientes no Refúgio Noturno.",h="Uma ordem transferível na Clareira da Lua solicita uma Great Rage Potion.",kw={"craftsman's writ","druidas","great rage potion","clareira da lua","refúgio noturno","raiva","rituais"},sec={{t="Uma ordem na Clareira da Lua",b="Um cliente na Clareira da Lua pede que você leve uma Great Rage Potion ao local indicado. A solicitação pode ser transferida, e você precisa estar com ela para concluir a troca. A nota também contém os detalhes da entrega e do pagamento."},{t="Rituais no Refúgio Noturno",b="O cliente diz que alguns druidas experientes no Refúgio Noturno participam de rituais violentos, afastados do restante do bosque. Uma Great Rage Potion os ajuda a superar a tranquilidade que se esforçaram para dominar. Nesse bosque, o cliente considera a raiva parte da manutenção do equilíbrio."}},faq={{q="O que a ordem solicita?",a="A ordem solicita uma Great Rage Potion e menciona informações sobre entrega e pagamento.",al={"ordem de great rage potion","qual poção é solicitada"}},{q="Onde devo levar a poção?",a="A ordem indica o local marcado no seu mapa.",al={"local de entrega da ordem","onde entregar"}},{q="Por que querem uma Great Rage Potion?",a="O cliente diz que alguns druidas experientes no Refúgio Noturno a usam para superar a tranquilidade durante rituais violentos e reservados.",al={"por que poção da raiva","para que serve"}},{q="Quem usa a poção?",a="O cliente diz que alguns druidas experientes no Refúgio Noturno usam uma Great Rage Potion como parte de seus rituais reservados.",al={"quem quer poção da raiva","poção dos druidas"}},{q="Outra pessoa pode levar a ordem?",a="Sim. A ordem diz que pode ser transferida.",al={"ordem transferível","posso passar a ordem adiante"}},{q="Preciso da ordem para concluir a troca?",a="Sim. Você precisa estar com a ordem para concluir a transação.",al={"precisa estar no inventário","ordem necessária"}}},fp="35,164,19.220.0,21.268.0,27.87.0,27.56.0,34.125.0,20.114.0,32.38.0,44.69.0"}
P.entries["quest:94274"] = {n="Craftsman's Writ: Golden Scale Coif",s="Uma requisição desbotada e transferível solicita uma Golden Scale Coif. Ela registra o local de entrega desejado pelo cliente e como será feito o pagamento.",h="Uma requisição desbotada e transferível solicita uma Golden Scale Coif.",kw={"coifa","requisição do artesão","entrega","golden scale coif","pagamento","transferível","requisição"},sec={{t="A requisição",b="Um bilhete desbotado de um cliente pede uma Golden Scale Coif. Ele também informa o local de entrega e os detalhes do pagamento. A requisição pode passar de mão em mão, mas você precisa estar com ela ao concluir a transação."}},faq={{q="O que a requisição pede?",a="O cliente solicita uma Golden Scale Coif.",al={"requisição de golden scale coif","qual item é necessário"}},{q="Onde devo entregar a coifa?",a="A requisição indica o local de entrega no seu mapa.",al={"local de entrega","onde levar"}},{q="Como vou receber?",a="A requisição contém informações sobre o pagamento.",al={"detalhes do pagamento","qual é o pagamento"}},{q="Posso passar a requisição para outra pessoa?",a="Sim. O bilhete diz que a requisição é transferível.",al={"requisição transferível","posso repassar"}},{q="Preciso da requisição para concluir a transação?",a="Sim. Você precisa estar com a requisição para concluir a transação.",al={"precisa da requisição para concluir","preciso levar o bilhete"}}},fp="35,131,8.212.0,27.44.0,28.53.0,19.44.0,36.44.0,47.68.0"}
P.entries["quest:94283"] = {n="Craftsman's Writ: Goblin Land Mine",s="Um pedido comercial, escrito com tinta desbotada, solicita uma única Goblin Land Mine. Quem tiver o documento transferível pode entregar o explosivo no local combinado e receber o pagamento.",h="Um pedido comercial, escrito com tinta desbotada, solicita uma única Goblin Land Mine.",kw={"craftsman's writ","entrega","engenharia","goblin","goblin land mine","ordem escrita"},ang={["profession:Engineering"]="Como engenheiro, construir uma Goblin Land Mine exige as habilidades da sua oficina para atender a um pedido personalizado de um cliente."},sec={{t="Um comprador de explosivos",b="Alguém fez um pedido comercial de armamento volátil, escrito com tinta desbotada e com termos claros para a entrega e o pagamento. Qualquer artesão com a nota transferível pode montar o dispositivo e receber a recompensa prometida."},{t="Cumprindo o pedido",b="O ponto de entrega indicado aguarda o explosivo pronto, desde que você leve o documento para comprovar o acordo. Quando a mina mudar de mãos no local designado, a transação será concluída e o pagamento será feito."}},faq={{q="O que a ordem solicita?",a="A nota pede que uma única Goblin Land Mine seja criada ou adquirida e levada ao cliente.",al={"o que foi solicitado","item da ordem","qual item é necessário"}},{q="Qualquer pessoa pode cumprir a ordem?",a="Qualquer pessoa com a ordem pode cumprir o pedido e receber o pagamento, pois o documento é transferível.",al={"quem pode cumprir esta ordem","outra pessoa pode usar a ordem","ordem transferível"}},{q="Onde deve ser feita a entrega?",a="A ordem inclui detalhes que indicam o local de entrega e o pagamento que espera por você ao chegar.",al={"onde entregar a mina","local de entrega"}},{q="Por que você precisa guardar o documento?",a="Você precisa estar com o documento escrito ao entregar a mina para concluir a transação.",al={"guardar a ordem","preciso do documento"}}},fp="34,185,22.220.0,20.223.0,27.98.0,28.111.0,27.105.0,36.107.0"}
P.entries["quest:94286"] = {n="Craftsman's Writ: Flash Bomb",s="Uma ordem transferível solicita que um cliente entregue uma Flash Bomb. A nota indica um local marcado para a entrega e informações sobre o pagamento.",h="Uma ordem transferível solicita que um cliente entregue uma Flash Bomb.",kw={"craftsman's writ","entrega","flash bomb","pagamento","transferível","ordem"},sec={{t="A ordem",b="Uma nota desbotada solicita uma Flash Bomb, informa o local de entrega e traz informações sobre o pagamento. A ordem pode ser transferida, mas você precisa tê-la em mãos para concluir a troca. O local marcado aparece no seu mapa."}},faq={{q="O que a ordem solicita?",a="A ordem solicita uma Flash Bomb, além de informações sobre a entrega e o pagamento.",al={"ordem de flash bomb","qual item é solicitado","ordem do artesão"}},{q="Posso transferir a ordem?",a="Sim. A nota diz que a ordem pode ser transferida.",al={"a ordem pode ser transferida","passar a ordem adiante","entregar a ordem a alguém"}},{q="O que preciso para concluir a troca?",a="Você precisa ter a ordem e o item solicitado em mãos, depois entregá-lo no local marcado no seu mapa.",al={"o que preciso","como concluir a transação","requisitos de entrega"}}},fp="28,140,8.205.0,27.84.0,24.44.0,40.112.0"}
P.entries["quest:94293"] = {n="Craftsman's Writ: Guardian Cloak",s="Um cliente de Ethel Rethor pede uma Guardian Cloak por meio de uma requisição transferível. A capa ajudará a proteger artefatos dos nagas e centauros.",h="Um cliente de Ethel Rethor pede uma Guardian Cloak por meio de uma requisição transferível.",kw={"artefatos","centauro","capa","requisição do artesão","ethel rethor","guardian cloak","naga","requisição transferível"},sec={{t="Um pedido por escrito",b="Uma requisição desbotada pede que você leve uma Guardian Cloak ao local marcado. Ela também informa os detalhes da entrega e do pagamento, e pode ser transferida para outra pessoa."},{t="Em Ethel Rethor",b="O cliente estuda os mistérios de Ethel Rethor. Com a capa em mãos, pretende embrulhar os artefatos encontrados lá e escondê-los dos nagas e centauros."}},faq={{q="O que a requisição pede?",a="O cliente pede uma Guardian Cloak, com os detalhes da entrega e do pagamento anotados no bilhete desbotado.",al={"requisição por guardian cloak","que item querem"}},{q="Posso passar a requisição para outra pessoa?",a="Sim. O bilhete diz que ela pode ser transferida.",al={"a requisição é transferível","passar a requisição adiante"}},{q="Por que o cliente quer uma Guardian Cloak?",a="O cliente pretende usá-la para embrulhar artefatos e mantê-los protegidos.",al={"capa para quê","por que guardian cloak"}},{q="De quem o cliente quer esconder os artefatos?",a="O cliente quer proteger os artefatos dos nagas e centauros em Ethel Rethor.",al={"esconder artefatos de quem","nagas e centauros"}}},fp="32,148,17.170.0,15.160.0,27.102.0,36.44.0,44.65.0,50.79.0"}
P.entries["quest:94297"] = {n="Craftsman's Writ: Quickdraw Quiver",s="Uma ordem de artesão solicita a entrega de uma única Quickdraw Quiver a um cliente indicado. Escrita em tinta desbotada, a folha garante pagamento a quem trouxer os bens com a ordem em mãos.",h="Uma ordem de artesão solicita a entrega de uma única Quickdraw Quiver a um cliente indicado.",kw={"ordem de artesão","quickdraw quiver","aljava","ordem"},sec={{t="Uma ordem transferível",b="Um cliente precisa que uma Quickdraw Quiver seja feita e levada a um local de entrega designado. A ordem está aberta a qualquer pessoa disposta a fornecer o trabalho em couro, desde que o papel original esteja em mãos na hora de receber o pagamento."}},faq={{q="O que é esta ordem de artesão?",a="A ordem, escrita em tinta desbotada, solicita uma Quickdraw Quiver para um cliente. Quem estiver com o documento pode atender ao pedido e entregar os bens em troca de pagamento.",al={"ordem de quickdraw quiver","ordem de artesão quickdraw quiver"}},{q="Quem pediu a aljava?",a="O bilhete não identifica o cliente pelo nome. Ele apenas informa o local de entrega, o pagamento e que a ordem pode ser transferida a quem estiver com o pergaminho.",al={"quem fez o pedido","cliente da ordem"}},{q="Qualquer pessoa pode atender a esta ordem?",a="O texto no fim indica que a ordem é transferível. Desde que você leve o documento ao local de entrega, a transação pode ser concluída.",al={"outro jogador pode atender à ordem","transferir ordem de artesão"}}},fp="34,199,20.217.0,30.172.0,25.166.0,30.153.0"}
P.entries["quest:94298"] = {n="Craftsman's Writ: Swift Boots",s="Um cliente pede um par de Swift Boots por meio de uma ordem transferível. Você precisa da ordem para concluir a entrega e receber o pagamento.",h="Um cliente pede um par de Swift Boots por meio de uma ordem transferível.",kw={"botas","craftsman's writ","entrega","pagamento","swift boots","transferível","ordem"},sec={{t="Pedido de um cliente",b="Um bilhete desbotado pede que você forneça um par de Swift Boots. Também menciona o local de entrega e o pagamento. A ordem pode ser transferida, mas você precisa estar com ela para concluir a transação."}},faq={{q="O que a ordem solicita?",a="O cliente pede um par de Swift Boots.",al={"ordem swift boots","quais botas são solicitadas"}},{q="Onde devo entregar as botas?",a="O local de entrega está marcado no seu mapa.",al={"local de entrega","onde levar as botas"}},{q="Preciso ficar com a ordem?",a="Sim. Você precisa estar com a ordem para concluir a transação.",al={"precisa da ordem","ordem necessária"}},{q="Posso dar a ordem para outra pessoa?",a="Sim. A ordem diz que pode ser transferida.",al={"transferir ordem","é transferível"}},{q="O cliente menciona o pagamento?",a="O bilhete menciona o pagamento, mas não informa o valor.",al={"pagamento das botas","qual é o valor do pagamento"}}},fp="29,128,20.200.0,27.46.0,29.44.0,27.65.0,36.41.0,34.47.0"}
P.entries["quest:943"] = {n="O prospector distraído",s="Essa missão marca o capítulo final da busca iniciada pelas escavações do Prospector Trilheiro na Costa Negra. O Arqueólogo Pançacheia, no Porto de Menethil, pretende combinar as descobertas de Trilheiro com seu próprio fóssil e a Pedra de Relu perdida para desvendar os poderes ocultos dessas relíquias antigas.",h="Essa missão marca o capítulo final da busca iniciada pelas escavações do Prospector Trilheiro na Costa Negra.",kw={"costa negra","liga dos exploradores","pançacheia","fóssil","menethil","trilheiro","pedra de relu","pantanal","whelgar"},ang={["faction:Alliance"]="Mensageiros e aventureiros da Aliança frequentemente cruzam a distância marítima entre as terras dos elfos noturnos na Costa Negra e os povoados anões próximos ao Porto de Menethil.",["race:Dwarf"]="Essa série de missões exemplifica a missão central da Liga dos Exploradores, conectando escavações remotas entre continentes para reconstruir a herança anã e os mistérios dos titãs."},sec={{t="Arqueologia entre continentes",b="O que começou como uma missão de escolta para ajudar o distraído Prospector Trilheiro no norte de Costa Negra atravessa o Grande Oceano e chega aos pântanos do Pantanal. O fóssil original de Pançacheia está com o Prospector Whelgar, em seu sítio de escavação no Pantanal. Ao examinar as descobertas reunidas, o Arqueólogo Pançacheia percebe que desvendar os poderes misteriosos dos fósseis exige um artefato essencial: a Pedra de Relu."},{t="Perdida nos pântanos",b="Antes que Pançacheia pudesse se encontrar com Whelgar, um bando de raptores mosqueados emboscou sua caravana na estrada e engoliu a Pedra de Relu. Para solucionar o mistério, Pançacheia precisa que um aventureiro cace essas feras, recupere a pedra engolida e busque o fóssil original no acampamento de Whelgar. Com os dois fósseis e a pedra reunidos, os pesquisadores anões esperam descobrir a verdadeira origem e o poder das relíquias."}},faq={{q="Por que uma missão da Costa Negra termina no Pantanal?",a="A Liga dos Exploradores mantém operações tanto em Kalimdor quanto nos Reinos do Leste. O Arqueólogo-chefe Greywhisker enviou o fóssil de Trilheiro da Costa Negra através do mar para o Arqueólogo Pançacheia no Pantanal, conectando os dois sítios de escavação por uma pesquisa conjunta.",al={"por que pantanal na missão de costa negra","ligação com porto de menethil","por que ir ao pantanal"}},{q="O que é a Pedra de Relu?",a="A Pedra de Relu é uma antiga relíquia recuperada pelo Arqueólogo Pançacheia. Ele acredita que ela funciona como uma chave ou catalisador capaz de revelar os segredos mágicos adormecidos nos fósseis escavados na Costa Negra e no Pantanal.",al={"pedra de relu","o que é a pedra de relu","artefato de relu"}},{q="Quem é o Arqueólogo Pançacheia?",a="O Arqueólogo Pançacheia é um membro da Liga dos Exploradores que atua no Porto de Menethil. Ele estuda relíquias antigas recuperadas nas escavações próximas e espera desvendar os poderes ocultos dos fósseis encontrados pelos prospectores Trilheiro e Whelgar.",al={"pançacheia","quem é pançacheia"}},{q="Quem está com o fóssil original?",a="O Prospector Whelgar guarda o fóssil original de Pançacheia em seu sítio de escavação no Pantanal. O fóssil de Trilheiro da Costa Negra é aquele que você já entregou a Pançacheia.",al={"onde está o fóssil","quem está com o fóssil de trilheiro","fóssil de whelgar"}},{q="Por que os raptores estão com a Pedra de Relu?",a="Enquanto seguia pela estrada do Pantanal para conversar com o Prospector Whelgar, Pançacheia foi emboscado por raptores mosqueados. Na confusão do ataque, uma das feras engoliu a pedra inteira.",al={"raptor engoliu a relíquia","por que os raptores têm a pedra"}},{q="O que os anões esperam que os fósseis façam?",a="Pançacheia acredita que os fósseis guardam um poder oculto e segredos do passado, e que a Pedra de Relu é a chave para revelá-los.",al={"poder dos fósseis","o que o fóssil faz"}}},fx={["1568e7b3"]={q="Para que serve o Fóssil do Pançacheia?",a="O Fóssil do Pançacheia é um dos espécimes antigos recuperados pelos escavadores anões, junto com a peça descoberta pelo Prospector Trilheiro em Costa Negra. O Arqueólogo Pançacheia acredita que essas relíquias antigas detêm poder mágico adormecido e segredos esquecidos, que ele espera finalmente desbloquear e decifrar usando o poder ressonante da Pedra de Relu.",al={"fóssil do pançacheia","uso do fóssil do pançacheia","o que é o fóssil do pançacheia"}}},fp="28,229,29.366.0,19.376.1,48.246.0,26.221.0,31.241.0,28.162.0,38.172.0,45.133.0"}
P.entries["quest:94300"] = {n="Craftsman's Writ: Big Voodoo Mask",s="Uma ordem transferível solicita uma Big Voodoo Mask e informa os detalhes da entrega e do pagamento. Você precisa da ordem para concluir a transação.",h="Uma ordem transferível solicita uma Big Voodoo Mask e informa os detalhes da entrega e do pagamento.",kw={"big voodoo mask","craftsman's writ","entrega","máscara","pagamento","transferível","ordem"},sec={{t="A ordem",b="O bilhete desbotado solicita uma Big Voodoo Mask e informa onde entregá-la e como o pagamento será feito. As linhas finais dizem que a ordem pode passar de um portador para outro. Você precisa estar com ela ao fazer a entrega."}},faq={{q="O que a ordem solicita?",a="O cliente solicita uma Big Voodoo Mask.",al={"qual item é solicitado","ordem para big voodoo mask"}},{q="Posso passar a ordem para outra pessoa?",a="Sim. O bilhete diz que a ordem é transferível.",al={"a ordem é transferível","outra pessoa pode carregá-la"}},{q="Do que preciso para concluir a transação?",a="Você precisa estar com a ordem para concluir a transação.",al={"o que devo levar","requisito da ordem"}},{q="A ordem informa os detalhes da entrega e do pagamento?",a="Sim. O bilhete informa o local de entrega e os detalhes do pagamento.",al={"onde entregar","como será feito o pagamento"}}},fp="33,135,8.234.0,27.42.0,36.44.0,43.69.0,48.75.0"}
P.entries["quest:94303"] = {n="Craftsman's Writ: Thick Leather Ammo Pouch",s="Uma ordem transferível de artesão pede uma bolsa de munição de couro espesso a um comprador indicado. Cumprir a encomenda rende o pagamento prometido no pergaminho.",h="Uma ordem transferível de artesão pede uma bolsa de munição de couro espesso a um comprador indicado.",kw={"bolsa de munição","ordem de artesão","couro","bolsa de munição de couro espesso","encomenda comercial","ordem"},sec={{t="Uma encomenda comercial",b="Uma nota desbotada descreve uma encomenda comercial de uma bolsa de munição de couro espesso. Quem tiver o documento transferível pode levar a bolsa confeccionada ao destino indicado e receber o pagamento combinado."}},faq={{q="O que a ordem solicita?",a="O documento pede a entrega de uma única bolsa de munição de couro espesso junto com a própria ordem.",al={"o que a ordem solicita","itens necessários","requisitos da ordem"}},{q="Qualquer pessoa pode cumprir esta encomenda?",a="A nota informa que é transferível, então qualquer pessoa que tenha o documento pode cumprir a encomenda e receber o pagamento.",al={"quem pode entregar","outra pessoa pode entregar","a ordem é vinculada"}},{q="Onde a entrega deve ser feita?",a="A ordem especifica o local de entrega e as condições de pagamento para quem levar os bens solicitados.",al={"onde levar a bolsa","local de entrega","onde entregar"}}},fp="42,172,18.188.0,27.100.0,30.108.0,27.96.0"}
P.entries["quest:94304"] = {n="Craftsman's Writ: Mageweave Bag",s="Uma ordem desbotada pede que um alfaiate forneça uma bolsa resistente de tecido mágico. O pergaminho informa as instruções de entrega e o pagamento prometido, e qualquer pessoa com a ordem transferível pode concluir a negociação.",h="Uma ordem desbotada pede que um alfaiate forneça uma bolsa resistente de tecido mágico.",kw={"ordem do artesão","entrega","bolsa de tecido mágico","alfaiataria","ordem de comércio","ordem escrita"},ang={["profession:Tailoring"]="Como alfaiate, você tem a habilidade de tecer fardo após fardo de tecido mágico para criar a bolsa resistente de que este cliente precisa."},sec={{t="Uma ordem de comércio em aberto",b="Um cliente registrou uma ordem de comércio com tinta desbotada, pedindo uma bolsa de tecido mágico. O papel informa onde os bens devem ser entregues e qual pagamento aguarda quem os levar. Como o acordo é transferível, qualquer pessoa com a ordem pode fornecer a bolsa pronta, levá-la ao local indicado e receber as moedas."}},faq={{q="Que item a ordem solicita?",a="A ordem pede uma única bolsa de tecido mágico.",al={"qual item é necessário","item da ordem escrita","o que a ordem solicita"}},{q="Outro artesão pode cumprir esta ordem?",a="Sim. O bilhete indica explicitamente que o acordo comercial é transferível, permitindo que quem estiver com o pergaminho faça a entrega e receba as moedas.",al={"quem pode cumprir a ordem","qualquer pessoa pode entregar a ordem","ordem transferível"}},{q="Onde o cliente quer que a entrega seja feita?",a="A ordem inclui instruções específicas de entrega que levam você a um ponto de entrega marcado no seu mapa.",al={"onde entregar a bolsa de tecido mágico","local de entrega da ordem","onde levar a bolsa"}}},fp="31,198,19.306.0,32.43.0,40.150.0,47.104.0"}
P.entries["quest:94312"] = {n="Craftsman's Writ: Orange Martial Shirt",s="Uma ordem de cliente solicita uma Orange Martial Shirt e informa os detalhes de entrega e pagamento. A ordem pode passar de mão em mão.",h="Uma ordem de cliente solicita uma Orange Martial Shirt e informa os detalhes de entrega e pagamento.",kw={"ordem de artesão","entrega","orange martial shirt","pagamento","camisa","ordem transferível"},sec={{t="A entrega",b="A nota informa o local de entrega e as condições de pagamento. Você precisa estar com a ordem para concluir a troca, e a camisa solicitada é uma Orange Martial Shirt."}},faq={{q="O que a ordem solicita?",a="O cliente solicita uma Orange Martial Shirt.",al={"ordem da camisa laranja","qual camisa","ordem de artesão"}},{q="Onde devo entregar a camisa?",a="O local de entrega está marcado no seu mapa.",al={"local de entrega","onde levar","local da ordem"}},{q="Do que preciso para concluir a transação?",a="Você precisa ter a camisa solicitada e a ordem em sua posse.",al={"o que levar","preciso da ordem","como concluir"}},{q="A ordem informa como funciona o pagamento?",a="A nota inclui informações sobre o pagamento.",al={"detalhes do pagamento","quanto pagar","pagamento"}},{q="A ordem pode ser transferida?",a="Sim. A nota informa que a ordem é transferível.",al={"passar a ordem adiante","ordem transferível","dar a ordem a alguém"}}},fp="38,127,12.157.0,27.47.0,29.44.0,35.61.0,36.44.0,28.44.0"}
P.entries["quest:94313"] = {n="Craftsman's Writ: White Bandit Mask",s="Uma ordem desbotada solicita uma White Bandit Mask e informa as condições de entrega e pagamento. Ela pode ser transferida, mas você precisa dela para concluir a troca.",h="Uma ordem desbotada solicita uma White Bandit Mask e informa as condições de entrega e pagamento.",kw={"ordem do artesão","entrega","pagamento","transferível","white bandit mask","ordem"},sec={{t="A entrega",b="O cliente pergunta se você veio fazer a entrega. A ordem especifica uma White Bandit Mask, informa o local de entrega e as condições de pagamento. Você precisa estar com a ordem para concluir a troca."}},faq={{q="O que a ordem solicita?",a="O cliente solicita uma White Bandit Mask.",al={"ordem da white bandit mask","qual item é solicitado"}},{q="Onde devo entregar a máscara?",a="O local de entrega está marcado no seu mapa.",al={"local de entrega","onde levar"}},{q="Preciso estar com a ordem?",a="Sim. Você precisa estar com a ordem para concluir a troca.",al={"preciso estar com a ordem","posso entregar sem a ordem"}},{q="Outra pessoa pode levar a ordem?",a="Sim. A nota informa que a ordem pode ser transferida.",al={"a ordem pode ser transferida","passar a ordem para alguém"}},{q="O que o cliente pergunta quando chego?",a="O cliente pergunta se você veio fazer a entrega.",al={"texto de progresso da entrega","você veio fazer a entrega"}}},fp="35,154,12.200.0,27.44.0,28.44.0,28.67.0,32.44.0,41.57.0"}
P.entries["quest:94316"] = {n="Craftsman's Writ: Potion of Demonslaying",s="Um documento transferível solicita uma Potion of Demonslaying. Ele também informa como fazer a entrega e receber o pagamento.",h="Um documento transferível solicita uma Potion of Demonslaying.",kw={"craftsman's writ","entrega","pagamento","poção","potion of demonslaying","transferível","documento"},sec={{t="O documento",b="O bilhete desbotado solicita uma Potion of Demonslaying e informa onde entregá-la e como o pagamento será feito. Você precisa estar com o documento para concluir a transação."}},faq={{q="O que o documento solicita?",a="O documento solicita uma Potion of Demonslaying.",al={"qual poção","solicitação do documento","poção contra demônios"}},{q="Onde devo entregá-la?",a="O local da entrega está marcado no seu mapa.",al={"local de entrega","onde levar","local marcado"}},{q="Como funciona o pagamento?",a="O documento inclui informações sobre o pagamento.",al={"informações sobre pagamento","quanto vou receber","pagamento do cliente"}},{q="Posso passar o documento para outra pessoa?",a="Sim. O bilhete diz que o documento é transferível.",al={"transferir documento","é transferível","passar adiante"}},{q="Preciso estar com o documento?",a="Sim. Você precisa estar com o documento para concluir a transação.",al={"precisa do documento","precisa carregá-lo","posse do documento"}}},fp="40,108,8.185.0,27.45.0,22.44.0,22.44.0,36.44.0,27.65.0"}
P.entries["quest:94369"] = {n="The Fate of Zephras",s="Você leva a Valanaar notícias sobre o perigo que ameaça Zephras para Talaanis Shadowsong. Com as proteções destruídas, a ilha fica exposta a Al'Akir, e o povo de Zephras precisa decidir como proteger seu lar.",h="Você leva a Valanaar notícias sobre o perigo que ameaça Zephras para Talaanis Shadowsong.",kw={"al'akir","elaadrin","lorthuna","santuário de akir","talaanis shadowsong","valanaar","proteções","senhor do vento","zephras"},sec={{t="Um aviso a Talaanis",b="Você conta a Talaanis o que aconteceu acima do Shrine of Akir e compartilha o plano de Elaadrin de deixar Ilha de Zefras. O Sumo Ancião Shadowsong precisa entender o perigo e o objetivo de sua missão a Azeroth enquanto o povo de Zephras busca uma forma de salvar seu lar."},{t="O que resta",b="Talaanis reflete sobre as notícias. Lorthuna se foi, e o culto perdeu sua líder. Zephras não foi invadida, embora Al'Akir possa voltar sua atenção para a ilha daqui a anos ou décadas. O medo e os motivos para celebrar agora coexistem."}},faq={{q="Com quem devo falar?",a="Você fala com Talaanis Shadowsong em Valanaar.",al={"com quem falar","talaanis","onde devo me apresentar"}},{q="O que digo a Talaanis?",a="Você conta a Talaanis o que aconteceu acima do Shrine of Akir e sobre o plano de Elaadrin de deixar Ilha de Zefras.",al={"o que aconteceu no santuário","o que devo relatar","notícias do shrine of akir"}},{q="Por que o povo de Zephras teme Al'Akir?",a="As proteções que escondiam Zephras foram derrubadas, e Al'Akir pode escolher atacar enquanto o povo está em seu domínio.",al={"por que temer al'akir","perigo do senhor do vento","ameaça de al'akir"}},{q="O que o Sumo Ancião Shadowsong precisa saber?",a="Ele precisa saber do perigo e do que o povo de Zephras pretende fazer em sua missão a Azeroth.",al={"o que talaanis precisa","notícias para o sumo ancião","intenções para azeroth"}}},fp="19,183,22.251.0,12.225.1,20.47.0,24.102.0,48.104.0,45.122.0"}
P.entries["quest:94373"] = {n="Call of Earth",s="A Call of Earth é uma prova sagrada supervisionada por Teo Hammerstorm em Sidermar, testando os iniciados na paciência e na resiliência da pedra. Os aspirantes devem confrontar os trolls Frostmane ao sul para obter seus pingentes de urso antes de receberem um Earth Sapta.",h="A Call of Earth é uma prova sagrada supervisionada por Teo Hammerstorm em Sidermar, testando os iniciados na...",kw={"sidermar","call of earth","vale cristálgida","totem da terra","frostmane","pingente de urso frostmane","urso iceclaw","sapta","xamã","teo hammerstorm"},ang={["class:Shaman"]="A Call of Earth marca uma iniciação inicial na comunhão com os espíritos da pedra e do solo, culminando na preparação de um Earth Sapta.",["faction:Alliance"]="Este rito testa defensores novatos contra o avanço dos trolls Frostmane que habitam as cavernas ao sul de Sidermar.",["race:Dwarf"]="Oferecida no Vale Cristálgida, perto de Sidermar, esta prova conecta a fortaleza dos anões e a herança das montanhas com a paciência duradoura da própria terra."},sec={{t="A Sabedoria da Pedra",b="Em Sidermar, no Vale Cristálgida, o mentor Teo Hammerstorm cuida dos iniciados prontos para trilhar o caminho acidentado da terra. Vendo a terra como uma fundação firme e inflexível, Teo orienta os jovens viajantes a darem ouvidos à sabedoria das montanhas. Ele adverte que, embora a pedra sirva como um escudo duradouro, seu favor não é concedido levianamente, exigindo verdadeira coragem e profundo respeito antes que quaisquer segredos do solo sejam compartilhados."},{t="Julgamento no Frostmane Den",b="Para demonstrar prontidão, o iniciado deve enfrentar os trolls Frostmane à espreita em uma caverna ao sul. Esses trolls fabricam pingentes rústicos a partir dos ferozes ursos Iceclaw que vagam pelas alturas congeladas. Recuperar dois desses pingentes de urso do covil dos trolls serve como prova tangível de que o suplicante possui a determinação obstinada e a fortaleza esperadas pelos espíritos elementais."},{t="O Earth Sapta",b="Ao apresentar os pingentes a Teo Hammerstorm, o ancião elogia a paciência do iniciado — a maior virtude da terra, que dura mais que picos desmoronando e vales fluviais esculpidos. Em reconhecimento a esse respeito comprovado, Teo começa a trabalhar na preparação de um Earth Sapta, um catalisador essencial que permite ao iniciado perceber e trilhar o verdadeiro caminho dos elementos."}},faq={{q="Quem oferece a missão Call of Earth?",a="Teo Hammerstorm, um guia ancião localizado em Sidermar, no Vale Cristálgida, oferece a prova. Ele instrui jovens iniciados nos caminhos da pedra e os encarrega de provar sua determinação diante dos espíritos da terra.",al={"quem dá call of earth","concedente da missão call of earth","missão de teo hammerstorm"}},{q="O que Teo Hammerstorm pede para você fazer?",a="Você deve se aventurar ao sul de Sidermar até a caverna habitada por trolls Frostmane e recuperar dois Frostmane Bear Pendants, que os trolls confeccionam a partir de ursos Iceclaw. Entregá-los a Teo Hammerstorm cumpre a prova.",al={"objetivos de call of earth","o que preciso para call of earth","missão dos pingentes frostmane"}},{q="Onde você encontra os Frostmane Bear Pendants?",a="Os pingentes são carregados pelos trolls Frostmane que vivem em uma caverna situada ao sul de Sidermar. Esses talismãs são confeccionados a partir de ursos Iceclaw locais e usados pelos trolls que habitam no Den.",al={"onde encontrar pingentes de urso frostmane","como conseguir pingentes de urso frostmane","caverna frostmane sidermar"}},{q="Qual recompensa Teo Hammerstorm prepara após a conclusão?",a="Um sapta é uma mistura ou poção cerimonial preparada por mentores espirituais para sintonizar um praticante com os espíritos elementais. Ao concluir esta prova, Teo cria um Earth Sapta para permitir que você trilhe o verdadeiro caminho da terra.",al={"o que é um sapta","earth sapta anão","o que teo hammerstorm cria"}},{q="Por que os iniciados devem enfrentar os trolls Frostmane para esta prova?",a="Confrontar os trolls Frostmane demonstra a coragem física e a resiliência espiritual necessárias para comungar com a terra. Ao reivindicar os pingentes de urso dos trolls hostis em seu covil, o iniciado se mostra digno do favor duradouro da montanha.",al={"por que matar trolls frostmane","por que pingentes frostmane"}},{q="O que Teo Hammerstorm ensina sobre a natureza da terra?",a="Teo ensina que a paciência é a maior virtude da terra, destacando como ela resiste enquanto montanhas desmoronam e rios esculpem vales lentamente. Ele enfatiza que a pedra protege aqueles que a respeitam, mas adverte que até mesmo a rocha sólida pode se mover se for desrespeitada.",al={"virtudes da terra teo hammerstorm","sabedoria da montanha"}}},fp="13,171,19.289.0,26.279.0,17.273.1,35.180.0,40.189.0,46.135.0,57.139.0,60.162.0,58.204.0"}
P.entries["quest:94374"] = {n="Call of Earth",s="O Call of Earth é um rito xamânico sagrado que vincula o espírito mortal de um iniciado aos alicerces duradouros do mundo. Ao ingerir a infusão visionária conhecida como Earth Sapta junto a uma isolada Spirit Stone na montanha, o buscador aprende humildade, paciência e percepção elemental em meio à neve e à rocha.",h="O Call of Earth é um rito xamânico sagrado que vincula o espírito mortal de um iniciado aos alicerces...",kw={"call of earth","dun morogh","earth sapta","rito elemental","caminho oculto","sapta","xamã","spirit stone"},ang={["class:Shaman"]="Este rito representa uma comunhão essencial para xamãs, vinculando espírito à pedra e concedendo visão além da percepção mortal através da poção ritual de sapta.",["faction:Alliance"]="A presença de um rito elemental nos despenhadeiros montanhosos nevados demonstra tradições xamânicas criando raízes em terras da Aliança.",["race:Dwarf"]="Proferida na cadência rude da fala dos anões entre picos montanhosos congelados, esta sagrada comunhão vincula a comunhão com a terra diretamente às alturas nevadas de Dun Morogh."},sec={{t="A Poção da Visão",b="O Call of Earth é uma prova sagrada de harmonização espiritual, que exige que o iniciado beba a infusão encantada conhecida como Earth Sapta em um santuário isolado na montanha. Forjado por meio de magia elemental ancestral, o sapta vincula o espírito de quem o bebe à rocha matriz do mundo, concedendo a olhos mortais o raro poder de testemunhar espíritos elementais e correntes sutis invisíveis à visão comum. Devido à sua potência, a poção só deve ser consumida em um local sagrado designado, onde o elo entre espírito e pedra possa se firmar com segurança."},{t="A Spirit Stone na Neve",b="No alto de uma montanha açoitada pela neve, escondida no término de um Caminho Oculto isolado, repousa a Spirit Stone. Os iniciados viajam para esta paisagem gélida e inóspita para se colocarem humildemente diante da rocha ancestral. Ao se apresentarem sem orgulho e ingerirem o sapta, eles descobrem que, mesmo nos despenhadeiros de inverno mais rigorosos, a terra viva estende suas boas-vindas. As montanhas se tornam um alicerce de força física duradoura, enquanto as vastas e serenas planícies ensinam o poder silencioso da paciência."},{t="Força e Serenidade",b="Comungar com a pedra serve como um rito fundamental para os desbravadores espirituais. Diferente da fúria inquieta do vento, do fogo ou das águas bravias, a terra ensina disciplina inabalável e resiliência silenciosa. Para ser aprovado no rito, o buscador deve absorver a essência serena da terra, preparando sua mente e seu corpo para as dualidades conflitantes e caóticas dos elementos mais voláteis que rugem pelo mundo."}},faq={{q="O que é o Earth Sapta?",a="O Earth Sapta é uma potente infusão mística criada com magia para vincular o espírito de um praticante diretamente aos elementos. Não se destina àqueles de vontade fraca, pois bebê-lo rompe a visão mortal comum e revela espíritos e verdades elementais que outros não conseguem perceber.",al={"o que é sapta","história de earth sapta","o que o sapta faz"}},{q="Onde o sapta deve ser consumido?",a="A infusão deve ser consumida apenas em um local sagrado dedicado. Neste rito, o praticante é orientado a seguir para o norte montanha acima por um caminho oculto a fim de localizar a ancestral Spirit Stone escondida entre os despenhadeiros.",al={"onde beber sapta","localização da spirit stone","onde fica a spirit stone"}},{q="Qual é o propósito do rito Call of Earth?",a="O Call of Earth é uma prova fundamental de comunhão e humildade. Ao beber o sapta na Spirit Stone, o iniciado aprende a extrair força das montanhas, paciência das planícies e a harmonizar seu espírito mortal com o mundo vivo antes de enfrentar elementos mais turbulentos.",al={"por que fazer esta missão","significado de call of earth","história de call of earth"}},{q="Quem sabe preparar o Earth Sapta?",a="Apenas alguns poucos xamãs iniciados possuem o conhecimento e a preparação espiritual necessários para preparar o sapta. Sua receita é guardada e tratada com grande reverência, pois a poção conecta a consciência mortal diretamente às forças primordiais.",al={"quem conhece a receita de sapta","qualquer um pode fazer sapta"}},{q="Como o elemento terra se diferencia dos outros elementos?",a="Enquanto outras forças elementais entram em conflito, ardem e rugem com violenta inquietação, o elemento terra representa serenidade inabalável, paciência e alicerce irredutível. Os iniciados devem primeiro aprender a humildade diante da pedra antes de confrontar a natureza dual volátil dos outros elementos.",al={"terra versus outros elementos","como a terra se compara a fogo água ar"}},{q="Em qual cenário este rito é realizado?",a="A missão se passa no alto de uma cordilheira fria e coberta de neve, onde os iniciados seguem por um caminho isolado serpenteando pela neve e pela rocha para comungar com os espíritos da terra, apesar do frio cortante.",al={"onde se passa call of earth","missão da terra em terra congelada"}}},fp="13,213,21.300.0,28.300.0,22.330.0,20.259.0,33.174.0,46.264.0,34.232.0,61.242.0,39.178.0"}
P.entries["quest:94375"] = {n="Call of Earth",s="Call of Earth é um rito de passagem elemental para jovens xamãs nas extensões nevadas de Dun Morogh. Ao comungar com os espíritos da terra locais, os iniciados recebem um Quartzo Grosseiro para levar a Teo Hammerstorm em Sidermar. Esta pedra simples comprova sua comunhão e serve como o núcleo de seu Totem da Terra.",h="Call of Earth é um rito de passagem elemental para jovens xamãs nas extensões nevadas de Dun Morogh.",kw={"sidermar","call of earth","vale cristálgida","dun morogh","totem da terra","quartzo grosseiro","xamã","teo hammerstorm","totem"},ang={["class:Shaman"]="Comungar com os espíritos da terra e conquistar um Totem da Terra é um rito de passagem fundamental para todo aspirante a xamã.",["faction:Alliance"]="Os ritos xamânicos realizados ao redor de Sidermar representam a crescente presença e orientação de espiritualistas elementais nas terras de Altaforja.",["race:Dwarf"]="Os laços dos anões com a pedra e a montanha são profundos, e comungar diretamente com os espíritos da terra em Dun Morogh une sua lapidação ancestral ao caminho xamânico."},sec={{t="A Pedra Sussurrante",b="O Call of Earth marca os primeiros passos de um iniciado no caminho espiritual do xamã em Dun Morogh. Nas profundezas dos picos congelados, um aspirante deve buscar o espírito da terra e ouvir seus ensinamentos. A provação exige humildade: o espírito concede apenas um Quartzo Grosseiro, uma simples pedra destinada a se tornar o coração pulsante de um Totem da Terra. Ela lembra ao buscador que a verdadeira resistência não é medida pela mera escala, mas pela paciência, força e determinação inabalável."},{t="O Favor da Montanha",b="Ao retornar a Sidermar com a pedra em mãos, Teo Hammerstorm julga o valor do iniciado. Como artesão e guia, Teo exige evidências inequívocas de que os espíritos da montanha reconheceram o buscador. Sem o Quartzo Grosseiro, o iniciado é dispensado sem cerimônia; com ele, Teo molda a pedra bruta em um Totem da Terra, vinculando o jovem xamã à força atemporal das raízes do mundo."}},faq={{q="Para que serve o Quartzo Grosseiro?",a="O Quartzo Grosseiro é concedido por um espírito elemental da terra como prova de comunhão. Embora pareça uma pedra modesta, serve como o coração essencial para confeccionar o seu Totem da Terra.",al={"propósito do quartzo grosseiro","o que é quartzo grosseiro","por que preciso de quartzo grosseiro"}},{q="Quem é Teo Hammerstorm?",a="Teo Hammerstorm é um mentor localizado em Sidermar, em Dun Morogh. Ele testa aspirantes a xamã, exigindo provas de comunhão elemental antes de confeccionar seus totens sagrados.",al={"quem é teo hammerstorm","localização de teo hammerstorm","onde fica teo"}},{q="O que é o Call of Earth?",a="Call of Earth é uma provação sagrada realizada por jovens xamãs para buscar comunhão com os espíritos da terra, demonstrar paciência e força e conquistar seu primeiro Totem da Terra.",al={"série de missões de call of earth","o que é call of earth","missão do totem da terra"}},{q="O que o espírito da terra pede ao iniciado?",a="O espírito da terra pede ao iniciado que permaneça forte, continue paciente e busque sabedoria. Ele ensina que até as menores coisas podem resistir mais que outras, e que o verdadeiro poder provém do respeito mútuo com a terra.",al={"lição do espírito da terra","o que a terra pede","filosofia da terra dos xamãs"}},{q="Onde fica Sidermar?",a="Sidermar é o assentamento anão situado no Vale Cristálgida, em Dun Morogh. Serve como campo de preparação onde jovens iniciados anões treinam e comungam com as montanhas ao redor.",al={"o que é sidermar","história de sidermar","onde ocorre call of earth"}},{q="Por que o Totem da Terra é importante?",a="Um totem age como um canal sagrado entre um xamã e os espíritos elementais. O Totem da Terra vincula a vontade do portador ao poder constante e à resiliência das montanhas.",al={"por que o totem importa","história dos totens de xamã","o que faz um totem da terra"}}},fp="13,190,20.342.0,20.329.0,29.111.0,23.159.0,26.107.0,47.186.0,26.129.0,33.140.0"}
P.entries["quest:944"] = {n="Glaive do Mestre",s="Esta missão envia aventureiros da Aliança ao sul através de Costa Negra para patrulhar a sinistra Glaive do Mestre em nome do anciente da tradição, Onu. O objetivo é investigar se o sombrio Martelo do Crepúsculo se infiltrou nos restos do antigo horror derrotado.",h="Esta missão envia aventureiros da Aliança ao sul através de Costa Negra para patrulhar a sinistra Glaive do...",kw={"costa negra","glaive do mestre","antigo senhor","onu","frasco de vidência","bacia de vidência","martelo do crepúsculo"},ang={["class:Druid"]="Os druidas atendem ao chamado de Onu para entender como a mácula antiga e adormecida, enterrada nas profundezas da terra, está perturbando as terras ao redor e sua fauna.",["faction:Alliance"]="As forças da Aliança em Costa Negra devem impedir que o Martelo do Crepúsculo desperte horrores ancestrais que poderiam devastar os assentamentos vulneráveis do norte de Kalimdor.",["race:NightElf"]="Para os elfos noturnos, a Glaive do Mestre é um lembrete sombrio dos terrores primordiais que antecederam sua civilização, e ver sectários insanos violando o solo sagrado de Costa Negra é uma profanação intolerável."},sec={{t="Uma Presença Perturbadora",b="Enquanto investiga a corrupção persistente e a fauna deslocada ao longo de Costa Negra, o anciente da tradição Onu nota pistas alarmantes. Os nagas pela costa já causam problemas suficientes, mas a presença do Martelo do Crepúsculo é muito mais sinistra. Esta seita fanática não adora poderes sombrios comuns; eles veneram os antigos senhores primordiais do mundo, derrubados em eras passadas."},{t="O Senhor Caído",b="Mais ao sul fica a Glaive do Mestre, uma escavação sombria centrada em torno de uma criatura colossal empalada por uma imensa arma de pedra. Onu fornece um Frasco de Vidência e encarrega os batedores de entrar no fosso para confirmar se os sectários se reuniram ali. Como Onu alerta, mesmo que o gigante empalado esteja morto há eras, fragmentos de seu poder antigo e corruptor ainda permanecem em seus ossos — um prêmio irresistível para o Martelo do Crepúsculo."}},faq={{q="Quem me envia nesta missão?",a="A missão é concedida por Onu, um venerável anciente da tradição situado ao longo da estrada no sul de Costa Negra, perto do Bosque dos Ancientes.",al={"iniciador da missão","quem dá a missão glaive do mestre","pnj inicial"}},{q="O que é a Glaive do Mestre?",a="A Glaive do Mestre é um local antigo no sul de Costa Negra onde um monstruoso senhor ancestral caiu eras atrás, empalado no crânio por uma glaive de pedra titânica. Seu enorme esqueleto petrificado continua cravado na terra.",al={"o que é glaive do mestre","história da glaive do mestre","crânio gigante em costa negra"}},{q="Por que o Martelo do Crepúsculo tem interesse no local?",a="O Martelo do Crepúsculo adora os antigos poderes sombrios de outrora de Azeroth. Mesmo que a criatura titânica empalada na glaive esteja morta há muito tempo, vestígios e fragmentos adormecidos de seu poder primordial permanecem em seus restos, os quais os sectários buscam desesperadamente controlar.",al={"seita do crepúsculo em costa negra","por que os sectários do crepúsculo estão aqui","martelo do crepúsculo glaive do mestre"}},{q="Como entrego o relatório para Onu?",a="Você não precisa caminhar de volta até a localização física de Onu. Depois de explorar o fosso de escavação da Glaive do Mestre, use o Frasco de Vidência em suas bolsas para conjurar uma Bacia de Vidência no chão, permitindo que você fale diretamente com Onu por meio de magia.",al={"onde entregar a missão","como usar frasco de vidência","bacia de vidência"}},{q="O que vem depois desta missão de reconhecimento?",a="Depois que você usar a Bacia de Vidência para confirmar a presença dos sectários, Onu imediatamente o direciona para o acampamento deles na missão 'The Twilight Camp' para descobrir mais detalhes sobre suas atividades.",al={"próxima missão","continuação de glaive do mestre"}}},fx={fcbe4ca5={q="Por que Onu envia você para investigar a The Master's Glaive?",a="Onu está profundamente inquieto com a presença do Martelo do Crepúsculo em Costa Negra. Como um antigo ancestral do saber vigiando os bosques, ele sabe que este culto niilista venera os Deuses Antigos derrotados da terra. A The Master's Glaive marca o antigo local de descanso de uma dessas monstruosidades caídas, e Onu teme que, mesmo na morte, remanescentes do poder sombrio persistente da entidade possam ser desenterrados e usados pelos cultistas.",al={"por que onu quer isso","motivo de onu sobre the master's glaive","por que explorar the master's glaive"}},["821e537b"]={q="Quem você foi enviado para investigar na The Master's Glaive?",a="Você foi enviado para reconhecer os cultistas do Martelo do Crepúsculo à espreita ao redor do monumento maciço. Esses fanáticos reverenciam poderes primordiais e antigos que já governaram Azeroth. Eles se reuniram no poço cavernoso da The Master's Glaive para aproveitar qualquer essência sobrenatural ou força remanescente que ainda irradie do crânio petrificado do ser antigo morto ali.",al={"alvo na the master's glaive","quem estou procurando na the master's glaive","quem está na the master's glaive"}},dfa4afd6={q="Por que Onu precisa que você explore a The Master's Glaive em vez de ir ele mesmo?",a="Onu é um ancestral do saber maciço e enraizado que não pode facilmente esgueirar-se sem ser notado para dentro do desfiladeiro profundo da The Master's Glaive. Além disso, as forças de elfos noturnos de Costa Negra estão sobrecarregadas lidando com os naga que avançam pela costa e a corrupção por toda a natureza. Um viajante ágil e capaz, armado com um Frasco de Vidência, pode explorar silenciosamente o acampamento dos cultistas e relatar magicamente de volta sem atrair atenção indesejada.",al={"por que eu, onu","por que me enviar à the master's glaive","por que onu não explora a the master's glaive"}}},fp="19,162,21.256.0,15.334.0,29.119.0,28.172.0,57.180.0,28.187.0,32.147.0"}
P.entries["quest:94411"] = {n="Meddlesome Mages",s="Meddlesome Mages centra-se no aumento do atrito no Planalto de Shen'dar, onde aprendizes da Alta Ordem invadem as proximidades de menires sagrados. Guardiões locais devem afugentá-los para proteger as delicadas forças místicas que mantêm sua ilha unida contra a manipulação arcana imprudente.",h="Meddlesome Mages centra-se no aumento do atrito no Planalto de Shen'dar, onde aprendizes da Alta Ordem...",kw={"intromissão arcana","alta ordem","aprendizes da alta ordem","meddlesome mages","planalto de shen'dar","shen'dorei","menires"},ang={["class:Mage"]="Os magos notarão a crítica contundente ao lançamento imprudente de feitiços; os aprendizes da Alta Ordem desconsideram o delicado equilíbrio ambiental que mantém a ilha unida, evidenciando os perigos da manipulação arcana desmedida."},sec={{t="Invasão nos Menires",b="As tensões aumentaram ao norte da aldeia no Planalto de Shen'dar, onde aprendizes da Alta Ordem se reuniram ao redor de antigos menires. Apesar dos repetidos avisos para não perturbar esses locais sagrados, os magos continuaram com seus interesses arcanos. A liderança local, embora hesitante em derramar o sangue de seus parentes shen'dorei, pediu intervenção externa para dispersar os aprendizes invasores antes que sua interferência cause danos permanentes."},{t="A Ilha Frágil",b="A urgência por trás de expulsar a Alta Ordem decorre do delicado equilíbrio que sustenta a ilha. As forças místicas que unem a terra são frágeis, deixando a pátria vulnerável a magias imprudentes. Para os defensores dos menires, a Alta Ordem demonstra total desrespeito pelos perigos de sua intromissão, o que significa que até mesmo um único feitiço descuidado poderia romper os laços da ilha e trazer a ruína a todos que ali habitam."}},faq={{q="Sobre o que é a missão Meddlesome Mages?",a="Meddlesome Mages é uma tarefa que pede aos aventureiros que confrontem e dispersem Aprendizes da Alta Ordem que invadiram menires sagrados ao norte da aldeia no Planalto de Shen'dar.",al={"o que é meddlesome mages","missão meddlesome mages","o que é esta missão"}},{q="Quem são os Aprendizes da Alta Ordem?",a="A Alta Ordem é uma facção de magos, descritos como irmãos e irmãs shen'dorei dos habitantes locais, cujos aprendizes estão invadindo terras sagradas e fazendo experimentos com magia, apesar dos avisos para ficarem longe.",al={"quem são os aprendizes da alta ordem","o que é a alta ordem","magos da alta ordem"}},{q="Por que os Aprendizes da Alta Ordem devem ser dispersados?",a="A Alta Ordem ignorou repetidamente os avisos para evitar os menires. Sua manipulação mágica imprudente ameaça as frágeis forças arcanas que unem a ilha, arriscando uma destruição catastrófica para a terra natal local.",al={"por que dispersar a alta ordem","por que lutar contra os aprendizes","problema dos menires"}},{q="Onde os Aprendizes da Alta Ordem estão se reunindo?",a="O confronto ocorre nos menires localizados ao norte da aldeia local dentro do Planalto de Shen'dar.",al={"onde fica esta missão","localização do planalto de shen'dar","menires ao norte da aldeia"}},{q="Quem são os shen'dorei mencionados na missão?",a="Os shen'dorei são parentes do povo de quem concede a missão. Embora o conflito interno enfraqueça a comunidade que compartilham, os líderes locais se sentem forçados a tomar medidas decisivas contra a Alta Ordem para evitar um desastre.",al={"quem são os shen'dorei","irmãos e irmãs shen'dorei","o que são shen'dorei"}},{q="Que perigo os magos representam para a ilha?",a="As forças que mantêm a ilha unida são delicadas e vulneráveis. A intromissão descontrolada de praticantes arcanos pode desestabilizar essas amarras, potencialmente destruindo a ilha por completo.",al={"qual é o perigo","forças frágeis da ilha","o que poderia acontecer com a ilha"}}},fp="16,168,26.347.0,18.259.0,41.133.0,35.191.0,49.195.0,47.100.0,46.196.0,44.133.0"}
P.entries["quest:94413"] = {n="A Magical Affront",s="A Magical Affront é uma missão em Zephras focada em um confronto por conta de linhas de ley que emergiram recentemente na superfície. Enquanto uma ordem local busca controlar e estudar as energias arcanas expostas, os Moldavento encaram essas fendas como cicatrizes na terra que devem ser curadas, desencadeando um conflito direto na floresta a sudoeste.",h="A Magical Affront é uma missão em Zephras focada em um confronto por conta de linhas de ley que emergiram...",kw={"a magical affront","arcano","linha de ley","linhas de ley","cicatrizes","moldavento","zephras"},ang={["class:Druid"]="Druidas podem se ver em meio a uma tensão filosófica, já que os Moldavento veem as linhas de ley expostas como cicatrizes profundas na paisagem natural que necessitam desesperadamente de cura.",["class:Mage"]="Para os praticantes do arcano, o afloramento das linhas de ley em Zephras oferece um raro acesso direto à energia mística pura, tornando a preservação delas uma questão de grande interesse acadêmico e mágico.",["class:Shaman"]="Os Moldavento buscam acalmar e curar as perturbações por toda Zephras, colocando sua tutela elemental e natural em confronto direto com ordens que aproveitam os fluxos de magia pura."},sec={{t="Correntes Reveladas",b="Na superfície de Zephras, antigos condutos subterrâneos de magia pura romperam a terra recentemente. Para os estudiosos e praticantes da ordem local, essa emergência é uma dádiva inestimável. O contato direto e tangível com as linhas de ley concede a eles uma percepção sem precedentes sobre as correntes arcanas que permeiam a região, expandindo amplamente seu domínio mágico."},{t="Cicatrizes e Discórdia",b="Nem todos encaram as energias expostas como um milagre. Os Moldavento veem as fendas como feridas abertas e cicatrizes destrutivas rasgadas pela superfície de Zephras. Determinados a curar a terra ferida, eles se reúnem nos locais das rupturas para conter ou regenerar as linhas de ley expostas. Para a ordem que depende desse poder bruto, essa interferência é uma ameaça intolerável, levando-a a enviar aventureiros a sudoeste floresta adentro para repelir os Moldavento."}},faq={{q="Quem são os Moldavento?",a="Os Moldavento são um grupo ativo em Zephras que enxerga as linhas de ley que emergiram na superfície não como uma dádiva de energia pura, mas como feridas não naturais ou cicatrizes na terra que precisam ser curadas. Seus esforços os colocam em oposição direta às ordens que buscam estudar e canalizar as linhas de ley.",al={"quem são os moldavento","o que são moldavento","moldavento zephras"}},{q="Por que a ordem quer expulsar os Moldavento?",a="Uma ordem que estuda as linhas de ley em Zephras precisa ter acesso ao poder que emergiu à superfície para avançar sua compreensão mística. Como os Moldavento tentam ativamente \"curar\", fechar ou reparar essas linhas de ley, a ordem enxerga essas ações como uma afronta intolerável e exige que eles sejam expulsos.",al={"por que matar os moldavento","por que enfrentar os moldavento","conflito dos moldavento"}},{q="O que são as linhas de ley em Zephras?",a="As linhas de ley são condutos de energia mística que atravessam o mundo. Em Zephras, esses canais romperam recentemente a superfície, expondo um poder mágico direto que permeia a terra e garantindo aos praticantes do arcano um acesso sem precedentes para estudá-lo.",al={"o que são linhas de ley zephras","linhas de ley de zephras","linhas de ley na superfície"}},{q="Onde fica a linha de ley disputada?",a="A linha de ley disputada mencionada nesta tarefa fica dentro da floresta a sudoeste em Zephras, onde Moldavento se reuniram para começar a fechar ou regenerar a torrente mágica exposta.",al={"onde fica a floresta da linha de ley","localização da linha de ley","floresta a sudoeste"}},{q="Por que os Moldavento consideram as linhas de ley cicatrizes?",a="Os Moldavento veem a ruptura repentina e o surgimento de energias subterrâneas puras através da terra como violentas cicatrizes por toda Zephras. Do ponto de vista deles, restaurar o equilíbrio natural exige fechar essas fendas, contrariando diretamente os conjuradores arcanos que desejam mantê-las abertas.",al={"por que os moldavento querem curar as linhas de ley","as linhas de ley são prejudiciais zephras","curando as cicatrizes"}},{q="Qual é a importância de Zephras neste conflito?",a="Zephras é a terra onde essas linhas de ley expostas emergiram. O surgimento repentino de poder mágico puro em sua superfície fez dela um ponto de conflito entre aqueles que buscam dominar suas energias arcanas e aqueles que as consideram rupturas não naturais que necessitam de restauração.",al={"o que é zephras","onde a magical affront acontece","história de zephras"}}},fp="17,236,17.287.0,16.313.0,24.195.0,51.208.0,33.200.0,39.139.0,51.254.0,53.214.0"}
P.entries["quest:94414"] = {n="As âncoras de Zephras",s="As âncoras de Zephras é uma missão introdutória oferecida por Halaan Hawk-Eye na Ilha de Zefras. Halaan convida os viajantes a pegar emprestada sua visão de longo alcance para observar os antigos pilones de ancoragem que prendem e preservam a ilha flutuante. Embora os imponentes monólitos pareçam intocados à distância, Halaan alerta que a magia estabilizadora dos espíritos dos ventos começou a vacilar.",h="As âncoras de Zephras é uma missão introdutória oferecida por Halaan Hawk-Eye na Ilha de Zefras.",kw={"pilone de ancoragem","âncoras de zefras","halaan hawk-eye","linhas de meridiano","visão celeste","espíritos dos ventos","zefras"},ang={["class:Mage"]="Halaan distingue sua visão aguçada da magia daqueles capazes de recorrer às linhas de meridiano sob Zephras.",["class:Shaman"]="Os pilones de ancoragem dependem diretamente da bênção dos espíritos dos ventos, tornando qualquer instabilidade em sua magia uma questão elemental urgente para os xamãs que buscam manter o equilíbrio."},sec={{t="Amarras da Ilha",b="Os pilones de ancoragem de Zephras são monólitos antigos e imponentes concedidos pelos espíritos dos ventos. Profundamente integrados à fundação mística da ilha, eles servem para prender, estabilizar e sustentar a massa terrestre em meio aos céus turbulentos. Olhar para um deles é testemunhar o frágil equilíbrio que mantém Zephras no ar, dependendo continuamente da benevolência dos espíritos dos ventos."},{t="Uma Mudança Preocupante",b="Apesar de se manterem altivos e intactos a olho nu, os pilones de ancoragem tornaram-se erráticos. Halaan Hawk-Eye observa que a harmonia mágica que os sustenta tornou-se instável e inconsistente nos últimos tempos. Sem sinais claros de desgaste físico, essa sutil deterioração gera um alarme silencioso entre aqueles que cuidam dos bosques, sugerindo desequilíbrios mais profundos que ameaçam a ilha."},{t="O Dom de Halaan",b="Desprovido da inata visão celeste que perscruta através dos mundos ou da proeza arcana para acessar as profundas linhas de meridiano de Zephras, Halaan possui um dom natural mais simples e afiado: uma visão aguçada e límpida por imensas distâncias. Ao compartilhar essa perspectiva, ele permite que outros observem os pilones distantes em detalhes minuciosos, encorajando os recém-chegados a cultivarem gratidão pelo presente enquanto permanecem atentos ao destino incerto de sua terra natal."}},faq={{q="O que são os pilones de ancoragem em Zephras?",a="Os pilones de ancoragem são antigas estruturas místicas concedidas pelos espíritos dos ventos. Eles prendem, ancoram e sustentam magicamente a ilha de Zephras, mantendo-a estável sobre o mundo ao redor.",al={"o que são as âncoras","pilone de ancoragem de zefras","o que é um pilone de ancoragem"}},{q="O que há de errado com os pilones de ancoragem?",a="Embora os pilones não apresentem danos físicos óbvios ou deterioração externa, sua magia estabilizadora tornou-se recentemente instável e inconsistente, gerando preocupação sobre o que estaria perturbando silenciosamente seu vínculo.",al={"por que as âncoras estão falhando","problema no pilone de ancoragem","o que aconteceu com as âncoras"}},{q="Quem é Halaan Hawk-Eye?",a="Halaan Hawk-Eye é um vigia que reside nos bosques da Ilha de Zefras. Abençoado com uma visão natural aguçada e de longo alcance, ele monitora a saúde da terra e pondera sobre o bem-estar místico da ilha.",al={"história de halaan","quem é halaan"}},{q="Qual é o dom de Halaan?",a="O dom de Halaan é uma visão de longa distância excepcionalmente aguçada. Ao contrário dos místicos que usam a visão celeste para perscrutar entre mundos ou canalizar as energias das linhas de meridiano, o poder de Halaan é natural e mundano, permitindo-lhe perceber marcos distantes com perfeita clareza.",al={"o dom de halaan","como halaan enxerga longe"}},{q="O que é visão celeste?",a="A visão celeste é uma percepção mística possuída por certos praticantes em Zephras que lhes permite atravessar o véu e perscrutar diretamente entre os mundos, superando em muito a visão física comum.",al={"o que é a visão celeste","significado de visão celeste"}},{q="De onde vem a magia que energiza os pilones?",a="Os pilones de ancoragem foram concedidos a Zephras pelos espíritos dos ventos. Halaan diz que os pilones prendem e sustentam a ilha, mas não explica a fonte de seu poder contínuo.",al={"quem fez os pilones","origem do pilone de ancoragem"}}},fx={["61bc2f74"]={q="Por que Halaan Hawk-Eye quer que você olhe para o pilão de ancoragem?",a="Halaan Hawk-Eye vigia o bosque e se preocupa profundamente com a saúde de Zephras. Os antigos pilões de ancoragem, presentes dos espíritos dos ventos, unem e sustentam a ilha, mas sua magia tornou-se recentemente instável e inconsistente. Embora pareçam fisicamente intactos, Halaan se oferece para compartilhar sua visão de longo alcance para que você possa testemunhar os pilões em primeira mão e entender o estado delicado de sua terra natal.",al={"motivo de halaan","por que olhar para o pilão de ancoragem","por que halaan quer isso"}}},fp="22,192,19.274.0,18.282.0,13.287.0,38.155.0,37.135.0,23.142.0,22.148.0,17.114.0,51.159.0"}
P.entries["quest:94427"] = {n="A Lesson in Divinity",s="Sua ordem envia você até Tanis Alderwood no Trade Quarter da Cidade Baixa. A necessidade de Tanis oferece a chance de demonstrar graça por meio de boas ações.",h="Sua ordem envia você até Tanis Alderwood no Trade Quarter da Cidade Baixa.",kw={"uma lição sobre divindade","divindade","graça","pedir esmolas","tanis alderwood","trade quarter","cidade baixa"},ang={["class:Priest"]="Como Sacerdote, sua ordem define divindade como fazer o bem por si mesmo e diz que a tragédia pode ameaçar a graça que definiu você em vida."},sec={{t="Um Chamado à Graça",b="Sua ordem ensina que divindade significa buscar o bem por si mesmo, não buscar a condição de divindade. Ela diz que uma tragédia trouxe você a este lugar e pede que procure Tanis Alderwood no Trade Quarter da Cidade Baixa. Tanis está precisando de ajuda e pode se beneficiar da sua graça."},{t="O Pedido de Tanis",b="Quando você se aproxima de Tanis, Tanis teme que você possa lhe fazer mal. Tanis diz que não tem desavenças com você nem com sua ordem e implora que você o deixe em paz."}},faq={{q="Quem é Tanis Alderwood?",a="Tanis Alderwood é alguém que precisa de ajuda no Trade Quarter da Cidade Baixa.",al={"tanis","quem é tanis","pessoa no trade quarter"}},{q="Por que fui enviado até Tanis?",a="Sua ordem diz que Tanis pode se beneficiar da sua graça.",al={"por que tanis","ajudar tanis","qual é o sentido"}},{q="O que divindade significa para minha ordem?",a="Significa buscar o bem por si mesmo, em vez de buscar a condição de divindade.",al={"significado de divindade","bem por si mesmo","o que é divindade"}},{q="Onde posso encontrar Tanis Alderwood?",a="Tanis Alderwood fica no Trade Quarter da Cidade Baixa.",al={"localização de tanis","onde fica tanis","trade quarter"}}},fp="20,127,16.244.0,14.156.1,23.66.0,23.60.0,36.88.0,33.60.0"}
P.entries["quest:94434"] = {n="A Lesson in Divinity",s="Tanis Alderwood pede tecido limpo na Cidade Baixa. Sua esposa está se desmanchando, e ele espera que uma faixa a mantenha inteira até que um boticário fique livre.",h="Tanis Alderwood pede tecido limpo na Cidade Baixa.",kw={"uma lição de divindade","boticários","mendigo","dama sombria","tecido de linho","tanis alderwood","cidade baixa","esposa"},sec={{t="O apelo de um mendigo",b="Tanis diz que os boticários estão ocupados com os assuntos da Dama Sombria. Ele pede que você lhe traga linho para enfaixar a esposa enquanto esperam por ajuda. O estado dela é o que importa agora."}},faq={{q="Quem está pedindo ajuda?",a="Tanis Alderwood, um mendigo da Cidade Baixa, pede que você ajude a esposa dele.",al={"quem é tanis","tanis alderwood","homem mendigo"}},{q="O que há de errado com a esposa de Tanis?",a="Tanis diz que ela está literalmente se desmanchando e precisa de uma faixa para mantê-la inteira.",al={"esposa se desmanchando","o que aconteceu com a esposa dele","esposa de tanis"}},{q="Por que os boticários não podem ajudar?",a="Tanis diz que os boticários estão ocupados com os assuntos da Dama Sombria.",al={"boticários ocupados","por que não há boticário","assuntos da dama sombria"}},{q="Do que Tanis precisa?",a="Tanis pede que você lhe traga tecido limpo para que possa enfaixar a esposa enquanto esperam pelos boticários.",al={"de que tecido ele precisa","linho para tanis","ajudar mendigo"}}},fp="20,140,15.175.0,23.70.0,31.84.0,32.71.0,21.97.0"}
P.entries["quest:94435"] = {n="A Lesson in Divinity",s="Tanis Alderwood agradece por você tê-lo ajudado e o chama de amigo. Danitha Morr vê nesse pequeno gesto uma forma de fortalecer a ligação dos Renegados com a Luz.",h="Tanis Alderwood agradece por você tê-lo ajudado e o chama de amigo.",kw={"uma lição de divindade","danitha morr","dama sombria","renegados","luz","desconfiança","símbolo","tanis alderwood"},ang={["faction:Alliance"]="Como viajante da Aliança, você ouve Danitha descrever o esforço dos Renegados para ajudar seu povo a prosperar novamente.",["race:Undead"]="Como Renegado, você ouve Danitha pedir coragem e retidão para ajudar seu povo a prosperar novamente."},sec={{t="Um Pequeno Favor",b="Danitha Morr diz que sua ajuda pode fortalecer a ligação dos Renegados com a Luz. Ela fala da desconfiança e das conspirações entre os seguidores da Dama Sombria, e de enfrentar esse medo com coragem e retidão. Ela lhe dá um símbolo para o que vem a seguir."}},faq={{q="Quem está me agradecendo?",a="Tanis Alderwood agradece por você tê-lo ajudado e diz que você sempre terá um amigo nele.",al={"tanis alderwood","quem é tanis","tanis agradece"}},{q="O que Danitha diz que minha ajuda significa?",a="Danitha diz que até um pequeno gesto de serviço pode fortalecer a ligação dos Renegados com a Luz.",al={"por que ajudar danitha","significado de pequeno gesto","ligação com a luz"}},{q="Por que Danitha menciona a desconfiança?",a="Danitha diz que a Dama Sombria e alguns de seus seguidores desconfiam deles, e que alguns até conspiram contra eles.",al={"desconfiança dos renegados","medo da dama sombria","por que desconfiam deles"}},{q="O que Danitha me dá?",a="Danitha lhe dá um símbolo para o que vem a seguir.",al={"qual símbolo","item de danitha","símbolo para o que vem a seguir"}}},fp="20,167,15.256.0,19.89.0,36.95.0,34.107.0,26.47.0"}
P.entries["quest:94436"] = {n="A Lesson in Divinity",s="Danitha Morr pede que você mostre o que um Sacerdote pode fazer com o Símbolo da Vida. Deathguard Billmuth, na Bastilha de Bandarion, veio buscar ajuda para um amigo.",h="Danitha Morr pede que você mostre o que um Sacerdote pode fazer com o Símbolo da Vida.",kw={"uma lição de divindade","bastilha de bandarion","danitha morr","deathguard billmuth","renegados","luz","sacerdote","símbolo da vida"},ang={["class:Priest"]="Como Sacerdote, Danitha pede que você demonstre sua capacidade de canalizar a Luz com o Símbolo da Vida."},sec={{t="Um Pedido de Ajuda",b="Billmuth diz que os sacerdotes o mandaram embora, e talvez o amigo dele não tenha mais ninguém para ajudar. Ele não se orgulha de pedir isso a você, mas precisa de ajuda para os Renegados. O Símbolo da Vida deve ajudar você a demonstrar sua capacidade de canalizar a Luz, embora manuseá-lo possa causar desconforto. Seu poder é um aliado e um guia, até mesmo para os Renegados, cuja criação está ligada a uma força que se opõe a ele."}},faq={{q="Quem está pedindo ajuda?",a="Deathguard Billmuth, na Bastilha de Bandarion, veio buscar ajuda para um amigo.",al={"ajuda para billmuth","quem precisa de ajuda"}},{q="Por que Billmuth pede ajuda a um sacerdote?",a="Billmuth diz que os sacerdotes o mandaram embora, e você pode ser a única chance de ajuda para o amigo dele.",al={"por que sacerdote","sacerdotes o mandaram embora"}},{q="O que é o Símbolo da Vida?",a="É um talismã da Luz que Danitha Morr lhe entrega para demonstrar sua capacidade de canalizar a Luz.",al={"símbolo da vida","talismã da luz"}},{q="Por que manusear o Símbolo da Vida pode causar dor?",a="Danitha avisa que o talismã pode causar desconforto porque a Luz se opõe à força que criou os Renegados.",al={"dor do símbolo","luz machuca"}},{q="Onde encontro Deathguard Billmuth?",a="Deathguard Billmuth fica no andar de baixo da Bastilha de Bandarion.",al={"localização de billmuth","bastilha de bandarion"}}},fp="20,173,14.380.0,23.73.0,31.83.0,27.116.0,44.121.0,37.52.0"}
P.entries["quest:94438"] = {n="A Lesson in Divinity",s="Danitha Morr pede que você encontre Deathguard Falgan no Vale Veneracnídeo. Ele e um companheiro descobriram ordens da Cruzada Escarlate para atacar Montalvo antes de se separarem.",h="Danitha Morr pede que você encontre Deathguard Falgan no Vale Veneracnídeo.",kw={"uma lição de divindade","billmuth","montalvo","danitha morr","deathguard falgan","cruzada escarlate","símbolo da vida","vale veneracnídeo"},sec={{t="O retorno de Falgan",b="Falgan foi enviado com Billmuth para investigar a atividade da Cruzada Escarlate no Vale Veneracnídeo. Ele diz que descobriram que a Cruzada Escarlate planeja algum tipo de ataque e pergunta se você ajudará os Renegados ainda mais."}},faq={{q="Quem está me pedindo para encontrar Falgan?",a="Danitha Morr pede que você encontre Deathguard Falgan e o ajude, se puder.",al={"quem me enviou","danitha morr","doador da missão"}},{q="Onde está Falgan?",a="Falgan está no Vale Veneracnídeo.",al={"localização de falgan","onde está falgan","encontrar deathguard"}},{q="O que aconteceu com Falgan?",a="Falgan ficou para trás depois que um ruído alertou as forças da Cruzada Escarlate sobre ele e seu companheiro. O companheiro dele chegou a Montalvo sem ele.",al={"falgan desaparecido","o que aconteceu","salvar falgan"}},{q="O que Falgan e Billmuth descobriram?",a="Eles descobriram que a Cruzada Escarlate planeja algum tipo de ataque.",al={"ordens da cruzada escarlate","o que descobriram","planos de ataque"}},{q="Para que serve o Símbolo da Vida?",a="O Símbolo da Vida é usado para trazer Deathguard Falgan de volta à vida.",al={"ressuscitar falgan","símbolo da vida","como salvar falgan"}},{q="O que Falgan pede depois de retornar?",a="Falgan pergunta se você está disposto a ajudar ainda mais os Renegados.",al={"ajudar os renegados","o que vem a seguir","pedido de falgan"}}},fp="20,163,15.200.0,32.72.0,16.27.0,24.124.0,38.79.0,31.67.0,37.82.0"}
P.entries["quest:94440"] = {n="A Lesson in Divinity",s="Deathguard Billmuth pede que você recupere os planos de ataque da Cruzada Escarlate no Vale Veneracnídeo. Os planos podem ajudar os Deathguard a se preparar para um ataque esperado.",h="Deathguard Billmuth pede que você recupere os planos de ataque da Cruzada Escarlate no Vale Veneracnídeo.",kw={"uma lição de divindade","planos de ataque","bastilha de bandarion","deathguard billmuth","renegados","cruzada escarlate","vale veneracnídeo"},sec={{t="Ordens para a Bastilha",b="Os membros da Cruzada Escarlate carregam ordens de mobilização nas bolsas, e os Deathguard esperam um ataque. Pedem que você leve uma cópia dos planos a Deathguard Billmuth na Bastilha de Bandarion para que os Deathguard possam preparar uma emboscada."},{t="Um amigo salvo",b="Billmuth agradece por você ter salvado o amigo dele e diz que levará os planos ao comandante. Ele também diz que suas ações mostraram que você é Renegado até o fundo da alma, apesar da desconfiança que alguns de seu povo sentem pela sua classe."}},faq={{q="Do que Billmuth precisa?",a="Deathguard Billmuth pede que você recupere os planos de ataque da Cruzada Escarlate no Vale Veneracnídeo.",al={"o que billmuth quer","planos de billmuth","planos para billmuth"}},{q="Onde estão os planos de ataque?",a="Os membros da Cruzada Escarlate no Vale Veneracnídeo carregam os planos de ataque.",al={"onde estão os planos","localização dos planos escarlates","encontrar planos de ataque"}},{q="Por que os Deathguard querem os planos?",a="Os Deathguard esperam um ataque e querem os planos para preparar uma emboscada.",al={"por que pegar os planos","para que servem os planos","emboscada dos deathguard"}},{q="Quem deve receber os planos?",a="Leve os planos a Deathguard Billmuth na Bastilha de Bandarion.",al={"quem recebe os planos","devolver os planos para","onde está billmuth"}}},fp="20,172,19.209.0,14.221.1,24.94.0,27.62.0,39.81.0,29.57.0"}
P.entries["quest:94441"] = {n="A Lesson in Divinity",s="Uma Renegada pede que você agradeça a Danitha Morr pelo serviço prestado pelos paladinos da Bastilha de Bandarion. Seu trabalho conquistou a gratidão da Guarda da Morte e lhe traz um presente de redenção.",h="Uma Renegada pede que você agradeça a Danitha Morr pelo serviço prestado pelos paladinos da Bastilha de...",kw={"uma lição de divindade","bastilha de bandarion","danitha morr","guarda da morte","renegados","luz","redenção","símbolo da vida"},sec={{t="Agradecimentos na Bastilha",b="Uma Renegada pede que você leve seus agradecimentos a Danitha Morr, na Bastilha de Bandarion. O restante da Guarda da Morte ficará sabendo do serviço que você e os outros paladinos prestaram. Eles têm orgulho de contar com você entre os Renegados e confiam que a Dama Sombria vela por você."},{t="Um presente de luz",b="Danitha diz que o Símbolo da Vida pode ser usado por um paladino pronto para receber uma das maiores bênçãos da Luz. Ela lhe concede o presente da redenção, que permite ressuscitar companheiros caídos. Seu serviço é importante tanto para os Renegados quanto para os paladinos da Bastilha de Bandarion, e a Guarda da Morte espera que atos assim conquistem os corações e as mentes dos demais Renegados."}},faq={{q="A quem devo agradecer?",a="Pedem que você agradeça a Danitha Morr, na Bastilha de Bandarion, pelo serviço prestado pelos paladinos de lá.",al={"quem é danitha","agradecer a danitha","danitha morr"}},{q="Quem ficará sabendo do serviço?",a="O restante da Guarda da Morte ficará sabendo do serviço prestado pelos paladinos da Bastilha de Bandarion.",al={"agradecimentos da guarda da morte","quem ficará sabendo","serviço na bastilha"}},{q="O que o Símbolo da Vida faz?",a="O Símbolo da Vida é para um paladino pronto para fazer uso de uma das maiores bênçãos da Luz.",al={"símbolo da vida","o que faz","o que isso faz"}},{q="Por que a Guarda da Morte tem orgulho de mim?",a="Eles têm orgulho de contar com você entre os Renegados e valorizam o serviço que você prestou com os paladinos da Bastilha de Bandarion.",al={"orgulho dos renegados","por que tem orgulho","orgulho da guarda da morte"}}},fp="20,178,18.262.0,15.335.1,15.82.0,32.82.0,32.101.0,34.129.0"}
P.entries["quest:94449"] = {n="Call of Fire",s="Call of Fire é uma missão xamânica que guia os iniciados ao perigoso e caótico reino das chamas nas alturas de Dun Morogh. Tendo dominado as lições pacientes da terra, o praticante é orientado a procurar Bruegs Kindleborn para testar sua prontidão para a Sapta do Fogo.",h="Call of Fire é uma missão xamânica que guia os iniciados ao perigoso e caótico reino das chamas nas alturas...",kw={"bruegs kindleborn","call of fire","dun morogh","earth sapta","totem do fogo","sapta do fogo","xamã","posto de guarda do portão sul"},ang={["class:Shaman"]="Esta missão marca uma provação espiritual crítica para o xamã, fazendo a transição da resistência da pedra para o poder feroz e destrutivo do fogo.",["faction:Alliance"]="Com a provação situada nas montanhas de Dun Morogh, os xamãs da Aliança seguem a orientação de seus anciãos para despertar a comunhão com os elementos do fogo.",["race:Dwarf"]="Realizado no alto acima do Posto de Guarda do Portão Sul em Dun Morogh, este rito testa se um anão tem a disciplina necessária para moderar a fome ardente da chama."},sec={{t="O Julgamento Flamejante",b="Após provar paciência e estabilidade por meio do elemento da terra, os xamãs são orientados a confrontar uma força muito mais volátil: o espírito elemental do fogo. Ao contrário da pedra estável e inflexível, o fogo chama com promessas de caos, ruína e energia feroz. Um ancião envia o iniciado através dos picos cobertos de neve de Dun Morogh para buscar orientação antes de tentar controlar esse calor selvagem."},{t="O Recluso dos Picos",b="No alto das montanhas acima do Posto de Guarda do Portão Sul, o mentor Bruegs Kindleborn vigia a partir de uma caverna isolada. Quando um iniciado chega com a recomendação de um ancião, Bruegs o prepara para a sapta de fogo. No entanto, ele faz um aviso severo: a ânsia de queimar e consumir é facilmente despertada, mas dominar a chama exige saber exatamente a hora de conter o ímpeto."}},faq={{q="Quem é Bruegs Kindleborn?",a="Bruegs Kindleborn é um mentor que reside em uma caverna nas montanhas, bem acima do Posto de Guarda do Portão Sul, em Dun Morogh. Ele avalia os xamãs enviados por anciãos para determinar se possuem a maturidade e a disciplina necessárias para receber a Sapta do Fogo.",al={"quem é bruegs kindleborn","história de bruegs kindleborn","onde fica bruegs"}},{q="O que é a sapta de fogo?",a="Uma sapta é uma poção ou preparação elemental que permite ao xamã comungar com os espíritos desse elemento. A sapta de fogo concede comunhão com a chama e seu poder bruto, exigindo foco mental e prévia estabilidade na pedra.",al={"o que é a sapta do fogo","sapta do fogo","significado de sapta"}},{q="Onde Bruegs Kindleborn está localizado?",a="Bruegs Kindleborn pode ser encontrado no extremo leste das montanhas nevadas de Dun Morogh, abrigado em uma caverna com vista para o Posto de Guarda do Portão Sul.",al={"onde encontrar bruegs kindleborn","caverna do posto de guarda do portão sul","onde entregar call of fire"}},{q="Qual é o propósito de Call of Fire?",a="Call of Fire é um rito de passagem para xamãs que demonstraram paciência e dominaram a terra. Ele os chama a confrontar o poder caótico da destruição sob o olhar vigilante de Bruegs Kindleborn.",al={"o que é call of fire","missão do totem do fogo em dun morogh"}},{q="Por que um xamã deve aprender as lições da pedra antes do fogo?",a="A terra representa paciência inabalável, estabilidade e controle. Sem a base estável ensinada pela pedra, o xamã corre o risco de ser dominado pela fome volátil e pelas paixões destrutivas do fogo.",al={"por que a pedra primeiro","lembre-se do que a pedra lhe ensinou"}},{q="Quais pré-requisitos são necessários antes de realizar Call of Fire?",a="A missão se baseia em provações anteriores nas quais o iniciado demonstrou paciência e se enraizou na terra. O ancião só envia um estudante a Bruegs Kindleborn quando sua disciplina se mostra sólida.",al={"pré-requisitos de call of fire","relação com a missão de paciência"}}},fp="12,175,17.311.0,24.321.0,25.214.0,26.225.0,35.122.0,40.155.0,57.173.0,68.186.0"}
P.entries["quest:94465"] = {n="Call of Fire",s="Call of Fire é uma provação sagrada realizada por iniciados que buscam provar sua prontidão espiritual para controlar a chama elemental. Os postulantes devem carregar a Tocha da Chama Latente por um caminho montanhoso isolado em Loch Modan para procurar Braldir Ashmantle no Altar da Chama Latente.",h="Call of Fire é uma provação sagrada realizada por iniciados que buscam provar sua prontidão espiritual para...",kw={"braldir ashmantle","call of fire","totem do fogo","loch modan","xamã","altar da chama latente","tocha da chama latente","vale dos reis"},ang={["class:Shaman"]="Esta provação testa a dedicação de um aspirante a xamã em comungar com os espíritos elementais do fogo, exigindo que ele carregue uma tocha sagrada até um pico isolado em Loch Modan.",["faction:Alliance"]="Enquanto viajantes comuns pelos territórios da Aliança veem apenas a pedra estéril da montanha, guardiões do altar protegem antigos segredos elementais ocultos dos olhos comuns.",["race:Dwarf"]="O diálogo da missão reflete a fala dos anões e direciona os iniciados para além do Vale dos Reis, rumo aos penhascos acidentados de Khaz Modan."},sec={{t="O Caminho Além do Vale dos Reis",b="Conquistar o Totem do Fogo exige mais do que mera força física. Os iniciados recebem a tarefa de carregar a Tocha da Chama Latente apagada até o alto dos penhascos de Loch Modan. Oculta além das esculturas de pedra do Vale dos Reis, uma subida árdua leva a um cume montanhoso isolado onde os elementos dominam, muito acima das estradas dos viajantes mortais."},{t="O Altar da Chama Latente",b="No alto do pico fustigado pelo vento está Braldir Ashmantle, o guardião encarregado de vigiar o Altar da Chama Latente. Andarilhos despreparados e caçadores de tesouros que escalam essas alturas encontram apenas silêncio e pedra nua. Aos verdadeiros iniciados que portam a tocha sagrada, Braldir revela um poder elemental mais profundo que dorme dentro do braseiro do altar, esperando para ser reacendido."}},faq={{q="O que é a missão Call of Fire?",a="Call of Fire é um rito de passagem para um iniciado que busca obter seu Totem do Fogo. A missão direciona o postulante aos penhascos de Loch Modan para apresentar a Tocha da Chama Latente a Braldir Ashmantle em um pico sagrado da montanha.",al={"o que é call of fire","missão de fogo de xamã loch modan","missão do totem do fogo"}},{q="Quem é Braldir Ashmantle?",a="Braldir Ashmantle é o guardião que protege o Altar da Chama Latente no alto dos penhascos de Loch Modan. Ele dispensa viajantes comuns e caçadores de tesouros, acolhendo apenas aqueles que portam a Tocha da Chama Latente.",al={"quem é braldir ashmantle","guardião do altar loch modan"}},{q="Onde fica o Altar da Chama Latente?",a="O Altar da Chama Latente fica no alto dos penhascos de Loch Modan, alcançado ao seguir por um caminho oculto que serpenteia além do Vale dos Reis.",al={"onde fica o altar da chama latente","localização da chama latente"}},{q="Qual é o propósito da Tocha da Chama Latente?",a="A Tocha da Chama Latente é um símbolo ritualístico carregado por iniciados para demonstrar sua intenção sincera e prontidão para comungar com o fogo elemental. Braldir Ashmantle exige ver a tocha antes de conceder audiência.",al={"o que é a tocha da chama latente","propósito da tocha da chama latente"}},{q="Por que o postulante deve viajar para Loch Modan?",a="O pico elemental sagrado que abriga o Altar da Chama Latente tem vista para Loch Modan além do Vale dos Reis, escolhido por seu isolamento em relação aos viajantes casuais.",al={"por que ir a loch modan","por que o altar do fogo fica em loch modan"}},{q="Como o Totem do Fogo é obtido por meio desta provação?",a="Ao chegar até Braldir Ashmantle e provar sua intenção com a tocha, o iniciado deve acender a chama no braseiro do altar para devolvê-la acesa e receber devidamente o Totem do Fogo.",al={"o que acontece após encontrar braldir","como obter o totem do fogo"}}},fp="12,157,35.270.0,31.328.0,31.202.0,25.204.0,49.124.0,54.195.0,45.165.0,48.166.0"}
P.entries["quest:94466"] = {n="Call of Fire",s="Call of Fire é um teste elemental em Loch Modan onde iniciados se preparam para comungar com a Eternal Flame e conquistar seu Totem do Fogo. Guiados por Braldir Ashmantle, os candidatos devem reunir reagentes elementais de kobolds e troggs locais para preparar uma Sapta do Fogo vinculadora. A jornada ensina que o fogo não é meramente um instrumento de ruína, mas a forja e o próprio sopro da vida.",h="Call of Fire é um teste elemental em Loch Modan onde iniciados se preparam para comungar com a Eternal Flame...",kw={"braldir ashmantle","call of fire","eternal flame","sapta do fogo","piche ígneo","totem do fogo","loch modan","stonesplinter seer","tunnel rat geomancer"},ang={["class:Shaman"]="Comungar com o fogo requer forjar um elo elemental por meio de uma sapta dedicada, levando à comunhão com a Eternal Flame e à aquisição do Totem do Fogo.",["faction:Alliance"]="Ambientado no território anão de Loch Modan, este teste firma ritos xamânicos solidamente dentro das terras da Aliança contra ameaças locais de troggs e kobolds.",["race:Dwarf"]="Braldir Ashmantle guia iniciados em Loch Modan com uma perspectiva anã e telúrica sobre o fogo elemental, encarando-o como o sopro da forja e da criação, em vez de mera destruição."},sec={{t="O Caminho para a Chama",b="Nas escarpas acidentadas de Loch Modan, um mentor elemental chamado Braldir Ashmantle supervisiona o caminho para iniciados que buscam o poder da chama. Comungar com os espíritos do fogo não é uma invocação simples; o espírito mortal deve primeiro ser sintonizado ao elemento ardente por meio de uma mistura sagrada conhecida como Sapta do Fogo. Sem essa preparação, o calor da Eternal Flame consumiria em vez de iluminar. Braldir exige que os proponentes provem sua determinação reunindo dois reagentes cruciais ligados à chama dos habitantes hostis do vale."},{t="Reagentes da Terra e da Faísca",b="Criar uma Sapta do Fogo requer substâncias ricas em ressonância elemental. Ao norte, Tunnel Rat Geomancers colhem Piche Ígneo pegajoso em seus labirintos subterrâneos, alimentando sua magia subterrânea. Ao sul, místicos troggs conhecidos como Stonesplinter Seers carregam bolsas de reagentes (Reagent Pouch) cheias de amuletos elementais primitivos pelas colinas acidentadas. Reivindicar esses itens exige enfrentar duas das pragas mais arraigadas de Loch Modan, arrancando os materiais necessários para vincular a alma de um iniciado à chama."},{t="O Temperamento da Sabedoria",b="Ao receber os reagentes, Braldir Ashmantle oferece uma sabedoria que tempera a destruição crua com paciência. Para o mentor veterano, o fogo é muito mais do que fúria e cinzas — ele representa a vida, a arte da forja e o próprio sopro da criação. O verdadeiro domínio dos elementos reside no equilíbrio: assim como a sombra dá significado à luz, a chama impede que a pedra permaneça apenas uma memória fria. Dominar a chama requer saber quando harmonizar em vez de meramente queimar."}},faq={{q="Qual é o propósito de Call of Fire?",a="Call of Fire é um rito de passagem para aspirantes a xamã que buscam comunhão com a Eternal Flame. Para comungar com espíritos do fogo e reivindicar um Totem do Fogo, deve-se primeiro preparar uma Sapta do Fogo para vincular o espírito mortal ao elemento.",al={"o que é call of fire","o que é esta missão","objetivo de call of fire"}},{q="Quem é Braldir Ashmantle?",a="Braldir Ashmantle é um guia elemental que reside em Loch Modan. Ele instrui iniciados no equilíbrio do fogo e prepara a necessária Sapta do Fogo assim que os reagentes elementais adequados forem reunidos.",al={"quem dá call of fire","quem é braldir ashmantle","localização de braldir ashmantle"}},{q="O que é uma Sapta do Fogo?",a="Uma Sapta do Fogo é uma poção ou preparação elemental criada a partir de reagentes ligados ao fogo. Bebê-la ou usá-la sintoniza e vincula o espírito do xamã ao plano elemental do fogo, permitindo visão e comunhão com a Eternal Flame.",al={"o que é uma sapta do fogo","o que faz uma sapta","por que precisa de sapta"}},{q="Onde o Piche Ígneo é encontrado?",a="O Piche Ígneo é carregado por Tunnel Rat Geomancers que habitam as cavernas de kobolds nos confins ao norte de Loch Modan. Os geomantes utilizam o piche para suas artes primitivas com chamas.",al={"onde consigo piche ígneo","localização do piche ígneo","piche ígneo das cavernas dos kobolds"}},{q="Onde a Reagent Pouch dos Stonesplinter é encontrada?",a="A Reagent Pouch deve ser tomada de Stonesplinter Seers à espreita nas colinas ao sul de Loch Modan. Esses místicos troggs usam as bolsas para guardar reagentes ligados à magia elemental.",al={"onde consigo reagent pouch","bolsa de reagentes de vidente pedranegro","localização de reagent pouch de stonesplinter"}},{q="Como Braldir Ashmantle vê o elemento fogo?",a="Em vez de tratar o fogo como destruição irracional, Braldir ensina que o fogo é forja, vida e o sopro da criação. Ele existe em equilíbrio com outras forças, temperando a pedra fria e concedendo calor e propósito à existência.",al={"visão de braldir sobre o fogo","significado do fogo loch modan","filosofia dos anões sobre o fogo"}}},fp="12,263,21.387.0,31.422.0,23.387.0,36.157.0,25.144.0,21.164.0,28.119.0,47.147.0,52.193.0"}
P.entries["quest:94467"] = {n="Call of Fire",s="O Call of Fire é uma provação elemental na qual um iniciado bebe um sapta preparado para perceber e confrontar uma Minor Manifestation of Fire. Ao subjugar o espírito e colocar suas brasas no braseiro sagrado, o suplicante conquista o favor da chama.",h="O Call of Fire é uma provação elemental na qual um iniciado bebe um sapta preparado para perceber e...",kw={"braseiro","call of fire","sapta do fogo","brasa faiscante","minor manifestation of fire","provação de xamã","shrine of eternal flame"},ang={["class:Shaman"]="Uma provação fundamental para xamãs em comunhão com o fogo, exigindo o uso de um sapta sagrado para perceber e confrontar os espíritos da chama."},sec={{t="O Rito da Chama",b="O Call of Fire é uma provação tradicional de espírito e coragem. Guiado pelo conhecimento elemental, um iniciado recebe um Sapta do Fogo preparado para despertar seus sentidos para o mundo invisível. Ao tomar a beberagem no santuário e subir em direção ao pico, o limiar entre os olhos mortais e as forças primordiais se estreita, revelando uma manifestação dormente de fogo aguardando o desafio."},{t="Enfrentando a Manifestação",b="Confrontar a Minor Manifestation of Fire testa tanto a determinação quanto a resistência. O espírito elemental não ataca sem provocação, mas, uma vez desafiado, sua intensidade aumenta a cada momento que passa. Superá-lo concede Brasas Faiscantes, que devem ser levadas ao braseiro no topo do Shrine of Eternal Flame para acender a tocha e garantir o favor duradouro do espírito."}},faq={{q="O que é o Call of Fire?",a="Call of Fire é um rito de passagem sagrado em que um iniciado bebe um Sapta do Fogo especialmente preparado para perceber um espírito de chama, confronta-o em combate e oferece sua Brasa Faiscante a um braseiro para conquistar o favor do fogo.",al={"o que é call of fire","missão call of fire","provação do totem do fogo"}},{q="Qual é o objetivo do Sapta do Fogo?",a="O Sapta do Fogo é uma beberagem preparada que abre a visão espiritual de um iniciado, permitindo-lhe ver o espírito elemental oculto que o aguarda no pico da montanha.",al={"objetivo do sapta do fogo","por que beber o sapta","o que o sapta faz"}},{q="Qual espírito aparece durante a provação?",a="A provação convoca o iniciado a confrontar uma Minor Manifestation of Fire no topo do pico, que aguarda ser atingida antes de entrar em combate.",al={"qual espírito enfrentar","mob de call of fire","manifestação do fogo"}},{q="Por que o espírito do fogo deve ser derrotado rapidamente?",a="O espírito elemental fica mais feroz e quente quanto mais a batalha se prolonga, tornando um ataque rápido e decisivo vital para subjugá-lo antes que suas chamas se tornem avassaladoras.",al={"por que atacar rápido","luta de call of fire","tempo do espírito do fogo"}},{q="O que se faz com as Brasas Faiscantes?",a="Após derrotar a Minor Manifestation of Fire, suas Brasas Faiscantes são levadas ao braseiro no topo do Shrine of Eternal Flame para acender a tocha ritual.",al={"para onde vão as brasas","braseiro de call of fire","braseiro de shrine of eternal flame"}},{q="O que significa conquistar o favor do fogo?",a="Completar o ritual e acender a tocha concede o favor direto e a comunhão dos elementais do fogo, estabelecendo um vínculo vital com as chamas.",al={"qual é a recompensa","o que o ritual concede","favor do fogo"}}},fp="12,165,17.289.0,24.311.0,25.159.0,38.135.0,37.96.0,45.150.0,37.157.0,40.124.0"}
P.entries["quest:94468"] = {n="Call of Fire",s="Call of Fire é um rito de passagem sagrado no qual um iniciado recupera a Tocha da Chama Eterna de um mirante acima de Loch Modan e a carrega até Dun Morogh. Devolver a chama ao mentor Bruegs Kindleborn prova o domínio elemental do viajante e lhe concede seu Totem do Fogo.",h="Call of Fire é um rito de passagem sagrado no qual um iniciado recupera a Tocha da Chama Eterna de um mirante...",kw={"bruegs kindleborn","call of fire","dun morogh","totem do fogo","nascido das chamas","loch modan","xamã","tocha da chama eterna"},ang={["class:Shaman"]="Este rito conclui a provação do fogo para aspirantes a xamã em Khaz Modan, concedendo-lhes o Totem do Fogo necessário para canalizar as chamas e comungar com os espíritos do fogo.",["faction:Alliance"]="À medida que os chamados espirituais criam raízes nos territórios da Aliança em Khaz Modan, mestres como Bruegs Kindleborn orientam novos iniciados a dominar as artes elementais.",["race:Dwarf"]="Carregar a chama das alturas acima de Loch Modan de volta para Dun Morogh reflete os laços profundos entre os buscadores espirituais anões e as forças elementais de seu lar montanhoso."},sec={{t="A Chama Sobre o Loch",b="O Call of Fire marca um momento crucial na comunhão elemental de um iniciado. No alto de uma cordilheira montanhosa com o vento açoitando as alturas, o iniciado acende a Tocha da Chama Eterna contemplando Loch Modan. A chama dançante reflete um espírito em despertar, agitando um entusiasmo elemental que deve ser nutrido e carregado em segurança pelas trilhas até os vales nevados de Dun Morogh."},{t="A Recompensa do Nascido das Chamas",b="Aguardando o viajante em Dun Morogh está Bruegs Kindleborn, um mentor elemental que avalia se o fogo interior do viajante realmente se firmou. Apresentar a tocha ardente prova que o peticionário possui a determinação e a reverência para comungar com o fogo. Celebrando o iniciado como nascido das chamas, Kindleborn concede o Totem do Fogo, inserindo-o em uma linhagem de orientação elemental para o seu povo."}},faq={{q="O que é o Call of Fire?",a="Call of Fire é uma provação espiritual para xamãs em Khaz Modan. Após acender a Tocha da Chama Eterna em um braseiro com vista para Loch Modan, o iniciado deve carregar a chama ardente através das montanhas de volta a Bruegs Kindleborn em Dun Morogh.",al={"o que é call of fire","missão call of fire","o que fazer em call of fire"}},{q="Quem é Bruegs Kindleborn?",a="Bruegs Kindleborn é um mentor e guia elemental residente em Dun Morogh. Ele supervisiona os ritos elementais do fogo e presenteia os iniciados que concluem a caminhada com seu Totem do Fogo.",al={"quem é bruegs kindleborn","onde fica bruegs kindleborn","localização de bruegs kindleborn"}},{q="O que é a Tocha da Chama Eterna?",a="A Tocha da Chama Eterna é uma tocha cerimonial sagrada acesa em um braseiro com vista para Loch Modan. Ela representa a conexão interior de um iniciado com o fogo elemental e deve ser levada em segurança de volta para Bruegs Kindleborn em Dun Morogh.",al={"o que é tocha da chama eterna","tocha da chama eterna","onde pegar a tocha"}},{q="O que você recebe ao concluir esta provação?",a="Ao entregar a Tocha da Chama Eterna em segurança a Bruegs Kindleborn, o mentor reconhece seu espírito ardente e lhe concede seu Totem do Fogo, consagrando você como nascido das chamas.",al={"qual é a recompensa de call of fire","você ganha totem do fogo","totem de call of fire"}},{q="Onde ocorre essa jornada?",a="A jornada começa em um mirante com vista para Loch Modan onde a tocha é acesa, e segue pelo caminho da montanha de volta ao território nevado de Dun Morogh para encontrar Bruegs Kindleborn.",al={"onde acontece call of fire","caminho de call of fire","onde levar a tocha"}},{q="Por que Bruegs menciona Madoran?",a="Bruegs jura \"Pela barba de Madoran\", fazendo referência a Madoran Bronzebeard, o reverenciado líder anão que liderou o clã Bronzebeard durante a Guerra dos Três Martelos.",al={"por que pela barba de madoran","significado de madoran","quem é o madoran que bruegs menciona"}}},fp="12,162,23.241.0,22.320.0,25.218.0,25.156.0,35.200.0,47.173.0,35.148.0,32.169.0"}
P.entries["quest:94480"] = {n="A Gift From Our Enemies",s="Você leva alimento roubado a Gorg, em Rog'mar, para alimentar seus aliados. Gnolls próximos e o avanço de Twilight ameaçam o assentamento.",h="Você leva alimento roubado a Gorg, em Rog'mar, para alimentar seus aliados.",kw={"aliados","fazenda","gnolls","gorg","ensopado reforçado","rog'mar","ração roubada","twilight"},sec={{t="Comida para Rog'mar",b="Gorg espera em Rog'mar pela ração roubada que você reuniu. Os humanos não são a única ameaça por perto: gnolls rosnam nas colinas, e Twilight se aproxima. Manter os aliados de Rog'mar alimentados pode ajudar a preservar suas forças."},{t="Um ensopado reforçado",b="A ração tem um cheiro forte e terroso, com algo desagradável por baixo. Gorg reconhece que você a tirou da fazenda e diz que ela dará um ensopado reforçado para os aliados."}},faq={{q="Por que Gorg quer a ração roubada?",a="Gorg vai usar a ração roubada para preparar um ensopado reforçado para os aliados de Rog'mar.",al={"por que ração","ração gorg","para que serve a ração roubada"}},{q="Que ameaças há perto de Rog'mar?",a="Os humanos são uma ameaça, enquanto gnolls rosnam nas colinas próximas e Twilight se aproxima.",al={"gnolls por perto","ameaça de twilight","o que há perto de rog'mar"}},{q="Quem é Gorg?",a="Gorg é quem recebe a ração roubada em Rog'mar e diz que ela pode virar um ensopado reforçado.",al={"quem é gorg"}},{q="Onde levo a ração roubada?",a="Leve a ração roubada para Gorg, em Rog'mar.",al={"local da ração","onde levar a ração","localização de gorg"}}},fp="23,134,16.224.0,13.177.1,35.73.0,30.92.0,12.91.0,32.40.0"}
P.entries["quest:94481"] = {n="A Serving of Strength",s="Um treinador pede que você leve ensopado aos recrutas Rog’mar no campo de treinamento. A refeição ajuda a mantê-los alimentados enquanto fica cada vez mais difícil defender as linhas de suprimento.",h="Um treinador pede que você leve ensopado aos recrutas Rog’mar no campo de treinamento.",kw={"uma porção de força","recrutas rog’mar","ensopado","linhas de suprimento","recrutas","campo de treinamento","guerreiros"},sec={{t="Comida para os Recrutas",b="Os recrutas no campo de treinamento precisam de comida, e o treinador envia você com um ensopado reforçado. Você deve alimentar os recrutas Rog’mar a oeste. As reclamações deles podem esperar; ficou cada vez mais difícil defender as linhas de suprimento, e os guerreiros agradecem pela comida que você leva."}},faq={{q="Quem precisa do ensopado?",a="Os recrutas Rog’mar no campo de treinamento precisam do ensopado.",al={"quem está com fome","quem recebe comida","comida para recrutas"}},{q="Onde devo levar o ensopado?",a="Os recrutas Rog’mar estão no campo de treinamento a oeste.",al={"onde alimentar os recrutas","localização dos recrutas","onde levar o ensopado"}},{q="Por que estão recebendo ensopado?",a="O ensopado mantém os recrutas alimentados enquanto ficou difícil defender as linhas de suprimento.",al={"por que ensopado","para que serve a comida","por que alimentar os recrutas"}},{q="O que o treinador acha das reclamações dos recrutas?",a="O treinador diz que os recrutas podem levar qualquer reclamação futura diretamente a ele.",al={"reclamações dos recrutas","por que estão reclamando","treinador irritado"}},{q="O treinador agradece pela comida?",a="Sim. O treinador e os guerreiros agradecem pela comida, apesar do que os guerreiros dizem.",al={"o treinador agradece","agradecimento pelo ensopado","guerreiros agradecidos"}}},fp="21,149,17.274.0,19.57.0,25.63.0,28.86.0,56.80.0,37.91.0"}
P.entries["quest:94483"] = {n="Show Them How It's Done",s="Um comandante envia você ao sul do rio para atacar os campos de treinamento de Farholde. O ataque deve manter os humanos perto de sua fortaleza e ganhar tempo para outras tarefas.",h="Um comandante envia você ao sul do rio para atacar os campos de treinamento de Farholde.",kw={"farholde","humanos","fortaleza","sacerdotes","rio","batedores","campos de treinamento"},sec={{t="Pelo rio",b="O comandante aponta os campos de Farholde ao sul do rio, onde batedores relataram a presença de forças humanas. Ele pede que você mate Farholde Priests e Farholde Scouts. Manter os humanos afastados de sua fortaleza dará ao comandante tempo para cuidar de outros assuntos."}},faq={{q="Quem está me pedindo para atacar os campos?",a="Um comandante que recebeu relatos dos batedores sobre campos de treinamento ao sul do rio envia você contra as forças de Farholde.",al={"quem deu isso","pedido do comandante"}},{q="Onde ficam os campos de Farholde?",a="Os campos de treinamento ficam ao sul do rio.",al={"onde ficam os campos","localização de farholde"}},{q="Quem devo atacar?",a="O comandante indica Farholde Priests e Farholde Scouts como alvos.",al={"quem matar","alvos"}},{q="Por que atacar os humanos?",a="A ideia é manter os humanos perto de sua fortaleza e ganhar tempo para que o comandante cuide de outros assuntos.",al={"por que lutar contra os humanos","qual é o objetivo"}},{q="O que acontece depois do ataque?",a="O comandante diz que a ação foi rápida e pretende continuar em outro lugar.",al={"o que vem depois","depois dos campos"}}},fp="23,160,12.264.0,37.119.0,29.42.0,28.72.0,22.96.0,30.74.0"}
P.entries["quest:94484"] = {n="Unnerving Silence",s="Unnerving Silence trata da perda abrupta de comunicação com um enclave de druidas situado dentro de uma caverna no nordeste da Floresta Umbréola. No rastro da ruína de Ban'aethall e da crescente agitação regional, um investigador é enviado para localizar Elegael Thornpaw e avaliar o destino do conclave.",h="Unnerving Silence trata da perda abrupta de comunicação com um enclave de druidas situado dentro de uma...",kw={"ban'aethall","druida","conclave de druidas","elegael thornpaw","floresta umbréola","unnerving silence"},ang={["class:Druid"]="A perda de contato com um enclave isolado na Floresta Umbréola gera preocupação imediata para druidas sintonizados com o equilíbrio da natureza. Investigar o silêncio de Elegael Thornpaw é uma questão de proteger irmãos e esclarecer o que perturbou a comunhão deles."},sec={{t="Silêncio na Copa",b="Uma inquietação silenciosa paira sobre a natureza selvagem após a queda de Ban'aethall. Com aquele vilarejo reduzido a ruínas e uma agitação misteriosa se espalhando pelo território, linhas de contato estabelecidas começaram a se romper. Em particular, os despachos regulares de um conclave isolado de druidas que habita as profundezas de uma caverna no nordeste da Floresta Umbréola cessaram abruptamente, deixando seus aliados em alerta."},{t="Em Busca do Enclave",b="Viajantes que se dirigem à Floresta Umbréola são incumbidos de encontrar Elegael Thornpaw, uma figura de destaque entre os druidas que habitam as cavernas. Aventurando-se pelo sombrio nordeste, um investigador deve descobrir se o enclave simplesmente se recolheu em uma comunhão mais profunda com a natureza ou sucumbiu aos mesmos perigos que assolaram Ban'aethall."}},faq={{q="Sobre o que é a missão Unnerving Silence?",a="Unnerving Silence é uma missão para investigar uma súbita interrupção na comunicação de um conclave de druidas situado na Floresta Umbréola. Uma parte interessada pede aos viajantes que se aventuram por aquelas bandas que revistem uma caverna no nordeste e descubram o que aconteceu com a ordem isolada.",al={"missão unnerving silence","o que é unnerving silence"}},{q="Onde Elegael Thornpaw pode ser encontrada?",a="Elegael Thornpaw reside dentro de uma caverna situada nos confins do nordeste da Floresta Umbréola. Ela atua como ponto de contato para o conclave de druidas isolado ali localizado.",al={"onde está elegael thornpaw","localização de elegael thornpaw","encontrar thornpaw"}},{q="Quem é Elegael Thornpaw?",a="Elegael Thornpaw é um membro do conclave de druidas que habita uma caverna no nordeste da Floresta Umbréola. Seu silêncio prolongado e a falta de envio de correspondências programadas suscitaram graves preocupações quanto à segurança de seu enclave.",al={"quem é elegael thornpaw","história de thornpaw"}},{q="O que é a Floresta Umbréola?",a="A Floresta Umbréola é uma extensão arborizada que abriga um conclave druídico oculto em uma caverna em sua região nordeste. Após a turbulência regional generalizada e a queda de Ban'aethall, a comunicação com os habitantes da floresta tornou-se perigosamente incerta.",al={"o que é floresta umbréola","conclave da floresta umbréola"}},{q="O que é Ban'aethall?",a="Ban'aethall era um vilarejo nas profundezas da Floresta Umbréola que recentemente caiu em ruínas. Sua destruição, somada a uma agitação mais ampla por todo o território, aumentou o temor de que acampamentos próximos, como o conclave da Floresta Umbréola, também possam estar em perigo.",al={"o que aconteceu com banaethall","história das ruínas de banaethall","ban'aethall caída"}},{q="Por que o conclave de druidas silenciou?",a="Mensagens e relatórios programados dos druidas na Floresta Umbréola cessaram sem explicação. Diante da destruição de Ban'aethall e do aumento das tensões regionais, há uma séria preocupação de que uma catástrofe ou forças hostis os tenham subjugado.",al={"por que os druidas pararam de enviar mensagens","por que os druidas estão quietos"}}},fp="17,142,21.259.0,19.271.0,42.188.0,36.131.0,24.183.0,26.223.0,20.193.0,39.222.0"}
P.entries["quest:94485"] = {n="Tears of the Lady",s="Tears of the Lady é uma urgente tarefa de misericórdia realizada para Elegael na Floresta Umbréola. Para tratar camaradas feridos deixados isolados em Nightclaw Den, viajantes precisam vasculhar troncos de árvores locais em busca de Lady's Tear, um musgo antisséptico vital para enfaixar ferimentos graves.",h="Tears of the Lady é uma urgente tarefa de misericórdia realizada para Elegael na Floresta Umbréola.",kw={"elegael","lady's tear","musgo","nightclaw den","cataplasma","floresta umbréola","tears of the lady"},ang={["class:Priest"]="Enquanto sacerdotes canalizam a Luz para curar ferimentos mortais, cataplasmas naturais como Lady's Tear servem como curativos físicos cruciais para sobreviventes feridos quando o alívio mágico é escasso.",["profession:Herbalism"]="Herboristas e curadores de campo valorizam Lady's Tear por suas secreções antissépticas pegajosas, capazes de fechar rapidamente carne aberta e prevenir infecções em emergências na natureza selvagem."},sec={{t="Remédios Desesperados na Floresta Umbréola",b="Nas profundezas sombrias da Floresta Umbréola, Elegael busca urgentemente ajuda para tratar companheiros presos dentro de Nightclaw Den. Com aliados gravemente feridos aguardando resgate, suprimentos convencionais estão em falta, exigindo medicamentos de campo recolhidos diretamente da natureza circundante. O esforço depende da obtenção de remédios naturais antes que o tempo se esgote para aqueles deixados para trás."},{t="O Musgo Curativo",b="O componente vital da cataplasma planejada por Elegael é Lady's Tear, um musgo franzino que se agarra à base das árvores por toda a Floresta Umbréola. A planta produz uma secreção viscosa e pegajosa com propriedades antissépticas naturais, capaz de vedar cortes abertos e proteger ferimentos traumáticos de piorarem na natureza úmida. Entregar musgo suficiente permite que Elegael prepare os curativos necessários para estabilizar os caídos."}},faq={{q="Sobre o que é a missão Tears of the Lady?",a="Tears of the Lady é um esforço de resgate liderado por Elegael na Floresta Umbréola. Camaradas feridos continuam presos em Nightclaw Den, e Elegael precisa da flora local para preparar uma cataplasma urgente para mantê-los vivos.",al={"o que é tears of the lady","informações da missão tears of the lady"}},{q="O que é Lady's Tear?",a="Lady's Tear é um musgo franzino que cresce perto da base de árvores por todas as matas da Floresta Umbréola. Ele secreta uma seiva naturalmente pegajosa que serve como um poderoso antisséptico, tornando-o ideal para tratar e enfaixar ferimentos abertos.",al={"o que é lady's tear","musgo lady's tear","o que é o musgo lady's tear"}},{q="Quem é Elegael?",a="Elegael é o sobrevivente que organiza os esforços médicos na Floresta Umbréola. Tendo deixado companheiros feridos para trás em Nightclaw Den, Elegael reúne suprimentos medicinais para preparar tratamentos antes de retornar para ajudá-los.",al={"quem é elegael","concedente da missão tears of the lady"}},{q="O que é Nightclaw Den?",a="Nightclaw Den é um local próximo à Floresta Umbréola onde vários dos aliados feridos de Elegael estão isolados. A condição deles é precária, motivando a corrida desesperada para reunir ingredientes de cura.",al={"o que é nightclaw den","onde fica nightclaw den"}},{q="Por que Elegael precisa do musgo Lady's Tear?",a="O musgo fornece uma secreção antisséptica crucial necessária para preparar uma cataplasma medicinal. Essa substância pegajosa veda cortes abertos e combate infecções nos sobreviventes deixados para trás no covil.",al={"por que precisa de lady's tear","o que o musgo faz"}},{q="Onde o musgo Lady's Tear é encontrado?",a="O musgo Lady's Tear normalmente se agarra à base das árvores por toda a Floresta Umbréola. Embora Elegael tenha coletado o que estava imediatamente ao alcance, mais precisa ser obtido nas matas ao redor.",al={"onde cresce lady's tear","encontrar lady's tear"}}},fp="17,157,32.238.0,16.312.0,42.164.0,20.178.0,15.135.0,26.156.0,39.165.0,32.153.0"}
P.entries["quest:94486"] = {n="Feathers for Binding",s="Feathers for Binding é uma missão na Floresta Umbréola centrada na coleta de plumagem isolante de jovens shrieklings para criar um emplastro medicinal protetor. Embora essas criaturas normalmente dóceis tenham se tornado perigosamente agressivas, suas penas continuam essenciais para preservar pomadas antissépticas contra as intempéries. Os aventureiros devem enfrentar os filhotes hostis para obter os materiais necessários para o cuidado regional.",h="Feathers for Binding é uma missão na Floresta Umbréola centrada na coleta de plumagem isolante de jovens...",kw={"seiva antisséptica","feathers for binding","emplastro","floresta umbréola","shadowgale shriekling","shriekling","shrieklings"},ang={["class:Druid"]="Os druidas podem compartilhar a tristeza de quem concede a missão ao abater jovens feras da floresta, mesmo quando a agressividade crescente e a necessidade médica urgente deixam poucas outras alternativas.",["profession:Herbalism"]="Herboristas e curadores naturais podem apreciar o equilíbrio cuidadoso de combinar musgo, seiva antisséptica de árvore e penas isolantes para criar um curativo de campo eficaz ou um emplastro medicinal."},sec={{t="Remédios da Floresta",b="Nas profundezas da Floresta Umbréola, preparar medicina de campo muitas vezes exige recursos da própria terra. Ao tratar ferimentos graves, herboristas e curadores recorrem a um emplastro especializado feito de musgo e seiva antisséptica de árvore. Para garantir que a seiva não seque rapidamente nem perca sua eficácia devido ao clima severo, ataduras isolantes e duráveis são necessárias. As penas juvenis dos Shadowgale shrieklings oferecem uma barreira natural ideal, protegendo o ferimento enquanto selam o tratamento medicinal."},{t="Hostilidade Incomum",b="Obter essas penas macias tornou-se inesperadamente perigoso. Em circunstâncias normais, os jovens Shadowgale shrieklings são habitantes florestais dóceis. Recentemente, no entanto, um aumento inexplicável na agressividade se espalhou por suas fileiras. Munidos de garras formidáveis capazes de infligir ferimentos letais, esses jovens predadores agora atacam agressivamente quem passa por perto. Colher sua plumagem exige que os aventureiros enfrentem uma criatura que deixou de ser um filhote inofensivo para se tornar um perigo real."},{t="Uma Necessidade Lamentável",b="Pedir aos viajantes que cacem criaturas jovens pesa bastante sobre os cuidadores locais, que lamentam abertamente a necessidade do abate. Contudo, com múltiplas emergências ameaçando a região e as feras tornando-se cada vez mais perigosas, reduzir seus números cumpre um duplo propósito: obter materiais curativos vitais enquanto reprime uma ameaça crescente às trilhas da floresta. Cada pena coletada é tratada com respeito, garantindo que seu sacrifício não seja em vão."}},faq={{q="Por que as penas de Shadowgale shriekling são necessárias para o emplastro?",a="As penas dos jovens Shadowgale shrieklings possuem qualidades isolantes naturais. Colocadas sobre uma camada de musgo, elas servem como uma atadura protetora que impede a seiva antisséptica de secar, ao mesmo tempo em que protege as feridas contra as intempéries ambientais.",al={"finalidade das penas","por que penas de shriekling","penas para emplastro"}},{q="Quão perigosos são os shrieklings jovens?",a="Embora os Shadowgale shrieklings sejam criaturas normalmente dóceis, eles se tornaram extraordinariamente hostis recentemente. Apesar da pouca idade, eles possuem garras grandes e cruéis, capazes de eviscerar um viajante desavisado.",al={"perigo dos shrieklings","os shrieklings são perigosos","agressividade dos shrieklings"}},{q="Por que os shrieklings jovens devem ser caçados em vez dos adultos?",a="Quem concede a missão expressa um remorso genuíno por abater feras jovens. No entanto, devido ao aumento repentino na hostilidade e à necessidade de gerenciar emergências simultâneas na natureza, reduzir seus números enquanto se colhe o medicamento necessário é considerado uma dolorosa necessidade.",al={"por que matar shrieklings jovens","matar shrieklings jovens"}},{q="Onde os Shadowgale shrieklings são encontrados?",a="Os Shadowgale shrieklings vagam pelas copas e pela vegetação rasteira da Floresta Umbréola, onde os viajantes devem se aventurar com cuidado pela floresta para rastreá-los.",al={"onde fica a floresta umbréola","localização dos shrieklings","onde estão os shrieklings"}},{q="Quais outros ingredientes estão sendo usados junto com essas penas?",a="O emplastro consiste em musgo local em camadas com seiva antisséptica, que é então atado e isolado com as penas macias colhidas de shrieklings jovens.",al={"ingredientes do emplastro","o que há no emplastro"}},{q="Por que os shrieklings ficaram tão hostis ultimamente?",a="A causa exata de sua hostilidade repentina não está clara, mas as criaturas jovens, normalmente pacíficas, tornaram-se extraordinariamente agressivas, somando-se à crescente lista de crises enfrentadas pelos cuidadores locais.",al={"por que os shrieklings estão zangados","o que causou a agressividade dos shrieklings"}}},fp="20,179,22.275.0,26.255.0,23.313.0,63.166.0,43.170.0,58.225.0,43.142.0,63.106.0,50.175.0"}
P.entries["quest:94487"] = {n="Unwanted and Unworthy",s="Unwanted and Unworthy é uma missão em Zephras onde aventureiros ajudam Elegael a retaliar contra os Sectários de Al'Aketh após uma emboscada sangrenta na Floresta Umbréola. Ao abater os sectários e recuperar relíquias de família roubadas, os jogadores vingam druidas caídos e recuperam relíquias ancestrais sagradas para o High Elder.",h="Unwanted and Unworthy é uma missão em Zephras onde aventureiros ajudam Elegael a retaliar contra os Sectários...",kw={"al'aketh","relíquias de família ensanguentadas","elegael","footsoldiers","relíquias de família","floresta umbréola","shen'dorei","stormchasers","zephras"},ang={["class:Druid"]="Os Sectários de Al'Aketh derramaram o sangue de druidas locais durante seu ataque não provocado em Zephras, tornando este golpe um ato direto de vingança e defesa do equilíbrio da natureza."},sec={{t="Emboscada na Floresta Umbréola",b="O equilíbrio pacífico de Zephras foi abruptamente despedaçado quando os Sectários de Al'Aketh lançaram uma emboscada surpresa contra os druidas locais na Floresta Umbréola. Elegael, que antes desdenhava desses fanáticos como sonhadores inofensivos com 'nuvens entre os ouvidos', foi pego de surpresa pela pura brutalidade de seu ataque. O ataque deixou sangue de druida derramado pelo chão da floresta, provocando uma exigência de retribuição rápida contra os Footsoldiers e Stormchasers responsáveis."},{t="Relíquias de Família Maculadas e Juventude Perdida",b="Para Elegael, a traição dos sectários os despojou de sua herança: eles não merecem mais ser chamados de shen'dorei, nem seus restos mortais merecem os ventos de sua terra natal. Muitos dos sectários eram jovens indivíduos com futuros promissores interrompidos pelo fanatismo. Ao recuperar suas relíquias de família ensanguentadas, os aventureiros ajudam a garantir que esses itens sagrados sejam devolvidos ao High Elder, aguardando uma geração mais sábia e mais digna."}},faq={{q="Quem são os Sectários de Al'Aketh?",a="Os Sectários de Al'Aketh são sectários obcecados por tempestades que operam na ilha de Zephras. De acordo com Elegael, eles antes eram considerados apenas tolos ou portadores de 'nuvens entre os ouvidos', mas subitamente se voltaram para a violência brutal contra os druidas locais.",al={"quem são alaketh","seita alaketh","quem são os sectários"}},{q="Quem é Elegael?",a="Elegael é um protetor ou druida shen'dorei afiliado a Zephras que sofreu uma emboscada dos Sectários de Al'Aketh. Angustiado com a traição e o derramamento de sangue de vidas jovens, Elegael busca retribuição e a recuperação de relíquias de família ancestrais roubadas.",al={"quem é elegael","elegael que concede a missão"}},{q="O que são as relíquias de família ensanguentadas?",a="As relíquias de família ensanguentadas pertenciam a jovens shen'dorei que foram atraídos para a Seita de Al'Aketh. Elegael as reúne para que possam eventualmente ser devolvidas à coleção do High Elder e passadas adiante para uma geração futura mais digna.",al={"relíquias de família ensanguentadas","por que coletar relíquias de família","o que são as relíquias de família"}},{q="O que são os shen'dorei?",a="Os shen'dorei são o povo que habita Zephras. Elegael considera que os traiçoeiros Sectários de Al'Aketh perderam o direito de ser chamados de shen'dorei devido à sua violenta traição e profanação da harmonia da ilha.",al={"significado de shendorei","quem são shendorei"}},{q="Onde fica a Floresta Umbréola?",a="A Floresta Umbréola é uma região arborizada localizada em Zephras onde operam Footsoldiers e Stormchasers de Al'Aketh e onde ocorreu a emboscada não provocada contra os druidas.",al={"localização da floresta umbréola","onde fica umbréola"}},{q="Por que os Sectários de Al'Aketh emboscaram os druidas?",a="Os motivos exatos dos sectários permanecem um mistério perturbador para Elegael. Embora tenham sido ignorados por muito tempo como fanáticos inofensivos, sua revolta repentina e cruel destruiu o delicado equilíbrio mantido na ilha.",al={"por que os sectários atacaram","motivos da seita","por que emboscaram druidas"}}},fp="21,124,27.286.0,32.360.0,30.198.0,15.244.0,32.200.0,24.189.0,27.146.0,48.174.0"}
P.entries["quest:94488"] = {n="The Ties That Bind",s="The Ties That Bind é uma missão na Floresta Umbréola centrada em uma amarga traição dentro do círculo druídico. Elegael Thornpaw descobre que um druida do círculo desaparecido, Haalien, se juntou aos cultistas atacantes como comandante e ordena sua execução. A tarefa revela o doloroso custo pessoal do dever quando a família se volta contra os seus semelhantes.",h="The Ties That Bind é uma missão na Floresta Umbréola centrada em uma amarga traição dentro do círculo...",kw={"círculo cenariano","comandante haalien","cultistas","druida","elegael thornpaw","haalien","floresta umbréola","the ties that bind"},ang={["class:Druid"]="O Círculo Cenariano considera a preservação do equilíbrio e do parentesco sagrada, tornando a traição de Haalien e o derramamento de sangue entre companheiros druidas do círculo uma ofensa especialmente grave contra a ordem."},sec={{t="Traição na Floresta",b="Nas profundezas da Floresta Umbréola, os druidas encontram uma presença cultista perversa semeando terror e derramamento de sangue. Para Elegael Thornpaw, o ataque é agravado por uma amarga descoberta: o rastro de um antigo druida do círculo chamado Haalien paira sobre o massacre. Tendo desaparecido meses antes, Haalien não pereceu na natureza, mas, em vez disso, aliou-se aos cultistas invasores, assumindo o comando de sua campanha violenta contra seus antigos semelhantes."},{t="Sangue e Parentesco",b="A traição de Haalien vai mais fundo do que votos quebrados ao Círculo Cenariano. Ao receber a cabeça decepada do comandante caído, Elegael revela que Haalien era seu próprio primo. Embora tomada de fúria por suas atrocidades, abater seu próprio parente provou ser um fardo pesado demais para suportar sozinha. Sua morte põe um fim sangrento a um renegado cuja malícia custou inúmeras vidas inocentes."}},faq={{q="Quem oferece a missão The Ties That Bind?",a="Elegael Thornpaw é uma druida posicionada na Floresta Umbréola. Lidando com uma incursão de cultistas, ela orienta os aventureiros a caçarem o Comandante Haalien após descobrir sua participação no derramamento de sangue.",al={"quem dá ties that bind","dador da missão floresta umbréola","quem é elegael thornpaw"}},{q="Quem é o Comandante Haalien?",a="O Comandante Haalien era anteriormente um druida do Círculo Cenariano que desapareceu meses antes dos ataques cultistas. Em vez de sucumbir à escuridão que avançava, ele voluntariamente se juntou aos cultistas hostis e ascendeu para comandar suas forças contra seus semelhantes.",al={"quem é haalien","história do comandante haalien","passado de haalien"}},{q="Por que Elegael quer o Comandante Haalien morto?",a="Haalien abandonou seu círculo druídico para comandar cultistas que massacraram vidas inocentes e derramaram o sangue de seus irmãos. Por causa de suas ações e do perigo que representa para a floresta, Elegael ordena sua execução.",al={"por que matar haalien","crime de haalien","o que haalien fez"}},{q="Qual é a ligação entre Elegael Thornpaw e Haalien?",a="O Comandante Haalien é primo de Elegael Thornpaw. Embora profundamente enfurecida por seus crimes, ela admite que executar sua própria carne e sangue diretamente teria sido um fardo amargo, o que a levou a pedir a ajuda de um aventureiro.",al={"elegael e haalien são parentes","como elegael e haalien se conhecem"}},{q="Por que há cultistas na Floresta Umbréola?",a="Os motivos exatos por trás da presença dos cultistas na Floresta Umbréola permanecem desconcertantes até mesmo para os druidas locais. No entanto, suas fileiras são lideradas por antigos membros do círculo como Haalien, que comandou violência e derramamento de sangue contra os defensores da floresta.",al={"cultistas da floresta umbréola","por que há cultistas na floresta umbréola"}},{q="Onde se passa esta missão?",a="Os eventos da missão se desenrolam dentro da Floresta Umbréola, onde Elegael Thornpaw investiga a invasão cultista e confronta a sombria realidade da traição de seu primo.",al={"onde ocorre ties that bind","localização da floresta umbréola"}}},fp="18,192,22.310.0,17.349.1,40.171.0,25.191.0,45.206.0,60.166.0,50.198.0,33.133.0"}
P.entries["quest:94489"] = {n="The Wounds of Betrayal",s="The Wounds of Betrayal é uma missão na Floresta Umbréola focada nas consequências de um trágico ataque contra os raros druidas shen'dorei. Os jogadores são enviados por Elegael para entregar emplastros urgentes aos seus irmãos feridos em Nightfang Den e procurar pelo seu companheiro desaparecido, Jorel Windsinger. A missão logo expõe o amargo preço da traição e incita um conflito vingativo contra os Al'Aketh.",h="The Wounds of Betrayal é uma missão na Floresta Umbréola focada nas consequências de um trágico ataque contra...",kw={"al'aketh","druida","elegael","jorel windsinger","nightfang den","floresta umbréola","shen'dorei","the wounds of betrayal"},ang={["class:Druid"]="Como guardiões druídicos da natureza selvagem, ver companheiros de prática — especificamente os escassos druidas shen'dorei — sucumbirem à traição e a graves ferimentos carrega um peso pessoal imenso.",["race:NightElf"]="Os elfos noturnos reverenciam as tradições druídicas, fazendo com que o sofrimento de companheiros druidas na Floresta Umbréola e a luta contra a traição ressoem profundamente."},sec={{t="Ajuda para os Shen'dorei",b="The Wounds of Betrayal começa com Elegael, uma druida shen'dorei cuidando das consequências de um ataque catastrófico na Floresta Umbréola. Tendo preparado às pressas emplastros medicinais, ela busca com urgência um aventureiro para levar ajuda aos seus irmãos abrigados na vizinha Nightfang Den, logo ao norte, do outro lado da clareira. Os druidas shen'dorei são extremamente poucos em número, tornando a sobrevivência de cada membro vital para o seu frágil enclave."},{t="A Busca por Jorel Windsinger",b="Além de prestar socorro emergencial aos sete druidas debilitados na caverna, Elegael traz um apelo pessoal em seu coração: encontrar seu companheiro, Jorel Windsinger. Quando ela fugiu do combate para preparar remédios, Jorel já estava à beira da morte. Aventure-se pelos recessos sombrios de Nightfang Den para revelar a verdadeira devastação provocada no santuário e o terrível destino que acometeu Jorel."},{t="Um Juramento de Retaliação",b="Ao saber do trágico fim de Jorel e do impacto terrível sobre os seus irmãos, a serenidade de Elegael se desfaz em luto e fúria. Cerrando os dentes com um rosnado de dor, ela renuncia ao desespero em prol de uma retaliação total, jurando que qualquer pessoa aliada aos sombrios Al'Aketh sofrerá sua ira implacável pelo massacre do seu povo."}},faq={{q="Quem concede a missão The Wounds of Betrayal?",a="A missão é concedida por Elegael, uma druida shen'dorei que tenta desesperadamente cuidar de seus irmãos feridos após um ataque violento na Floresta Umbréola.",al={"quem dá the wounds of betrayal","concedente da missão the wounds of betrayal","quem é elegael"}},{q="Onde fica Nightfang Den?",a="Nightfang Den é uma caverna situada ao norte, logo do outro lado da clareira na Floresta Umbréola, onde druidas shen'dorei feridos recuaram em busca de refúgio.",al={"onde fica nightfang den","localização de nightfang den","onde estão os druidas feridos"}},{q="Quem é Jorel Windsinger?",a="Jorel Windsinger é o companheiro de Elegael. Ele ficou gravemente ferido no ataque e permaneceu dentro de Nightfang Den, onde o jogador descobre seu trágico destino.",al={"quem é jorel windsinger","destino de jorel windsinger","onde está jorel"}},{q="O que são os druidas shen'dorei?",a="Os shen'dorei são um grupo raro com pouquíssimos praticantes druídicos entre eles. Como seu número é tão reduzido, Elegael ressalta que cada vida sobrevivente entre eles é preciosa.",al={"o que são os shen'dorei","quem são os druidas shen'dorei","história dos druidas shen'dorei"}},{q="Quem são os Al'Aketh?",a="Os Al'Aketh são inimigos responsáveis por aqueles que atacaram os druidas ou aliados a eles. Ao saber do destino de Jorel e da devastação de sua ordem, Elegael jura vingança contra os Al'Aketh e qualquer um que seja aliado a eles.",al={"quem são os al'aketh","al'aketh","por que elegael odeia os al'aketh"}},{q="O que acontece com Jorel Windsinger na missão?",a="Ao localizar Jorel Windsinger no covil, você descobre que a situação dele teve um desfecho trágico. Retornar a Elegael com notícias sobre o destino dele e o estado terrível dos druidas sobreviventes a leva ao luto e a um juramento furioso de vingança.",al={"o que acontece com jorel windsinger","jorel sobrevive","desfecho de jorel"}}},fp="22,202,22.265.0,31.307.1,20.247.2,43.111.0,31.123.0,24.120.0,31.101.0,21.214.0,46.206.0"}
P.entries["quest:94490"] = {n="Ripped Missive",s="A Missiva Rasgada é uma carta manchada de sangue recuperada de Haalien que lança luz sobre um ataque brutal de cultistas contra um antro de druidas na Floresta Umbréola. Seu conteúdo expõe os motivos cruéis por trás do massacre e sugere uma perigosa subversão com origem dentro de Valanaar.",h="A Missiva Rasgada é uma carta manchada de sangue recuperada de Haalien que lança luz sobre um ataque brutal...",kw={"cultista","antro dos druidas","elegael thornpaw","haalien","lotheluum","pilone","missiva rasgada","floresta umbréola","valanaar"},ang={["class:Druid"]="Os druidas encontrarão uma tragédia amarga nesta carta, que revela que os druidas massacrados do antro estavam simplesmente no caminho dos cultistas que buscavam um antigo pilone."},sec={{t="Ordens Manchadas de Sangue",b="Escondido atrás da braçadeira de Haalien, este documento rasgado e manchado de sangue contém informações sombrias sobre a recente violência na Floresta Umbréola. Recuperado após uma batalha feroz, o pedaço de escrita esclarece as intenções sombrias dos cultistas que atacaram o antro de druidas local, oferecendo pistas vitais para aqueles que buscam justiça para os caídos."},{t="Massacre Sem Sentido",b="Ao apresentar o pergaminho a Elegael Thornpaw na Floresta Umbréola, a horrível verdade sobre o ataque vem à tona. Os cultistas não atacaram por causa de uma desavença específica com os druidas; eles vieram em busca de um pilone misterioso, assassinando os habitantes do antro simplesmente porque eram um inconveniente em seu caminho. Enfurecida pelo massacre sem sentido, Elegael jura vingança contra quaisquer cultistas que restem na floresta."},{t="Traição em Valanaar",b="Além de revelar o foco dos cultistas no pilone, a missiva traz uma revelação muito mais alarmante: a ordem parece ter se originado da própria Valanaar. Essa constatação sombria aponta para um traidor agindo de dentro do assentamento. Para desmascarar a conspiração antes que mais vidas sejam perdidas, a missiva deve ser levada sem demora a Lotheluum em Valanaar."}},faq={{q="O que é a Missiva Rasgada?",a="A Missiva Rasgada é uma carta manchada de sangue e rasgada, descoberta enfiada atrás da braçadeira de Haalien após uma batalha. Ela contém informações essenciais expondo os motivos por trás do ataque de cultistas a um antro de druidas na Floresta Umbréola.",al={"o que é missiva rasgada","missiva rasgada missão","bilhete manchado de sangue haalien"}},{q="De onde a missiva é recuperada?",a="A missiva é recuperada diretamente de Haalien, encontrada enfiada atrás de uma de suas braçadeiras após um confronto violento. A carta foi danificada e manchada de sangue durante o combate.",al={"quem deixou cair a missiva rasgada","de onde veio a missiva rasgada","quem é haalien"}},{q="Quem deve receber a Missiva Rasgada?",a="A missiva é levada inicialmente a Elegael Thornpaw na Floresta Umbréola. Ao ler o documento, Elegael orienta que ele seja entregue rapidamente a Lotheluum em Valanaar para alertar sobre uma possível traição.",al={"quem quer a missiva rasgada","a quem entrego a missiva rasgada","missiva de elegael thornpaw"}},{q="Por que os cultistas atacaram o antro dos druidas?",a="A carta revela que os cultistas não atacaram o antro dos druidas por ódio aos próprios druidas, mas sim para garantir o controle de um pilone situado no local. Os druidas que residiam lá foram impiedosamente massacrados apenas por estarem no caminho dos cultistas.",al={"por que os cultistas atacaram o antro dos druidas","motivo dos cultistas antro dos druidas","por que haalien atacou"}},{q="De onde se originaram as ordens de ataque?",a="A missiva indica que as ordens dos cultistas se originaram de Valanaar, sugerindo que um traidor está ativamente escondido e orquestrando operações de dentro do assentamento.",al={"de onde vieram as ordens","quem enviou haalien","traidor de valanaar"}},{q="Quem é Lotheluum e por que deve ser notificado?",a="Lotheluum é um contato localizado em Valanaar. Elegael Thornpaw ordena ao aventureiro que leve a missiva até Lotheluum para alertá-lo de que as ordens mortais dos cultistas remontam a alguém escondido em Valanaar.",al={"quem é lotheluum","por que levar a missiva para lotheluum","lotheluum valanaar"}}},fp="14,167,19.240.0,19.260.1,21.250.2,27.155.0,36.126.0,38.158.0,42.114.0,38.96.0,47.166.0"}
P.entries["quest:94491"] = {n="The Fate of the Den",s="The Fate of the Den relata o terrível desfecho de um ataque de cultistas a um isolado antro de druidas. Um aventureiro é enviado para levar uma missiva recuperada a Lotheluum em Valanaar, entregando notícias de graves baixas. O despacho revela uma realidade profundamente perturbadora: alguém em Valanaar tem fornecido informações vitais ao inimigo.",h="The Fate of the Den relata o terrível desfecho de um ataque de cultistas a um isolado antro de druidas.",kw={"cultistas","antro druida","altíssimo ancião","lotheluum","missiva","the fate of the den","traidor","valanaar"},ang={["class:Druid"]="Os Druidas sentem intensamente o peso dessa tragédia, pois os mortos no antro eram seus companheiros cujo refúgio isolado foi traído para cultistas hostis."},sec={{t="Tragédia em The Den",b="Após uma incursão violenta de cultistas ao antro dos druidas, os defensores sobreviventes encontram-se abalados e lamentando a perda de seus companheiros. Embora a crise imediata tenha sido estabilizada com ajuda externa, a devastação física e emocional é imensa. Aqueles que tombaram não podem ser restaurados, e os sobreviventes feridos permanecem sem condições de realizar uma longa jornada enquanto cultistas remanescentes ainda vagam por perto."},{t="Traição em Valanaar",b="Uma missiva recuperada confirma que o culto não agiu por acaso; alguém escondido em Valanaar tem vazado ativamente informações para eles. Ao receber o despacho, Lotheluum expressa absoluto horror diante do massacre de seus companheiros e da terrível implicação de que um cúmplice ou traidor anda livre por seu assentamento. Determinado a não deixar que o sacrifício deles seja esquecido, ele leva as evidências diretamente ao High Elder."}},faq={{q="Quem é Lotheluum?",a="Lotheluum é uma figura residente em Valanaar que recebe relatórios relativos ao antro dos druidas. Ao saber do ataque e analisar a missiva recuperada, ele expressa profundo pesar por seus companheiros caídos e jura levar as evidências da traição diretamente ao High Elder.",al={"lotheluum","quem é lotheluum","pnc lotheluum"}},{q="O que aconteceu no antro dos druidas?",a="O antro dos druidas sofreu um ataque devastador por cultistas hostis, deixando muitos defensores mortos. Embora a ameaça imediata tenha sido contida com a ajuda de um aventureiro, os protetores sobreviventes ficaram gravemente feridos e descobriram evidências de que o ataque foi guiado por um infiltrado.",al={"o que aconteceu em the den","ataque ao antro druida","história de the fate of the den"}},{q="O que a missiva recuperada revela?",a="A missiva revela que um correspondente escondido no assentamento de Valanaar tem fornecido informações secretamente ao culto. Essas informações sugerem que a incursão mortal ao antro foi possível graças à espionagem e sabotagem locais.",al={"o que diz a missiva","missiva de the den","missiva do traidor"}},{q="Quem é o High Elder mencionado por Lotheluum?",a="O High Elder é uma autoridade proeminente em Valanaar a quem Lotheluum responde. Devido à gravidade das baixas e à ameaça de um traidor ativo, Lotheluum leva imediatamente a missiva e as notícias da tragédia ao High Elder.",al={"quem é o altissímo ancião","altíssimo ancião de valanaar","altíssimo ancião"}},{q="Quem foi o responsável por atacar o antro dos druidas?",a="O ataque foi realizado por membros de um culto que opera na região. Os cultistas conseguiram infligir perdas catastróficas aos habitantes do antro graças às orientações de um informante abrigado em Valanaar.",al={"quem atacou the den","quem atacou o antro druida","cultistas de the den"}},{q="Por que o sobrevivente no antro não pôde entregar a missiva pessoalmente?",a="O sobrevivente no antro estava ferido demais para suportar a jornada até Valanaar após o ataque. Além de estar fisicamente incapacitado para a viagem, o sobrevivente ficou para trás para eliminar os cultistas restantes enquanto enviava um aventureiro para soar o alarme.",al={"por que entregamos a missiva","concedente da missão ferido","por que o sobrevivente não pode ir a valanaar"}}},fp="19,269,18.340.0,21.379.1,17.202.0,31.204.0,39.171.0,45.194.0,48.164.0,69.180.0"}
P.entries["quest:94493"] = {n="A Sacrifice in Vain",s="Elegael Thornpaw teme que os Cultistas de Al'Aketh dominem os feridos em seu covil. Uma mensagem destinada a Valanaar não chegou até eles, e ela precisa pedir ajuda.",h="Elegael Thornpaw teme que os Cultistas de Al'Aketh dominem os feridos em seu covil.",kw={"a sacrifice in vain","cultistas de al'aketh","covil","elegael thornpaw","reforços","valanaar","feridos"},sec={{t="Um Pedido de Ajuda",b="Os cultistas de Al'Aketh atacaram os companheiros de Elegael Thornpaw quase sem aviso. Muitos em seu covil estão feridos ou morrendo, e ela não sabe por quanto tempo conseguirão sobreviver ao ataque. Ela tentou enviar uma mensagem para Valanaar, mas ela não chegou. Sem reforços à vista, Elegael pede sua ajuda."}},faq={{q="Quem está pedindo ajuda?",a="Elegael Thornpaw pede ajuda enquanto os Cultistas de Al'Aketh atacam seus companheiros.",al={"quem precisa de ajuda","elegael thornpaw","elegael"}},{q="O que aconteceu com as pessoas no covil?",a="Os Cultistas de Al'Aketh as emboscaram sem dar muito aviso. Muitas estão feridas ou morrendo.",al={"feridos no covil","o que aconteceu aqui","ataque dos cultistas"}},{q="Por que Valanaar não enviou reforços?",a="A mensagem de Elegael não chegou a Valanaar, então os reforços ainda não chegaram.",al={"onde estão os reforços","mensagem para valanaar"}},{q="Do que Elegael precisa?",a="Elegael pede que você ajude seus companheiros feridos a sobreviver ao ataque dos Cultistas de Al'Aketh.",al={"como posso ajudar","ajudar elegael","o que ela pede"}}},fp="19,163,14.316.0,23.75.0,39.83.0,41.77.0,23.83.0"}
P.entries["quest:94494"] = {n="Call of Water",s="O Call of Water é uma missão espiritual para xamãs prontos para comungar com a natureza purificadora do elemento água. Tendo estabelecido harmonia com o vento, a terra e a chama, o iniciado chega a Norric Lochthane em Loch Modan, que o incita a dar o primeiro passo para aprender a pureza da água.",h="O Call of Water é uma missão espiritual para xamãs prontos para comungar com a natureza purificadora do...",kw={"call of water","elementos","montanha","pureza","xamã","provação do totem","totem da água"},ang={["class:Shaman"]="Esta provação marca um passo fundamental na sintonização com os espíritos elementais, progredindo da terra e do fogo em direção à compreensão da fluidez e pureza da água.",["race:Dwarf"]="A cadência anã e ríspida do mentor reflete como os xamãs anões em Forever abordam a comunhão com a natureza por meio de trilhas montanhosas e acidentadas."},sec={{t="O Caminho da Pureza",b="O Call of Water marca um estágio vital na jornada de um xamã rumo ao equilíbrio elemental. Com a terra firmando cada passo, o ímpeto do vento às suas costas e o fogo interior ardendo intensamente, o viajante é chamado a compreender a natureza mais profunda da água. Ela não é apenas uma força externa, mas um reflexo espiritual de pureza e resiliência."},{t="Ascensão aos Elementos",b="Guiado por um mentor experiente que fala na cadência firme dos picos, o iniciado é instigado a seguir em frente sem hesitação. A comunhão xamânica nunca é concedida levianamente; ela exige esforço físico, espírito perseverante e uma ascensão por terrenos acidentados. Como alerta o mentor, a montanha não espera por ninguém, e a jornada rumo à verdadeira compreensão deve começar com esse primeiro passo decisivo."}},faq={{q="O que é o Call of Water?",a="Call of Water representa um rito de passagem espiritual para xamãs que buscam a comunhão com o elemento da água. Já tendo aprendido a firmeza da terra, o ímpeto do vento e a centelha do fogo, o postulante é convocado a conhecer a verdade mais profunda da água.",al={"o que é call of water","missão call of water","o que é esta missão"}},{q="Quem guia este passo da jornada?",a="Eldrun Stormbreaker, o instrutor de xamãs em Altaforja, envia o iniciado para Norric Lochthane em Loch Modan. Norric profere estas palavras, incitando uma ação decisiva e lembrando ao viajante que os elementos e as alturas não esperam pelos hesitantes.",al={"quem dá call of water","quem diz que a montanha não espera por ninguém","mentor de call of water"}},{q="O que significa que a montanha não espera por ninguém?",a="É um chamado para dar o primeiro passo de uma subida exigente. As jornadas xamânicas frequentemente conduzem ao alto de picos e a ermos remotos onde os espíritos habitam, exigindo determinação em vez de dúvidas persistentes.",al={"o que significa a montanha não espera por ninguém","a montanha não espera por ninguém","significado da montanha"}},{q="Qual é a verdade sobre a pureza da água?",a="Na prática xamânica, cada elemento oferece ensinamentos distintos. Enquanto a pedra fornece estabilidade e o fogo alimenta a determinação, a água personifica a purificação, a fluidez e a pureza — sabedoria essencial para equilibrar os espíritos dentro de si mesmo.",al={"por que a pureza da água","verdade sobre a pureza da água","significado do elemento água"}},{q="Como a água se relaciona com os outros elementos aqui?",a="A jornada reconhece a terra, o vento e o fogo como alicerces já sentidos na bota, na respiração e no ventre antes de se aproximar da água. A harmonia com os elementos requer dominar o equilíbrio em vez de buscar um único poder isoladamente.",al={"quais elementos vêm primeiro","pré-requisitos para a água","elementos de call of water"}},{q="Para onde o iniciado vai após ouvir essas palavras?",a="O iniciado deve dar o primeiro passo. Norric Lochthane o envia para o Pantanal em busca do Water Sapta com Hervdana Saegrund, que habita uma caverna sob as quedas d'água do sul.",al={"o que acontece a seguir em call of water","para onde vou agora","próximo passo call of water"}}},fp="13,164,18.179.0,24.227.0,26.141.0,36.205.0,53.171.0,36.156.0,49.173.0,53.148.0"}
P.entries["quest:94495"] = {n="Call of Water",s="Call of Water envia buscadores espirituais ao Pantanal para aprender sobre o poder purificador da água e buscar o Water Sapta. Em uma caverna isolada sob as quedas ao sul, o anão Hervdana Saegrund recebe os viajantes que desafiam a natureza selvagem.",h="Call of Water envia buscadores espirituais ao Pantanal para aprender sobre o poder purificador da água e...",kw={"call of water","anão","hervdana saegrund","xamã","cachoeiras do sul","water sapta","pantanal"},ang={["class:Shaman"]="A missão marca um passo vital no aprendizado sobre a natureza da água e na obtenção de um water sapta para comungar com os espíritos.",["faction:Alliance"]="A jornada leva os viajantes às profundezas do perigoso Pantanal, bem longe de quaisquer patrulhas de guardas anões ou da Aliança.",["race:Dwarf"]="Hervdana reconhece o buscador como um parente desbravando os perigosos pântanos e os anões Ferro Negro à espreita nas proximidades."},sec={{t="A Natureza da Água",b="A jornada para compreender a água começa com uma simples lição sobre sua natureza dual: a água personifica o renascimento, esculpindo a pedra e purificando impurezas quando pura, mas ameaçando com a ruína quando maculada. Os iniciados que buscam comunhão são enviados à natureza selvagem para obter um water sapta daqueles que habitam ao lado do elemento."},{t="Abrigo Sob as Quedas d'Água",b="Nas profundezas dos pântanos úmidos do Pantanal, Hervdana Saegrund e sua família vivem em uma caverna oculta diretamente sob as cachoeiras do sul. Distantes da proteção dos guardas de Altaforja, eles enfrentam a ameaça dos anões Ferro Negro que espreitam nos pântanos ao redor para manter sua vida isolada junto às quedas d'água turbulentas."}},faq={{q="Quem é Hervdana Saegrund?",a="Hervdana Saegrund é uma anã que vive com sua família em uma caverna sob as cachoeiras do sul do Pantanal. Ela ajuda xamãs que buscam comunhão com a água e os segredos do water sapta.",al={"quem é hervdana","hervdana saegrund","onde fica hervdana"}},{q="O que é o water sapta?",a="Um water sapta é um elixir cerimonial usado por xamãs para comungar com os espíritos da água. Para adquirir um nos reinos orientais, os buscadores são direcionados a Hervdana Saegrund perto das cachoeiras do sul.",al={"o que é water sapta","significado de sapta","por que obter water sapta"}},{q="Onde Hervdana Saegrund pode ser encontrada?",a="Hervdana e sua família vivem isoladas dentro de uma caverna localizada diretamente sob as cachoeiras do sul no Pantanal.",al={"onde hervdana mora","onde fica a caverna","localização das cachoeiras do sul"}},{q="Por que Hervdana vive no perigoso Pantanal?",a="Apesar do perigo constante dos anões Ferro Negro à espreita por todos os pântanos e da total ausência de guardas da cidade, Hervdana e seus parentes escolheram o isolamento da caverna da cachoeira por seus próprios motivos.",al={"por que viver no pantanal","perigos do pantanal","ferro negro pantanal"}},{q="Qual é a lição da água ensinada aqui?",a="A água representa o renascimento, esculpindo a rocha, lavando a imundície e acalmando os cansados quando pura. Contudo, se corrompida ou maculada, ela arruína tudo o que toca.",al={"o que a água significa","filosofia da água","lição da água"}},{q="Qual é o propósito da missão Call of Water?",a="Call of Water é um rito de passagem de xamã que guia os iniciados a compreender a natureza do elemento e a buscar o water sapta com guias isolados.",al={"que tipo de missão é esta","para quem é esta missão","missão de xamã anão"}}},fp="13,172,19.234.0,25.277.0,25.191.0,24.183.0,37.114.0,49.167.0,40.130.0,47.114.0"}
P.entries["quest:94497"] = {n="Call of Water",s="Call of Water é uma missão espiritual no Pantanal que guia um iniciado no caminho para obter o sapta. Ao coletar água salobra de estuário onde as quedas das montanhas encontram as marés do mar, o buscador aprende as energias vitais da água enquanto enfrenta os perigos do pântano.",h="Call of Water é uma missão espiritual no Pantanal que guia um iniciado no caminho para obter o sapta.",kw={"call of water","ferro negro","estuário","hervdana","sapta","odre","pantanal"},ang={["class:Shaman"]="Buscar o sapta exige compreender a natureza da água em diferentes terras, sintonizando o espírito com suas várias manifestações.",["race:Dwarf"]="Hervdana lamenta a divisão persistente entre os clãs de anões, especialmente com os anões Ferro Negro avançando tão ao norte quanto o Pantanal."},sec={{t="O Caminho do Sapta",b="Para obter o sapta e comungar com os espíritos, um iniciado deve buscar a água em suas várias formas. Hervdana orienta os buscadores a observar como a água se move, muda vidas e sustenta a terra. A jornada começa com a compreensão das águas do estuário, onde a maré do oceano encontra o escoamento das águas doces das terras altas."},{t="Onde o Doce Encontra o Salobro",b="Na base das cachoeiras sob a caverna de Hervdana, a água de nascente das terras altas desce para o pântano para colidir com a água salgada trazida para o interior pelas marés costeiras. As marés oceânicas carregam sedimentos, minerais e energias vastamente diferentes do degelo límpido das montanhas, tornando o estuário uma fonte de sabedoria natural."},{t="Sombras no Pântano",b="Coletar água no Pantanal não é livre de perigos. Além da perigosa fauna do pântano, anões Ferro Negro avançaram desconfortavelmente para o norte. Hervdana observa com pesar a hostilidade contínua entre os clãs de anões, notando o quanto o povo anão poderia alcançar se ao menos deixasse de lado suas disputas."}},faq={{q="O que é o sapta?",a="O sapta é uma poção sagrada usada para comungar com os espíritos elementais. Para obtê-lo, um iniciado deve procurar a água em seus vários estados e entender como ela molda a terra e nutre os seres vivos.",al={"o que é o sapta","significado de sapta","por que buscar o sapta"}},{q="Quem é Hervdana?",a="Hervdana dá a tarefa a partir de sua caverna situada acima das cachoeiras no Pantanal. Ela atua como guia na coleta de amostras de água para sintonizar um iniciado com o elemento.",al={"quem dá call of water","onde fica hervdana","caverna de hervdana"}},{q="Por que coletar água onde o doce encontra o salobro?",a="A água de estuário representa uma confluência especial onde o degelo das terras altas e as nascentes de água doce se misturam com as marés oceânicas. Esse encontro de água doce e água salgada rica em minerais carrega sedimentos únicos e sabedoria espiritual.",al={"por que água de estuário","água salobra pantanal","doce encontra salgada"}},{q="Quais perigos espreitam perto das cachoeiras?",a="Anões Ferro Negro avançaram furtivamente para o norte no Pantanal, representando um perigo ativo para viajantes e buscadores elementais que tentam alcançar os pântanos e cachoeiras.",al={"ferro negro no pantanal","por que os anões ferro negro estão aqui","ameaça ferro negro"}},{q="O que significa se tornar um receptáculo?",a="Um receptáculo é um iniciado que começou a buscar ativamente a sabedoria das águas, carregando oferendas das águas da natureza para desenvolver uma harmonia elemental mais profunda.",al={"o que é um receptáculo","receptáculo de água"}},{q="Para que serve o Odre Marrom Vazio?",a="O Odre Marrom Vazio é o receptáculo fornecido por Hervdana para coletar a amostra salobra da base das cachoeiras do pântano.",al={"uso do odre marrom vazio","qual odre é usado"}}},fp="13,176,20.273.0,26.308.0,20.248.0,18.191.0,16.149.0,52.128.0,38.136.0,37.126.0,43.116.0"}
P.entries["quest:94499"] = {n="Call of Water",s="Call of Water é uma missão que encarrega os viajantes de irem até a Cachoeira do Mirante de Pedra, nas Montanhas Cristarrubra, para investigar uma suspeita de corrupção no escoamento do Lago Plácido. Ao encher um Odre Vermelho Vazio e devolvê-lo a Hervdana Saegrund no Pantanal, os xamãs descobrem a verdadeira fonte por trás da mutação dos murlocs locais, ao mesmo tempo em que garantem um reagente essencial para seus testes espirituais.",h="Call of Water é uma missão que encarrega os viajantes de irem até a Cachoeira do Mirante de Pedra, nas...",kw={"call of water","hervdana saegrund","lago plácido","murlocs rastejanoturnos","montanhas cristarrubra","sapta","videntes das sombras","cachoeira do mirante de pedra","pantanal"},ang={["class:Shaman"]="Esta missão é um passo essencial na preparação de um Water Sapta, testando a devoção e a percepção de um xamã por cursos d'água distantes antes de comungar com os espíritos da água."},sec={{t="Uma Cascata Suspeita",b="Hervdana Saegrund, no Pantanal, envia aspirantes a xamãs para o sul, nas Montanhas Cristarrubra, a fim de investigar as águas que descem pela Cachoeira do Mirante de Pedra. Enquanto o Lago Plácido abastece o assentamento de Vila Plácida com água pura, os murlocs que espreitam na base da cascata transformaram-se em feras incomumente gigantescas e deformadas. Suspeitando de veneno, feitiçaria nefasta ou infiltração vinda da antiga fortaleza acima, Hervdana encarrega os viajantes de coletar uma amostra em um Odre Vermelho Vazio."},{t="A Verdadeira Fonte da Corrupção",b="Ao inspecionar o odre cheio, Hervdana descobre que a água em cascata vinda do Lago Plácido é totalmente límpida e não foi afetada pela poluição. A distorção física observada entre os murlocs Rastejanoturnos locais não é causada por água imprópria para consumo, mas sim pela feitiçaria sombria empregada por videntes das sombras à espreita ao redor de Mirante de Pedra. Provando tanto a pureza da cachoeira quanto a dedicação do xamã, a amostra serve como um reagente vital necessário para preparar um sapta espiritual."}},faq={{q="Quem dá esta missão e onde se encontra?",a="Hervdana Saegrund, localizada no Pantanal, atribui esta tarefa. Ela estuda fontes de água e reagentes necessários para criar um sapta para os testes espirituais de um aspirante a xamã.",al={"quem dá call of water","concedente da missão hervdana"}},{q="Por que você é enviado para coletar água da Cachoeira do Mirante de Pedra?",a="Hervdana suspeita que um veneno estranho, magia sombria ou corrupção possam estar escorrendo pela Cachoeira do Mirante de Pedra a partir do antigo forte acima, resultando em murlocs deformados na base. Ela precisa de uma amostra fresca para inspecionar.",al={"por que encher odre montanhas cristarrubra","propósito de cachoeira do mirante de pedra"}},{q="A água da Cachoeira do Mirante de Pedra está realmente corrompida?",a="Não, a água em si demonstra ser completamente pura e incontaminada. Hervdana determina que o estado deformado dos murlocs locais decorre, na verdade, da magia sombria lançada por videntes das sombras da região, e não de um escoamento poluído.",al={"as águas de mirante de pedra estão corrompidas","o lago plácido está corrompido"}},{q="Por que os murlocs ao redor da Cachoeira do Mirante de Pedra são tão grandes e deformados?",a="Os murlocs Rastejanoturnos perto da base da cachoeira são grandes e deformados em comparação aos encontrados no Loch ou no Pantanal. Hervdana conclui que essa alteração é provocada pela magia nefasta dos videntes das sombras locais.",al={"por que os murlocs de montanhas cristarrubra sofreram mutação","diferença dos murlocs de mirante de pedra"}},{q="Para que serve a amostra de água?",a="Um sapta é uma mistura cerimonial que permite a um xamã atravessar o véu e vislumbrar espíritos elementais. Hervdana coleta amostras puras de várias águas para preparar o reagente necessário para o seu.",al={"o que é sapta","propósito da recompensa de call of water"}},{q="Quem é Norric?",a="Norric é um associado ou mentor envolvido nos testes xamânicos que, segundo Hervdana, ficará satisfeito com a sua recuperação bem-sucedida da amostra de água pura.",al={"quem é norric","norric call of water"}}},fp="13,154,17.377.0,29.321.1,48.155.0,56.206.0,50.111.0,65.166.0,34.165.0,14.135.0"}
P.entries["quest:945"] = {n="A fuga de Therylune",s="No sul de Costa Negra, uma jovem elfa noturna chamada Therylune se aventurou pelas escavações sinistras da Glaive do Mestre e acabou cercada por sectários hostis. Ela precisa de uma escolta da Aliança para chegar a um lugar seguro e dar notícias de sua sobrevivência à irmã preocupada, Therysil, que está no Altar de Aessina.",h="No sul de Costa Negra, uma jovem elfa noturna chamada Therylune se aventurou pelas escavações sinistras da...",kw={"vale gris","sectários","escolta","glaive do mestre","altar de aessina","therylune","therysil","martelo do crepúsculo"},ang={["faction:Alliance"]="Ajudar viajantes em apuros, como Therylune, fortalece a presença e a boa reputação da Aliança entre os elfos noturnos que defendem o Vale Gris.",["race:NightElf"]="A Glaive do Mestre é uma cicatriz ancestral na história de Kalimdor. Ver outros kaldorei entrarem sem cautela nas escavações de sectários é um lembrete preocupante das ameaças que se infiltram no Vale Gris."},sec={{t="Um passeio perigoso",b="A Glaive do Mestre é um dos locais mais inquietantes de Costa Negra, dominado pelo crânio colossal de uma monstruosidade ancestral atravessado por uma imensa lâmina de pedra. Apesar do terror que paira sobre o vale, Therylune entrou sem hesitar no coração da ravina. Logo se viu encurralada por sectários do Martelo do Crepúsculo, sobrevivendo apenas graças aos reflexos rápidos e à habilidade de se esconder entre as rochas."},{t="Notícias para o altar",b="Therysil, irmã de Therylune, vive bem ao sul, no tranquilo Altar de Aessina. Embora Therylune seja conhecida por seu espírito aventureiro e por não se importar em sujar as roupas, até seus parentes ficaram chocados ao saber que ela entrou nas escavações sinistras da Glaive do Mestre. Levar a notícia de que Therylune está a salvo tranquiliza sua irmã, que conhece bem as forças sombrias que escavam o solo ancestral de Costa Negra."}},faq={{q="Quem é Therylune?",a="Therylune é uma jovem elfa noturna aventureira que se perdeu nas perigosas escavações da Glaive do Mestre, no sul de Costa Negra. Ela é irmã de Therysil.",al={"therylune","quem é a garota","elfa encurralada"}},{q="Quem é Therysil?",a="Therysil é irmã de Therylune e fica no tranquilo Altar de Aessina, no Vale Gris. Ela fica consternada ao saber que a irmã se aventurou tão perto de um lugar sombrio e corrompido.",al={"therysil","irmã de therylune"}},{q="Por que a Glaive do Mestre é tão perigosa?",a="A Glaive do Mestre é uma ravina ancestral e ameaçadora onde um antigo senhor caiu há muito tempo. Sectários do Martelo do Crepúsculo infestam a região, escavam o local e atacam qualquer intruso.",al={"perigos da glaive do mestre","sectários da glaive do mestre"}},{q="Até onde Therylune precisa ser escoltada?",a="Therylune precisa ser escoltada para longe das imediações da Glaive do Mestre, até um lugar seguro. Depois disso, quem a resgatou deve viajar ao Altar de Aessina para avisar sua irmã.",al={"destino da escolta","para onde therylune vai"}},{q="Onde fica o Altar de Aessina?",a="O Altar de Aessina fica no sudoeste do Vale Gris, a oeste de Astranaar, e é um santuário dedicado ao espírito da floresta Aessina.",al={"localização do altar de aessina","onde fica therysil"}},{q="Como Therylune sobreviveu cercada por sectários?",a="Therylune escapou da captura ao encontrar um esconderijo apertado entre as rochas, antes que os sectários do Martelo do Crepúsculo ao redor pudessem avistá-la.",al={"como therylune se escondeu"}}},fx={["8c0c4bd7"]={q="Por que Therylune precisa da sua ajuda para escapar?",a="Therylune vagou pela escavação sinistra na The Master's Glaive e rapidamente se viu presa e cercada pelos cultistas do Martelo do Crepúsculo. Embora sua habilidade de se esconder a tenha mantido viva, ela não consegue passar pelos fanáticos que a cercam sozinha para alcançar a segurança e tranquilizar sua irmã, Therysil.",al={"por que therylune quer ajuda","motivo de therylune","por que ajudar therylune"}},cc515991={q="Por que Therylune não consegue escapar sozinha?",a="Embora seja habilidosa o suficiente em se esconder para evitar a captura imediata, Therylune está completamente desarmada, indefesa e presa profundamente em território hostil. Sem guardas locais ou aliados por perto para ajudá-la, ela depende inteiramente de um aventureiro de passagem para abrir um caminho de fuga através dos cultistas.",al={"por que therylune precisa de mim","por que therylune não consegue escapar","por que eu, therylune"}}},fp="18,189,17.304.0,18.371.0,17.159.0,16.156.0,40.167.0,41.143.0,39.130.0,49.129.0"}
P.entries["quest:94500"] = {n="Call of Water",s="Call of Water incumbe um aventureiro de viajar sob a copa esmeralda de Vale Gris para coletar água pura e ancestral do lago que abriga Astranaar. Isso marca a etapa final de coleta antes de o viajante ser enviado de volta para Norric.",h="Call of Water incumbe um aventureiro de viajar sob a copa esmeralda de Vale Gris para coletar água pura e...",kw={"vale gris","astranaar","auberdine","call of water","menethil","norric","costa sul","cantil"},ang={["faction:Alliance"]="Esta missão guia os viajantes pela rota marítima da Aliança, dos Reinos do Leste até Kalimdor, conectando o Porto de Menethil a Auberdine e ao assentamento de Elfos Noturnos de Astranaar.",["race:NightElf"]="A missão direciona os viajantes às águas cristalinas ao redor de Astranaar, um dos corações dos Kaldorei em Vale Gris, onde ruínas ancestrais ainda repousam intocadas."},sec={{t="A Busca por Água Pura",b="Call of Water encarrega um aventureiro de encher um cantil com as águas incorruptas de Vale Gris. O buscador precisa se aventurar até Astranaar, um refúgio aninhado em meio a águas límpidas e ancestrais que banham ruínas submersas de uma era passada. Essa amostra imaculada serve como o líquido final necessário ao distribuidor da missão antes de o viajante ser enviado até Norric."},{t="A Estrada para Astranaar",b="Alcançar as profundezas de Vale Gris exige cruzar o mar a partir dos Reinos do Leste. O caminho recomendado leva os viajantes a bordo do navio que zarpa do Porto de Menethil rumo a Auberdine, atracando em Costa Sul ao longo da jornada. Das docas de Auberdine, a estrada segue terra adentro em direção aos ramos esmeralda de Vale Gris, onde os viajantes são alertados a permanecer atentos entre as sombras vigilantes das árvores."}},faq={{q="O que é a missão Call of Water?",a="Call of Water é uma missão que exige que o viajante leve um cantil vazio para as profundezas da floresta ancestral de Vale Gris. O objetivo é coletar uma amostra de água pura, ancestral e potencialmente encantada do lago que abriga o assentamento de Astranaar antes de devolvê-la ao distribuidor da missão.",al={"o que é call of water","missão call of water","objetivo de call of water"}},{q="Onde coleto a água para esta missão?",a="A água deve ser coletada no lago que cerca Astranaar, localizado nas profundezas de Vale Gris. As águas de lá permanecem incorruptas, fluindo em meio a antigas ruínas submersas que remontam a uma era passada.",al={"onde encontrar água pura","onde encher o cantil","localização de call of water"}},{q="Como viajo para Vale Gris para esta missão?",a="Recomenda-se aos viajantes embarcar no barco do Porto de Menethil para Auberdine, que faz uma parada em Costa Sul pelo caminho. De Auberdine, na Costa Negra, viaja-se para o sul em direção aos bosques verde-esmeralda profundos de Vale Gris para chegar a Astranaar.",al={"como chegar a astranaar","viajar para vale gris","barco para astranaar"}},{q="O que torna a água em Astranaar especial?",a="O lago que abriga Astranaar é conhecido por conter águas intocadas pela corrupção. Sob sua superfície encontram-se ruínas de pedra submersas que remetem a uma era ancestral e passada da civilização élfica, conferindo à água suas propriedades imaculadas e potencialmente encantadas.",al={"qual lago em astranaar","ruínas aquáticas de astranaar","ruínas no lago de astranaar"}},{q="Quem é Norric?",a="Norric é o indivíduo que aguarda o viajante após a coleta dessa última amostra líquida. O distribuidor da missão coleta essa água pura de Vale Gris como o último ingrediente antes de enviar o aventureiro de volta para Norric.",al={"quem é norric","retornar a norric"}},{q="Quais perigos devo esperar em Vale Gris?",a="Vale Gris é uma floresta ancestral e densa, repleta de perigos. O distribuidor da missão adverte os viajantes a ficarem constantemente atentos, alertando que a floresta tem olhos vigilantes que não piscam quando alguém se aventura sob sua copa esmeralda.",al={"perigo em vale gris","ameaças de vale gris"}}},fp="13,126,25.233.0,21.285.0,32.174.0,44.137.0,44.197.0,42.188.0,14.146.0,42.147.0"}
P.entries["quest:94501"] = {n="Call of Water",s="O Call of Water é uma provação espiritual para xamãs em busca dos ritos sagrados do Totem da Água. Ao entregar água pura abençoada por Hervdana a Norric Lochthane em Loch Modan, os buscadores preparam o sapta elemental necessário para comungar com espíritos no Lago Stendel.",h="O Call of Water é uma provação espiritual para xamãs em busca dos ritos sagrados do Totem da Água.",kw={"call of water","hervdana","loch modan","arroio da lua","norric lochthane","xamã","lago stendel","ampola da mais pura água","water sapta","totem da água"},ang={["class:Shaman"]="Esta provação é um passo crucial na comunhão com os elementos para obter os ritos do Totem da Água e criar o sapta necessário para ver espíritos elementais.",["faction:Alliance"]="Xamãs da Aliança buscam comunhão com espíritos da água pelas terras orientais, unindo Loch Modan e Cerro Oeste.",["race:Dwarf"]="A jornada conecta candidatos a xamã anões com mentores elementais como Norric Lochthane por Khaz Modan."},sec={{t="O Caminho para o Totem da Água",b="O Call of Water representa uma provação essencial de sintonização espiritual para aspirantes a xamã em busca de harmonia com o elemento da água. Seguir este caminho exige coletar água abençoada pela própria Hervdana, provando paciência e reverência pelos espíritos antes de levar o recipiente a Norric Lochthane em Loch Modan."},{t="Gerando o Sapta",b="Ao receber o recipiente abençoado, Norric revela que o líquido sagrado é destinado a preparar um Water Sapta. Este trago permite ao buscador atravessar o invisível e testemunhar os espíritos da água que habitam o Lago Stendel, perto de Arroio da Lua. Cada gota é considerada preciosa, pois até mesmo uma rolha umedecida tem propósito nos ritos sagrados."}},faq={{q="Quem é Norric Lochthane?",a="Norric Lochthane é um mentor residente em Loch Modan que guia candidatos através de sua comunhão elemental. Ele supervisiona as preparações e ritos necessários para obter o Totem da Água.",al={"quem é norric","norric loch modan","quem é norric lochthane"}},{q="Quem é Hervdana?",a="Hervdana Saegrund é a guia no Pantanal que vive com sua família em uma caverna perto das cachoeiras do sul e abençoa a água sagrada coletada por aspirantes a xamãs, imbuindo-a com a pureza espiritual necessária para criar Water Sapta.",al={"quem é hervdana","abençoada por hervdana","água de hervdana"}},{q="Para que serve um sapta?",a="Um sapta é uma poção elemental preparada usando água sagrada. Bebê-lo permite que um xamã rompa o véu e perceba espíritos da água esquivos que habitam lagoas naturais.",al={"o que é water sapta","propósito do sapta","o que o sapta faz"}},{q="Onde fica o Lago Stendel?",a="O Lago Stendel fica em Cerro Oeste, perto de Arroio da Lua. Suas águas abrigam espíritos elementais da água que um xamã deve procurar após consumir seu sapta preparado.",al={"onde fica o lago stendel","localização do lago stendel","espíritos da água stendel"}},{q="Por que a Ampola da Mais Pura Água é importante?",a="A Ampola da Mais Pura Água contém água abençoada essencial para preparar o Water Sapta e realizar os ritos sagrados necessários para obter um Totem da Água. Norric adverte que nem mesmo uma única gota pode ser desperdiçada.",al={"por que precisa de água pura","propósito da ampola da mais pura água"}},{q="O que são os ritos do Totem da Água?",a="Os ritos do Totem da Água são provações espirituais realizadas por xamãs para se sintonizarem com o elemento da água, demonstrando respeito e equilíbrio antes de receberem um Totem da Água.",al={"o que são os ritos do totem da água","como obter o totem da água"}}},fp="13,168,27.150.0,18.228.1,24.159.0,16.165.0,25.123.0,32.133.0,42.162.0,31.137.0"}
P.entries["quest:94502"] = {n="Call of Water",s="Call of Water é uma missão elemental que exige uma jornada de Loch Modan até Cerro Oeste para restaurar o equilíbrio de uma nascente corrompida. Ao expurgar a entidade maculada no Lago Stendel e realizar um ritual ancestral no santuário esquecido, os postulantes conquistam o favor dos espíritos da água e seu Totem da Água.",h="Call of Water é uma missão elemental que exige uma jornada de Loch Modan até Cerro Oeste para restaurar o...",kw={"call of water","loch modan","arroio da lua","norric","xamã","lago stendel","totem da água","cerro oeste"},ang={["class:Shaman"]="Este teste representa um rito de passagem crucial para sintonizar-se com os espíritos da água e conquistar o Totem da Água, demonstrando harmonia e domínio sobre as forças elementais.",["faction:Alliance"]="Xamãs da Aliança precisam viajar por seus territórios, aventurando-se de Loch Modan até as terras conturbadas de Cerro Oeste para purificar águas corrompidas."},sec={{t="Uma Nascente Maculada pela Sombra",b="Na sombra de Arroio da Lua fica o Lago Stendel, outrora celebrado como uma nascente límpida e pura. Influências sombrias que se espalham por Cerro Oeste macularam suas águas tranquilas, mergulhando os espíritos da água locais em um silêncio profundo. Um santuário antigo ergue-se à beira da margem, negligenciado e coberto de poeira e teias de aranha, esperando que alguém desperte os poderes adormecidos em seu interior."},{t="O Rito de Purificação",b="Norric em Loch Modan orienta os postulantes no ritual necessário para restaurar o equilíbrio. O rito exige enfrentar a entidade imunda que polui o Lago Stendel, obter suas braçadeiras e oferecê-las sobre o santuário de pedra junto com gotas de uma poção alquímica. Quando o encantamento é proferido, os vapores invocam um espírito purificado, transmitindo sabedoria e provando que o portador é digno do Totem da Água."}},faq={{q="O que é a missão Call of Water?",a="Call of Water é uma provação espiritual para xamãs que buscam comungar com os elementos da água. A missão encarrega o suplicante de purificar a corrupção no Lago Stendel, em Cerro Oeste, usando um antigo santuário no local para evocar um espírito da água purificado e conquistar seu Totem da Água.",al={"o que é call of water","missão do totem da água","missão da água cerro oeste"}},{q="Quem dá esta missão?",a="A missão é dada por Norric, um mentor situado em Loch Modan. Ele instrui os postulantes em ritos elementais, fornece poções especiais e os orienta na purificação de águas elementais corrompidas.",al={"quem dá call of water","norric loch modan","concedente da missão"}},{q="Onde fica o Lago Stendel?",a="O Lago Stendel fica nos arredores de Arroio da Lua, no sudoeste de Cerro Oeste. Outrora uma nascente pura, ele se tornou estagnado e turvo sob a influência de forças sombrias e corruptoras.",al={"onde fica o lago stendel","localização do lago stendel","lago perto de arroio da lua"}},{q="Como você purifica a corrupção no Lago Stendel?",a="Para purificar as águas, você deve derrotar a presença corruptora no Lago Stendel, pegar suas braçadeiras e colocá-las no santuário ancestral junto com as gotas restantes de poção enquanto recita as palavras ensinadas por Norric.",al={"como purificar o lago","purificar o lago stendel","ritual do santuário"}},{q="O que você ganha ao concluir esta missão?",a="Concluir o teste e levar a prova da purificação para Norric em Loch Modan recompensa o postulante com o seu Totem da Água, concedendo domínio sobre os poderes elementais da água.",al={"qual a recompensa de call of water","recompensa do totem da água"}},{q="Por que o Lago Stendel está corrompido?",a="A fonte da escuridão é incerta. O lago jaz anormalmente estagnado, cercado por ossos de feras, gerando preocupações se ele foi envenenado pelo mal que se espalha por Cerro Oeste ou se atua como uma própria nascente de corrupção.",al={"por que o lago stendel está corrompido","o que corrompeu o lago"}}},fp="13,212,26.284.0,21.359.1,32.235.0,21.168.0,24.152.0,52.195.0,43.169.0,32.211.0"}
P.entries["quest:94503"] = {n="Call of Water",s="Call of Water é uma missão centrada em Cerro Oeste que incumbe aventureiros de purificar forças elementais corrompidas. Ao dissipar espíritos inquietos com luz radiante, os jogadores comungam com uma Manifestação Menor da Água para proteger a vitalidade cada vez menor da região.",h="Call of Water é uma missão centrada em Cerro Oeste que incumbe aventureiros de purificar forças elementais...",kw={"call of water","purificação","corrupção","elemental","manifestação menor da água","espírito da água","cerro oeste"},ang={["class:Shaman"]="Comungar com elementos primordiais e purificar espíritos da água maculados é um rito fundamental dos elementos, lembrando aos xamãs seu dever eterno de equilibrar a natureza.",["faction:Alliance"]="A manifestação reside em Cerro Oeste, um território da Aliança onde os espíritos locais suportam a praga rastejante que atinge a terra."},sec={{t="Purificando as Águas Maculadas",b="Nas terras fustigadas pelo vento de Cerro Oeste, o equilíbrio natural das águas enfrenta a contaminação por espíritos corruptos. O rito conhecido como Call of Water exige enfrentar essa malevolência, invocando palavras sagradas que conjuram luz radiante para dispersar as essências inquietas e maculadas em cinzas inofensivas e névoa silenciosa."},{t="O Alerta do Espírito",b="Com as entidades corrompidas repelidas, uma Manifestação Menor da Água pode emergir em segurança para comungar. Enquanto a corrupção imediata míngua, o espírito adverte que as energias vitais da terra continuam a diminuir, lembrando aos campeões que preservar a vida é uma vigília sem fim."}},faq={{q="O que é Call of Water?",a="Call of Water é uma provação espiritual em Cerro Oeste onde espíritos corruptos são banidos por uma invocação ritual que irrompe em luz, libertando as águas perturbadas e permitindo a comunhão com uma Manifestação Menor da Água.",al={"o que é call of water","call of water cerro oeste","missão da água de cerro oeste"}},{q="Onde a Manifestação Menor da Água pode ser encontrada?",a="A Manifestação Menor da Água está localizada em Cerro Oeste. Ela aparece assim que os espíritos corrompidos ao redor são subjugados e dissipados, aguardando para falar com aqueles que ajudaram as águas.",al={"onde fica a manifestação menor da água","localização da manifestação","espírito da água de cerro oeste"}},{q="O que acontece quando os espíritos corrompidos são purificados?",a="À medida que o encantamento termina, uma luz brilhante irrompe para dispersar os espíritos corruptos, fazendo com que sua essência maculada se desfaça e se espalhe como cinzas enquanto a água sibila em névoa suave.",al={"o que acontece durante o ritual","espíritos corrompidos call of water"}},{q="A terra é totalmente restaurada após a conclusão da tarefa?",a="A corrupção imediata é repelida e míngua, mas o elemental adverte que a vitalidade continua a diminuir, deixando a proteção duradoura da vida nas mãos dos mortais.",al={"a corrupção sumiu","nós salvamos a água"}},{q="Quem é chamado para ajudar a manifestação?",a="A missão reconhece o chamado do jogador, agradecendo à sua classe por dar um passo à frente para purificar os espíritos e assumir a responsabilidade de proteger a vida decadente.",al={"quem pode fazer call of water","requisito de classe missão da água"}},{q="Por que os espíritos da água foram corrompidos em Cerro Oeste?",a="Espíritos corrompidos perturbaram as águas naturais ao longo de Cerro Oeste. Embora a origem precisa da mácula permaneça sutil, sua presença malevolente drena diretamente a vitalidade viva da área.",al={"por que a água está corrompida em cerro oeste","problema da água em cerro oeste"}}},fp="13,113,28.166.0,20.184.0,22.203.0,52.163.0,53.149.0,53.155.0,47.147.0,49.153.0"}
P.entries["quest:94505"] = {n="Call of Water",s="O Call of Water é um rito de passagem elemental no qual xamãs aprendem a comungar com espíritos da água e a empunhar seus poderes restauradores. Ao recuperar um Estilhaço de Água de Cerro Oeste para Norric Lochthane em Loch Modan, os iniciados provam sua dedicação e recebem seu Totem da Água.",h="O Call of Water é um rito de passagem elemental no qual xamãs aprendem a comungar com espíritos da água e a...",kw={"call of water","loch modan","norric lochthane","xamã","estilhaço de água","totem da água","cerro oeste"},ang={["class:Shaman"]="Esta provação marca um rito de passagem fundamental, concedendo ao xamã a comunhão com espíritos da água e seu Totem da Água para curar e sustentar a vida.",["faction:Alliance"]="Ao contrário dos xamãs da Horda de Kalimdor, os iniciados alinhados à Aliança reportam-se a mentores como Norric Lochthane em Loch Modan e enfrentam provações em lugares como Cerro Oeste."},sec={{t="O Caminho da Água",b="O Call of Water é uma provação espiritual vital realizada por xamãs para forjar um vínculo com o elemento da água. Os iniciados têm a tarefa de viajar até Cerro Oeste e retornar a Norric Lochthane em Loch Modan com o Estilhaço de Água. Ao demonstrar sua compreensão da essência vivificante da água e de seu papel na purificação da corrupção, os xamãs conquistam seu Totem da Água e dão um passo essencial em sua jornada elemental."},{t="Doadora da Vida",b="A provação transmite uma verdade elemental fundamental: a água é vida, e a corrupção põe fim à vida. Os xamãs são encarregados de empunhar a força restauradora da água para proteger os vulneráveis e preservar os seres vivos. Como o mentor Norric Lochthane observa ao receber o Estilhaço de Água, as dádivas puras da água vão muito além da simples recuperação física, alcançando resistência, renovação e equilíbrio espiritual."}},faq={{q="Quem é Norric Lochthane?",a="Norric Lochthane é um mentor xamã situado em Loch Modan. Ele guia os iniciados através de suas provações para compreender os espíritos da água, testa sua determinação com uma jornada a Cerro Oeste e lhes entrega seu Totem da Água após apresentarem a prova de sua comunhão.",al={"quem é norric lochthane","quem dá o totem da água","norric loch modan"}},{q="O que é o Estilhaço de Água?",a="O Estilhaço de Água é a prova física trazida de Cerro Oeste para Norric Lochthane em Loch Modan. Ele significa que o iniciado comungou com a água, compreendeu sua natureza vivificante e aprendeu a combater a corrupção.",al={"o que é estilhaço de água","uso do estilhaço de água","item de missão estilhaço de água"}},{q="Por que a provação leva a Cerro Oeste?",a="Iniciados são enviados a Cerro Oeste para compreender o poder vivificante da água e como a corrupção o ameaça. Mesmo vitórias modestas naquela terra atribulada têm peso ao demonstrar a habilidade do iniciado de proteger a vida.",al={"por que ir a cerro oeste","missão da água em cerro oeste","jornada a cerro oeste call of water"}},{q="Qual é o significado do Totem da Água?",a="O Totem da Água personifica o vínculo de um xamã com o elemento da água. Embora seja conhecido principalmente por suavizar e curar ferimentos por meio de água pura, suas dádivas espirituais vão muito além da cura básica, englobando preservação e vitalidade.",al={"o que o totem da água faz","por que xamãs precisam do totem da água","história do totem da água"}},{q="Que lição a provação ensina sobre a água?",a="A filosofia elemental ensinada durante a provação enfatiza que a água dá a vida, ao passo que a corrupção a interrompe. Um xamã é encarregado de usar o poder elemental da água para nutrir, proteger e restaurar o equilíbrio onde quer que a corrupção ameace os seres vivos.",al={"o que é água é vida","filosofia de call of water","ensinamentos da água para xamãs"}},{q="O que vem depois de concluir o Call of Water?",a="Norric Lochthane observa que a próxima provação elemental de um iniciado não virá de imediato. Ele encoraja os xamãs a reservarem um tempo para praticar e explorar os mistérios mais profundos da água antes de realizar outras provações.",al={"qual provação vem a seguir","próxima provação do xamã","o que acontece após call of water"}}},fp="13,163,17.305.0,13.267.0,24.236.0,27.193.0,36.173.0,44.145.0,45.201.0,46.170.0"}
P.entries["quest:94532"] = {n="Gnoll Infestation",s="Neza Bloodsnout, em Rog'mar, pede que você expulse os gnolls das colinas a sudoeste. A presença deles atrapalha o comércio e as viagens, embora o avanço do Crepúsculo tenha reduzido seus números.",h="Neza Bloodsnout, em Rog'mar, pede que você expulse os gnolls das colinas a sudoeste.",kw={"brutamontes","infestação de gnolls","gnolls","místicos","neza bloodsnout","montanhas cristarrubra","rog'mar","armadilheiros","crepúsculo"},sec={{t="Gnolls nas colinas",b="Com o avanço do Crepúsculo reduzindo seus números, os gnolls de Montanhas Cristarrubra ainda causam problemas nas colinas a sudoeste de Rog'mar. Neza Bloodsnout pede que você abra caminho para os aliados, eliminando a ameaça. O comércio e as viagens continuam prejudicados enquanto os gnolls mantêm posição."}},faq={{q="Por que os gnolls são um problema?",a="Os gnolls nas colinas a sudoeste de Rog'mar atrapalham o comércio e causam problemas aos viajantes.",al={"gnolls atrapalhando o comércio","por que expulsar os gnolls","ameaça dos gnolls"}},{q="Onde estão os gnolls?",a="Eles infestam as colinas a sudoeste.",al={"colinas dos gnolls","onde estão os gnolls de montanhas cristarrubra"}},{q="Quem pede que eu cuide deles?",a="Neza Bloodsnout, em Rog'mar, pede que você elimine a ameaça dos gnolls.",al={"quem deu a missão infestação de gnolls","missão de neza"}},{q="Há menos gnolls agora?",a="Sim. A presença deles diminuiu com o avanço do Crepúsculo, mas a ameaça continua.",al={"número de gnolls","crepúsculo e gnolls"}},{q="Que tipos de gnolls existem?",a="Os gnolls mencionados são Redridge Mystics, Redridge Trappers e Redridge Brutes.",al={"tipos de gnolls","místicos, armadilheiros e brutamontes"}}},fp="17,187,19.268.0,29.81.0,21.39.0,30.63.0,27.86.0,31.78.0"}
P.entries["quest:94533"] = {n="Snargl's Snout",s="Neza Bloodsnout quer o focinho de Snargl como troféu. Os sons desagradáveis do gnoll ancião incomodam aliados e batedores nas Colinas Cerdosas.",h="Neza Bloodsnout quer o focinho de Snargl como troféu.",kw={"colinas cerdosas","gnoll","neza bloodsnout","snargl","focinho de snargl","focinho","troféu"},sec={{t="Um Troféu para Neza",b="Neza Bloodsnout quer uma lembrança para sua coleção, e Snargl é o gnoll que ela indica. Você é enviado às Colinas Cerdosas para trazer o focinho dele. Neza espera que você seja rápido; os aliados e batedores que entram nessa área enfrentam problemas por causa dos sons de Snargl."}},faq={{q="Quem é Snargl?",a="Snargl é um gnoll ancião nas Colinas Cerdosas, a sudoeste de Neza Bloodsnout.",al={"snargl","gnoll snargl","gnoll ancião"}},{q="Por que Neza quer o focinho de Snargl?",a="Neza quer o focinho de Snargl como lembrança para sua coleção de troféus.",al={"por que o focinho","troféu snargl","coleção neza"}},{q="Onde fica Snargl?",a="Snargl fica nas Colinas Cerdosas, a sudoeste de Neza Bloodsnout.",al={"localização snargl","onde fica snargl","gnoll colinas cerdosas"}},{q="Que problemas Snargl causa?",a="Snargl faz sons desagradáveis que incomodam aliados e batedores que entram nas Colinas Cerdosas.",al={"sons snargl","por que os batedores são incomodados","barulho de gnoll"}},{q="O que Neza diz quando você retorna?",a="Neza diz que o troféu é mais pesado do que esperava e o recebe como uma adição à coleção.",al={"conclusão de snargl","reação de neza","focinho entregue"}}},fp="14,133,17.247.0,14.75.0,34.63.0,16.61.0,31.90.0,35.95.0"}
P.entries["quest:94535"] = {n="Bristle Hills Bandits",s="Kreza Darkthorn envia você às Colinas Cerdosas depois que gnolls atacam mineradores aliados. Você deve recuperar o minério roubado nos acampamentos deles.",h="Kreza Darkthorn envia você às Colinas Cerdosas depois que gnolls atacam mineradores aliados.",kw={"mineradores aliados","bandidos","colinas cerdosas","gnolls","kreza darkthorn","minério roubado"},sec={{t="Minério das Colinas",b="Mineradores aliados relatam ataques de gnolls nas colinas ao sul de Kreza Darkthorn. Você deve encontrar os acampamentos nas Colinas Cerdosas e recuperar o minério roubado. As perdas dos mineradores estão em jogo."},{t="Depois da Recuperação",b="Kreza Darkthorn diz que o minério foi recuperado e que o fogo apagará quaisquer marcas ou rastros deixados para trás."}},faq={{q="Quem me envia atrás do minério roubado?",a="Kreza Darkthorn pede que você recupere o minério roubado dos mineradores aliados.",al={"quem é kreza","quem pede o minério"}},{q="Onde estão os bandidos?",a="Os gnolls estão em acampamentos nas Colinas Cerdosas, ao sul de Kreza Darkthorn.",al={"acampamentos de gnolls","onde estão os bandidos"}},{q="Quem roubou o minério?",a="Gnolls nas Colinas Cerdosas atacaram mineradores aliados e levaram o minério deles.",al={"ladrões de minério","quem levou o minério"}},{q="O que aconteceu com os mineradores?",a="Mineradores aliados que trabalham nas colinas ao sul relataram vários ataques de gnolls.",al={"mineradores atacados","por que roubaram o minério"}}},fp="21,139,18.187.0,18.98.1,34.70.0,22.71.0,18.70.0,28.83.0"}
P.entries["quest:94556"] = {n="Jom-jom's Escape",s="Jom-jom quer voltar para casa e pede que você o acompanhe até Clugfist em Bolder'ok.",h="Jom-jom quer voltar para casa e pede que você o acompanhe até Clugfist em Bolder'ok.",kw={"bolder'ok","clugfist","acompanhar","amigo","casa","jom-jom"},sec={{t="O caminho de volta",b="Jom-jom partiu em busca de um amigo. Agora, precisa que você o guie até Clugfist em Bolder'ok para poder voltar para casa."}},faq={{q="Quem é Jom-jom?",a="Jom-jom veio à procura de um amigo e agora quer voltar para casa.",al={"quem é jom-jom","jom-jom"}},{q="Para onde Jom-jom quer ir?",a="Jom-jom quer voltar para casa, e pedem que você o acompanhe até Clugfist em Bolder'ok.",al={"para onde jom-jom vai","jom-jom casa"}},{q="Quem é Clugfist?",a="Clugfist é a pessoa até quem Jom-jom deve ser escoltado em Bolder'ok.",al={"clugfist","quem é clugfist"}},{q="Por que Jom-jom veio até aqui?",a="Jom-jom veio à procura de um amigo.",al={"por que jom-jom veio aqui","jom-jom veio"}},{q="Jom-jom considera você um amigo?",a="Depois que você o salva, Jom-jom chama você de amigo.",al={"jom-jom amigo","pequeno"}}},fp="16,81,12.107.0,15.59.0,30.87.0,16.62.0,26.34.0,35.47.0"}
P.entries["quest:94568"] = {n="The Cult's True Plans",s="The Cult's True Plans aborda as consequências da morte prematura de um desertor do culto. Com o informante morto e seus segredos perdidos, os investigadores precisam consultar Talaanis Shadowsong para elaborar uma nova estratégia contra o culto.",h="The Cult's True Plans aborda as consequências da morte prematura de um desertor do culto.",kw={"culto","desertor","pacificadores","talaanis shadowsong","the cult's true plans","vira-casaca"},sec={{t="Um Desertor Silenciado",b="Um membro infiltrado desertou do culto após ficar aterrorizado com seus planos iminentes, na esperança de buscar ajuda externa. Tragicamente, o desertor foi morto antes que pudesse compartilhar o que sabia, deixando avisos sinistros, mas nenhum detalhe concreto sobre o que o culto pretende desencadear."},{t="Repensando a Abordagem",b="Com o principal informante morto, a liderança deve consultar Talaanis Shadowsong para reavaliar sua estratégia. Enfrentar o culto em um confronto aberto usando pacificadores é considerado uma batalha perdida, forçando aqueles que investigam a ameaça a buscar um caminho alternativo a seguir."}},faq={{q="Quem era o vira-casaca mencionado nesta missão?",a="Um desertor do culto buscou ajuda após ficar aterrorizado com o que quer que o culto estivesse tramando. Infelizmente, ele foi morto antes de conseguir revelar os detalhes dos seus planos, levando suas informações valiosas para o túmulo.",al={"quem morreu em the cults true plans","quem e o vira-casaca morto","segredos do culto do vira-casaca"}},{q="Quem é Talaanis Shadowsong?",a="Talaanis Shadowsong é o contato essencial consultado para discutir como proceder contra o culto após a morte repentina do informante. Você observa uma conversa estratégica com Talaanis para definir o próximo curso de ação.",al={"papel de talaanis shadowsong","quem e talaanis shadowsong","falar com talaanis"}},{q="Por que os pacificadores não podem simplesmente atacar o culto diretamente?",a="Mobilizar pacificadores diretamente para uma batalha aberta contra as forças do culto é considerado arriscado demais, pois não se espera que os pacificadores se saiam bem em um confronto frontal. Em vez disso, é necessária uma estratégia mais sutil ou alternativa.",al={"por que nao lutar contra o culto","pacificadores vs culto","ataque direto culto"}},{q="Quais são os verdadeiros planos do culto?",a="A natureza exata dos planos do culto permanece envolta em mistério porque o informante morreu antes de poder compartilhar o que sabia. Seja qual for o objetivo deles, foi aterrorizante o suficiente para fazer um membro desertar em desespero.",al={"o que o culto esta planejando","plano do culto","significado de the cults true plans"}},{q="Qual é o próximo passo após falar com Talaanis?",a="Após perceberem que uma batalha aberta está fora de questão e que sua principal fonte de inteligência está morta, a liderança deve conceber um método alternativo para descobrir e frustrar as maquinações do culto.",al={"o que acontece depois de the cults true plans","proximos passos missao do culto"}},{q="O que acontece durante The Cult's True Plans?",a="Você fala com Talaanis Shadowsong e acompanha uma reunião sobre a situação. A discussão se concentra nos desdobramentos da morte do informante e na avaliação dos motivos pelos quais a força militar padrão não pode ser utilizada para deter o culto.",al={"resumo da missao the cults true plans","o que voce faz em the cults true plans"}}},fp="21,139,19.170.0,23.268.1,45.146.0,27.161.0,55.145.0,33.163.0,51.142.0,42.178.0"}
P.entries["quest:94613"] = {n="My Kingdom for a Horse",s="Uma fazenda próxima perdeu seus cavalos, deixando Farholde sem cavalaria para sua campanha contra a Horda. Você é enviado à Wheeler’s Grange para falar com Benjy.",h="Uma fazenda próxima perdeu seus cavalos, deixando Farholde sem cavalaria para sua campanha contra a Horda.",kw={"benjy","horda","cavalos desaparecidos","meu reino por um cavalo","cavalaria de farholde","cavalos de guerra","wheeler’s grange"},sec={{t="O Rebanho Desaparecido",b="Os cavalos de guerra de Farholde vêm de duas fazendas próximas, mas a Wheeler’s Grange perdeu todos os seus. A causa é desconhecida e, sem cavalos, Farholde não tem cavalaria para sua campanha contra a Horda. Você é enviado para falar com Benjy na fazenda e descobrir o que ele tem a dizer."}},faq={{q="Por que Farholde precisa dos cavalos?",a="Farholde depende de cavalos de guerra para sua cavalaria, que considera necessária para sua campanha contra a Horda.",al={"por que cavalos","precisar de cavalos de guerra","cavalaria de farholde"}},{q="O que aconteceu com os cavalos de Wheeler’s Grange?",a="Todos os animais da família Wheeler desapareceram, e a causa é desconhecida.",al={"cavalos desaparecidos","para onde foram os cavalos","cavalos de wheeler"}},{q="Quem é Benjy?",a="Benjy está em Wheeler’s Grange, para onde você é enviado a fim de perguntar sobre os cavalos desaparecidos.",al={"benjy","homem de wheeler’s grange","com quem devo falar"}},{q="Onde ficam os cavalos de guerra de Farholde?",a="Os cavalos de guerra de Farholde vêm de duas fazendas próximas. A família Wheeler é dona de uma delas, a Wheeler’s Grange.",al={"fazendas de cavalos","de onde vêm os cavalos","fazendas de cavalos de guerra"}}},fp="22,159,17.278.0,34.110.0,50.73.0,13.83.0,38.107.0"}
P.entries["quest:94614"] = {n="Freshwater Fiends",s="Um fazendeiro perto de Wheeler's Grange pede que você expulse os murlocs Mudfin do rio. Eles ameaçam seus animais e a fauna local, além de terem tomado seu ponto de pesca favorito.",h="Um fazendeiro perto de Wheeler's Grange pede que você expulse os murlocs Mudfin do rio.",kw={"ponto de pesca","freshwater fiends","mudfin","murloc","oracle","sendas do rio","guerreiro","wheeler's grange"},sec={{t="À beira do rio",b="Os animais do fazendeiro e a fauna local sofrem enquanto os murlocs Mudfin permanecem ao longo do rio, perto de Wheeler's Grange. A presença deles também lhe custou seu ponto de pesca favorito. Pedem que você mate alguns murlocs, e o povo das Sendas do Rio ficaria grato pela ajuda."}},faq={{q="Por que o fazendeiro quer que os murlocs vão embora?",a="O fazendeiro diz que os murlocs Mudfin fazem mal aos animais dele e à fauna local, além de terem se instalado em seu ponto de pesca favorito.",al={"por que matar murlocs","murlocs perto do rio"}},{q="Onde estão os murlocs Mudfin?",a="Eles estão ao longo do rio, perto de Wheeler's Grange.",al={"localização dos mudfin","onde estão os murlocs"}},{q="Quais murlocs estão envolvidos?",a="O fazendeiro cita Mudfin Oracles e Mudfin Warriors.",al={"tipos de mudfin","quais murlocs"}},{q="O que o fazendeiro me pede para fazer?",a="Ele pede que você mate oito Mudfin Oracles e oito Mudfin Warriors ao longo do rio, perto de Wheeler's Grange.",al={"tarefa dos freshwater fiends","quantos murlocs matar"}},{q="Quem apreciaria a ajuda?",a="O fazendeiro diz que o povo das Sendas do Rio apreciaria que alguns murlocs fossem eliminados.",al={"quem quer que os murlocs vão embora","povo das sendas do rio"}}},fp="17,166,12.269.0,42.123.0,29.47.0,27.52.0,34.105.0,30.89.0"}
P.entries["quest:94615"] = {n="Foal Play",s="Em Wheeler's Grange, os cavalos desapareceram dos estábulos. Você procura pistas para descobrir o que aconteceu.",h="Em Wheeler's Grange, os cavalos desapareceram dos estábulos.",kw={"coiotes","farholde","brincadeira de potros","cavalos","cavalos desaparecidos","murlocs","estábulos","wheeler's grange"},sec={{t="Uma busca na propriedade",b="Os estábulos de Wheeler's Grange podem guardar pistas sobre os cavalos desaparecidos. O responsável diz que eles já tinham sumido quando ele se levantou para alimentá-los. Fora de Farholde, animais, murlocs, orcs ou outros perigos podem ser os culpados. Você procura perto dos estábulos para descobrir o que aconteceu."}},faq={{q="Para onde foram os cavalos?",a="Os cavalos desapareceram de Wheeler's Grange, e você procura evidências perto dos estábulos para descobrir para onde foram.",al={"cavalos desaparecidos","cavalos sumidos","onde estão os cavalos"}},{q="O que pode ter levado os cavalos?",a="O responsável considera animais, murlocs, orcs ou outros perigos fora de Farholde como possíveis culpados.",al={"quem levou os cavalos","culpado pelos cavalos","o que pegou os cavalos"}},{q="Por que os cavalos são importantes?",a="O responsável ganha a vida com os cavalos.",al={"por que os cavalos importam","cavalos sustento","negócio com cavalos"}},{q="Onde devo procurar pistas?",a="Procure perto dos estábulos de Wheeler's Grange por evidências sobre os cavalos desaparecidos.",al={"pistas nos estábulos","onde procurar","brincadeira de potros"}}},fp="9,116,22.266.0,24.110.0,33.100.0,29.47.0,30.82.0"}
P.entries["quest:94616"] = {n="Water Sapta",s="O Water Sapta é uma poção cerimonial usada para sintonizar a visão espiritual de alguém com os espíritos ocultos e as corrupções da água. Confiada essa preparação, o portador é enviado para localizar águas maculadas de uma lagoa nos campos de Cerro Oeste para investigar um desequilíbrio elemental.",h="O Water Sapta é uma poção cerimonial usada para sintonizar a visão espiritual de alguém com os espíritos...",kw={"sintonia elemental","sapta","provação de xamã","lagoa maculada","water sapta","espíritos da água","cerro oeste"},ang={["class:Shaman"]="Um sapta é uma poção alquímica ou ritual usada por xamãs para sintonizar seus sentidos espirituais com espíritos elementais que permanecem invisíveis à visão comum.",["faction:Alliance"]="Investigar águas corrompidas em Cerro Oeste traz ritos de purificação elemental para o coração de um território da Aliança."},sec={{t="A Visão das Águas",b="Nas tradições elementais dos xamãs, um sapta é uma mistura cerimonial preparada para romper o véu entre o reino físico e os espíritos. O Water Sapta sintoniza os sentidos especificamente com o elemento da água, concedendo a visão espiritual necessária para perceber perturbações elementais e espíritos ocultos. Sem tal sintonia, viajantes comuns poderiam olhar diretamente para uma manifestação elemental e não ver nada mais do que ondulações comuns."},{t="Perturbação em Cerro Oeste",b="A diretriz por trás do Water Sapta envia o portador a Cerro Oeste, um reino árido da Aliança conturbado por agitação e negligência. Dentro desta terra varrida pelo vento jaz uma lagoa maculada cujas águas sofrem de poluição espiritual. Guiado pela percepção do sapta, o portador deve procurar essas águas corrompidas para desvendar a perturbação e restaurar a harmonia com os espíritos da água locais."}},faq={{q="O que é um Water Sapta?",a="Um water sapta é uma infusão espiritual especializada criada para xamãs comungarem com os elementos. Beber ou usar um sapta abre temporariamente a percepção de alguém para entidades elementais e desequilíbrios espirituais que, de outra forma, ficariam ocultos aos olhos mortais.",al={"o que é um water sapta","propósito do water sapta","o que o water sapta faz"}},{q="Onde fica a lagoa maculada em Cerro Oeste?",a="A água da lagoa maculada está localizada nas terras de Cerro Oeste. Os xamãs são direcionados para lá com o water sapta em mãos para localizar fontes de água corrompidas e lidar com qualquer perturbação espiritual que se prolifere na região.",al={"onde fica a lagoa maculada","lagoa maculada cerro oeste","localização da lagoa maculada"}},{q="Por que o water sapta leva a Cerro Oeste?",a="Mesmo em terras humanas agrárias e assoladas pela seca como Cerro Oeste, as águas elementais podem ser vítimas de poluição ou corrupções sombrias. A missão incumbe você de procurar a água da lagoa maculada para investigar e restaurar o equilíbrio dos espíritos perturbados que residem ali.",al={"por que ir a cerro oeste","corrupção da água em cerro oeste","por que a água de cerro oeste está maculada"}},{q="Quem usa o water sapta?",a="Os water saptas são confiados a xamãs que passam por provações de comunhão elemental. Ao ingerir o sapta, o praticante sintoniza seus sentidos com os espíritos da água, permitindo-lhe perceber elementais ocultos ou inspecionar poças maculadas.",al={"quem bebe o water sapta","quem usa o water sapta","bebida sapta de xamã"}},{q="O que acontece quando você leva o sapta para a lagoa maculada?",a="Ao usar o water sapta perto da lagoa maculada em Cerro Oeste, a visão elemental é concedida, revelando o estado espiritual da água ou invocando espíritos ocultos ligados à provação da água local.",al={"o que acontece após usar o sapta","visão elemental do sapta"}},{q="Como funcionam os saptas elementais na tradição xamânica?",a="Os saptas combinam reagentes terrenos e bênçãos elementais em uma poção cerimonial. Os xamãs confiam neles durante suas provações para se sintonizarem com elementos específicos — terra, fogo, água ou ar —, unindo o mundo físico ao reino dos espíritos.",al={"como funcionam os saptas","história dos saptas"}}},fp="11,183,23.267.0,23.267.0,22.127.0,38.138.0,42.163.0,25.180.0,58.170.0,51.171.0"}
P.entries["quest:94617"] = {n="Coyote Huntin'",s="Benjy Wheeler pede que você dê um jeito em Sootfur, o líder de pelagem escura de uma matilha de coiotes a oeste do rio. Os coiotes passaram a comer cavalos depois que murlocs os expulsaram de seu pesqueiro habitual.",h="Benjy Wheeler pede que você dê um jeito em Sootfur, o líder de pelagem escura de uma matilha de coiotes a...",kw={"benjy wheeler","coiote","toca","cavalos","murlocs","pele","sootfur","estábulos"},sec={{t="Uma ameaça aos cavalos",b="Benjy Wheeler conta que os coiotes costumavam caçar peixes na margem, mas murlocs os expulsaram desse local de alimentação. Agora, a matilha passou a comer cavalos. Seu líder é um coiote maior, de pelagem escura, chamado Sootfur. Benjy pede que você traga a pele de Sootfur, na esperança de que o restante da matilha se disperse."},{t="Os estábulos de Benjy",b="Quando você volta com a pele de Sootfur, Benjy diz que o coiote andava fuçando em seus estábulos. Ele agradece e diz que espera que os cavalos fiquem seguros quando os estábulos voltarem a funcionar."}},faq={{q="Quem é Sootfur?",a="Sootfur é o líder maior, de pelagem escura, da matilha de coiotes a oeste do rio.",al={"sootfur","coiote escuro","líder dos coiotes"}},{q="Por que os coiotes estão comendo cavalos?",a="Murlocs afastaram os coiotes de seu pesqueiro habitual na margem, então eles começaram a comer cavalos.",al={"por que cavalos","coiotes comendo cavalos","comida dos coiotes"}},{q="Quem pede a pele de Sootfur?",a="Benjy Wheeler pede que você traga a pele de Sootfur para ele.",al={"benjy","quem é benjy","pele de sootfur"}},{q="Onde fica a toca dos coiotes?",a="A matilha vive em uma toca a oeste de onde Benjy está, do outro lado do rio.",al={"toca dos coiotes","onde ficam os coiotes","local da toca"}}},fp="14,202,22.300.0,15.190.1,15.79.0,34.109.0,28.51.0,24.67.0"}
P.entries["quest:94618"] = {n="Wheeler's Fleeing Steeds",s="Benjy pede que você encontre um cavalo que fugiu de Wheeler's Grange após um ataque de coiotes. Dê comida a ele para ganhar sua confiança e poder levá-lo de volta.",h="Benjy pede que você encontre um cavalo que fugiu de Wheeler's Grange após um ataque de coiotes.",kw={"benjy","coiotes","comida","cavalos que fugiram","cavalos","wheeler's fleeing steeds","wheeler's grange"},sec={{t="Fugiu da fazenda",b="Benjy, em Wheeler's Grange, precisa da sua ajuda para encontrar um dos cavalos que fugiram do ataque dos coiotes. Alguns cavalos foram levados pelos coiotes, enquanto outros fugiram assustados. Dê um pouco de comida a um cavalo para ganhar sua confiança e poder levá-lo de volta."}},faq={{q="O que aconteceu com os cavalos?",a="Os coiotes pegaram a maioria dos cavalos, enquanto alguns fugiram assustados de Wheeler's Grange.",al={"cavalos em wheeler's grange","cavalos atacados por coiotes"}},{q="Quem está pedindo ajuda?",a="Benjy pede que você encontre um cavalo que fugiu de Wheeler's Grange.",al={"quem me deu isto","cavalos de benjy"}},{q="O que devo fazer com a comida?",a="Dê um pouco de comida a um cavalo para ganhar sua confiança e poder levá-lo de volta.",al={"como usar o saco","dar comida ao cavalo"}},{q="Por que estão procurando os cavalos?",a="Benjy diz que os cavalos que fugiram devem ser encontrados antes que os coiotes voltem.",al={"por que encontrar os cavalos","para onde foram"}}},fp="24,127,20.231.0,28.78.0,23.58.0,31.70.0,32.72.0"}
P.entries["quest:94638"] = {n="Strength and Mercy",s="O companheiro de Ur'endra pede que você ponha fim ao sofrimento dela depois que ela sucumbe à loucura. Sua determinação lhe rende uma bênção para assumir a forma dos semelhantes dele.",h="O companheiro de Ur'endra pede que você ponha fim ao sofrimento dela depois que ela sucumbe à loucura.",kw={"bênção do druida","baixios dos lufopomos","forma da garra","planalto de shen'dar","strength and mercy","ur'endra","magia dos ventos"},ang={["class:Druid"]="Como druida, você deve provar sua determinação antes de receber uma bênção para assumir a forma dos semelhantes do druida."},sec={{t="Um pedido doloroso",b="Um druida pede que você ponha fim ao sofrimento de Ur'endra no Planalto de Shen'dar. Ela é sua companheira, mas a loucura a fez se voltar contra os próprios semelhantes. A perda da magia dos ventos fez muitas criaturas perderem a razão, e Ur'endra está entre elas. Seu covil fica em uma caverna a oeste daqui, nas escarpas entre o Planalto de Shen'dar e os Baixios dos Lufopomos."},{t="A bênção",b="No Planalto de Shen'dar, o companheiro de Ur'endra lamenta a perda dela e a considera necessária para o equilíbrio. Ele reconhece sua determinação ao aceitar um preço tão terrível. Ele concede a você uma bênção que permite assumir a forma dos semelhantes dele e lhe incumbe de ajudar os fracos e defender os necessitados."}},faq={{q="Quem é Ur'endra?",a="Ur'endra é a companheira do druida que pede que você ponha fim ao sofrimento dela.",al={"ur'endra","quem é urendra","companheira do druida"}},{q="Por que Ur'endra está atacando seus semelhantes?",a="Ur'endra sucumbiu à loucura. A perda da magia dos ventos fez muitas criaturas perderem a razão.",al={"por que urendra enlouqueceu","urendra atacando","o que aconteceu com urendra"}},{q="Onde fica o covil de Ur'endra?",a="Ur'endra tem seu covil em uma caverna a oeste do druida, nas escarpas entre o Planalto de Shen'dar e os Baixios dos Lufopomos.",al={"caverna de urendra","onde está urendra","caverna de shen'dar"}},{q="O que o druida pede que eu faça?",a="O druida pede que você ponha fim ao sofrimento de Ur'endra.",al={"tarefa de urendra","o que fazer","matar urendra"}},{q="Que bênção o druida concede?",a="O druida concede a você uma bênção que permite assumir a forma dos semelhantes dele.",al={"bênção de forma","way of the claw","bênção do druida"}},{q="Por que o druida pede isso?",a="O druida considera necessário pôr fim ao sofrimento de Ur'endra para preservar o equilíbrio.",al={"por que matar urendra","por que isso é necessário","equilíbrio"}}},fp="18,141,12.353.0,12.293.1,16.68.0,34.112.0,25.125.0,33.47.0,35.72.0,32.74.0"}
P.entries["quest:94668"] = {n="Bloodmaster's Ring",s="No Bloodmaster's Ring, você se apresenta a Jezap após provar seu valor contra os Twilight ogres. O Bloodmaster está pronto para julgar se você pertence a esse lugar.",h="No Bloodmaster's Ring, você se apresenta a Jezap após provar seu valor contra os Twilight ogres.",kw={"bloodmaster","bloodmaster's ring","goblin","jezap","precipício do poder","twilight ogres"},sec={{t="No Ring",b="O desafio na Bloodmaster's Ring levou você até Jezap, o goblin da arena. Depois de derrotar os ogros Twilight, você se apresenta a ele, observado pelo Bloodmaster e por Jezap. Eles decidem se você merece estar entre aqueles que se aproximam do precipício do poder."}},faq={{q="A quem devo me apresentar no Bloodmaster's Ring?",a="Você se apresenta a Jezap no Bloodmaster's Ring.",al={"quem é jezap","apresentar-se a jezap","goblin do bloodmaster's ring"}},{q="O que fiz antes de vir para cá?",a="Você esmagou os Twilight ogres que foram julgados fracos.",al={"o que aconteceu antes","twilight ogres","etapa anterior do ring"}},{q="O que o Bloodmaster está procurando?",a="O Bloodmaster está julgando se você pertence ao precipício do poder.",al={"provar meu valor","o que o bloodmaster quer","eu pertenço a esse lugar"}}},fp="18,147,11.267.0,45.46.0,33.49.0,36.72.0"}
P.entries["quest:94669"] = {n="Pay to Play",s="Um coletor exige um depósito de segurança antes que você possa entrar na Bloodmaster's Ring. Pague e você estará apto a provar sua força lá.",h="Um coletor exige um depósito de segurança antes que você possa entrar na Bloodmaster's Ring.",kw={"bloodmaster's ring","clugfist","pague para jogar","provar sua força","arena","depósito de segurança"},sec={{t="O preço da entrada",b="Para entrar na Bloodmaster's Ring, pedem que você pague um depósito de segurança. O Collector diz que o pagamento é necessário para sua segurança. Sem ele, ameaça contar a Clugfist que você se recusou a provar sua força à companhia que o recebe. Sua escolha determina se você se qualifica para a arena."}},faq={{q="Por que tenho que pagar?",a="O Collector diz que o depósito de segurança é necessário para sua segurança e para se qualificar para a Bloodmaster's Ring.",al={"por que pagar","depósito de segurança","missão pague para jogar"}},{q="Quem é Clugfist?",a="Clugfist é a pessoa a quem o Collector ameaça contar caso você se recuse a pagar.",al={"quem é clugfist","clugfist","velho clugfist"}},{q="O que acontece se eu recusar?",a="O Collector diz que contará a Clugfist que você não quis provar sua força.",al={"não pagar","recusar depósito","sem depósito"}},{q="Para que o pagamento me qualifica?",a="Pagar o depósito de segurança qualifica você para a Bloodmaster's Ring.",al={"qualificação para quê","entrada na arena","bloodmaster ring"}}},fp="11,132,18.294.0,21.106.0,16.76.0,25.90.0,32.67.0"}
P.entries["quest:94670"] = {n="Bloodmaster's Ring",s="O desafio de Bloodmaster's Ring coloca você contra Buzzbeak em busca de fama. O goblin do ring espera que a luta seja fácil.",h="O desafio de Bloodmaster's Ring coloca você contra Buzzbeak em busca de fama.",kw={"mestre de sangue","anel do mestre de sangue","buzzbeak","fama","criatura","luta","ringue"},sec={{t="Para o Ringue",b="O goblin do ring coloca Buzzbeak diante de você na arena. Dizem que esta primeira luta deve ser fácil, embora a criatura derrube seu oponente e fique com seus pertences. Prometem fama a quem entrar."}},faq={{q="Com quem luto no Anel do Mestre de Sangue?",a="Você enfrenta Buzzbeak no Anel do Mestre de Sangue.",al={"luta do mestre de sangue","quem é buzzbeak","oponente do ringue"}},{q="O que Buzzbeak deveria fazer?",a="Buzzbeak é descrito como uma criatura arisca que pode derrubar você e levar seus pertences.",al={"ataque de buzzbeak","o que buzzbeak faz","criatura no ringue"}},{q="Por que entrar no ringue?",a="O goblin do ring promete fama a quem entrar na arena.",al={"fama no ringue","fama do mestre de sangue","por que lutar contra buzzbeak"}},{q="Esta luta deveria ser fácil?",a="O goblin do ring apresenta esta luta como um primeiro combate fácil.",al={"luta fácil no ringue","mestre de sangue fácil","buzzbeak difícil"}}},fp="18,129,13.212.0,41.44.0,32.90.0,19.54.0,31.55.0"}
P.entries["quest:94672"] = {n="Encroaching Twilight",s="Tran'gul avisa que a Twilight's Hammer atacou um povoado humano a oeste de Rog'mar. Você é enviado a Solclaro para reduzir o número de cultistas antes que eles se estabeleçam por perto.",h="Tran'gul avisa que a Twilight's Hammer atacou um povoado humano a oeste de Rog'mar.",kw={"crepúsculo iminente","povoado humano","rog'mar","solclaro","tran'gul","neófitos da twilight","saqueadores da twilight","twilight's hammer"},sec={{t="Uma ameaça próxima",b="O povoado humano a oeste já foi devastado, e Rog'mar pode ser o próximo. Tran'gul envia você a Solclaro, onde a Twilight's Hammer iniciou sua campanha contra aqueles que chama de hereges. Seus saqueadores e neófitos ameaçam estabelecer uma base perto de Rog'mar."},{t="Depois da luta",b="Com o número de cultistas reduzido, Tran'gul pode buscar a origem dessa expansão sem precedentes."}},faq={{q="Quem preocupa Tran'gul?",a="Tran'gul teme a Twilight's Hammer, um culto que ataca aqueles que considera hereges.",al={"quem é a ameaça","ameaça da twilight's hammer"}},{q="O que aconteceu com o povoado humano?",a="A Twilight's Hammer devastou um povoado humano a oeste de Rog'mar.",al={"povoado a oeste","o que aconteceu a oeste"}},{q="Por que estou indo para Solclaro?",a="Tran'gul envia você a Solclaro para reduzir o número de membros da Twilight's Hammer.",al={"por que solclaro","o que há em solclaro"}},{q="Quem o culto pode atacar em seguida?",a="Tran'gul teme que Rog'mar seja o próximo alvo, depois do povoado humano a oeste.",al={"quem é o próximo","rog'mar em seguida"}}},fp="20,173,15.274.0,15.96.1,30.75.0,38.65.0,29.74.0,31.74.0"}
P.entries["quest:94678"] = {n="Gnoll Infestation",s="Cedric Dalton em Southern Watch pede que você reduza o número de gnolls nas Montanhas Cristarrubra. A quantidade deles torna perigosa a passagem ao norte e ameaça as pessoas além da Bastilha de Ermoforte.",h="Cedric Dalton em Southern Watch pede que você reduza o número de gnolls nas Montanhas Cristarrubra.",kw={"cedric dalton","bastilha de ermoforte","infestação de gnolls","gnolls","passagem ao norte","redridge brutes","redridge mystics","redridge trappers","southern watch"},sec={{t="Uma ameaça próxima",b="Cedric Dalton em Southern Watch enfrenta gnolls nas colinas além do posto. A quantidade deles torna perigosa a passagem ao norte, e as pessoas fora da Bastilha de Ermoforte correm perigo. Pedem que você reduza o domínio deles na região matando Redridge Mystics, Trappers e Brutes."}},faq={{q="Por que os gnolls são um problema?",a="Os gnolls são agressivos e numerosos. Eles tornam perigosa a passagem ao norte e ameaçam as pessoas que vivem fora da Bastilha de Ermoforte.",al={"por que gnolls","gnolls perigosos","infestação de gnolls"}},{q="Quem me pede para lidar com os gnolls?",a="Cedric Dalton em Southern Watch pede que você reduza a ameaça dos gnolls.",al={"quem deu a tarefa dos gnolls","cedric dalton","gnolls de southern watch"}},{q="Quais gnolls estão envolvidos?",a="Redridge Mystics, Redridge Trappers e Redridge Brutes são os gnolls indicados para serem mortos.",al={"tipos de gnoll","gnolls das montanhas cristarrubra","místicos caçadores brutamontes"}},{q="Onde estão os gnolls?",a="Eles infestam as colinas além de Southern Watch e tornam perigosa a passagem para o norte.",al={"localização dos gnolls","onde eles estão","colinas além do posto"}}},fp="17,161,15.266.0,29.123.0,36.68.0,26.93.0,21.83.0"}
P.entries["quest:94679"] = {n="Snargl's Snout",s="Cedric Dalton, em Southern Watch, quer o focinho de Snargl, das Colinas Cerdosas. Ele acredita que matar um gnoll forte enfraquecerá as fileiras das Montanhas Cristarrubra e os assustará.",h="Cedric Dalton, em Southern Watch, quer o focinho de Snargl, das Colinas Cerdosas.",kw={"colinas cerdosas","cedric dalton","gnoll","montanhas cristarrubra","snargl","focinho de snargl","southern watch"},sec={{t="Um gnoll nas colinas",b="Em Southern Watch, Cedric Dalton pede que você cuide de Snargl, um gnoll notório que vive numa toca entre as Colinas Cerdosas. Ele acredita que os gnolls prezam a força acima de tudo, então a morte de Snargl poderia enfraquecer as fileiras das Montanhas Cristarrubra e espalhar o medo entre eles. Cedric quer que você traga o focinho de Snargl."},{t="Um troféu devolvido",b="Cedric recebe o focinho de Snargl como troféu e diz que ele logo será usado. A morte do gnoll deve espalhar o medo entre as fileiras das Montanhas Cristarrubra."}},faq={{q="Quem é Snargl?",a="Snargl é um gnoll notório que vive numa toca entre as Colinas Cerdosas.",al={"quem é snargl","snargl gnoll","gnoll das colinas cerdosas"}},{q="Quem quer o focinho de Snargl?",a="Cedric Dalton, em Southern Watch, pede que você traga o focinho de Snargl para ele.",al={"para quem é o focinho de snargl","pedido de cedric dalton","focinho southern watch"}},{q="Por que Cedric quer Snargl morto?",a="Cedric acredita que os gnolls valorizam a força acima de tudo e que matar o mais forte deles vai enfraquecê-los e assustá-los.",al={"por que matar snargl","força dos gnolls","assustar montanhas cristarrubra"}},{q="Onde fica Snargl?",a="Snargl está numa toca entre as Colinas Cerdosas.",al={"localização de snargl","onde fica snargl","toca nas colinas cerdosas"}}},fp="14,159,20.287.0,17.144.1,14.61.0,25.69.0,33.122.0,16.43.0"}
P.entries["quest:94680"] = {n="Twilight Missives",s="Tran'gul quer descobrir por que os cultistas do Twilight's Hammer estão aparecendo em maior número nos arredores de Solclaro. Ele pede que você traga as missivas deles para descobrir o que procuram.",h="Tran'gul quer descobrir por que os cultistas do Twilight's Hammer estão aparecendo em maior número nos...",kw={"cultistas","missivas","rog'mar","solclaro","tran'gul","missivas do twilight","twilight shadowmancers","twilight's hammer"},sec={{t="Uma presença crescente",b="Tran'gul viu mais cultistas do Twilight's Hammer na região do que antes. Seus Twilight Shadowmancers são membros de confiança da ordem e podem conhecer os planos da campanha. Ele pede que você traga missivas deles para descobrir o que o culto procura."}},faq={{q="Quem pede as missivas do Twilight?",a="Tran'gul, em Rog'mar, pede que você recupere missivas dos Twilight Shadowmancers em Solclaro.",al={"quem quer as missivas","pedido de tran'gul","quem é tran'gul"}},{q="Onde posso encontrar os Twilight Shadowmancers?",a="Os Twilight Shadowmancers estão em Solclaro.",al={"localização dos shadowmancers","onde estão os cultistas do twilight","missivas de solclaro"}},{q="Por que Tran'gul quer as missivas?",a="Tran'gul quer saber mais sobre os cultistas e o que procuram.",al={"por que pegar as missivas","o que tran'gul quer saber","documentos dos cultistas"}},{q="Por que Tran'gul está preocupado com os cultistas?",a="Tran'gul viu mais cultistas do Twilight's Hammer do que antes, e eles parecem estar mais ousados para expandir sua influência.",al={"por que há twilight aqui","cultistas em maior número","número de twilight"}}},fp="17,171,18.258.0,35.91.0,44.45.0,36.67.0,45.128.0"}
P.entries["quest:947"] = {n="Cogumelos da caverna",s="Cogumelos da caverna é uma missão da Aliança oferecida pelo elfo noturno Barithras Sombraluna em Auberdine. Enquanto formula uma poção especializada, Barithras encarrega um aventureiro de se aventurar em uma caverna escondida atrás das Quedas do Fontescarpa para colher fungos raros e verificar premonições perturbadoras sentidas pelo Bosque dos Ancientes.",h="Cogumelos da caverna é uma missão da Aliança oferecida pelo elfo noturno Barithras Sombraluna em Auberdine.",kw={"auberdine","barithras sombraluna","cave mushrooms","quedas de fontescarpa","costa negra","cogumelo-cicuta","bosque dos ancientes","onu","talos-de-sarna"},ang={["faction:Alliance"]="Auberdine serve como o principal bastião da Aliança na costa de Kalimdor, e males crescentes nas montanhas orientais colocam em risco diretamente a estabilidade de toda a costa.",["profession:Herbalism"]="Forrageadores e herbalistas apreciarão a caça ao Cogumelo-cicuta e aos talos-de-sarna, embora esses espécimes específicos vivam em cavernas escurecidas em vez de solo fértil de floresta.",["race:NightElf"]="O Bosque dos Ancientes permanece profundamente sintonizado com o equilíbrio natural de Costa Negra, tornando qualquer perturbação que eles detectem sob as quedas uma questão de preocupação urgente para os Kaldorei."},sec={{t="Uma Receita Atrás das Quedas",b="Barithras Sombraluna precisa de ingredientes específicos para uma mistura potente: talos-de-sarna e um esquivo Cogumelo-cicuta. Estes fungos específicos florescem na caverna úmida e sombria escondida diretamente atrás das Quedas do Fontescarpa, no nordeste de Costa Negra. Embora a alquimia em si seja delicada, colher esses espécimes é muito mais perigoso do que colher ervas comuns da floresta."},{t="O Aviso dos Ancientes",b="Barithras não evitou a caverna por mera ociosidade. Os veneráveis guardiões arbóreos no Bosque dos Ancientes emitiram avisos severos, sentindo que uma presença maligna começara a se instalar dentro das cavernas da montanha. Ao enviar um explorador resistente em vez de investigar ele mesmo, Sombraluna busca confirmar se as intuições terríveis dos anciões sobre um mal crescente no norte de Costa Negra são de fato bem fundamentadas."}},faq={{q="Onde esta tarefa começa?",a="Você recebe esta missão de Barithras Sombraluna, que reside no assentamento costeiro de elfos noturnos de Auberdine, no centro de Costa Negra.",al={"onde pegar cave mushrooms","localização de barithras sombraluna","início da missão cave mushrooms"}},{q="Onde os cogumelos estão localizados?",a="Eles crescem dentro de uma caverna escondida atrás das Quedas do Fontescarpa, situada ao longo da encosta da montanha a nordeste de Auberdine.",al={"onde estão os talos-de-sarna","localização do cogumelo-cicuta","caverna atrás da cachoeira costa negra"}},{q="Por que Barithras Sombraluna não buscará os cogumelos ele mesmo?",a="Barithras foi especificamente aconselhado pelo Bosque dos Ancientes a ficar longe das quedas. Os grandes ancientes sentiram que um mal antinatural e crescente se refugiou dentro daquela caverna.",al={"por que barithras não vai","por que barithras fica em auberdine"}},{q="Quais cogumelos específicos são necessários?",a="Sombraluna precisa de cinco talos-de-sarna junto com um único e altamente perigoso Cogumelo-cicuta para completar sua poção.",al={"cogumelos necessários","quais fungos para sombraluna"}},{q="Para onde este recado leva a seguir?",a="Uma vez que a presença na caverna é verificada e os fungos entregues, a jornada vira para o sul, em direção ao antigo protetor Onu no Bosque dos Ancientes.",al={"próxima missão após cave mushrooms","continuação com onu"}},{q="Por que os Ancientes estão preocupados com as Quedas do Fontescarpa?",a="O Bosque dos Ancientes avisou Barithras que um mal crescente pode estar à espreita na caverna atrás das quedas. Ele pede a um viajante que colha cogumelos e investigue o aviso.",al={"aviso dos ancientes sobre as quedas de fontescarpa","por que explorar a caverna"}}},fx={a048db56={q="Por que Barithras Sombraluna quer que isso seja feito?",a="Barithras Sombraluna é um herbalista preparando uma nova poção potente que exige fungos raros encontrados apenas na caverna atrás das Quedas do Fontescarpa. Além de seu trabalho alquímico, no entanto, ele carrega uma preocupação mais profunda: o Bosque dos Ancientes o avisou que um mal crescente espreita dentro daquela mesma caverna. Ao enviar você para coletar os ingredientes, ele também espera saber se os presságios sombrios dos Ancientes são verdadeiros.",al={"por que barithras quer cogumelos da caverna","motivo de barithras sombraluna","por que coletar cogumelos para barithras"}},["991c4c10"]={q="Para que serve o Cogumelo-cicuta?",a="O Cogumelo-cicuta é um fungo tóxico excepcionalmente raro e potente nativo da caverna atrás das Quedas do Fontescarpa. Barithras Sombraluna precisa de um espécime puro como reagente chave em uma poção especializada que ele está fabricando em Auberdine.",al={"para que serve o cogumelo-cicuta","propósito do cogumelo-cicuta","por que barithras precisa de cogumelo-cicuta"}},be6516db={q="Para que serve o Galho de Piolho?",a="Galhos de Piolho são cogumelos raros que florescem na caverna úmida e sombria atrás das Quedas do Fontescarpa. Barithras Sombraluna precisa de cinco deles para misturar em suas concoções alquímicas em andamento, juntamente com o potente Cogumelo-cicuta.",al={"para que servem galhos de piolho","propósito do galho de piolho","por que barithras precisa de galhos de piolho"}}},fp="14,210,25.227.0,21.252.1,27.115.0,32.104.0,61.156.0,35.87.0,35.141.0,55.161.1"}
P.entries["quest:94727"] = {n="Digging for Answers",s="O Twilight's Hammer está escavando as Sendas do Rio em busca de uma fonte de poder desconhecida. Você é enviado a Solclaro para interrogar um de seus mineradores.",h="O Twilight's Hammer está escavando as Sendas do Rio em busca de uma fonte de poder desconhecida.",kw={"em busca de respostas","minerador","sendas do rio","source of power","solclaro","twilight's hammer"},sec={{t="Mineradores de Solclaro",b="O Twilight's Hammer tem trabalhadores escavando em Solclaro, e você é enviado para interrogar um dos mineradores. A busca aponta para uma fonte de poder, mas sua natureza permanece desconhecida. Os fanáticos guardam seus segredos, então os mineradores podem saber o que procuram."}},faq={{q="O que o Twilight's Hammer está escavando?",a="O Twilight's Hammer parece estar procurando uma fonte de poder nas Sendas do Rio, mas não se sabe o que ela é.",al={"o que estão escavando","escavação do twilight hammer","source of power"}},{q="Por que estou interrogando um minerador?",a="Os fanáticos do Twilight's Hammer guardam seus segredos, por isso você é enviado para interrogar um de seus mineradores em Solclaro.",al={"por que um minerador","falar com o minerador","missão em busca de respostas"}},{q="Onde estão os mineradores?",a="Os mineradores estão escavando em Solclaro, nas Sendas do Rio.",al={"onde fica solclaro","localização do minerador","escavação nas sendas do rio"}}},fp="19,148,20.255.0,42.119.0,29.112.0,21.61.0"}
P.entries["quest:94733"] = {n="Our Ogre Friend",s="Um goblin pede que você encontre Gobam em Bolder'ok e leve comida para Snufflesnout, o javali de estimação de Chub'chob. Gobam está disposto a ajudar porque Chub'chob é seu amigo.",h="Um goblin pede que você encontre Gobam em Bolder'ok e leve comida para Snufflesnout, o javali de estimação de...",kw={"bolder'ok","chub'chob","clube","gobam","goblin","nosso amigo ogro","javali de estimação","snufflesnout"},sec={{t="Um Pedido de Amigo",b="Depois que você vence algumas batalhas, o goblin pede que encontre Gobam em Bolder'ok. Ele precisa de comida para Snufflesnout, o javali de estimação de Chub'chob, mas diz que o trabalho o mantém ocupado. Gobam fica a leste do clube de Clugfist, e o goblin espera que você consiga encontrá-lo."}},faq={{q="Quem é Gobam?",a="Gobam é o sujeito tímido que o goblin manda você encontrar em Bolder'ok.",al={"quem é gobam"}},{q="Onde posso encontrar Gobam?",a="Gobam fica a leste do clube de Clugfist, em Bolder'ok.",al={"localização de gobam","onde fica gobam"}},{q="Quem é Snufflesnout?",a="Snufflesnout é o javali de estimação de Chub'chob, e o goblin pede que você leve comida para ele.",al={"snufflesnout","comida para javali"}},{q="Por que o goblin precisa de ajuda?",a="O goblin diz que o trabalho o mantém ocupado, então pede que você encontre comida para Snufflesnout.",al={"por que ajudar o goblin","goblin ocupado"}},{q="Por que Gobam vai ajudar?",a="Gobam diz que não gosta do goblin, mas vai ajudar Chub'chob porque eles são bons amigos.",al={"ajuda de gobam","por que gobam ajuda"}}},fp="15,157,20.242.0,13.66.0,23.51.0,20.83.0,30.86.0,20.92.0"}
P.entries["quest:94734"] = {n="A Boar's Delight",s="Gobam pede que você reúna bagas doces e plantas do rio para Snufflesnout, o mascote de Chub'chob. Os ingredientes vão compor um petisco especial.",h="Gobam pede que você reúna bagas doces e plantas do rio para Snufflesnout, o mascote de Chub'chob.",kw={"fruta silvestre","gobam","mascote","erva-do-rio","snufflesnout","baga-doce","petisco"},sec={{t="Um petisco para o mascote",b="Gobam quer preparar algo especial para Snufflesnout, que adora comida boa. Ele pede que você traga frutas silvestres doces e plantas do rio para o petisco."}},faq={{q="Quem é Gobam?",a="Gobam pede que você leve ingredientes para um petisco especial para Snufflesnout, mascote de Chub'chob.",al={"quem é gobam","quem pede frutas silvestres"}},{q="Quem é Snufflesnout?",a="Snufflesnout é o mascote de Chub'chob e adora comida boa.",al={"mascote snufflesnout","mascote de gobam"}},{q="Quais ingredientes Gobam quer?",a="Gobam pede frutas silvestres doces e erva-do-rio para preparar um petisco para Snufflesnout.",al={"fruta e planta","qual comida"}},{q="Por que Gobam quer frutas silvestres?",a="Gobam quer frutas silvestres doces e erva-do-rio para preparar um petisco especial para Snufflesnout.",al={"por que frutas silvestres","frutas silvestres para quê"}}},fp="16,133,13.150.0,13.95.0,20.52.0,33.76.0,28.81.0"}
P.entries["quest:94737"] = {n="A Treat for a Friend",s="Gobam pede que você leve um petisco para Jezap Jinglesprocket em Bolder'ok. Jezap diz que o mais importante é manter Snufflesnout feliz, ou seja, Chub'chob.",h="Gobam pede que você leve um petisco para Jezap Jinglesprocket em Bolder'ok.",kw={"um agrado para um amigo","bolder'ok","pacote de mercadorias","chub'chob","jezap jinglesprocket","snufflesnout"},sec={{t="Pedido de Gobam",b="O pacote de itens que Gobam lhe entrega é um petisco para Snufflesnout, a javali de estimação de Chub'chob, e ele diz que ela vai grunhir de felicidade quando o vir. Ele também pede que você diga ao goblin Jezap para falar menos."}},faq={{q="Para quem é o agrado?",a="Gobam diz que o petisco é para Snufflesnout, a javali de estimação de Chub'chob.",al={"quem recebe o agrado","agrado para snufflesnout"}},{q="Para quem devo entregar as mercadorias?",a="O pacote de mercadorias é para Jezap Jinglesprocket, em Bolder'ok.",al={"onde entregar o pacote","entrega para jezap"}},{q="Que mensagem devo transmitir?",a="Gobam pede que você diga a Jezap para parar de falar tanto.",al={"o que dizer a jezap","mensagem do goblin"}},{q="Quem é Snufflesnout?",a="Snufflesnout é a javali de estimação de Chub'chob, de quem Jezap prometeu cuidar. Jezap brinca que manter Snufflesnout feliz, na verdade, significa manter Chub'chob feliz.",al={"quem é snufflesnout","snufflesnout"}}},fp="20,151,15.202.0,21.63.0,34.61.0,33.53.0,20.155.0"}
P.entries["quest:94739"] = {n="Bloodmaster's Ring",s="O goblin do Bloodmaster's Ring manda você para o fosso para enfrentar Kronk. A plateia já está ansiosa pela próxima rodada.",h="O goblin do Bloodmaster's Ring manda você para o fosso para enfrentar Kronk.",kw={"anunciador","bloodmaster","bloodmaster's ring","luta","adversário","kronk","arena"},sec={{t="A próxima luta",b="O anunciador anima a plateia enquanto Kronk aguarda como próximo adversário. Você é enviado à arena para enfrentá-lo, e o barulho aumenta com a chegada da luta."}},faq={{q="Quem é Kronk?",a="Kronk é o próximo adversário no Bloodmaster's Ring. O anunciador diz que eles se conhecem há muito tempo e o descreve como um brigão forte.",al={"kronk","quem é kronk","kronk bloodmaster"}},{q="O que o Bloodmaster quer que eu faça?",a="Você é enviado ao fosso do Bloodmaster's Ring para enfrentar Kronk.",al={"o que fazer","tarefa da arena","bloodmaster ring"}},{q="Por que estou lutando contra Kronk?",a="O anunciador apresenta Kronk como o próximo adversário, e a luta está marcada para o Bloodmaster's Ring.",al={"por que kronk","lutar contra kronk","luta com kronk"}},{q="Onde acontece a luta?",a="A luta acontece na arena do Bloodmaster's Ring.",al={"onde é a luta","a arena","local da arena"}},{q="O que acontece depois que entro na arena?",a="O anunciador se prepara para apresentar Kronk enquanto você se apronta na arena.",al={"depois de entrar","próximo na arena","o que acontece depois"}},{q="O que o anunciador diz sobre Kronk?",a="O anunciador diz que Kronk não é muito inteligente, mas sabe espancar qualquer coisa que apareça em seu caminho.",al={"história de kronk","como é kronk","anunciador kronk"}}},fp="18,136,13.160.0,13.130.0,40.66.0,24.101.0,31.58.0,35.78.0,40.91.0"}
P.entries["quest:94744"] = {n="The Wayward Warrior",s="Krom'rosh pede que você se junte ao irmão dele, Dag'rosh, na fortaleza do Twilight's Hammer a oeste de Rog'mar. O domínio do culto em Solclaro enfraqueceu, e a batalha está se deslocando para a fortaleza.",h="Krom'rosh pede que você se junte ao irmão dele, Dag'rosh, na fortaleza do Twilight's Hammer a oeste de...",kw={"dag'rosh","krom'rosh","guerreiros ogros","rog'mar","solclaro","o guerreiro errante","twilight's hammer"},sec={{t="Um irmão à frente",b="Krom'rosh manda você procurar Dag'rosh, que partiu à frente com um grupo de reconhecimento. Você deve encontrá-lo nas colinas a oeste de Rog'mar. Krom'rosh diz que o Twilight's Hammer perdeu terreno em Solclaro, e que seus guerreiros ogros se voltaram contra ele. Agora, ele quer você ao lado do irmão enquanto a batalha se desloca para a fortaleza do culto."}},faq={{q="Quem está me pedindo para encontrar Dag'rosh?",a="Krom'rosh pede que você se junte ao irmão dele, Dag'rosh, na fortaleza do Twilight's Hammer.",al={"quem me enviou","krom'rosh","quem quer dag'rosh"}},{q="Onde posso encontrar Dag'rosh?",a="Krom'rosh diz para procurar Dag'rosh nas colinas a oeste de Rog'mar.",al={"onde está dag'rosh","localização de dag'rosh","encontrar da'grosh"}},{q="Quem é Dag'rosh?",a="Dag'rosh é irmão de Krom'rosh. Ele partiu à frente com um grupo de reconhecimento.",al={"história de dag'rosh","irmão de krom'rosh","quem é dag'rosh"}},{q="O que aconteceu com o Twilight's Hammer em Solclaro?",a="O domínio do Twilight's Hammer em Solclaro enfraqueceu, e seus guerreiros ogros se voltaram contra ele.",al={"culto de solclaro","domínio do twilight's hammer","o que aconteceu com os ogros"}}},fp="19,191,15.334.0,34.84.0,26.65.0,16.73.0,53.104.0"}
P.entries["quest:94745"] = {n="Carving a Path",s="Da'grosh manda você desafiar o Martelo do Crepúsculo na Mortalha do Crepúsculo. Ele acredita que a dependência deles de artes demoníacas e deuses antigos os deixa vulneráveis.",h="Da'grosh manda você desafiar o Martelo do Crepúsculo na Mortalha do Crepúsculo.",kw={"deuses antigos","abrindo caminho","da'grosh","artes demoníacas","campeão do crepúsculo","corruptor do crepúsculo","fanático do crepúsculo","martelo do crepúsculo","mortalha do crepúsculo"},sec={{t="A Mortalha",b="Da'grosh indica a Mortalha do Crepúsculo, uma fortaleza a oeste de onde está. Ele chama de covardes os integrantes do Martelo do Crepúsculo que vivem lá e despreza a dependência deles de artes demoníacas e deuses antigos. Ele quer que você mostre como são vulneráveis."},{t="Teste de força",b="Na Mortalha do Crepúsculo, Da'grosh pede que você derrote Twilight Fanatics, Twilight Corrupters e Twilight Champions. Ele insiste que a verdadeira força vem das próprias mãos."}},faq={{q="Quem Da'grosh está pedindo que você enfrente?",a="Da'grosh pede que você enfrente Twilight Fanatics, Twilight Corrupters e Twilight Champions na Mortalha do Crepúsculo.",al={"quem devo enfrentar","inimigos de da'grosh"}},{q="Onde fica a Mortalha do Crepúsculo?",a="Da'grosh descreve a Mortalha do Crepúsculo como uma fortaleza logo a oeste de onde está.",al={"onde fica a mortalha","localização da fortaleza do crepúsculo"}},{q="Por que Da'grosh chama o Martelo do Crepúsculo de fraco?",a="Da'grosh acredita que a dependência deles de artes demoníacas e deuses antigos os torna fracos.",al={"por que são fracos","da'grosh e o crepúsculo"}},{q="O que Da'grosh quer que você prove?",a="Da'grosh quer que você mostre ao Martelo do Crepúsculo que eles são vulneráveis.",al={"o que devo provar","mostrar que são vulneráveis"}}},fp="14,157,10.237.0,18.173.0,35.115.0,31.81.0,50.77.0,36.74.0"}
P.entries["quest:94748"] = {n="Break Their Chains",s="Da’grosh pede que você liberte os Rog’mar Scouts presos em Twilight’s Shroud. Seus guerreiros precisam voltar a Rog’mar antes de poder lutar de novo.",h="Da’grosh pede que você liberte os Rog’mar Scouts presos em Twilight’s Shroud.",kw={"quebrar as correntes","orcs capturados","da’grosh","fortaleza","rog’mar scouts","twilight’s hammer","twilight’s shroud"},ang={["race:Orc"]="Como Orc, Da’grosh pede que você liberte seus irmãos e irmãs orcs do cativeiro."},sec={{t="Batedores em cativeiro",b="Os guerreiros de Da’grosh foram capturados por Twilight’s Hammer antes que o ataque deles pudesse começar. Os campeões do culto os levaram para uma fortaleza a oeste de Da’grosh e os prenderam. Ele pede que você liberte seus irmãos e irmãs orcs em Twilight’s Shroud."},{t="Depois do resgate",b="Da’grosh diz que seus guerreiros estão feridos demais para lutar e voltaram a Rog’mar. Ele conta que o trabalho de vocês continua."}},faq={{q="Quem está pedindo ajuda?",a="Da’grosh pede que você liberte seus guerreiros capturados.",al={"quem é da’grosh","quem precisa de ajuda"}},{q="Quem foi capturado?",a="Twilight’s Hammer capturou os guerreiros de Da’grosh, os Rog’mar Scouts.",al={"orcs capturados","rog’mar scouts"}},{q="Onde os batedores estão presos?",a="Os Rog’mar Scouts estão presos em uma fortaleza a oeste de Da’grosh, em Twilight’s Shroud.",al={"localização dos batedores","onde estão presos"}},{q="Quem capturou os guerreiros de Da’grosh?",a="Os campeões de Twilight’s Hammer capturaram os guerreiros de Da’grosh.",al={"quem levou os orcs","prisioneiros de twilight’s hammer"}}},fp="18,153,19.261.0,16.130.1,23.50.0,17.79.0,32.101.0,37.71.0"}
P.entries["quest:94768"] = {n="Bring Me His Head",s="Da'grosh reúne seus guerreiros libertos para destruir a presença do Martelo do Crepúsculo na Mortalha do Crepúsculo. Com o culto em desordem, você é chamado a invadir a fortaleza e trazer a cabeça do Senhor Supremo Kilgar.",h="Da'grosh reúne seus guerreiros libertos para destruir a presença do Martelo do Crepúsculo na Mortalha do...",kw={"traga-me a cabeça dele","da'grosh","senhor supremo kilgar","fortaleza","tran'gul","martelo do crepúsculo","mortalha do crepúsculo"},ang={["class:Warrior"]="Da'grosh encontra forças em seus guerreiros libertos e convoca seus companheiros de armas a destruir a fortaleza do culto e vingar o cativeiro deles."},sec={{t="Ataque à Fortaleza",b="Anotações recuperadas deixadas por Tran'gul revelaram que o Senhor Supremo Kilgar comanda o Martelo do Crepúsculo dentro da Mortalha do Crepúsculo. Agora que seus guerreiros cativos escaparam e lançaram o culto em desordem, Da'grosh pretende atacar a fortaleza antes que eles se recuperem. Ele pede que você invada o reduto, derrote Kilgar e decapite a liderança deles."},{t="Uma Queixa Resolvida",b="Nas profundezas da Mortalha do Crepúsculo, o Senhor Supremo Kilgar sucumbe ao seu ataque. Ao retornar com a cabeça decepada do senhor da guerra, você encontra Da'grosh satisfeito com a morte de seu captor. Ele joga o troféu na terra, marcando o fim do comando de Kilgar sobre a fortaleza."}},faq={{q="Quem é o Senhor Supremo Kilgar?",a="O Senhor Supremo Kilgar comanda os cultistas do Martelo do Crepúsculo dentro da fortaleza na Mortalha do Crepúsculo. As anotações de Tran'gul o apontaram como o líder que organizou a presença deles ali.",al={"quem é kilgar","história do senhor supremo kilgar","quem comanda a mortalha do crepúsculo"}},{q="Quem é Da'grosh?",a="Da'grosh é um guerreiro cativo cujos combatentes reconquistaram a liberdade do culto. Ele busca vingança contra o Senhor Supremo Kilgar para destruir a fortaleza do Martelo do Crepúsculo.",al={"quem é da'grosh","da'grosh, concedente da missão","da'grosh"}},{q="O que é a Mortalha do Crepúsculo?",a="A Mortalha do Crepúsculo é a fortaleza onde os cultistas do Martelo do Crepúsculo estabeleceram seu reduto e mantiveram prisioneiros.",al={"o que é a mortalha do crepúsculo","localização da mortalha do crepúsculo","onde fica a fortaleza do culto"}},{q="Quem é Tran'gul?",a="Tran'gul foi uma presa anterior cujas anotações recuperadas revelaram a liderança do Senhor Supremo Kilgar dentro da fortaleza.",al={"quem é tran'gul","anotações de tran'gul","anotações sobre kilgar"}},{q="Por que Da'grosh quer derrotar Kilgar?",a="Com seus guerreiros resgatados e os cultistas em desordem, Da'grosh quer atacar o centro do poder do culto e vingar o cativeiro deles.",al={"por que matar kilgar","por que da'grosh quer a cabeça dele","por que derrotar o senhor supremo kilgar"}},{q="Onde encontrar o Senhor Supremo Kilgar?",a="O Senhor Supremo Kilgar está nas profundezas da fortaleza na Mortalha do Crepúsculo, atrás das defesas fortificadas do culto.",al={"onde kilgar está escondido","onde encontrar kilgar","localização de kilgar"}}},fp="17,215,24.375.0,19.259.1,23.184.0,16.173.0,30.124.0,16.111.0,39.141.0,35.110.0"}
P.entries["quest:94773"] = {n="Divine Grace",s="Uma lição chamada Divine Grace agradece a você por servir à Luz. Seu exemplo é importante para viajantes em terras perigosas.",h="Uma lição chamada Divine Grace agradece a você por servir à Luz.",kw={"terras perigosas","divine grace","lição","luz","viajantes"},sec={{t="Uma lição de gratidão",b="Após seu serviço, a Luz é louvada pelo exemplo que você deu aos viajantes em terras perigosas. Uma lição é oferecida a você em agradecimento pelo que fez."}},faq={{q="Do que trata Divine Grace?",a="Divine Grace agradece a você por servir à Luz e dar exemplo aos viajantes em terras perigosas.",al={"divine grace","o que é divine grace","missão divine grace"}},{q="Para quem é esta lição?",a="A lição é oferecida a você em agradecimento por seu serviço à Luz.",al={"quem recebe a lição","lição para mim","recompensa de divine grace"}},{q="Que exemplo eu dei?",a="Você se tornou um exemplo para viajantes em terras perigosas e além.",al={"meu exemplo","exemplo brilhante","o que eu fiz"}}},fp="12,116,18.159.0,27.102.0,23.69.0,23.65.0"}
P.entries["quest:94774"] = {n="Divine Grace",s="A Alta-sacerdotisa Laurena chama você à Catedral da Luz de Ventobravo porque seus superiores aprovaram mais treinamento. Suas lições nos caminhos da Luz estão prontas para começar.",h="A Alta-sacerdotisa Laurena chama você à Catedral da Luz de Ventobravo porque seus superiores aprovaram mais...",kw={"catedral da luz","graça divina","alta-sacerdotisa laurena","luz","servo da luz","ventobravo","treinamento"},ang={["class:Priest"]="Como sacerdote, você recebeu de seus superiores a aprovação para mais treinamento nos caminhos da Luz."},sec={{t="Um chamado a Ventobravo",b="Seus superiores enviam você à Catedral da Luz em Ventobravo após julgarem que você demonstrou seu valor. Lá, a Alta-sacerdotisa Laurena está pronta para orientar seu treinamento adicional. Ela diz que há lições que todo servo da Luz deve aprender e está preparada para conversar sobre elas com você."}},faq={{q="Por que estou sendo enviado a Ventobravo?",a="Seus superiores acreditam que você demonstrou seu valor e aprovaram mais treinamento nos caminhos da Luz.",al={"por que ventobravo","enviado à catedral","por que ir até lá"}},{q="Quem é a Alta-sacerdotisa Laurena?",a="A Alta-sacerdotisa Laurena está na Catedral da Luz em Ventobravo e está pronta para orientar seu treinamento.",al={"laurena quem","quem é laurena","alta-sacerdotisa"}},{q="Onde encontro a Alta-sacerdotisa Laurena?",a="A Alta-sacerdotisa Laurena está na Catedral da Luz em Ventobravo.",al={"localização de laurena","onde está laurena","localização da catedral"}},{q="Que treinamento Laurena está oferecendo?",a="Laurena está preparada para conversar sobre lições que todos os servos da Luz devem aprender.",al={"treinamento na luz","quais lições","aprender sobre a luz"}}},fp="12,181,19.290.0,33.108.0,30.101.0,39.65.0,34.81.0"}
P.entries["quest:94789"] = {n="Call of Air",s="Um xamã é enviado a Veyric Thundervein nas colinas ao norte do Planalto Arathi. Ele ensinará você a dominar melhor o ar.",h="Um xamã é enviado a Veyric Thundervein nas colinas ao norte do Planalto Arathi.",kw={"ar","planalto arathi","call of air","xamã","espíritos do ar","veyric thundervein","feitiços de vento"},sec={{t="As colinas do norte",b="Um xamã envia você ao norte do Planalto Arathi para encontrar Veyric Thundervein. O elemento ar é difícil de dominar, e ele pode ensinar mais a você. Sua habilidade crescente trouxe você até aqui; agora seu treinamento se volta ao vento e aos espíritos do ar."}},faq={{q="Quem é Veyric Thundervein?",a="Veyric Thundervein está nas colinas ao norte do Planalto Arathi, onde pode ensinar mais a você sobre o ar.",al={"veyric","quem é veyric","instrutor de ar"}},{q="Onde encontro Veyric?",a="Encontre Veyric Thundervein nas colinas ao norte do Planalto Arathi.",al={"localização de veyric","onde está veyric","instrutor de ar de arathi"}},{q="Do que trata Call of Air?",a="Um xamã envia você a Veyric Thundervein para que ele ensine mais a você sobre o elemento ar.",al={"missão call of air","treinamento de ar","feitiços de vento"}},{q="Por que estou indo ao Planalto Arathi?",a="Veyric Thundervein está nas colinas ao norte do Planalto Arathi e ensinará mais a você sobre o ar.",al={"por que arathi","missão de ir ao norte","encontrar veyric"}},{q="O que Veyric ensina?",a="Veyric ensina você a concentrar feitiços de vento e invocar os espíritos do ar.",al={"treinamento de veyric","espíritos do ar","concentrar feitiços de vento"}}},fp="11,125,18.245.0,26.103.0,23.66.0,26.91.0,35.102.0,23.73.0"}
P.entries["quest:94792"] = {n="Taming the Beast",s="Taming the Beast é uma prova introdutória em que aspirantes a aventureiros aprendem a arte de acalmar animais selvagens e criar laços com eles. Sob a orientação de Josephine Carson, os iniciantes levam um Bastão de Adestramento à floresta para domar um Rockhide Boar e praticar habilidades essenciais de sobrevivência. A tarefa demonstra que sobreviver em regiões inóspitas é muito mais fácil ao lado de uma fera leal, desde que se honre e preserve o delicado equilíbrio da natureza.",h="Taming the Beast é uma prova introdutória em que aspirantes a aventureiros aprendem a arte de acalmar animais...",kw={"companheiro animal","equilíbrio da natureza","adestramento de feras","ajudante de caçador","josephine carson","rockhide boar","bastão de adestramento","taming the beast"},ang={["class:Druid"]="Embora os druidas não mantenham companheiros animais como os caçadores, a ênfase da missão em preservar o delicado equilíbrio da natureza reflete ensinamentos druídicos fundamentais. Interagir com a fauna da floresta com cuidado e moderação honra o equilíbrio natural que eles juraram proteger.",["class:Hunter"]="Para os caçadores, dominar a arte de domar feras selvagens é um rito de passagem decisivo que transforma profundamente sua maneira de sobreviver na natureza. Um companheiro leal oferece proteção essencial em combate e vigilância, criando uma parceria duradoura entre rastreador e fera."},sec={{t="Laços com as feras",b="Para muitos que vagam pela natureza, aventurar-se a sós por territórios selvagens é um convite ao perigo. Um companheiro animal oferece não apenas proteção feroz em combate, mas também companhia constante em jornadas extenuantes. Aprender a formar esse laço é um marco vital para qualquer aspirante a caçador ou rastreador. Sob a orientação de Josephine Carson, os novatos recebem um Bastão de Adestramento especializado e a instrução de procurar um Rockhide Boar na floresta. Acalmar e conduzir uma criatura assim serve como uma prova fundamental, demonstrando se um viajante possui a concentração e a serenidade necessárias para guiar uma fera sem sucumbir ao medo nem provocar derramamento de sangue desnecessário."},{t="O equilíbrio da natureza",b="Dominar animais selvagens traz profundas responsabilidades éticas e ecológicas. Como Josephine Carson lembra a seus alunos, colocar feras a serviço de alguém jamais deve degenerar em exploração imprudente, pois o equilíbrio da natureza é frágil e deve ser sempre preservado. O processo de adestramento não se baseia em crueldade ou dominação, mas em estabelecer harmonia e disciplina entre fera e mestre. O uso do bastão encantado permite que um novato pratique com segurança o manejo de uma criatura formidável como um Rockhide Boar sem reduzir permanentemente a fauna local. Depois que os fundamentos de comandar e acalmar a fera são aprendidos, o bastão é devolvido, demonstrando que o respeito pela ordem natural vem antes do orgulho."}},faq={{q="Qual é o objetivo da missão Taming the Beast?",a="Esta missão serve como um treinamento essencial para aventureiros que buscam criar laços com criaturas selvagens. Sob a instrução de Josephine Carson, os novatos aprendem a se aproximar de um Rockhide Boar selvagem e acalmá-lo usando um Bastão de Adestramento especializado. O exercício ensina aos aspirantes a caçadores como um companheiro animal pode ajudá-los a sobreviver na natureza, ao mesmo tempo que ressalta a importância de respeitar o equilíbrio natural.",al={"missão taming the beast","o que é taming the beast","missão de ajudante de caçador"}},{q="Quem é Josephine Carson?",a="Josephine Carson é uma mentora que instrui aventureiros na delicada arte de lidar com companheiros animais. Ela fornece o Bastão de Adestramento e dá aos alunos a tarefa de praticar suas habilidades com um Rockhide Boar na floresta próxima. Josephine enfatiza que aprender a trabalhar ao lado das feras exige paciência, prática e atenção ao delicado equilíbrio da natureza.",al={"josephine carson","quem oferece taming the beast","quem oferece a missão do bastão de adestramento"}},{q="Para que serve o Bastão de Adestramento?",a="O Bastão de Adestramento é um instrumento especializado fornecido por Josephine Carson para facilitar o treinamento de animais. Os aventureiros levam o bastão à floresta para acalmar e domar um Rockhide Boar selvagem. Ele permite que os novatos pratiquem com segurança o comando de uma fera sem causar danos duradouros à fauna local e deve ser devolvido a Josephine quando a prova terminar.",al={"bastão de adestramento","o que faz o bastão de adestramento","como usar o bastão de adestramento"}},{q="Por que os caçadores precisam de companheiros animais?",a="Enfrentar sozinho os perigos da natureza expõe os viajantes a graves riscos e emboscadas. Um companheiro animal oferece proteção confiável, vigilância compartilhada e ajuda formidável em combate, tornando as situações perigosas muito mais fáceis de suportar. Uma fera leal atua tanto como uma guardiã feroz na linha de frente quanto como uma companheira de confiança durante expedições longas e perigosas por terras selvagens.",al={"por que ter um ajudante","benefícios de uma fera companheira","por que domar feras"}},{q="Que criatura deve ser domada durante esta prova?",a="A prova exige que os aventureiros entrem na floresta e domem um Rockhide Boar usando o Bastão de Adestramento fornecido. Essas feras robustas servem como um teste ideal para praticar habilidades básicas de manejo de animais, ensinando os viajantes a manter a serenidade e a disciplina diante de animais selvagens agressivos antes de retornar para relatar seu progresso a Josephine Carson.",al={"qual javali domar","alvo rockhide boar","criatura de taming the beast"}},{q="Por que Josephine Carson enfatiza o equilíbrio da natureza?",a="Josephine Carson adverte que subjugar feras selvagens sempre exige cautela e respeito, em vez de ganância ou força. A ordem natural é delicada, e perturbar a fauna local de forma imprudente ou maltratar criaturas compromete o equilíbrio ambiental. O verdadeiro domínio sobre as feras exige compreender e honrar seu lugar no ecossistema, em vez de tratá-las como meras ferramentas descartáveis.",al={"significado do equilíbrio da natureza","equilíbrio da natureza e adestramento","por que respeitar a natureza"}}},fp="16,181,19.403.0,21.405.0,50.234.0,24.231.0,32.240.0,38.186.0,46.237.0,58.205.0"}
P.entries["quest:94793"] = {n="Training the Beast",s="Training the Beast é uma missão fundamental para jovens caçadores, direcionando-os a procurar o veterano homem da floresta Isaac Chan em Vila d'Ouro. Ao concluir esta etapa, os caçadores aprendem a treinar, alimentar e reviver adequadamente seus companheiros animais, transformando uma fera recém-domesticada em um parceiro leal de combate.",h="Training the Beast é uma missão fundamental para jovens caçadores, direcionando-os a procurar o veterano...",kw={"floresta de elwynn","alimentar ajudante","vila d'ouro","ajudante de caçador","isaac chan","treinamento de ajudante","reviver ajudante","training the beast","homem da floresta"},ang={["class:Hunter"]="Esta missão marca um rito de passagem vital para caçadores em desenvolvimento, fazendo a transição do mero ato de capturar feras para a formação de um vínculo duradouro e disciplinado por meio da alimentação, do renascimento e do treinamento delas.",["faction:Alliance"]="Caçadores da Aliança que atuam na Floresta de Elwynn contam com homens da floresta veteranos como Isaac Chan em Vila d'Ouro para dominar os fundamentos do manejo de feras."},sec={{t="As Responsabilidades da Caçada",b="Aprender a domesticar uma criatura selvagem é apenas o passo inicial para um aspirante a caçador; manter uma parceria duradoura exige disciplina e conhecimento. A missão orienta os caçadores novatos a procurar Isaac Chan, um experiente homem da floresta estabelecido em Vila d'Ouro, para adquirir o ofício essencial do treinamento de feras. Sem a orientação adequada, uma fera domesticada permanece um animal selvagem indisciplinado em vez de um aliado constante na natureza."},{t="A Orientação de um Homem da Floresta",b="Ao chegar a Vila d'Ouro, Isaac Chan concede as habilidades necessárias para cuidar de um companheiro animal. Esta instrução vai além de simples comandos de combate, abrangendo as tarefas vitais de alimentar o companheiro para mantê-lo satisfeito e aprender os ritos para revivê-lo caso caia em batalha. Chan lembra aos seus alunos que exercer poder sobre a vida selvagem traz o dever de respeitar o equilíbrio natural e viver em reverência pelo mundo ao seu redor."}},faq={{q="Quem é Isaac Chan?",a="Isaac Chan é um experiente homem da floresta de longa data que reside em Vila d'Ouro, na Floresta de Elwynn. Respeitado por sua profunda compreensão da vida selvagem e da sobrevivência na natureza, ele ensina caçadores novatos a guiar, alimentar, reviver e ensinar habilidades adequadamente aos seus companheiros animais.",al={"quem é isaac chan","treinador de feras de vila d'ouro","história de isaac chan"}},{q="Qual é o objetivo de Training the Beast?",a="Embora um caçador já possa saber como domesticar uma fera, esta missão fornece o conhecimento essencial para manter esse vínculo. Ela instrui o caçador a alimentar seu companheiro, revivê-lo se ele cair em combate e ensinar a ele novas habilidades de combate.",al={"o que esta missão faz","por que treinar a fera","objetivo de training the beast"}},{q="Onde Isaac Chan pode ser encontrado?",a="Isaac Chan está localizado em Vila d'Ouro, o vilarejo central da Floresta de Elwynn, logo ao sul do Vale de Vila Norte e a sudoeste de Ventobravo.",al={"onde fica isaac chan","onde entrego isso","localização de isaac chan"}},{q="Quais habilidades Isaac Chan ensina?",a="Isaac Chan transmite os princípios fundamentais dos cuidados e treinamento de ajudantes. Isso abrange alimentar sua fera para manter seu bem-estar, revivê-la caso pereça em combate e ensinar novas habilidades a ela à medida que cresce ao seu lado.",al={"quais habilidades você ganha","habilidades de ajudante aprendidas","o que isaac chan ensina"}},{q="Por que Isaac Chan lembra aos caçadores de respeitarem a natureza?",a="Isaac Chan enfatiza que dominar feras selvagens requer humildade em vez de dominação. Ele incentiva os caçadores a honrarem o equilíbrio do mundo natural e viverem em reverência pela natureza ao redor, garantindo que a parceria entre caçador e fera seja construída sobre a tutela responsável e não sobre a exploração.",al={"por que respeitar a natureza","respeite o equilíbrio caçador"}},{q="Quem realiza esta missão?",a="Training the Beast é feita sob medida especificamente para caçadores que adquiriram a habilidade inicial de domesticar feras e precisam da disciplina da vida selvagem necessária para sustentar e treinar um companheiro animal.",al={"quem pode fazer esta missão","training the beast é apenas para caçadores"}}},fp="18,184,32.248.0,21.284.0,18.217.0,42.181.0,30.129.0,34.194.0,53.207.0,26.115.0"}
P.entries["quest:948"] = {n="Onu",s="Esta tarefa leva os viajantes de Auberdine para o sul, até o Bosque dos Ancientes, para consultar Onu. Após explorar a caverna atrás das Quedas Vertentes, suas descobertas despertaram a atenção urgente de um dos guardiões mais antigos de Costa Negra.",h="Esta tarefa leva os viajantes de Auberdine para o sul, até o Bosque dos Ancientes, para consultar Onu.",kw={"anciente da tradição","auberdine","barithras sombraluna","quedas vertentes","costa negra","bosque dos ancientes","onu"},ang={["class:Druid"]="Os druidas reverenciam profundamente os ancientes como manifestações da sabedoria da natureza. Investigar os estranhos crescimentos nas cavernas a pedido de Onu está diretamente ligado aos deveres do Círculo Cenariano.",["faction:Alliance"]="Para os viajantes da Aliança que ajudam a proteger Costa Negra, conquistar a confiança e ouvir os conselhos dos ancientes da região é essencial para explorar os misteriosos ermos do norte de Kalimdor.",["race:NightElf"]="Os Ancientes da Tradição são parceiros sagrados dos kaldorei e orientam seu povo desde antes da Cisão. Atender ao chamado de Onu é um dever solene para preservar a santidade de Costa Negra."},sec={{t="Um chamado dos ancientes",b="Ao retornar a Auberdine com amostras de fungos das profundezas das Quedas Vertentes, Barithras Sombraluna percebe que as implicações vão muito além da mera curiosidade botânica. A notícia sobre as cavernas contaminadas chega rapidamente a Onu, um Anciente da Tradição que vive no tranquilo Bosque dos Ancientes, ao sul da cidade. Embora os ancientes sejam pacientes e ponderados por natureza, a urgência com que Onu deseja conversar indica que a corrupção nas águas de Costa Negra pode estar ligada a poderes antigos e inquietantes."},{t="Jornada até o bosque",b="Seguir pela estrada ao sul de Auberdine leva para longe das ruínas costeiras e para o interior, em direção às encostas das montanhas. O Bosque dos Ancientes é um refúgio ancestral da natureza, em grande parte protegido da decadência que se espalha pelo litoral. Ali, Onu aguarda entre imponentes monumentos de pedra e espíritos afins, preparando-se para orientar seus aliados contra males ainda mais aterradores que despertam nos limites das terras selvagens."}},faq={{q="Quem é Onu?",a="Onu é um Anciente da Tradição, um colossal guardião arbóreo dotado de consciência e dedicado a reunir e preservar conhecimentos. Ele zela pelo Bosque dos Ancientes, no sul de Costa Negra, e oferece sabedoria e orientação aos defensores da região.",al={"quem é onu","identidade de onu","o que é onu"}},{q="Por que Onu quer falar comigo?",a="Você se aventurou recentemente pelas cavernas sob as Quedas Vertentes para coletar amostras de fungos para Barithras Sombraluna. A natureza incomum do que foi encontrado alarmou os estudiosos da natureza, levando Onu a solicitar uma conversa sobre a corrupção crescente.",al={"por que onu chamou","motivo da conversa","por que ir até onu"}},{q="Onde fica o Bosque dos Ancientes?",a="O Bosque dos Ancientes fica ao sul de Auberdine, aos pés das montanhas a leste. Siga a estrada principal para o sul através de Costa Negra e depois vá para o leste, em direção às encostas, para encontrar Onu.",al={"localização de onu","onde fica o bosque dos ancientes","como encontrar onu"}},{q="Que tipo de criatura é um Anciente da Tradição?",a="Os Ancientes da Tradição são seres arbóreos ancestrais aliados dos elfos noturnos e do Círculo Cenariano. Reverenciados por sua sabedoria e memória, eles são repositórios vivos da magia da natureza e de segredos históricos.",al={"anciente da tradição","que criatura é onu","diferença entre arvoroso e anciente"}},{q="Por que o chamado de Onu é considerado urgente?",a="Os ancientes são conhecidos por sua postura ponderada e tranquila, raramente agindo com pressa. Como observa Barithras Sombraluna, se um ser tão paciente e metódico quanto Onu pede sua ajuda, a ameaça a Costa Negra deve ser grave.",al={"por que é urgente","onu está preocupado","aviso de barithras"}},{q="O que acontece depois de encontrar Onu?",a="Ao recebê-lo no Bosque dos Ancientes, Onu solicita sua ajuda para investigar uma ameaça muito mais sombria ao sul, na costa: as escavações sinistras ao redor da Glaive do Mestre.",al={"próxima missão após onu","o que acontece depois","para onde onu envia você"}}},fx={be40e913={q="Por que Barithras Sombraluna me envia a Onu?",a="Barithras sabe que os Ancestrais do Saber possuem profunda sabedoria em relação à corrupção da terra, e Onu notou diretamente o que você encontrou dentro da caverna nas Quedas do Fontescarpa. Como um Ancestral raramente entra em contato a menos que Costa Negra enfrente uma ameaça profunda e urgente, Barithras insta você a atender à convocação imediatamente.",al={"motivo de barithras","por que enviar a onu","por que barithras quer isso feito"}}},fp="3,166,27.409.0,20.339.0,11.167.0,35.197.0,35.190.0,44.180.0,39.132.0,34.167.1"}
P.entries["quest:94819"] = {n="Contingency Plan",s="Alguém envia você a Altaforja para encontrar a Alta-sacerdotisa Mims. Sua próxima prova se aproxima, e ela espera na Ala Mística.",h="Alguém envia você a Altaforja para encontrar a Alta-sacerdotisa Mims.",kw={"plano de contingência","alta-sacerdotisa mims","altaforja","luz","ala mística","próxima prova","ritos"},sec={{t="Uma audiência à espera",b="Em Altaforja, a Alta-sacerdotisa Mims espera para falar com você na Ala Mística. Sua próxima prova se aproxima, e quem enviou você não pode deixar seu posto para testemunhar os ritos do seu povo. Que a Luz acompanhe sua jornada até Mims."}},faq={{q="Quem devo encontrar?",a="A Alta-sacerdotisa Mims espera para falar com você na Ala Mística de Altaforja.",al={"quem está esperando","encontrar mims","mims"}},{q="Onde posso encontrar Mims?",a="Mims deve estar na Ala Mística, em Altaforja.",al={"onde fica mims","localização de mims","ala mística"}},{q="Por que estou indo para Altaforja?",a="A Alta-sacerdotisa Mims quer falar com você lá, e sua próxima prova se aproxima.",al={"por que altaforja","o que tem em altaforja","audiência"}},{q="O que quem me enviou diz sobre os ritos do meu povo?",a="Quem enviou você gostaria de testemunhar os ritos do seu povo, mas diz que seu posto é onde está.",al={"ritos da minha raça","ritos especiais","por que não podem vir"}},{q="O que desejam para minha jornada?",a="Quem enviou você deseja que a Luz acompanhe sua jornada.",al={"bênção da luz","que a luz me acompanhe","bênção para a jornada"}}},fp="16,129,18.253.0,23.76.0,22.47.0,28.82.0,49.97.0,30.61.0"}
P.entries["quest:94822"] = {n="Confounding Flash",s="Seus superiores enviam você a Altaforja para continuar seu treinamento com High Priestess Mims. Seu serviço à Light chamou a atenção deles.",h="Seus superiores enviam você a Altaforja para continuar seu treinamento com High Priestess Mims.",kw={"confounding flash","salão dos mistérios","high priestess mims","altaforja","light","superiores","treinamento"},sec={{t="Mais uma lição",b="Seus superiores enviam você até High Priestess Mims no Salão dos Mistérios de Altaforja. Eles consideram que seu serviço preparou você para mais treinamento. Mims vai orientar você, e a lição aguarda sua chegada."},{t="Diante de Mims",b="High Priestess Mims recebe você em Altaforja e observa que você chegou tarde. Ela perdoa o atraso em consideração ao seu serviço à Light, então pede que você preste atenção à lição."}},faq={{q="Quem me enviou a Altaforja?",a="Seus superiores pediram que você viajasse até o Salão dos Mistérios em Altaforja para receber mais treinamento.",al={"quem me enviou","quem são meus superiores"}},{q="Quem é High Priestess Mims?",a="High Priestess Mims é quem seus superiores mandam você procurar em Altaforja. Ela pode orientar você na continuação do treinamento.",al={"quem é mims","mims"}},{q="Por que estou sendo enviado para treinamento?",a="Seus superiores acreditam que você demonstrou seu valor por meio do seu serviço à Light.",al={"por que treinar","por que eu"}},{q="Onde encontro High Priestess Mims?",a="Encontre High Priestess Mims no Salão dos Mistérios em Altaforja.",al={"onde está mims","salão dos mistérios"}}},fp="17,139,16.203.0,11.169.0,25.94.0,27.115.0,33.82.0,36.63.0"}
P.entries["quest:94824"] = {n="Confounding Flash",s="Uma mensagem leva você a Altaforja para falar com a Alta-sacerdotisa Mims. Ela pediu que você vá ao Salão dos Mistérios, mas o motivo ainda não está claro.",h="Uma mensagem leva você a Altaforja para falar com a Alta-sacerdotisa Mims.",kw={"confounding flash","salão dos mistérios","alta-sacerdotisa mims","altaforja","falar com mims","chamado"},sec={{t="Um chamado para Altaforja",b="A estrada à frente leva a Altaforja, onde a Alta-sacerdotisa Mims espera no Salão dos Mistérios. Você foi enviado para falar com ela pessoalmente, embora a mensagem não explique o motivo do chamado. Ela supõe que seus feitos tenham sido bem-sucedidos, mas deixa para Mims explicar o assunto."}},faq={{q="Quem quer falar comigo?",a="A Alta-sacerdotisa Mims quer que você vá falar com ela em Altaforja.",al={"quem me chamou","chamado de mims","alta-sacerdotisa mims"}},{q="Aonde devo ir?",a="Pedem que você fale com a Alta-sacerdotisa Mims no Salão dos Mistérios, em Altaforja.",al={"onde fica mims","localização do salão dos mistérios","ir para altaforja"}},{q="Por que Mims quer me ver?",a="A mensagem não explica por que a Alta-sacerdotisa Mims quer falar com você.",al={"por que mims me chamou","o que ela quer","motivo do chamado"}},{q="O que estão me pedindo para fazer?",a="Estão pedindo que você fale com a Alta-sacerdotisa Mims em Altaforja.",al={"qual é a tarefa","falar com mims","pedido de mims"}}},fp="17,148,19.277.0,27.66.0,14.86.0,29.77.0,28.67.0"}
P.entries["quest:94829"] = {n="What We Lost",s="Um fazendeiro da Elbrim's Farm lamenta as pessoas mortas pelos Twilight Raiders. Pedem a você que recupere as lembranças delas e as coloque nos túmulos a oeste da fazenda.",h="Um fazendeiro da Elbrim's Farm lamenta as pessoas mortas pelos Twilight Raiders.",kw={"cultistas","elbrim's farm","fazendeiros","lembranças dos fazendeiros","túmulos","cemitério","twilight raiders","o que perdemos"},sec={{t="O Apelo de um Fazendeiro",b="O fazendeiro pede a você que reúna os pertences de quem foi morto quando os cultistas chegaram à Elbrim's Farm. Os campos já alimentaram tropas e civis, mas, segundo o fazendeiro, a proteção prometida nunca veio. Seu povo jaz nas ruínas da fazenda, e seus parentes estão enterrados no cemitério a oeste."},{t="Junto aos Túmulos",b="O fazendeiro quer que você leve as lembranças dos mortos aos túmulos a oeste da Elbrim's Farm. Isso não os trará de volta, mas o fazendeiro espera que suas almas possam descansar junto aos parentes."}},faq={{q="O que aconteceu na Elbrim's Farm?",a="O fazendeiro diz que os cultistas chegaram à Elbrim's Farm, destruíram as plantações e mataram as pessoas que trabalhavam lá.",al={"elbrim's farm o que aconteceu","fazenda destruída","o que aconteceu aqui"}},{q="Quem me pede para recuperar as lembranças?",a="Um fazendeiro da Elbrim's Farm pede a você que recupere os pertences das pessoas mortas pelos cultistas.",al={"quem quer as lembranças","pedido do fazendeiro","quem está pedindo"}},{q="De quem são as lembranças que estou recolhendo?",a="Elas pertenciam às pessoas que trabalhavam nos campos da Elbrim's Farm e foram mortas quando os cultistas chegaram.",al={"lembranças dos fazendeiros","a quem pertencem","lembranças para quem"}},{q="Onde devo deixar as lembranças?",a="O fazendeiro pede a você que coloque as lembranças nos túmulos do cemitério a oeste da Elbrim's Farm.",al={"onde deixar as lembranças","quais túmulos","localização do cemitério"}},{q="Por que o fazendeiro quer que as lembranças sejam devolvidas?",a="O fazendeiro acredita que deixar os pertences dos mortos nos túmulos de seus parentes ajudará suas almas a descansar.",al={"por que recuperá-las","dar descanso às almas","por que as lembranças"}}},fp="12,158,15.292.0,13.180.0,31.110.0,36.98.0,31.109.0,29.95.0,47.106.0"}
P.entries["quest:94841"] = {n="Lost Shipping Crate",s="Uma caixa de carga destinada a Friz Frazzlespark desapareceu nas Sendas do Rio. A etiqueta pede que seja devolvida ao Porto Detonapavio.",h="Uma caixa de carga destinada a Friz Frazzlespark desapareceu nas Sendas do Rio.",kw={"caixa","friz frazzlespark","etiqueta","caixa de carga perdida","mapa","porto detonapavio","sendas do rio"},sec={{t="Uma caixa marcada",b="A caixa de Friz Frazzlespark tem uma etiqueta escrita à mão que indica o Porto Detonapavio, nas Sendas do Rio. Um mapa marca uma margem a sudeste, ao norte de um templo cercado por água, com criaturas aladas por perto. A etiqueta avisa para não abrir a caixa sem supervisão e indica Friz como a pessoa que deve recebê-la."}},faq={{q="Quem é o dono da caixa de carga?",a="A etiqueta identifica Friz Frazzlespark como dono da caixa.",al={"dono da caixa","quem é o dono"}},{q="Onde devo levar a caixa?",a="A etiqueta diz para devolver a caixa a Friz Frazzlespark, no Porto Detonapavio, nas Sendas do Rio.",al={"onde entregar a caixa","entrega da caixa"}},{q="O que diz a etiqueta da caixa?",a="Ela identifica Friz Frazzlespark e o Porto Detonapavio, avisa para não abrir a caixa sem supervisão e informa um local para devolvê-la nas Sendas do Rio.",al={"etiqueta da caixa","o que está escrito nela"}},{q="É seguro abrir a caixa?",a="A etiqueta diz para não abri-la sem supervisão.",al={"abrir a caixa","aviso da caixa"}}},fp="19,137,14.300.0,28.55.0,30.94.0,32.153.0,26.50.0"}
P.entries["quest:94842"] = {n="Unsavory Plant Food",s="Halligan Turner precisa de ingredientes para o fertilizante usado pela equipe madeireira. Você pode ajudar a reunir carapaças de lagostins, esterco e cabeças de murlocs Mudfin.",h="Halligan Turner precisa de ingredientes para o fertilizante usado pela equipe madeireira.",kw={"carapaças de lagostim","fertilizante","fresh manure","halligan turner","jumbo crawfish shells","madeira","mudfin murloc heads","adubo"},sec={{t="Reunindo ingredientes",b="Halligan Turner diz que a equipe madeireira produz o próprio fertilizante com carapaças de lagostins, esterco e cabeças de murlocs. O esterco vem de um rancho ao sul, enquanto as carapaças e as cabeças ficam no rio. Ele precisa de quatro Jumbo Crawfish Shells, quatro peças de Fresh Manure e oito Mudfin Murloc Heads para começar o plantio."}},faq={{q="De quais ingredientes Halligan precisa?",a="Halligan precisa de quatro Jumbo Crawfish Shells, quatro peças de Fresh Manure e oito Mudfin Murloc Heads.",al={"ingredientes para fertilizante","do que halligan precisa"}},{q="Do que é feito o fertilizante?",a="O fertilizante da equipe madeireira usa carapaças de lagostins, esterco e cabeças de murlocs na proporção de um para um para dois.",al={"o que vai no fertilizante","ingredientes para adubo"}},{q="De onde vem o esterco?",a="Halligan diz que o esterco vem de um rancho ao sul.",al={"local do esterco","onde conseguir esterco"}},{q="Onde estão as carapaças e as cabeças de murloc?",a="Halligan diz que você precisa entrar no rio para pegar as carapaças e as cabeças de murloc.",al={"local das carapaças de lagostim","onde ficam as cabeças mudfin"}},{q="Quem está pedindo esses ingredientes?",a="Halligan Turner pede os ingredientes para fazer fertilizante para a equipe madeireira.",al={"quem precisa de adubo","halligan turner"}}},fp="19,147,21.321.0,36.102.0,33.105.0,32.57.0,38.78.0,36.80.0"}
P.entries["quest:94843"] = {n="From Seed to Sprout",s="Halligan Turner preparou um kit de plantio com o fertilizante que você forneceu. Ele pede que você plante mudas nos locais de trabalho do acampamento madeireiro.",h="Halligan Turner preparou um kit de plantio com o fertilizante que você forneceu.",kw={"fertilizante","da semente ao broto","halligan turner","acampamento madeireiro","kit de plantio","mudas","sementes","locais de trabalho"},sec={{t="Um novo plantio",b="Halligan Turner reuniu sementes enquanto a equipe madeireira trabalhava entre as árvores. Com o fertilizante que você trouxe, preparou um kit para plantá-las como mudas. Você deve encontrar lugares nos locais de trabalho para colocá-las na terra."}},faq={{q="Quem preparou o kit de plantio?",a="Halligan Turner preparou o kit de plantio usando o fertilizante que você forneceu.",al={"quem preparou o kit","kit de halligan"}},{q="O que há no kit?",a="O kit serve para plantar sementes recolhidas das árvores e fazê-las crescer como mudas.",al={"conteúdo do kit","qual kit"}},{q="Onde devo plantar as mudas?",a="Halligan pede que você as plante nos locais de trabalho do acampamento madeireiro.",al={"onde plantar","locais para mudas"}},{q="Por que estão plantando mudas?",a="A equipe madeireira corta árvores e cultiva novas no lugar delas.",al={"por que plantar mudas","motivo do plantio"}}},fp="19,142,14.243.0,26.72.0,19.85.0,34.70.0,31.61.0"}
P.entries["quest:94857"] = {n="If a Tree Falls, and No One Hears...",s="Um lenhador preso pede que você busque ajuda no Turner's Logging Camp. Ele teme sangrar até morrer ou ser devorado se continuar preso.",h="Um lenhador preso pede que você busque ajuda no Turner's Logging Camp.",kw={"acidente","ajuda","se uma árvore cair","acampamento madeireiro","lenhador","preso","turner's logging camp"},sec={{t="Um pedido de ajuda",b="Um lenhador está preso no local de um acidente. Ele pede que você vá ao Turner's Logging Camp e traga ajuda antes que sangre até morrer ou seja encontrado por animais selvagens."}},faq={{q="Quem está preso?",a="Um lenhador do acampamento madeireiro próximo está preso após um acidente.",al={"lenhador preso","quem precisa de ajuda","trabalhador ferido"}},{q="De que ajuda ele precisa?",a="Ele pede que você busque ajuda no Turner's Logging Camp.",al={"como ajudá-lo","ajudar homem preso","do que ele precisa"}},{q="Por que ele está em perigo?",a="Ele diz que pode sangrar até morrer ou ser devorado por animais selvagens se continuar preso.",al={"por que está preso","ele está ferido","o que aconteceu com o lenhador"}}},fp="36,131,15.156.0,15.71.0,23.53.0,20.73.0"}
P.entries["quest:94858"] = {n="All That's Left",s="O fazendeiro Elbrim pede que você procure no celeiro próximo o que restou de sua família após o ataque do Martelo do Crepúsculo. Ele espera levá-los para casa, para descansarem ao seu lado.",h="O fazendeiro Elbrim pede que você procure no celeiro próximo o que restou de sua família após o ataque do...",kw={"tudo o que restou","celeiro","sepultamento","família","fazendeiro elbrim","pertences","martelo do crepúsculo"},sec={{t="Lembranças de uma Família",b="Elbrim não consegue olhar no celeiro, onde escondeu aqueles que não podiam se defender durante o ataque. Ele pede que você encontre os pertences de sua família e os traga de volta. Precisa saber o que restou e espera que possam ser enterrados em casa, ao lado dele."}},faq={{q="Quem está me pedindo para procurar no celeiro?",a="O fazendeiro Elbrim pede que você procure os pertences de sua família no celeiro próximo.",al={"quem me quer no celeiro","fazendeiro elbrim","quem me deu isto"}},{q="O que aconteceu com a família de Elbrim?",a="Elbrim escondeu no celeiro aqueles que não podiam se defender durante o ataque do Martelo do Crepúsculo. Ele pede que você encontre os pertences deles, mas não sabe o que restou.",al={"família de elbrim","o que aconteceu no celeiro","ataque à família"}},{q="Por que Elbrim os escondeu no celeiro?",a="Elbrim colocou no celeiro aqueles que não podiam se defender porque achou que estariam seguros.",al={"por que o celeiro","onde ele os escondeu","elbrim escondendo"}},{q="O que Elbrim quer que eu encontre?",a="Elbrim pede que você encontre os pertences de sua família no celeiro próximo e os devolva a ele.",al={"o que estou procurando","coisas do celeiro","encontrar pertences da família"}},{q="Onde Elbrim quer que sua família seja enterrada?",a="Elbrim espera que sua família possa ser enterrada em casa, ao lado dele.",al={"onde enterrar a família","sepultamento da família","descansar juntos"}}},fp="15,163,20.264.0,36.78.0,33.168.0,37.95.0,33.91.0,41.55.0"}
P.entries["quest:94861"] = {n="Helping Hands",s="Hurley precisa da sua ajuda para salvar Curly, que não voltou do intervalo para o almoço. Ele teme que haja pouco tempo para encontrá-lo.",h="Hurley precisa da sua ajuda para salvar Curly, que não voltou do intervalo para o almoço.",kw={"curly","mãos prestativas","hurley","intervalo para o almoço","trabalhador desaparecido","salvar curly"},sec={{t="A preocupação de Hurley",b="Hurley está preocupado porque Curly não voltou do almoço. Ele pede que você vá com ele salvar o trabalhador desaparecido e teme que haja pouco tempo. Curly é um bom trabalhador, apesar de ser tolo, e Hurley espera que ele se recupere e aprenda a ter juízo."}},faq={{q="Quem é Curly?",a="Curly é um trabalhador que não voltou do almoço. Hurley o considera um bom trabalhador, embora ache que ele pode ser tolo.",al={"quem é curly","história de curly"}},{q="Quem pede ajuda para salvar Curly?",a="Hurley pede que você vá com ele salvar Curly.",al={"quem pede ajuda","ajudar curly","hurley pede"}},{q="Por que Hurley está preocupado?",a="Curly não voltou do almoço, e Hurley teme que haja pouco tempo para salvá-lo.",al={"por que está preocupado","curly desaparecido","onde está curly"}},{q="O que Hurley espera para Curly?",a="Hurley espera que Curly se recupere bem e aprenda a ter juízo.",al={"destino de curly","curly se recupera"}}},fp="13,123,18.248.0,13.120.0,31.46.0,22.85.0,32.52.0"}
P.entries["quest:94863"] = {n="Taming the Beast",s="Taming the Beast é uma lição de treinamento de caçador supervisionada por Josephine Carson. Depois de aprender os fundamentos do manejo de feras com um javali, o aspirante a Caçador deve usar um Bastão de Adestramento para conquistar a confiança de um Gray Forest Wolf mais feroz.",h="Taming the Beast é uma lição de treinamento de caçador supervisionada por Josephine Carson.",kw={"adestramento de feras","gray forest wolf","caçador","treinamento de caçador","josephine carson","bastão de adestramento","taming the beast"},ang={["class:Hunter"]="Este treinamento marca um rito de passagem essencial para caçadores, ensinando a paciência e o respeito necessários para comungar com predadores ferozes da natureza."},sec={{t="O Caminho do Caçador",b="A conexão de um caçador com a natureza exige mais do que mero rastreamento e pontaria; demanda o respeito e a paciência necessários para conquistar a confiança de uma criatura selvagem. Depois de provar suas habilidades fundamentais em javalis simples, os aspirantes a caçadores são apresentados a um desafio muito mais feroz: aventurar-se na floresta para domar um Gray Forest Wolf. Sob o olhar atento da instrutora Josephine Carson, o Caçador é incumbido de usar um bastão encantado para acalmar o predador e aprender o delicado equilíbrio entre caçador e fera."},{t="Um Teste de Instinto e Confiança",b="Josephine Carson fornece ao Caçador um Bastão de Adestramento especializado, projetado para canalizar uma influência calmante que permite ao caçador se aproximar da vida selvagem perigosa. A tarefa requer paciência e precisão, pois o lobo deve ser abordado sem força letal enquanto sua agressividade natural é suavemente contida. Uma vez que o vínculo é praticado e o Caçador se mostra capaz de se harmonizar com o espírito da fera, o bastão é devolvido a Josephine como prova de seu crescente domínio sobre o ambiente selvagem."}},faq={{q="O que é a missão Taming the Beast?",a="Taming the Beast é um teste de treinamento de caçador no qual uma instrutora encarrega um aspirante a Caçador de rastrear e domar um Gray Forest Wolf usando um Bastão de Adestramento encantado.",al={"missão taming the beast","missão gray forest wolf","lição de domar lobo"}},{q="Quem dá e conclui esta missão?",a="Josephine Carson atua como instrutora deste teste. Ela fornece o Bastão de Adestramento e avalia seu vínculo com as feras da floresta antes de pegar o bastão de volta após a conclusão.",al={"quem dá taming the beast","quem é josephine carson","onde entregar taming the beast"}},{q="Qual criatura você deve domar?",a="Você é instruído a domar um Gray Forest Wolf, avançando de sua prática anterior com javalis para um predador mais feroz da floresta.",al={"o que eu domo","qual fera","alvo de taming the beast"}},{q="Para que serve o Bastão de Adestramento?",a="O Bastão de Adestramento é uma ferramenta de instrução fornecida por Josephine Carson para ajudar um caçador aprendiz a acalmar e formar um vínculo temporário com um Gray Forest Wolf selvagem sem causar danos permanentes.",al={"o que faz o bastão de adestramento","por que usar o bastão de adestramento","história do bastão de adestramento"}},{q="O que o caçador domou antes deste teste?",a="Antes de enfrentar o Gray Forest Wolf, você demonstrou seu comando inicial do manejo de feras ao dominar a forma de domar um javali da floresta.",al={"lição anterior de adestramento","o que foi domado antes do lobo"}},{q="Você fica com o Gray Forest Wolf como um companheiro permanente?",a="Não, o teste foi projetado como uma lição focada no domínio da técnica de vínculo com feras. Depois de praticar suas habilidades, você devolve o Bastão de Adestramento a Josephine Carson.",al={"você fica com o lobo","o lobo é um ajudante permanente"}}},fp="16,174,22.331.0,28.279.0,35.112.0,35.99.0,34.107.0,32.133.0,43.73.0,58.94.0"}
P.entries["quest:94864"] = {n="Taming the Beast",s="Taming the Beast é o ápice do treinamento inicial de um caçador na Floresta de Elwynn, supervisionado por Josephine Carson. Depois de demonstrar domínio sobre javalis e lobos, os caçadores recebem a tarefa de usar um Bastão de Adestramento para pacificar e conquistar a confiança de um Young Forest Bear. Este teste final aprofunda a sintonia do caçador com as feras e mantém o equilíbrio natural da floresta por meio do respeito e da habilidade.",h="Taming the Beast é o ápice do treinamento inicial de um caçador na Floresta de Elwynn, supervisionado por...",kw={"sintonia com feras","treinamento de feras","floresta de elwynn","missão de caçador","josephine carson","bastão de adestramento","taming the beast","young forest bear"},ang={["class:Hunter"]="Este teste marca um rito de passagem definitivo para caçadores aprendizes, transformando simples habilidades de rastreamento em uma sintonia profunda e empática com as feras da natureza selvagem.",["faction:Alliance"]="Mestres das feras habilidosos fortalecem os batedores da natureza selvagem da Aliança, fornecendo companheiros disciplinados capazes de defender propriedades rurais e patrulhar estradas comerciais pelos territórios de Ventobravo.",["race:Human"]="Para caçadores humanos em treinamento na Floresta de Elwynn, adestrar a vida selvagem nativa ensina a importância de coexistir com os predadores naturais do reino em vez de apenas erradicá-los."},sec={{t="O Teste Final da Caçada",b="Aspirantes a caçador na Floresta de Elwynn passam por um treinamento rigoroso para compreender as criaturas selvagens que compartilham suas terras. Tendo já demonstrado domínio sobre o lobo astuto e o javali resistente, os caçadores enfrentam um teste final de coragem e paciência. Josephine Carson os orienta a confrontar o Young Forest Bear, o mais corpulento e poderoso dos predadores comuns da floresta. Este rito testa se um caçador consegue resistir à força bruta do urso e conquistar sua confiança em vez de simplesmente subjugá-lo."},{t="Respeito e Equilíbrio em Elwynn",b="A lição por trás de adestrar a vida selvagem de Elwynn está enraizada no respeito, e não no domínio. Os ursos da floresta representam a força e a vitalidade da mata, desempenhando um papel vital na manutenção da ordem natural. Ao usar um Bastão de Adestramento especialmente preparado, os caçadores aprendem a acalmar a agressividade da fera e a estabelecer um vínculo genuíno de compreensão mútua. Acalmar com sucesso um animal tão formidável aprofunda a sintonia espiritual do caçador com a natureza selvagem, concluindo suas lições fundamentais sob a orientação de Carson."}},faq={{q="Quem atribui este teste aos caçadores?",a="Josephine Carson supervisiona este teste para caçadores em treinamento na Floresta de Elwynn. Ela avalia o progresso do caçador após ele ter adestrado com sucesso feras menores, fornecendo as orientações necessárias e o Bastão de Adestramento necessário para adestrar o urso da floresta. Assim que o teste é concluído, os caçadores devolvem o bastão diretamente a ela para marcar a conclusão do treinamento.",al={"quem dá taming the beast","concedente da missão taming the beast","missão de josephine carson"}},{q="Quais feras devem ser adestradas antes deste desafio?",a="Antes de assumir o desafio de adestrar um Young Forest Bear, os caçadores devem primeiro provar sua habilidade e paciência adestrando um javali e um lobo. Esses testes preliminares demonstram que o caçador consegue lidar tanto com feras agressivas quanto com feras que vivem em matilha antes de tentar confrontar a pura força e vigor dos ursos de Elwynn.",al={"feras pré-requisito para adestramento","o que adestrei antes do urso","feras adestradas antes desta"}},{q="Por que os caçadores são enviados atrás de um Young Forest Bear?",a="O Young Forest Bear representa a força e o poder da vida selvagem da Floresta de Elwynn. Enquanto javalis e lobos testam a capacidade do caçador de lidar com feras velozes ou resistentes, o urso serve como o teste definitivo de resistência, respeito e coragem física. Conquistar a confiança de um predador tão poderoso demonstra domínio completo sobre o manejo básico de feras.",al={"por que adestrar young forest bear","propósito do young forest bear","por que ursos em elwynn"}},{q="Qual é o propósito do Bastão de Adestramento?",a="O Bastão de Adestramento é um instrumento de treinamento especializado fornecido por Josephine Carson para ajudar os caçadores a acalmar animais selvagens. Ele canaliza a concentração necessária para tranquilizar um Young Forest Bear agressivo sem matá-lo, permitindo que o caçador estabeleça um vínculo pacífico. Assim que o teste termina, o bastão é devolvido a Carson à medida que o treinamento é finalizado.",al={"propósito do bastão de adestramento","o que o bastão de adestramento faz","por que usar bastão de adestramento"}},{q="Como adestrar feras ajuda a Floresta de Elwynn?",a="Adestrar a vida selvagem é visto como uma prática essencial para manter o equilíbrio natural da Floresta de Elwynn. Ao se aproximarem dos predadores com respeito e moderação em vez de caçá-los, os caçadores ajudam a preservar a harmonia entre o ecossistema local e os assentamentos humanoides por toda a região, garantindo que feras perigosas sejam guiadas pacificamente em vez de destruídas.",al={"por que o equilíbrio de elwynn importa","equilíbrio da floresta de elwynn","adestramento e equilíbrio da floresta"}},{q="O que a conclusão desta lição significa para um caçador?",a="Concluir esta tarefa final aprofunda a sintonia intrínseca do caçador com as feras da natureza selvagem. Ao conquistar a confiança da criatura mais poderosa de Elwynn, o caçador vai além de simples técnicas de caça e domina a conexão espiritual necessária para formar parcerias duradouras com companheiros animais por toda Azeroth.",al={"o que acontece após adestrar o urso","conclusão do treinamento de caçador","significado da sintonia com feras"}},{q="Onde Young Forest Bears são encontrados?",a="Young Forest Bears vagam pelas áreas arborizadas da Floresta de Elwynn, vivendo entre as árvores densas ao lado de lobos e aranhas. Caçadores que se aventuram a partir de assentamentos próximos devem rastrear essas criaturas corpulentas pela vegetação rasteira da floresta para usar o bastão de adestramento e cumprir a diretriz final de Carson.",al={"localização de young forest bear","onde encontrar ursos em elwynn","urso da floresta elwynn"}}},fp="16,291,27.363.0,29.396.0,34.219.0,49.184.0,47.224.0,38.240.0,42.245.0,54.219.0,35.246.0"}
P.entries["quest:94872"] = {n="Buying Friendship: Magram",s="A preocupação com a força dos Magram leva você a oferecer totens entalhados na Aldeia Magram. O presente pode abrir caminho para que o clã se torne um aliado.",h="A preocupação com a força dos Magram leva você a oferecer totens entalhados na Aldeia Magram.",kw={"centauro","desolação","amizade","gorhak","magram","aldeia magram","intendente","totens"},sec={{t="Uma oferta a Gorhak",b="Alguém preocupado com o crescente poder dos Magram pede que você entregue um saco de totens a Gorhak, o intendente deles. A aldeia do clã está crescendo, e seus soldados estão ficando mais ousados. A força deles preocupa quem envia você, embora os Magram possam se tornar aliados."},{t="Na aldeia",b="Na Aldeia Magram, em Desolação, Gorhak recebe os totens entalhados e percebe que sua oferta tem um propósito. Ele não sabe o que você busca dele ou do clã. Por enquanto, ele recebe você como forasteiro."}},faq={{q="Por que estou levando totens aos Magram?",a="Alguém preocupado com o crescente poder dos Magram espera que o presente conquiste a confiança deles e os torne possíveis aliados.",al={"por que totens","presente para os magram","comprando amizade"}},{q="Quem é Gorhak?",a="Gorhak é o intendente Magram na Aldeia Magram.",al={"quem é gorhak","intendente magram","entregador de totens"}},{q="Onde devo levar os totens?",a="Leve o saco de totens entalhados ao intendente Magram na Aldeia Magram, em Desolação.",al={"onde levar os totens","localização da aldeia magram"}},{q="O que Gorhak acha do presente?",a="Gorhak percebe que o presente tem um propósito, mas mesmo assim recebe você na Aldeia Magram.",al={"reação de gorhak","ele aceita os totens","boas-vindas dos magram"}},{q="Por que as pessoas estão preocupadas com os Magram?",a="A aldeia Magram está crescendo e seus soldados estão ficando mais ousados, o que gera preocupação com a força do clã.",al={"crescimento dos magram","ameaça dos magram","por que se preocupar"}}},fp="25,131,18.270.0,14.195.1,39.116.0,14.53.0,28.90.0,35.102.0,40.110.0"}
P.entries["quest:94873"] = {n="Buying Friendship: Gelkis",s="Um forasteiro oferece ao clã Gelkis uma sacola de totens na Aldeia Gelkis. O intendente vê o presente como ajuda contra o clã Magram.",h="Um forasteiro oferece ao clã Gelkis uma sacola de totens na Aldeia Gelkis.",kw={"comprando amizade","centauro","gelkis","clã gelkis","aldeia gelkis","magram","molkar","sacola de totens"},sec={{t="Um presente para os Gelkis",b="Alguém preparou uma sacola de totens para você levar ao intendente Gelkis na Aldeia Gelkis. Os Gelkis estão perdendo terreno para os Magram, e o isolamento deles pode deixá-los mais receptivos à ajuda de fora. O presente pretende melhorar sua posição junto ao clã."}},faq={{q="Por que levar uma sacola de totens aos Gelkis?",a="O presente pretende melhorar sua posição junto ao clã Gelkis, que está perdendo terreno para os Magram.",al={"sacola de totens","por que totens","presente para gelkis"}},{q="Quem recebe a sacola?",a="O intendente Gelkis na Aldeia Gelkis recebe a sacola.",al={"intendente gelkis","quem recebe a sacola","destinatário dos totens"}},{q="Que problema os Gelkis enfrentam?",a="Os Gelkis estão em desvantagem contra os Magram, cujo clã tem sido excepcionalmente cruel.",al={"problema dos gelkis","magram gelkis","por que estão perdendo"}},{q="Quem é Molkar?",a="Molkar é o intendente Gelkis que recebe a sacola.",al={"molkar gelkis","intendente molkar","quem é molkar"}}},fp="25,137,21.259.0,38.102.0,22.61.0,32.92.0,14.57.0"}
P.entries["quest:94877"] = {n="Saving Sunnyglade",s="Demar Brant pede que você expulse as forças do Martelo do Crepúsculo de Solclaro, um assentamento no noroeste de Farholde. Seus habitantes perderam as casas e recebem pouca ajuda de Ventobravo.",h="Demar Brant pede que você expulse as forças do Martelo do Crepúsculo de Solclaro, um assentamento no noroeste...",kw={"demar brant","farholde","refugiados","salvando solclaro","solclaro","neófitos de twilight","saqueadores de twilight","feiticeiros das sombras de twilight","martelo do crepúsculo"},sec={{t="Um assentamento perdido",b="Demar Brant fala em nome do povo exausto de Farholde, incluindo refugiados que escaparam de uma tragédia sem suas famílias. Ventobravo os deixou à própria sorte, com recursos cada vez menores. O Martelo do Crepúsculo tomou um assentamento no noroeste, e Demar pede que você expulse suas forças de Solclaro."}},faq={{q="Quem está pedindo ajuda?",a="Demar Brant pede que você expulse as forças do Martelo do Crepúsculo de Solclaro.",al={"quem é demar","demar brant","quem deu isso"}},{q="O que aconteceu com Solclaro?",a="O Martelo do Crepúsculo tomou um assentamento no noroeste de Farholde.",al={"o que aconteceu aqui","solclaro perdida","quem tomou solclaro"}},{q="Quem são as pessoas de Farholde?",a="Muitas são refugiadas que escaparam de uma tragédia sem suas famílias.",al={"povo de farholde","quem mora lá","refugiados"}},{q="Por que Demar quer ajuda?",a="Farholde perdeu um assentamento para o Martelo do Crepúsculo, enquanto seu povo tem cada vez menos recursos para se defender.",al={"por que ajudar demar","por que lutar","qual é o problema"}}},fp="17,188,17.280.0,23.71.0,28.64.0,31.61.0,25.114.0"}
P.entries["quest:94879"] = {n="Scraps of Knowledge",s="Ashe Amberall pede que você procure documentos do Martelo do Crepúsculo em Solclaro. Ela espera que as páginas revelem os planos do culto.",h="Ashe Amberall pede que você procure documentos do Martelo do Crepúsculo em Solclaro.",kw={"ashe amberall","demar","documentos","bastilha de ermoforte","fragmentos de conhecimento","solclaro","twilight pages","martelo do crepúsculo"},sec={{t="Páginas em Solclaro",b="Da Bastilha de Ermoforte, Ashe Amberall olha para Solclaro, a cidade em ruínas ao norte. Demar enviou tropas, mas a cidade continua irrecuperável. Ashe acredita que o Martelo do Crepúsculo já atacou antes e coordena seus ataques a partir de um lugar central. Ela pede que você procure documentos perdidos em Solclaro, na esperança de que páginas suficientes a ajudem a descobrir as intenções do culto."}},faq={{q="Quem quer as Twilight Pages?",a="Ashe Amberall, na Bastilha de Ermoforte, pede que você encontre as Twilight Pages.",al={"quem quer as páginas","páginas de ashe","quem me pediu"}},{q="Onde devo procurar as páginas?",a="Ashe pede que você procure as Twilight Pages em Solclaro.",al={"onde estão as páginas","documentos de solclaro","encontrar twilight pages"}},{q="O que Ashe espera descobrir?",a="Ashe espera que os documentos a ajudem a descobrir as intenções do Martelo do Crepúsculo.",al={"o que ashe quer saber","por que as páginas","planos do crepúsculo"}},{q="Por que Ashe está perguntando sobre o Martelo do Crepúsculo?",a="Ashe acredita que o ataque a Solclaro não foi o primeiro do Martelo do Crepúsculo e suspeita que o culto coordene seus ataques a partir de um lugar central.",al={"por que o martelo do crepúsculo","ataques do culto","o que aconteceu antes"}}},fp="19,131,19.381.0,29.67.0,34.61.0,29.89.0,47.132.0"}
P.entries["quest:94881"] = {n="Curious Trinkets",s="Ashe Amberhall, na Bastilha de Ermoforte, pede que você investigue o culto em Solclaro levando a ela seus amuletos encantados. Ela acredita que esses objetos podem revelar algo sobre a magia do culto.",h="Ashe Amberhall, na Bastilha de Ermoforte, pede que você investigue o culto em Solclaro levando a ela seus...",kw={"ashe amberhall","culto","bugigangas curiosas","bastilha de ermoforte","solclaro","twilight charms","twilight neophyte","twilight shadowmancer"},ang={["class:Druid"]="Como druida, Ashe acredita que você pode ajudá-la a investigar o culto em Solclaro."},sec={{t="Um Pedido em Farholde",b="Ashe Amberhall quer estudar o culto em Solclaro, onde a habilidade mágica conquista favor e amuletos para alguns membros. Ela acredita que os amuletos carregam a magia dos cultistas. Por isso, pede que você traga amuletos dos Twilight Shadowmancers e dos Twilight Neophytes."}},faq={{q="Quem está pedindo os amuletos?",a="Ashe Amberhall, na Bastilha de Ermoforte, quer examinar os amuletos do culto.",al={"quem quer amuletos","ashe amberhall","pedido de ashe"}},{q="Por que Ashe quer os amuletos?",a="Ashe quer saber mais sobre o culto em Solclaro e acredita que seus amuletos contêm a magia dos cultistas.",al={"por que amuletos","para que servem os amuletos","ashe quer objetos"}},{q="O que são os Twilight Charms?",a="São objetos dados aos membros do culto com afinidade pela magia e depois imbuídos com a magia dos cultistas.",al={"twilight charms","objetos do culto","amuletos mágicos"}},{q="Quem carrega os amuletos?",a="Os Twilight Shadowmancers e os Twilight Neophytes de Solclaro carregam os amuletos que Ashe procura.",al={"onde conseguir amuletos","amuletos dos shadowmancers","objetos dos neophytes"}}},fp="16,184,21.250.0,29.71.0,30.97.0,25.97.0,23.88.0"}
P.entries["quest:94885"] = {n="Field Marshal's Log",s="O diário do marechal de campo registra os movimentos do Martelo do Crepúsculo pelas Sendas do Rio. Saber onde está pode ajudar quem está na Bastilha de Ermoforte a entender os movimentos inimigos.",h="O diário do marechal de campo registra os movimentos do Martelo do Crepúsculo pelas Sendas do Rio.",kw={"demar brant","movimentos inimigos","farholde","diário do marechal de campo","sendas do rio","solclaro","martelo do crepúsculo"},sec={{t="O diário",b="Demar Brant, na Bastilha de Ermoforte, está esperando o diário do marechal de campo. Os registros acompanham as forças do Martelo do Crepúsculo que atravessam as Sendas do Rio, e alguém em Farholde quer vê-los. O autor não está em lugar algum. As anotações podem ajudar a revelar por onde o inimigo tem passado."},{t="A preocupação de Farholde",b="Demar Brant diz que as anotações chegaram tarde demais. Farholde já conhece os perigos em Solclaro, e ele está preocupado porque você também as encontrou lá."}},faq={{q="O que há no diário do marechal de campo?",a="O diário registra as idas e vindas das forças do Martelo do Crepúsculo pelas Sendas do Rio.",al={"diário do marechal de campo","o que diz o diário"}},{q="Quem escreveu o diário?",a="O autor do diário do marechal de campo não está em lugar algum.",al={"autor do diário","quem fez as anotações"}},{q="Quem quer ver o diário?",a="Alguém em Farholde quer ver o diário. Pediram que você o entregue a Demar Brant, na Bastilha de Ermoforte.",al={"quem recebe o diário","diário de demar brant"}},{q="Por que o diário é importante?",a="Os registros dos movimentos do Martelo do Crepúsculo podem ajudar a esclarecer os movimentos inimigos.",al={"por que levar o diário","movimentos inimigos"}},{q="Para onde as forças do Martelo do Crepúsculo estavam indo?",a="O diário registra as forças do Martelo do Crepúsculo pelas Sendas do Rio.",al={"martelo do crepúsculo sendas do rio","para onde foram"}}},fp="19,155,7.280.0,18.153.1,35.94.0,18.61.0,25.102.0,24.82.0,47.68.0"}
P.entries["quest:94886"] = {n="The Western Front",s="A patrulha de Farholde desapareceu na fronteira oeste. As descobertas de Miss Amberhall apontam para um acampamento do Martelo do Crepúsculo. Você deve encontrar o Sargento Riftan perto da Mortalha do Crepúsculo.",h="A patrulha de Farholde desapareceu na fronteira oeste.",kw={"farholde","miss amberhall","patrulha desaparecida","sargento riftan","solclaro","martelo do crepúsculo","mortalha do crepúsculo","fronteira oeste","frente ocidental"},sec={{t="Uma patrulha desaparecida",b="Uma patrulha de Farholde desapareceu na fronteira oeste, e o Sargento Riftan está entre os desaparecidos. As descobertas de Miss Amberhall levantam a suspeita de que a patrulha chegou ao acampamento central do Martelo do Crepúsculo. Você deve procurar Riftan perto da Mortalha do Crepúsculo, a oeste."}},faq={{q="Quem está desaparecido?",a="Uma patrulha de Farholde desapareceu na fronteira oeste. Pediram que você encontrasse o Sargento Riftan.",al={"patrulha desaparecida","onde está riftan","sargento desaparecido"}},{q="Onde devo procurar o Sargento Riftan?",a="O Sargento Riftan está perto da Mortalha do Crepúsculo, a oeste.",al={"localização de riftan","encontrar riftan","onde está o sargento"}},{q="Por que a patrulha está desaparecida?",a="As descobertas de Miss Amberhall levam Farholde a temer que a patrulha tenha entrado no acampamento central do Martelo do Crepúsculo.",al={"o que aconteceu com a patrulha","por que a patrulha desapareceu","patrulha do martelo do crepúsculo"}},{q="Quem é Miss Amberhall?",a="Miss Amberhall é a dama cujas descobertas levantam a suspeita de que a patrulha chegou ao acampamento central do Martelo do Crepúsculo.",al={"amberhall","informações sobre miss amberhall","quem é amberhall"}},{q="O que está acontecendo em Solclaro?",a="Farholde diz que consegue cuidar da limpeza em Solclaro por conta própria, enquanto pedem que você verifique como está o Sargento Riftan.",al={"problema em solclaro","limpeza em solclaro","o que há em solclaro"}}},fp="17,204,16.283.0,15.105.0,40.58.0,26.112.0,22.121.0,32.110.0"}
P.entries["quest:94887"] = {n="Saving Marshal Ryan",s="A Aliança precisa encontrar Marshal Ryan, um de seus melhores batedores. Seus últimos relatos apontam para uma fortaleza do Martelo do Crepúsculo a oeste, e seu diário pode conter mais pistas.",h="A Aliança precisa encontrar Marshal Ryan, um de seus melhores batedores.",kw={"aliança","diário","marshal ryan","marechal desaparecido","salvando marshal ryan","martelo do crepúsculo","mortalha do crepúsculo"},ang={["faction:Alliance"]="Como membro da Aliança, você está ajudando a encontrar Marshal Ryan, cujos relatos têm sido importantes para o esforço de guerra."},sec={{t="O Marechal Desaparecido",b="Os últimos relatórios de Marshal Ryan o situam perto de uma fortaleza do Martelo do Crepúsculo, a oeste. Você é enviado para encontrá-lo na Mortalha do Crepúsculo, levando o diário dele. A Aliança conta com seu olhar aguçado e informações confiáveis, e os relatórios dele podem ajudar a descobrir onde está."}},faq={{q="Quem é Marshal Ryan?",a="Marshal Ryan é um dos melhores da Aliança, valorizado por seu olhar aguçado e suas informações confiáveis.",al={"quem é marshal ryan","quem é ryan"}},{q="Onde está Marshal Ryan?",a="Marshal Ryan está sendo procurado na Mortalha do Crepúsculo, perto de uma fortaleza do Martelo do Crepúsculo a oeste.",al={"onde está ryan","encontrar marshal ryan"}},{q="Por que Ryan está desaparecido?",a="Seus últimos relatos mencionam uma fortaleza do Martelo do Crepúsculo a oeste, e a Aliança ainda não o encontrou.",al={"por que ryan desapareceu","o que aconteceu com marshal ryan"}},{q="Por que a Aliança quer o diário dele?",a="O diário de Marshal Ryan pode dar pistas sobre seu paradeiro.",al={"por que o diário de ryan","o que há no diário"}}},fp="19,173,19.277.0,20.95.0,22.99.0,20.104.0,39.58.0"}
P.entries["quest:94890"] = {n="Bring Me His Head",s="O sargento Riftan manda você voltar à Mortalha do Crepúsculo, onde Overlord Kilgar continua escondido em sua fortaleza. Os soldados resgatados estão prontos para lutar, e Riftan quer derrotar Kilgar.",h="O sargento Riftan manda você voltar à Mortalha do Crepúsculo, onde Overlord Kilgar continua escondido em sua...",kw={"traga-me a cabeça dele","orc","overlord kilgar","soldados resgatados","sargento riftan","mortalha do crepúsculo"},sec={{t="De volta à fortaleza",b="Os soldados resgatados estão ansiosos para lutar, e o sargento Riftan diz que sua força ajudou a levar o ataque até aqui. Overlord Kilgar, um orc, está escondido nas profundezas de sua fortaleza na Mortalha do Crepúsculo. Riftan pede que você o derrote e traga sua cabeça."}},faq={{q="Quem é Overlord Kilgar?",a="Overlord Kilgar é um líder orc escondido nas profundezas de sua fortaleza na Mortalha do Crepúsculo.",al={"kilgar","quem é kilgar","líder orc"}},{q="Por que estou sendo enviado de volta à Mortalha do Crepúsculo?",a="Os soldados resgatados estão prontos para lutar, e o sargento Riftan diz que o ataque deve continuar. Ele pede que você volte à Mortalha do Crepúsculo e traga a cabeça de Overlord Kilgar.",al={"por que voltar","missão na mortalha do crepúsculo","o que vem a seguir"}},{q="Quem quer a cabeça de Kilgar?",a="O sargento Riftan pede que você traga a cabeça de Overlord Kilgar para ele.",al={"o que riftan quer","quem pediu kilgar","traga-me a cabeça dele"}},{q="Onde Kilgar está escondido?",a="Overlord Kilgar está escondido nas profundezas de sua fortaleza na Mortalha do Crepúsculo.",al={"localização de kilgar","onde está o overlord","fortaleza de kilgar"}}},fp="17,185,16.255.0,23.86.0,50.180.0,24.61.0,23.72.0"}
P.entries["quest:94891"] = {n="News to Farholde",s="Ashe Amberhall, na Bastilha de Ermoforte, aguarda seu relatório após o trabalho com o Sargento Riftan. Seu retorno mostrará se a expedição foi bem-sucedida.",h="Ashe Amberhall, na Bastilha de Ermoforte, aguarda seu relatório após o trabalho com o Sargento Riftan.",kw={"ashe amberhall","bastilha de ermoforte","kilgar","notícias para farholde","relatório","sargento riftan"},sec={{t="Um relatório para Ashe",b="O Sargento Riftan manda você de volta para Ashe Amberhall, na Bastilha de Ermoforte, com um relatório. Ele lhe entrega a cabeça de Kilgar para levar. Ashe diz que começou a duvidar do próprio julgamento enquanto você esteve fora, mas agora elogia seus talentos."}},faq={{q="Quem quer o relatório?",a="Ashe Amberhall, na Bastilha de Ermoforte, está esperando seu relatório.",al={"para quem devo levar o relatório","relatório para ashe","relatório de farholde"}},{q="O que Riftan me entrega?",a="O Sargento Riftan lhe entrega a cabeça de Kilgar para levar a Ashe Amberhall.",al={"o que riftan jogou de volta","cabeça de kilgar","o que estou carregando"}},{q="O que Ashe diz quando eu volto?",a="Ashe diz que começou a temer ter julgado mal seus talentos, depois afirma que você era a pessoa certa para o trabalho.",al={"reação de amberhall","diálogo de ashe","ashe estava preocupada"}},{q="O que Ashe diz sobre Riftan?",a="Ashe pergunta se Riftan ainda está por perto e diz que esperava que vocês dois se dessem bem.",al={"riftan ainda está vivo","e o sargento riftan","ashe e riftan"}}},fp="16,141,17.222.0,21.59.0,25.66.0,33.98.0,32.84.0"}
P.entries["quest:94892"] = {n="Dying Wish",s="O marechal Ryan está morrendo e pede que você leve seu brasão ao comandante cavaleiro Demar Brant. Suas últimas palavras se voltam para o lar e Abigail.",h="O marechal Ryan está morrendo e pede que você leve seu brasão ao comandante cavaleiro Demar Brant.",kw={"abigail","brasão","desejo final","bastilha de ermoforte","comandante cavaleiro demar brant","marechal ryan","ryan"},sec={{t="As últimas palavras de Ryan",b="Enquanto os olhos de Ryan perdem o brilho, ele fala do lar e de Abigail. O marechal lhe entrega seu brasão e pede que você avise o comandante cavaleiro Demar Brant. Você leva o símbolo de sua patente à Bastilha de Ermoforte, onde o comandante aguarda."}},faq={{q="Quem está morrendo?",a="O marechal Ryan está morrendo quando pede que você leve seu brasão ao comandante cavaleiro Demar Brant.",al={"quem está morrendo desejo","marechal ryan"}},{q="O que Ryan quer que eu faça?",a="Ryan pede que você leve seu brasão ao comandante cavaleiro Demar Brant e o avise.",al={"pedido de ryan","o que fazer com o brasão"}},{q="Quem é Abigail?",a="Nas últimas palavras, Ryan menciona Abigail e diz que deveria ter voltado para casa.",al={"abigail e ryan","quem é abigail"}},{q="Onde devo levar o brasão?",a="Leve o brasão do marechal Ryan ao comandante cavaleiro Demar Brant na Bastilha de Ermoforte.",al={"onde está o brasão","localização de demar brant"}}},fp="10,132,19.218.0,13.89.0,29.78.0,15.68.0,26.75.0"}
P.entries["quest:94893"] = {n="Delivering Closure",s="Demar pede que você leve o brasão do marechal Ryan a Abigail Lawson, em Ventobravo. A morte de Ryan deixa uma mensagem para a mulher com quem ele planejava se casar.",h="Demar pede que você leve o brasão do marechal Ryan a Abigail Lawson, em Ventobravo.",kw={"abigail lawson","praça da catedral","levando um desfecho","demar","bastilha de ermoforte","marechal ryan","brasão de ryan","ventobravo"},sec={{t="Uma mensagem em Ventobravo",b="Abigail Lawson espera na Praça da Catedral, e você leva o brasão do marechal Ryan até ela a pedido de Demar. Ela não se juntou a Demar e Ryan quando eles fundaram a Bastilha de Ermoforte. Ryan e Abigail tinham divergido, embora Demar não saiba o motivo. Ele acredita que sua presença não seria bem-vinda, então o brasão precisa falar em seu lugar."},{t="Palavras não ditas",b="A família de Ryan morreu durante a invasão dos orcs, e seu senso de dever contra a Horda se transformou em ódio. Abigail já o convidou para morar com ela e os pais em Ventobravo, mas Ryan recusou. Ele jurou ficar até expulsar os orcs de sua casa. Ryan e Abigail não se falavam desde então."},{t="O brasão recebido",b="Quando você entrega o brasão, Abigail fala da recusa de Ryan em deixar sua casa e do longo silêncio entre eles. Ela chama Demar de herói, mas alerta que heróis costumam trazer perigo para quem está ao redor. Então, segura o brasão de Ryan junto ao peito e o chama de idiota."}},faq={{q="Quem é Abigail Lawson?",a="Abigail Lawson era a prometida do marechal Ryan. Ela mora em Ventobravo e não se juntou a Ryan e Demar na Bastilha de Ermoforte.",al={"abigail quem","quem é abigail","prometida de ryan"}},{q="Quem me pede para levar o brasão de Ryan?",a="Demar pede que você leve o brasão do marechal Ryan para Abigail Lawson, em Ventobravo. Ele acredita que a presença dele não seria bem-vinda.",al={"quem me enviou","brasão de demar","quem quer que o brasão seja entregue"}},{q="Por que Ryan ficou para trás?",a="Depois que a família de Ryan foi morta durante a invasão dos orcs, seu dever contra a Horda se tornou ódio. Ele jurou ficar até expulsar os orcs de sua casa.",al={"por que ryan ficou","ryan e os orcs","a família dele"}},{q="Por que Abigail e Ryan pararam de se falar?",a="Abigail e Ryan tiveram um desentendimento, mas Demar não sabe os detalhes. Eles não se falavam desde então.",al={"por que pararam de se falar","abigail e ryan","o desentendimento deles"}},{q="Para que serve o brasão de Ryan?",a="Demar pede que você leve o brasão do marechal Ryan para Abigail Lawson, na Praça da Catedral, em Ventobravo.",al={"brasão do marechal","brasão de ryan","o que devo levar"}}},fp="18,150,22.324.0,17.293.0,18.252.1,22.126.0,36.131.0,25.162.0,39.102.0,27.101.0"}
P.entries["quest:94894"] = {n="The Twilight Threat",s="Farholde busca a ajuda de Ventobravo contra o aumento repentino das atividades do Martelo do Crepúsculo. Você leva provas a Bolvar Fordragon, embora a Aliança tenha outras guerras para enfrentar.",h="Farholde busca a ajuda de Ventobravo contra o aumento repentino das atividades do Martelo do Crepúsculo.",kw={"bolvar fordragon","brant","farholde","horda","kilgar","sendas do rio","bastilha ventobravo","martelo do crepúsculo"},ang={["faction:Alliance"]="Como aventureiro da Aliança, você leva as provas de Farholde a Bolvar Fordragon enquanto seu povo busca ajuda contra o Martelo do Crepúsculo e a Horda."},sec={{t="O apelo de Farholde",b="O povo de Farholde procura você depois que Lady Amberhall fica sabendo de seus encontros com o Martelo do Crepúsculo. A campanha começou para expulsar a Horda de sua terra natal, mas a atividade dos cultistas aumentou muito. Eles temem que Ventobravo não responda aos apelos antes que Farholde enfrente inimigos em duas frentes. Você leva provas a Bolvar Fordragon na Bastilha Ventobravo."},{t="A resposta de Ventobravo",b="Na Bastilha Ventobravo, Bolvar Fordragon ouve o alerta de Farholde. Ele diz que a Aliança já está em guerra em uma escala muito maior e não pode dedicar suas forças à disputa particular de uma aldeia. A Horda arrasou mais lares do que os das Sendas do Rio. Bolvar não vê muita esperança de que Brant deixe o orgulho de lado e traga sua cavalaria para ajudar a Aliança."}},faq={{q="Quem pede a ajuda de Ventobravo?",a="Farholde pede ajuda a Ventobravo enquanto as atividades do Martelo do Crepúsculo aumentam.",al={"quem quer ajuda","apelo de farholde","quem me enviou"}},{q="Por que Farholde está preocupada?",a="Farholde teme ser vencida por inimigos em duas frentes se Ventobravo não atender a seus apelos.",al={"o que há de errado em farholde","problema com cultistas","por que está preocupada"}},{q="Que provas estou levando?",a="Você leva a Cabeça de Kilgar a Bolvar Fordragon na Bastilha Ventobravo.",al={"quais provas","cabeça de kilgar","entrega da cabeça"}},{q="De quem Bolvar recebe notícias?",a="Bolvar Fordragon recebe notícias de Farholde, cuja campanha começou para expulsar a Horda de sua terra natal.",al={"quem enviou as notícias","relato de farholde","pergunta sobre bolvar"}},{q="Por que Ventobravo não pode apoiar Farholde?",a="Bolvar diz que a Aliança está lutando em uma escala muito maior e não tem recursos para apoiar a disputa pessoal de Farholde.",al={"por que não ajudam","apoio de ventobravo","bolvar recusa"}}},fp="19,175,15.357.0,18.365.1,30.69.0,24.100.0,25.62.0,27.105.0,37.120.0"}
P.entries["quest:94895"] = {n="Lost Shipping Crate",s="O caixote de carga de Friz Frazzlespark desapareceu do Porto Detonapavio, nas Sendas do Rio. A etiqueta alerta para não abri-lo sem supervisão e pede que você o devolva a Friz.",h="O caixote de carga de Friz Frazzlespark desapareceu do Porto Detonapavio, nas Sendas do Rio.",kw={"etiqueta do caixote","mapa do caixote","friz frazzlespark","caixote de carga perdido","porto detonapavio","sendas do rio","aviso"},sec={{t="Um Caixote Marcado",b="Um mapa e um aviso identificam o caixote que você carrega pelas Sendas do Rio. A etiqueta informa o nome de Friz Frazzlespark e do Porto Detonapavio, e pede que o caixote seja devolvido para lá caso se perca. Você está levando-o de volta ao dono."}},faq={{q="Quem é o dono do caixote de carga?",a="A etiqueta identifica Friz Frazzlespark como dono do caixote de carga.",al={"dono do caixote","quem é o dono","caixote de friz"}},{q="Onde devo levar o caixote?",a="O caixote deve ser devolvido a Friz Frazzlespark no Porto Detonapavio, nas Sendas do Rio.",al={"onde devolver o caixote","destino do caixote","porto detonapavio"}},{q="Sobre o que a etiqueta alerta?",a="A etiqueta alerta contra adulterações e diz para não abrir o caixote sem supervisão.",al={"aviso do caixote","posso abrir o caixote","abrir o caixote"}},{q="O que está marcado no mapa do caixote?",a="O mapa mostra um círculo vermelho junto a uma costa no sudeste, ao norte de um templo mal desenhado, cercado por água e criaturas aladas.",al={"mapa do caixote","o que há no mapa","círculo vermelho no mapa"}}},fp="19,188,14.214.0,28.69.0,30.87.0,31.85.0,34.131.0"}
P.entries["quest:94896"] = {n="Aid For The Refugees",s="Aid For The Refugees se concentra nos sobreviventes deslocados de Ban'aethal, um assentamento nas profundezas da Floresta Umbréola que foi evacuado repentinamente no meio da noite. Com seu lar caindo em direção ao céu e a região selvagem ao redor tendo se tornado perigosa demais para adentrar, os refugiados dependem de viajantes corajosos para recuperar os pertences que tiveram de deixar para trás.",h="Aid For The Refugees se concentra nos sobreviventes deslocados de Ban'aethal, um assentamento nas profundezas...",kw={"aid for the refugees","ban'aethal","banaethal","pertences","ealaane","refugiados","floresta umbréola"},sec={{t="Um Apelo Desesperado",b="Aid for the Refugees é um apelo de assistência de Ealaane e de seus companheiros aldeões desabrigados. Tendo escapado por pouco de seus lares nas profundezas da Floresta Umbréola, os sobreviventes reuniram-se quase sem nada em suas posses, na esperança de que um viajante de passagem enfrente os perigos deixados para trás."},{t="A Calamidade de Ban'aethal",b="O assentamento de Ban'aethal teve um destino impensável na calada da noite, quando a vila subitamente começou a cair no céu. A calamidade bizarra e aterrorizante deu aos habitantes meros instantes para fugir, forçando-os a abandonar seus pertences pessoais enquanto os bosques ao redor tornavam-se hostis e perigosos."}},faq={{q="Quem é Ealaane?",a="Ealaane é uma refugiada de Ban'aethal que fugiu com outros quando seu assentamento começou a ruir. Ela pede a aventureiros de passagem que viajam em direção à Floresta Umbréola que recuperem pertences pessoais deixados para trás nas ruínas.",al={"quem deu aid for the refugees","concedente da missão aid for the refugees","ealaane"}},{q="O que aconteceu com Ban'aethal?",a="Ban'aethal era um assentamento situado nas profundezas da Floresta Umbréola. Seus residentes foram forçados recentemente a evacuar no meio da noite devido a uma catástrofe repentina e bizarra.",al={"o que é banaethal","onde fica banaethal","vila de ban aethal"}},{q="Por que os aldeões tiveram que evacuar Ban'aethal?",a="A evacuação foi desencadeada repentinamente no meio da noite quando Ban'aethal começou a cair no céu. A vila e a floresta ao redor tornaram-se perigosas demais para que os moradores ficassem ou retornassem.",al={"por que evacuar banaethal","caindo no céu","desastre de ban aethal"}},{q="Por que os aldeões estão pedindo para que seus pertences sejam recuperados?",a="A catástrofe ocorreu repentinamente no meio da noite, forçando os aldeões a fugir para salvar suas vidas praticamente sem nada. Com a floresta e as ruínas agora tomadas pelo perigo, eles dependem de aventureiros capazes para recuperar o que foi deixado para trás.",al={"por que precisam de pertences","pertences abandonados","por que recuperar pertences"}},{q="O que é a Floresta Umbréola?",a="A Floresta Umbréola é a região arborizada que abriga o assentamento de Ban'aethal. Após o desastre bizarro que despedaçou a vila, a floresta tornou-se extremamente perigosa para as pessoas comuns.",al={"onde fica a floresta umbréola","história da floresta umbréola"}},{q="Os refugiados podem retornar aos seus lares?",a="Não. De acordo com Ealaane, tanto a Floresta Umbréola quanto as Ruínas de Ban'aethal são perigosas demais para que os moradores deslocados consigam retornar por conta própria.",al={"refugiados podem voltar","banaethal é segura"}}},fp="20,237,16.174.0,26.196.0,15.173.0,28.138.0,50.180.0,66.227.0,26.166.0,39.121.0"}
P.entries["quest:94897"] = {n="The Fate of a Loved One",s="The Fate of a Loved One é uma missão sobre Resaan, que se aventurou nas perigosas Ruínas de Ban'aethal para buscar suprimentos e nunca mais voltou. Mais de uma semana depois, seu parceiro em luto pede aos viajantes que vão para as ruínas que descubram seu paradeiro e o tragam para casa ou recuperem sua querida relíquia de família.",h="The Fate of a Loved One é uma missão sobre Resaan, que se aventurou nas perigosas Ruínas de Ban'aethal para...",kw={"ban'aethal","relíquia de família","resaan","ruínas de ban'aethal","suprimentos","the fate of a loved one"},sec={{t="Um Apelo Desesperado",b="The Fate of a Loved One gira em torno de um apelo desesperado de alguém cujo parceiro, Resaan, aventurou-se de volta às Ruínas de Ban'aethal. Apesar dos pedidos sinceros para que ficasse, Resaan sentiu-se compelido a enfrentar as ruínas em busca de suprimentos, deixando para trás alguém que agora espera em uma incerteza angustiante."},{t="Desaparecido nas Ruínas",b="Mais de uma semana se passou desde que Resaan partiu, superando em muito qualquer expectativa razoável de um retorno rápido. Viajantes a caminho de Ban'aethal recebem súplicas para procurá-lo entre as ruínas — para guiá-lo de volta se ainda restar vida, ou para recuperar sua relíquia de família se apenas uma tragédia restar para ser encontrada."}},faq={{q="Quem é Resaan?",a="Resaan é um indivíduo que se aventurou de volta às Ruínas de Ban'aethal para reunir suprimentos, apesar de receberem súplicas para ficar. Após mais de uma semana sem notícias, seu parceiro teme que ele tenha encontrado um fim trágico entre as ruínas.",al={"quem é resaan","onde está resaan","encontrar resaan"}},{q="O que são as Ruínas de Ban'aethal?",a="As Ruínas de Ban'aethal são um local perigoso onde Resaan se aventurou em busca de suprimentos necessários. Seu parceiro considera a jornada perigosa o suficiente para que sobreviver uma semana lá sozinho seja improvável.",al={"o que é banaethal","história das ruínas de banaethal","onde fica banaethal"}},{q="Por que Resaan retornou a Ban'aethal?",a="Resaan retornou a Ban'aethal especificamente para buscar suprimentos. Ele decidiu fazer a perigosa jornada mesmo com seu parceiro implorando para que ele não fosse.",al={"por que resaan voltou","por que resaan está em banaethal"}},{q="O que o doador da missão pede para você trazer de volta?",a="Se Resaan ainda estiver vivo, o doador da missão pede que ele seja trazido em segurança para casa. Se ele tiver morrido nas ruínas, o doador da missão implora pela recuperação de sua relíquia de família como uma lembrança final.",al={"o que o doador da missão quer","o que acontece se resaan estiver morto"}},{q="Há quanto tempo Resaan está desaparecido?",a="Resaan está desaparecido há mais de uma semana desde que partiu para as Ruínas de Ban'aethal. Diante dos perigos da área, esse silêncio prolongado leva seu parceiro a temer o pior.",al={"há quanto tempo resaan está desaparecido","há quanto tempo resaan se foi"}},{q="Quem oferece esta missão?",a="A missão é oferecida pelo parceiro ou companheiro em luto de Resaan, que continua desesperado por um desfecho e disposto a pedir ajuda aos viajantes que passam em direção a Ban'aethal.",al={"quem dá the fate of a loved one","doador da missão the fate of a loved one"}}},fp="23,187,16.187.0,21.250.0,14.178.0,33.131.0,36.92.0,47.155.0,33.146.0,22.123.0"}
P.entries["quest:949"] = {n="O Acampamento do Crepúsculo",s="O Acampamento do Crepúsculo é uma missão de reconhecimento da Aliança voltada para os cultistas sigilosos acampados ao redor da Glaive do Mestre, no sul de Costa Negra. Após vislumbrarem o local do ritual por meio de uma tigela de vidência, os investigadores devem se infiltrar na escavação para descobrir o que o Martelo do Crepúsculo busca desenterrar.",h="O Acampamento do Crepúsculo é uma missão de reconhecimento da Aliança voltada para os cultistas sigilosos...",kw={"costa negra","glaive do mestre","onu","scrying bowl","o acampamento do crepusculo","twilight tome","martelo do crepusculo"},ang={["class:Druid"]="Descobrir as pesquisas do culto é essencial para que os guardiões cenarianos mantenham entidades ancestrais corruptoras devidamente sepultadas.",["faction:Alliance"]="Interromper as estranhas escavações do culto impede que uma ameaça crescente desestabilize o norte de Kalimdor.",["race:NightElf"]="O Martelo do Crepúsculo profana as terras sagradas de Kalimdor com feitiçarias sombrias bem sob as copas dos antigos arvoredos de Costa Negra."},sec={{t="Sondando a Escavação",b="A Glaive do Mestre há muito se ergue como um mistério petrificado e sinistro ao longo das colinas escarpadas do sul de Costa Negra, mas a chegada repentina do culto do Martelo do Crepúsculo transformou uma antiga curiosidade em uma ameaça ativa. Depois de usar uma tigela de vidência para perscrutar suas fortificações, batedores são enviados para o meio do acampamento para determinar seus verdadeiros planos antes que medidas defensivas possam ser tomadas."},{t="O Tomo Ilustrado",b="Vasculhar o acampamento revela que os cultistas não são meros saqueadores ou bandidos; sua operação é guiada por um profundo estudo ocultista. Bem no interior do acampamento ao norte repousa um tomo antigo, meticulosamente impresso à mão e ilustrado com uma arte magistral, porém perturbadora. Esse texto serve como prova de que o Martelo do Crepúsculo está deliberadamente investigando a entidade colossal enterrada sob a terra."}},faq={{q="Qual é o objetivo da missão O Acampamento do Crepúsculo?",a="Você deve se infiltrar no acampamento do Martelo do Crepúsculo perto da Glaive do Mestre, no sul de Costa Negra, e recuperar uma pista detalhando seus motivos — especificamente um livro ritual impresso à mão que se encontra no acampamento.",al={"objetivo da missao o acampamento do crepusculo","o que fazer em o acampamento do crepusculo"}},{q="Quem envia você para investigar o acampamento?",a="A missão é obtida diretamente na Scrying Bowl no mirante acima da Glaive do Mestre, dando continuidade à investigação iniciada em nome do antigo protetor Onu.",al={"quem da o acampamento do crepusculo","doador da missao o acampamento do crepusculo"}},{q="Onde a pista é encontrada no acampamento?",a="A pista válida é o Twilight Tome situado na parte norte do acampamento. Outros tomos no acampamento podem ser perigosas iscas que liberam magia de proteção contra invasores.",al={"onde fica o livro","localizacao do twilight tome","encontrar pista o acampamento do crepusculo"}},{q="Por que o Martelo do Crepúsculo está na Glaive do Mestre?",a="Os cultistas são obcecados pelos poderes sombrios e ancestrais dos Deuses Antigos e de seus servos. Eles estão escavando a enorme carcaça petrificada cravada pela lâmina de pedra gigante para estudar ou despertar qualquer mal ancestral que permaneça ali.",al={"por que cultistas estao na glaive do mestre","objetivo do martelo do crepusculo em costa negra"}},{q="O que acontece após encontrar o tomo?",a="Recuperar o tomo leva à missão A volta a Onu, instruindo você a levar os escritos descobertos para o norte, até o antigo anciente no Bosque dos Ancientes.",al={"proxima missao depois de o acampamento do crepusculo","para onde ir depois do twilight tome"}}},fx={["8554815a"]={q="Por que a Tigela de Vidência manda você investigar o acampamento?",a="A tigela de vidência de Onu revela que sectários do Martelo do Crepúsculo se reuniram ao redor da Glaive do Mestre, onde um antigo senhor caiu há muito tempo. Ninguém sabe o que eles procuram ali, mas Onu tem certeza de que suas intenções são sombrias. Antes que ele e os defensores do bosque possam traçar um plano, precisam obter algo do acampamento que revele as intenções do culto.",al={"por que investigar o acampamento do crepúsculo","para que serve a tigela de vidência","por que vasculhar o acampamento do crepúsculo"}}},fp="17,240,15.204.0,20.195.1,44.149.0,38.146.0,36.119.0,52.204.0,36.121.0"}
P.entries["quest:94907"] = {n="A Small Favor",s="Pedem a uma druida que leve a magia do Martelo do Crepúsculo até sua origem no Twilight Shroud. Amberhall quer capturar um lacaio do culto para interrogá-lo.",h="Pedem a uma druida que leve a magia do Martelo do Crepúsculo até sua origem no Twilight Shroud.",kw={"um pequeno favor","amberhall","conduto","druida","reagentes","pedra da alma","ritual de invocação","twilight shroud","martelo do crepúsculo","thrall do crepúsculo"},ang={["class:Druid"]="Como druida, você é quem Amberhall chama de boa druida obediente antes de pedir esse favor."},sec={{t="Um Favor da Druida",b="Amberhall pede sua ajuda no Twilight Shroud. Os reagentes que você reuniu estão sintonizados com a magia do Martelo do Crepúsculo, e Amberhall diz que podem ser usados em um ritual de invocação. Para chegar à origem desse poder, pedem que você use um conduto para chamar um Thrall do Crepúsculo e capturá-lo com a Pedra da Alma de Amberhall."}},faq={{q="O que Amberhall quer que eu faça?",a="Amberhall pede que você invoque um Thrall do Crepúsculo por um conduto no Twilight Shroud e o capture com a Pedra da Alma de Amberhall.",al={"favor de amberhall","pequeno favor","o que fazer"}},{q="Por que os reagentes são úteis?",a="Os reagentes estão sintonizados com a magia do Martelo do Crepúsculo, o que os torna adequados para um ritual de invocação.",al={"para que servem os reagentes","por que os reagentes","reagentes para magia do crepúsculo"}},{q="Onde uso o conduto?",a="O conduto fica no Twilight Shroud.",al={"localização do conduto","onde invocar o lacaio","conduto no twilight shroud"}},{q="Por que capturar o lacaio?",a="Amberhall quer que o Thrall do Crepúsculo seja capturado para interrogatório.",al={"por que usar a pedra da alma","por que capturar o lacaio","interrogatório do thrall"}}},fp="13,143,15.307.0,34.129.0,28.97.0,27.42.0,23.63.0"}
P.entries["quest:94911"] = {n="Child of Nature",s="Um membro dos Skyborne vê potencial em suas artes druídicas e indica Turak Runa Totem, no Penhasco do Trovão. Ele pode ensinar você a chegar à fortaleza do Círculo Cenariano, na Clareira da Lua.",h="Um membro dos Skyborne vê potencial em suas artes druídicas e indica Turak Runa Totem, no Penhasco do Trovão.",kw={"círculo cenariano","filho da natureza","druida","clareira da lua","skyborne","penhasco do trovão","turak runa totem"},ang={["class:Druid"]="Como druida, você é encaminhado a Turak Runa Totem, que pode ensinar você a chegar ao Círculo Cenariano, na Clareira da Lua.",["race:Skyborne"]="Como membro dos Skyborne, você é informado de que os druidas do Círculo Cenariano vão acolher você e compartilhar seus conhecimentos."},sec={{t="Boas-vindas a um Druida",b="Seu mestre acredita que os druidas do Círculo Cenariano vão acolher você e compartilhar seus conhecimentos. Turak Runa Totem, no Penhasco do Trovão, pode ensinar você a chegar à fortaleza deles, na Clareira da Lua."}},faq={{q="Com quem devo falar?",a="Fale com Turak Runa Totem, no Penhasco do Trovão. Ele pode ensinar você a chegar à Clareira da Lua.",al={"com quem falar","turak runa totem","quem é turak"}},{q="Onde fica a fortaleza do Círculo Cenariano?",a="A fortaleza do Círculo Cenariano fica na Clareira da Lua, em Kalimdor.",al={"onde fica o círculo","localização do círculo cenariano","clareira da lua"}},{q="Por que estão me enviando à Clareira da Lua?",a="Os druidas do Círculo Cenariano podem transmitir seus conhecimentos a você.",al={"por que clareira da lua","aprender druidismo","treinamento de druida"}}},fp="15,186,19.189.0,24.85.0,44.63.0,33.69.0"}
P.entries["quest:94912"] = {n="Child of Nature",s="Sheldras Moontree, em Ventobravo, pode ensinar você a chegar à Clareira da Lua, reduto do Círculo Cenariano. Os druidas da ordem antiga têm sabedoria para compartilhar com um filho da natureza.",h="Sheldras Moontree, em Ventobravo, pode ensinar você a chegar à Clareira da Lua, reduto do Círculo Cenariano.",kw={"círculo cenariano","filho da natureza","druida","kalimdor","clareira da lua","sheldras moontree","skyborne","ventobravo"},ang={["class:Druid"]="Como druida, você é enviado ao Círculo Cenariano, uma ordem antiga cujos membros praticam as artes druídicas.",["race:Skyborne"]="Como Skyborne, você é recebido entre os primeiros de seu povo a chegar a Azeroth."},sec={{t="Um Reduto Distante",b="Você é enviado até Sheldras Moontree, um elfo noturno em Ventobravo. Ele pode ensinar você a chegar à Clareira da Lua, em Kalimdor, onde fica o reduto do Círculo Cenariano. O Círculo é uma ordem antiga de naturalistas e praticantes das artes druídicas, com muito a ensinar a você."}},faq={{q="Quem é Sheldras Moontree?",a="Sheldras Moontree é um elfo noturno em Ventobravo que pode ensinar você a chegar à Clareira da Lua.",al={"sheldras","elfo noturno em ventobravo","quem me ensina a chegar à clareira da lua"}},{q="O que é o Círculo Cenariano?",a="O Círculo Cenariano é uma ordem antiga de naturalistas e praticantes das artes druídicas.",al={"círculo cenariano","ordem druídica","círculo da natureza"}},{q="Onde fica o reduto do Círculo Cenariano?",a="O reduto do Círculo Cenariano fica na Clareira da Lua, em Kalimdor.",al={"reduto cenariano","onde fica a clareira da lua","clareira da lua"}},{q="O que posso aprender com o Círculo Cenariano?",a="Os druidas do Círculo Cenariano têm muita sabedoria para transmitir a você.",al={"ensinamentos cenarianos","o que podem ensinar","sabedoria druídica"}}},fp="15,149,16.215.0,25.86.0,28.93.0,42.66.0,42.66.0"}
P.entries["quest:94914"] = {n="Clareira da Lua",s="Um instrutor druida oferece a você um meio de chegar à Clareira da Lua e encontrar Dendrite Stellardor. Lá, você pode conversar com ele sobre o caminho que começou a trilhar.",h="Um instrutor druida oferece a você um meio de chegar à Clareira da Lua e encontrar Dendrite Stellardor.",kw={"forma de urso","dendrite stellardor","druida","guardião remulos","clareira da lua","refúgio noturno","teleporte"},ang={["class:Druid"]="Como druida, você é recebido por seu instrutor na Clareira da Lua e aprende uma magia para viajar até lá."},sec={{t="Uma Primeira Lição",b="Seu instrutor recebe todos os druidas na Clareira da Lua, onde o Guardião Remulos cuida de quem descansa ali. Você recebe a magia Teleporte: Clareira da Lua, que permite viajar até lá quando busca conhecimento ou consolo. Sua primeira lição é conversar com Dendrite Stellardor no Refúgio Noturno sobre o caminho que você está trilhando."},{t="A Forma de Urso",b="Dendrite percebe que você já dominou a forma de urso. Ele considera que você está no caminho certo."}},faq={{q="Com quem devo conversar na Clareira da Lua?",a="Converse com Dendrite Stellardor no vilarejo do Refúgio Noturno sobre o caminho que você está trilhando.",al={"com quem conversar","dendrite stellardor","druida do refúgio noturno"}},{q="Como chego à Clareira da Lua?",a="Seu instrutor ensina a magia Teleporte: Clareira da Lua, que transporta você até lá.",al={"teleporte para clareira da lua","como chegar à clareira da lua","magia de teleporte"}},{q="Quem cuida dos druidas na Clareira da Lua?",a="O Guardião Remulos é o protetor da Clareira da Lua e cuida dos druidas que descansam ali.",al={"guardião remulos","protetor da clareira da lua","quem protege a clareira da lua"}},{q="O que Dendrite diz sobre meu progresso?",a="Dendrite percebe que você já dominou a forma de urso.",al={"forma de urso","dominei a forma de urso","resposta de dendrite"}}},fp="9,132,14.290.0,13.112.1,35.70.0,26.75.0,37.57.0,41.72.0"}
P.entries["quest:94923"] = {n="Hats Off",s="Robbie pede que você encontre o chapéu de aniversário que perdeu perto do rio, junto aos murlocs. Ele teme que a família descubra que esteve lá.",h="Robbie pede que você encontre o chapéu de aniversário que perdeu perto do rio, junto aos murlocs.",kw={"chapéu de aniversário","ellie","chapéu","chapéu perdido","murlocs","rio","robbie"},sec={{t="Um Chapéu Perdido",b="Robbie perdeu o chapéu que a irmã lhe deu de aniversário enquanto brincava perto do rio. Ele não pode se aproximar dos murlocs, então não pode pedir ajuda ao pai nem a Ellie. Ele suspeita que um dos murlocs encontrou o chapéu. Pedem que você procure por ele em algum lugar ao longo do rio."}},faq={{q="Quem é Robbie?",a="Robbie é um garoto que perdeu o chapéu de aniversário que a irmã lhe deu enquanto brincava perto do rio.",al={"robbie","quem é robbie"}},{q="O que Robbie perdeu?",a="Robbie perdeu um chapéu que a irmã lhe deu de aniversário.",al={"chapéu de robbie","chapéu perdido"}},{q="Onde Robbie perdeu o chapéu?",a="Robbie perdeu o chapéu enquanto brincava no rio e pede que você procure por ele em algum lugar ao longo do rio, perto dos murlocs.",al={"local do chapéu","onde está o chapéu"}},{q="Por que Robbie não pode pedir ajuda à família?",a="Robbie não pode se aproximar dos murlocs, e pedir ajuda ao pai ou a Ellie revelaria onde ele esteve.",al={"por que não pedir ao pai","por que esconder isso"}},{q="Robbie sabe se algum murloc pegou o chapéu?",a="Robbie imagina que um dos murlocs encontrou e ficou com o chapéu.",al={"chapéu de murloc","os murlocs pegaram o chapéu"}}},fp="8,125,10.268.0,14.89.0,21.55.0,30.111.0,41.111.0,42.62.0"}
P.entries["quest:94924"] = {n="Hunting the Hunters",s="Watcher Cornelius pede que você detenha os Rog'mar Poachers nas Sendas do Rio. Eles matam pessoas e animais e ameaçam toda a vida nas planícies.",h="Watcher Cornelius pede que você detenha os Rog'mar Poachers nas Sendas do Rio.",kw={"caçando os caçadores","poachers orcs","poachers","sendas do rio","rog'mar poachers","watcher cornelius"},sec={{t="Poachers nas Planícies",b="Os Rog'mar Poachers percorrem as Sendas do Rio em bandos, e Watcher Cornelius pede que você os enfrente. Eles matam pessoas, leões e cavalos, ameaçando toda a vida nas planícies. Nenhuma criatura está a salvo de suas caçadas."}},faq={{q="Quem me pede para deter os Poachers?",a="Watcher Cornelius pede que você detenha os Rog'mar Poachers.",al={"quem me enviou","pedido de cornelius"}},{q="Quem são os Rog'mar Poachers?",a="São caçadores orcs que percorrem as Sendas do Rio em bandos.",al={"rog'mar","os poachers"}},{q="Por que os Poachers são uma ameaça?",a="Eles matam pessoas, leões e cavalos, ameaçando toda a vida nas Sendas do Rio.",al={"por que deter os poachers","perigo dos poachers"}},{q="Por onde os Poachers andam?",a="Os Rog'mar Poachers percorrem as planícies das Sendas do Rio.",al={"local dos poachers","onde estão os rog'mar"}}},fp="19,137,22.217.0,33.56.0,29.58.0,30.74.0,27.56.0"}
P.entries["quest:94925"] = {n="A Fur Trade",s="O Vigia Terral procura peles de leão para o comércio de Farholde com um negociante no Porto Detonapavio. Em troca, o assentamento recebe munições especiais.",h="O Vigia Terral procura peles de leão para o comércio de Farholde com um negociante no Porto Detonapavio.",kw={"um comércio de peles","negociante","farholde","pele de leão","porto detonapavio","prized lion hides","munições especiais","vigia terral"},sec={{t="O comércio de Farholde",b="Farholde depende do comércio para obter alguns produtos, embora valorize sua independência. O Vigia Terral diz que o assentamento organizou uma troca com um negociante no Porto Detonapavio. Farholde fornece produtos perigosos de obter, e o negociante oferece munições especiais. Agora, o negociante quer pele de leão, e Terral pede que você traga oito Prized Lion Hides do bando que vive no alto de uma grande colina no centro das planícies."}},faq={{q="Do que o Vigia Terral precisa?",a="O Vigia Terral precisa de oito Prized Lion Hides para o comércio de Farholde com um negociante no Porto Detonapavio.",al={"o que terral quer","peles para terral","pele de leão"}},{q="Com quem Farholde está negociando?",a="Farholde organizou uma troca com um negociante no Porto Detonapavio.",al={"quem é o negociante","comércio no porto detonapavio","negociante de peles"}},{q="O que Farholde recebe na troca?",a="O negociante fornece munições especiais a Farholde.",al={"para que servem as munições","munições especiais","o que o negociante fornece"}},{q="Onde estão os leões?",a="Um bando de leões vive no alto de uma grande colina no centro das planícies.",al={"colina dos leões","onde está o bando","leões nas planícies"}}},fp="11,144,18.415.0,30.101.0,29.67.0,36.54.0,20.69.0"}
P.entries["quest:94928"] = {n="A Few Furs for Friz",s="Cornelius pede que você leve peles de leão para Friz Frazzlespark, no Porto Detonapavio. A troca já foi combinada, e Friz deve receber o pacote.",h="Cornelius pede que você leve peles de leão para Friz Frazzlespark, no Porto Detonapavio.",kw={"algumas peles para friz","cornelius","friz frazzlespark","porto goblin","peles de leão","porto detonapavio"},sec={{t="Uma entrega no porto",b="No Porto Detonapavio, Friz Frazzlespark aguarda um pacote de peles de leão. Cornelius já combinou a troca. Entregue as peles a Friz e diga que vêm de Cornelius."}},faq={{q="Para quem são as peles?",a="O pacote de peles de leão é para Friz Frazzlespark, no Porto Detonapavio.",al={"quem recebe as peles","peles para friz","a quem entregar as peles"}},{q="Onde fica o Porto Detonapavio?",a="O Porto Detonapavio é um porto administrado por goblins, a nordeste.",al={"onde fica o portodetonapavio","localização do portodetonapavio","onde fica o porto goblin"}},{q="Quem enviou as peles?",a="As peles são de Cornelius.",al={"quem enviou as peles","peles de cornelius","de onde vêm"}},{q="De que animal são as peles?",a="São peles de leão.",al={"que peles","peles de leão","quais peles"}}},fp="19,137,15.183.0,22.69.0,25.54.0,19.29.0,28.20.0"}
P.entries["quest:94930"] = {n="Lost Shipping Crate",s="O caixote de carga de Friz Frazzlespark está marcado para voltar ao Porto Detonapavio, nas Sendas do Rio. A etiqueta avisa para não abri-lo sem supervisão.",h="O caixote de carga de Friz Frazzlespark está marcado para voltar ao Porto Detonapavio, nas Sendas do Rio.",kw={"etiqueta do caixote","friz frazzlespark","caixote de carga perdido","porto detonapavio","círculo vermelho no mapa","sendas do rio"},sec={{t="Um Caixote Marcado",b="Uma etiqueta escrita à mão identifica o caixote como propriedade de Friz Frazzlespark, no Porto Detonapavio. Ela avisa você para não mexer nem abrir o caixote sem supervisão. Se encontrá-lo perdido, a etiqueta indica Friz, no Porto Detonapavio, nas Sendas do Rio, como destino."}},faq={{q="Quem é o dono do caixote?",a="A etiqueta identifica Friz Frazzlespark como dono.",al={"dono do caixote","quem é friz","caixote de friz"}},{q="Para onde o caixote deve ir?",a="A etiqueta diz para devolver o caixote a Friz Frazzlespark, no Porto Detonapavio, nas Sendas do Rio.",al={"local do caixote","para onde devolver o caixote","caixote no porto detonapavio"}},{q="Posso abrir o caixote?",a="A etiqueta avisa para não abrir o caixote sem supervisão.",al={"abrir caixote","o que tem dentro","aviso do caixote"}},{q="O que o mapa no caixote mostra?",a="O mapa mostra um grande círculo vermelho numa costa a sudeste, ao norte de um templo cercado por água e de algumas criaturas aladas.",al={"mapa do caixote","círculo vermelho no mapa","o que diz a etiqueta"}}},fp="19,152,14.260.0,19.52.0,26.94.0,21.62.0,36.124.0"}
P.entries["quest:94931"] = {n="Stolen Saws",s="No moinho de madeira, Halligan Turner pede que você recupere lâminas de serra roubadas por gnolls. O moinho precisa delas de volta.",h="No moinho de madeira, Halligan Turner pede que você recupere lâminas de serra roubadas por gnolls.",kw={"colinas cerdosas","gnolls","halligan turner","serraria","lâminas de serra","southern watch","serras roubadas"},sec={{t="Lâminas desaparecidas",b="A Southern Watch mantém a maioria dos gnolls afastados, mas alguns ainda conseguem entrar no acampamento à noite e roubar lâminas de serra. Halligan Turner, no moinho de madeira, pede que você procure por elas nos acampamentos dos gnolls nas Colinas Cerdosas, onde as lâminas podem estar guardadas. O moinho de madeira precisa receber de volta o metal afiado."}},faq={{q="Quem quer as lâminas de serra de volta?",a="Halligan Turner, da serraria, quer que as lâminas de serra roubadas sejam devolvidas.",al={"quem pediu as lâminas de serra","serras de halligan turner"}},{q="De onde as lâminas de serra foram roubadas?",a="Alguns gnolls conseguem passar pela Southern Watch e se esgueiram para o acampamento madeireiro à noite para levá-las.",al={"onde os gnolls roubaram serras","onde estão as serras roubadas"}},{q="Onde os gnolls podem guardar as lâminas?",a="Os acampamentos dos gnolls nas Colinas Cerdosas são onde as lâminas podem estar escondidas.",al={"acampamentos dos gnolls com lâminas de serra","onde estão as serras"}},{q="Por que as lâminas de serra são úteis para os gnolls?",a="É provável que os gnolls usem o metal afiado para fabricar armas.",al={"o que os gnolls fazem com serras","gnolls fabricando armas"}},{q="Por que a serraria precisa das lâminas?",a="Halligan diz que a devolução das lâminas pouparia tempo e recursos à serraria.",al={"por que recuperar lâminas de serra","serraria precisa de serras"}}},fp="11,110,14.280.0,30.72.0,38.90.0,39.69.0,44.54.0,41.81.0"}
P.entries["quest:94946"] = {n="The Magical City of Dalaran",s="Um Mago em Valanaar envia você da Ilha de Zefras à Cidade de Dalaran, onde Magos aguardam a chegada do seu povo. A cidade é um ponto de partida para explorar Azeroth, mas as terras além dela são perigosas sem preparo e experiência.",h="Um Mago em Valanaar envia você da Ilha de Zefras à Cidade de Dalaran, onde Magos aguardam a chegada do seu...",kw={"culto","dalaran","cidade de dalaran","danaaris stargale","magos","cortacéu","valanaar","ilha de zefras"},ang={["race:Skyborne"]="Como Nascido dos Céus, você está viajando da Ilha de Zefras para se juntar aos Magos que aguardam a chegada do seu povo em Dalaran."},sec={{t="Chegada a Dalaran",b="Acontecimentos recentes envolvendo o culto mantiveram quem fala em Valanaar, enquanto vários Magos aguardam seu povo em Dalaran. Você é enviado ao cais, do lado de fora da hospedaria, para embarcar em um navio cortacéu rumo à Cidade de Dalaran. Ao chegar, fale com Danaaris Stargale. Seu povo ainda está se estabelecendo na cidade, e o território além de sua proteção pode ser perigoso."}},faq={{q="Quem está esperando em Dalaran?",a="Vários Magos aguardam a chegada do seu povo em Dalaran. Ao chegar, você deve falar com Danaaris Stargale.",al={"magos em dalaran","quem está em dalaran","magos de dalaran"}},{q="De onde devo partir?",a="Você viaja da Ilha de Zefras à Cidade de Dalaran a bordo do navio cortacéu que está no cais, do lado de fora da hospedaria.",al={"como chegar a dalaran","partindo de zefras","cortacéu"}},{q="Por que quem fala vai ficar em Valanaar?",a="Acontecimentos recentes envolvendo o culto mudaram os planos de quem fala, que pretende ficar em Valanaar por algum tempo.",al={"por que ficar em valanaar","culto mudou os planos","mago de valanaar"}},{q="É seguro sair de Dalaran?",a="As terras além de Dalaran podem ser perigosas sem o preparo e a experiência adequados.",al={"é seguro sair de dalaran","perigo perto de dalaran","arredores de dalaran"}}},fp="27,238,18.368.0,26.125.0,23.96.0,39.105.0,27.83.0"}
P.entries["quest:94947"] = {n="Welcome to Azeroth",s="'Welcome to Azeroth' marca a chegada de viajantes Skyborne à capital humana de Ventobravo através do Skyborne Portal. Apresentando-se na Bastilha Ventobravo, os recém-chegados recebem reconhecimento formal e permissão do Grão-lorde Bolvar Fordragon para viajar livremente por todas as terras da Aliança.",h="'Welcome to Azeroth' marca a chegada de viajantes Skyborne à capital humana de Ventobravo através do Skyborne...",kw={"bolvar fordragon","alto-elfo","alta ordem","kirin tor","portal","skyborne","bastilha ventobravo","welcome to azeroth"},ang={["faction:Alliance"]="O Grão-lorde Bolvar Fordragon recebe oficialmente a Alta Ordem em nome do Rei Anduin Wrynn, concedendo-lhes permissão para percorrer livremente as terras da Aliança.",["race:Skyborne"]="Para os Skyborne, esta audiência abre formalmente os portões de Ventobravo e do território da Aliança aos viajantes altos-elfos que chegam pelo portal."},sec={{t="Chegada à Capital",b="Chegando através do místico Skyborne Portal, os viajantes entram diretamente na movimentada capital de Ventobravo. Encarregados de se apresentar à sede da liderança humana, os recém-chegados sobem pelas grandes vias da cidade até a Bastilha Ventobravo para comparecer perante a regência."},{t="Uma Audiência com o Regente",b="De pé no grande salão do trono, o Grão-lorde Bolvar Fordragon cumprimenta os membros da Alta Ordem que chegam após aviso prévio de um mensageiro do Kirin Tor. Notando que já faz bastante tempo desde que altos-elfos caminharam pelos salões da Bastilha Ventobravo, o Regente graciosamente os aceita como convidados e lhes concede livre passagem por todos os territórios da Aliança em nome do Rei."}},faq={{q="Sobre o que é esta missão?",a="'Welcome to Azeroth' é uma missão introdutória na qual um viajante atravessa o Skyborne Portal até Ventobravo e se apresenta perante o Grão-lorde Bolvar Fordragon na Bastilha Ventobravo.",al={"o que é welcome to azeroth","missão welcome to azeroth"}},{q="Quem é Bolvar Fordragon?",a="O Grão-lorde Bolvar Fordragon atua como regente do trono de Ventobravo, governando o reino na Bastilha Ventobravo em nome do jovem Rei Anduin Wrynn enquanto o Rei Varian permanece desaparecido.",al={"quem é bolvar fordragon","regente de ventobravo"}},{q="Por que Bolvar está recebendo os Skyborne?",a="Um mensageiro do Kirin Tor alertou Bolvar Fordragon de que membros da Alta Ordem estariam chegando. Bolvar os acolhe como convidados da coroa, concedendo-lhes permissão para explorar e viajar livremente pelas terras da Aliança.",al={"por que os skyborne estão em ventobravo","altos-elfos ventobravo"}},{q="O que é a Alta Ordem?",a="A Alta Ordem representa a facção ou grupo associado aos altos-elfos Skyborne cuja chegada foi anunciada à liderança de Ventobravo pelo Kirin Tor.",al={"quem é a alta ordem","história da alta ordem"}},{q="Para onde o Skyborne Portal leva?",a="O Skyborne Portal leva os viajantes diretamente à cidade capital humana de Ventobravo, permitindo que os recém-chegados sigam direto para a Bastilha Ventobravo em busca de uma audiência com a coroa.",al={"destino do skyborne portal","para onde o portal leva"}},{q="Os Skyborne têm permissão para circular por todo o território da Aliança?",a="Bolvar Fordragon dá as boas-vindas formais aos Skyborne como convidados em nome do Rei e lhes concede explicitamente permissão para viajar sem impedimentos por todas as terras da Aliança.",al={"os skyborne são da aliança","boas-vindas aos skyborne aliança"}}},fp="18,159,22.196.0,27.336.0,25.120.0,24.159.0,37.190.0,23.130.0,36.163.0,55.129.0"}
P.entries["quest:94961"] = {n="Biting the Hand",s="Fuzzle oferece um acordo a quem o ajudar a se vingar. Ele promete mostrar um tesouro quando você lhe trouxer Twilight Finger Bones.",h="Fuzzle oferece um acordo a quem o ajudar a se vingar.",kw={"morder a mão","fuzzle","gnoll","vingança","tesouro","twilight finger bones"},sec={{t="A oferta de Fuzzle",b="Fuzzle acena com um pouco de ouro para você enquanto oferece um acordo. O gnoll promete mais tesouros se você ajudá-lo a se vingar. Ele pede que você lhe traga vinte Twilight Finger Bones antes de mostrar o que tem."}},faq={{q="Quem é Fuzzle?",a="Fuzzle é um gnoll que oferece ouro e promete tesouros em troca de ajuda para se vingar.",al={"fuzzle","gnoll com ouro"}},{q="O que Fuzzle quer?",a="Fuzzle pede que você lhe traga vinte Twilight Finger Bones para ajudá-lo a se vingar.",al={"o que ele quer","vingança de fuzzle"}},{q="Para que servem os Twilight Finger Bones?",a="Fuzzle quer vinte Twilight Finger Bones antes de mostrar o tesouro.",al={"ossos de dedos","ossos crepusculares"}}},fp="15,131,14.206.0,14.97.0,22.82.0,39.75.0"}
P.entries["quest:94962"] = {n="Bloodmaster's Ring",s="Uma luta contra Bonegnaw é o próximo combate rumo ao título de campeão no Bloodmaster's Ring. Os ogros esperam para ver se você lhes dará uma batalha que valha a pena assistir.",h="Uma luta contra Bonegnaw é o próximo combate rumo ao título de campeão no Bloodmaster's Ring.",kw={"bloodmaster","bloodmaster's ring","bonegnaw","combate","campeão","luta","ogros"},sec={{t="O Próximo Combate",b="Suas vitórias ainda não fizeram de você um campeão, e o goblin do ringue já tem outra batalha em mente. Bonegnaw será seu oponente, e o goblin promete uma surpresa. Os ogros estão assistindo, e a próxima luta deve diverti-los."},{t="Depois da Luta",b="O goblin está insatisfeito com a forma como a luta o retrata. Os ogros, porém, parecem entretidos, e ele alerta você para não se orgulhar do resultado."}},faq={{q="Quem é meu oponente?",a="Bonegnaw é seu oponente no Bloodmaster's Ring.",al={"luta com bonegnaw","com quem eu luto"}},{q="Já sou campeão?",a="O goblin do ringue diz que suas vitórias ainda não fizeram de você um campeão.",al={"campeão bloodmaster","tornar-se campeão"}},{q="Quem está assistindo à luta?",a="Ogro está assistindo ao combate no Bloodmaster's Ring.",al={"ogros assistindo","quem está entretido"}}},fp="18,170,13.226.0,15.151.1,19.52.0,20.66.0,26.54.0"}
P.entries["quest:94963"] = {n="Biting the Hand",s="Fuzzle pede que você fuja com ele e promete uma recompensa quando estiverem a salvo. Ele rosna, ameaçando qualquer um que tente persegui-los.",h="Fuzzle pede que você fuja com ele e promete uma recompensa quando estiverem a salvo.",kw={"mordendo a mão","fuzzle","gnoll","ouro","partir","recompensa","a salvo"},sec={{t="Fugindo com Fuzzle",b="Fuzzle está pronto para partir e pede que você vá com ele. Ele avisa que vai despedaçar qualquer um que tente impedi-los. Sua segurança vem primeiro; ele promete uma recompensa quando vocês estiverem a salvo."}},faq={{q="Quem está me pedindo para partir?",a="Fuzzle pede que você fuja com ele.",al={"quem é fuzzle","fuzzle?","quem quer partir"}},{q="O que Fuzzle ameaça fazer?",a="Fuzzle ameaça despedaçar qualquer um que tente impedi-los.",al={"o que fuzzle diz","ameaça de fuzzle","quem ele vai atacar"}},{q="Quando Fuzzle vai me dar uma recompensa?",a="Fuzzle diz que vai dar uma recompensa a você quando estiver a salvo.",al={"recompensa de fuzzle","quando vem a recompensa","o que ele promete"}},{q="Qual é a recompensa?",a="Fuzzle juntou uma boa quantia em ouro, que agora será sua.",al={"o que vou receber","ouro de fuzzle","recompensa de fuzzle"}}},fp="15,125,19.190.0,26.34.0,26.60.0,34.56.0,19.60.0"}
P.entries["quest:94964"] = {n="Bloodmaster's Ring",s="Um locutor de ringue chama você para enfrentar Mog’thar no Bloodmaster’s Ring. A plateia espera o próximo desafiante.",h="Um locutor de ringue chama você para enfrentar Mog’thar no Bloodmaster’s Ring.",kw={"locutor","bloodmaster’s ring","desafiante","plateia","mog’thar","ringue"},sec={{t="O próximo desafiante",b="O locutor manteve a plateia animada e agora apresenta Mog’thar como o próximo desafiante. Você é chamado ao Bloodmaster’s Ring, enquanto a plateia espera para ver o que acontece."}},faq={{q="Quem vou enfrentar no Bloodmaster’s Ring?",a="Você é chamado para enfrentar Mog’thar no Bloodmaster’s Ring.",al={"luta contra mog’thar","quem é o próximo desafiante","oponente no bloodmaster’s ring"}},{q="O que o locutor diz sobre Mog’thar?",a="O locutor diz que Mog’thar não é brincadeira.",al={"quem é mog’thar","próximo desafiante","mog’thar é brincadeira"}},{q="Por que estão me mandando para o ringue?",a="O locutor quer manter a empolgação da plateia apresentando outro desafiante.",al={"por que lutar contra mog’thar","motivo da luta no ringue","o que o locutor quer"}}},fp="18,123,18.181.0,42.62.0,45.41.0,34.91.0"}
P.entries["quest:94965"] = {n="Bloodmaster's Ring",s="O goblin Jezap pede que você prove seu valor aos ogros enfrentando Snufflesnout no Bloodmaster's Ring. O petisco favorito dela vai atraí-la para a luta, embora Chub'chob talvez não goste do resultado.",h="O goblin Jezap pede que você prove seu valor aos ogros enfrentando Snufflesnout no Bloodmaster's Ring.",kw={"ringue do bloodmaster","chub'chob","ogros","snufflesnout","petisco"},sec={{t="Um teste para você",b="Jezap deixa um petisco à sua espera antes de você entrar no Bloodmaster's Ring. Snufflesnout gosta muito dele, e só de vê-lo ela se anima. Sua prova é enfrentar a companheira de Chub'chob enquanto demonstra seu valor aos ogros."},{t="Depois da luta",b="A companheira de Chub'chob é Snufflesnout, e derrotá-la deixa uma situação complicada entre você e os ogros. Tenha cuidado com eles agora."}},faq={{q="Quem é Snufflesnout?",a="Snufflesnout é a companheira de Chub'chob e gosta muito de um petisco específico.",al={"snufflesnout","focinho farejador","animal de estimação de chubchob"}},{q="Para que serve o petisco?",a="Jezap usa o petisco favorito de Snufflesnout para atraí-la ao Bloodmaster's Ring.",al={"petisco de snufflesnout","para que serve o petisco","alimentar snufflesnout"}},{q="O que é o Bloodmaster's Ring?",a="É o ringue onde você enfrenta Snufflesnout para provar seu valor aos ogros.",al={"ringue do bloodmaster","o ringue","onde lutar contra snufflesnout"}},{q="Por que estou lutando contra Snufflesnout?",a="Jezap diz que provar seu valor aos ogros é o mais importante, e que enfrentar Snufflesnout é sua prova.",al={"luta contra snufflesnout","por que lutar contra ela","provar meu valor aos ogros"}}},fp="18,207,14.204.0,15.124.1,20.72.0,21.81.0,31.74.0,31.98.0"}
P.entries["quest:94968"] = {n="Eye of Mugg",s="Krom'rosh envia você à Fortaleza de Krol'Dok, onde a presença do culto do Crepúsculo é maior do que o esperado. Ele pede uma prova da morte do líder.",h="Krom'rosh envia você à Fortaleza de Krol'Dok, onde a presença do culto do Crepúsculo é maior do que o...",kw={"caverna","líder do culto","eye of mugg","fortaleza de krol'dok","krom'rosh","sacrifícios","culto do crepúsculo"},sec={{t="Fortaleza de Krol'Dok",b="Krom'rosh teme que mais aliados sejam sacrificados se o culto do Crepúsculo continuar devastando estas terras. Poucos sobreviveram à entrada na caverna, e a presença do culto é maior do que ele imaginava. Agora, você deve entrar na Fortaleza de Krol'Dok e voltar com uma prova da morte do líder."}},faq={{q="Quem está me pedindo para entrar na Fortaleza de Krol'Dok?",a="Krom'rosh envia você à Fortaleza de Krol'Dok para trazer uma prova de que o líder do culto do Crepúsculo está morto.",al={"quem me enviou","pedido de krom'rosh"}},{q="O que está acontecendo na fortaleza?",a="O culto do Crepúsculo tem uma presença maior do que Krom'rosh esperava e vem devastando as terras e sacrificando aliados.",al={"o que está acontecendo lá","problema com o culto do crepúsculo"}},{q="Por que Krom'rosh quer que eu entre?",a="Krom'rosh quer deter o culto antes que ele continue devastando as terras e sacrificando aliados.",al={"por que entrar","por que entrar na fortaleza"}},{q="Que prova Krom'rosh está pedindo?",a="Ele pede uma prova de que o líder do culto do Crepúsculo está morto.",al={"prova necessária","o que devo trazer de volta"}},{q="Muitos dos que entraram na caverna sobreviveram?",a="Poucos dos que conseguiram entrar na caverna sobreviveram.",al={"sobreviventes da caverna","quem conseguiu sair"}}},fp="11,150,19.268.0,46.105.0,32.119.0,36.98.0,34.58.0,38.43.0"}
P.entries["quest:94971"] = {n="A Paladin's Steed",s="O cavalo de guerra do paladino leva seu cavaleiro e suas armas para a batalha. Danitha Morr pode ensinar você a invocar um.",h="O cavalo de guerra do paladino leva seu cavaleiro e suas armas para a batalha.",kw={"consagrado","danitha morr","montaria","paladino","cavalo","invocar","cavalo de guerra"},ang={["class:Paladin"]="Como paladino, você pode invocar um cavalo de guerra especialmente consagrado para levar você e suas armas para a batalha."},sec={{t="Um Cavalo de Guerra para a Batalha",b="Há muito tempo, paladinos cavalgam para a batalha em cavalos de guerra especialmente consagrados, levando seus cavaleiros e armas. Danitha Morr pode ensinar você a invocar sua própria montaria, para que cavalgue para a batalha com ela ao seu lado."}},faq={{q="O que é a montaria de um paladino?",a="É um cavalo de guerra especialmente consagrado que leva um paladino e suas armas para a batalha.",al={"cavalo de paladino","cavalo de guerra","montaria de paladino"}},{q="Quem me ensina a invocar um cavalo de guerra?",a="Danitha Morr ensina você a invocar seu cavalo de guerra.",al={"danitha morr","invocar cavalo de guerra","obter montaria de paladino"}},{q="Por que paladinos precisam de um cavalo de guerra?",a="Um cavalo de guerra leva um paladino e suas armas para a batalha.",al={"por que cavalo de paladino","para que serve a montaria"}}},fp="17,114,21.211.0,28.89.0,36.49.0,32.54.0"}
P.entries["quest:94972"] = {n="Tome of Twilight",s="Na Fortaleza de Krol'Dok, pedem que você recupere o Tome of Twilight. O conteúdo dele pode ajudar na luta contra os cultistas.",h="Na Fortaleza de Krol'Dok, pedem que você recupere o Tome of Twilight.",kw={"cultistas","informações","fortaleza de krol'dok","segredos","tome of twilight"},sec={{t="Um Registro Oculto",b="Os segredos da fortaleza podem conter conhecimentos úteis sobre os cultistas. Pedem que você vasculhe a Fortaleza de Krol'Dok e recupere o Tome of Twilight para que suas informações possam ser levadas de volta."}},faq={{q="O que devo procurar?",a="Pedem que você recupere o Tome of Twilight na Fortaleza de Krol'Dok.",al={"tome of twilight","que tomo","qual livro"}},{q="Por que o tomo é importante?",a="O tomo pode conter informações úteis na luta contra os cultistas.",al={"por que pegar o tomo","para que serve","informações sobre cultistas"}},{q="Onde está o Tome of Twilight?",a="O Tome of Twilight deve ser recuperado na Fortaleza de Krol'Dok.",al={"onde está o tomo","tomo de kroldok","livro da fortaleza"}}},fp="16,123,15.190.0,22.71.0,25.74.0,30.65.0"}
P.entries["quest:94973"] = {n="Krol'dok Moulding",s="Um molde encontrado perto de Rog'mar parece fazer parte de uma chave. Alguém no assentamento talvez saiba o que ele abre.",h="Um molde encontrado perto de Rog'mar parece fazer parte de uma chave.",kw={"chave","krol'dok moulding","molde","rog'mar","fortaleza"},sec={{t="Um molde curioso",b="Você tem um molde que parece feito para uma chave. Em Rog'mar, alguém talvez saiba para que serve essa peça. Se veio da fortaleza, pode ser importante."}},faq={{q="Para que serve o molde?",a="O molde parece ser para uma chave.",al={"peça de molde","o que é este molde","molde de chave"}},{q="Quem pode identificar o molde?",a="Alguém em Rog'mar talvez saiba algo sobre o molde.",al={"quem sabe sobre o molde","perguntar sobre o molde","onde levar o molde"}},{q="Por que isso pode ser importante?",a="Se o molde veio da fortaleza, deve ser importante.",al={"o molde é importante","molde da fortaleza","por que se importar com o molde"}}},fp="17,108,15.151.0,25.37.0,30.44.0,20.61.0"}
P.entries["quest:94974"] = {n="Key Ingredients",s="Kreza Darkthorn precisa de couro e ferro para moldar uma chave. Você reúne os materiais enquanto ela mantém as brasas quentes.",h="Kreza Darkthorn precisa de couro e ferro para moldar uma chave.",kw={"brasas","iron bar","chave","ingredientes da chave","kreza darkthorn","moldagem","thick leather"},sec={{t="Materiais para a moldagem",b="Kreza Darkthorn tem uma moldagem gasta que pode ser usada para fazer uma chave. Você leva a ela quatro Thick Leather e doze Iron Bar enquanto ela mantém as brasas quentes. A moldagem deve aguentar, e Kreza está pronta para ver o que pode ser feito."}},faq={{q="Do que Kreza precisa?",a="Kreza pede que você traga quatro Thick Leather e doze Iron Bar.",al={"quais materiais","ingredientes da chave","do que kreza precisa"}},{q="Para que servem os materiais?",a="Os materiais servem para fazer uma chave usando uma moldagem rudimentar e gasta.",al={"por que couro e ferro","chave para quê","materiais para a moldagem"}},{q="Quem está mantendo as brasas quentes?",a="Kreza Darkthorn diz que manterá as brasas quentes enquanto você reúne os materiais.",al={"quem cuida das brasas","brasas de kreza","brasas quentes"}},{q="O que Kreza diz sobre a moldagem?",a="Kreza diz que a moldagem é rudimentar e gasta, mas ainda pode ser usada para fazer uma chave.",al={"estado da moldagem","a moldagem ainda serve","molde de chave"}}},fp="15,115,26.225.0,21.63.0,27.67.0,30.81.0,39.82.0"}
P.entries["quest:94975"] = {n="A Token of Vengeance",s="Um aliado pede que você encontre o Twilight’s Hammer, escondido em uma rede de cavernas perto da Fortaleza de Krol'Dok. Seus ataques feriram seus aliados e ameaçam a região.",h="Um aliado pede que você encontre o Twilight’s Hammer, escondido em uma rede de cavernas perto da Fortaleza de...",kw={"um símbolo de vingança","orelhas de cultista","cultistas","caverna escondida","fortaleza de krol'dok","twilight's hammer"},sec={{t="As cavernas ocultas",b="Os batedores relataram que cultistas do Twilight’s Hammer estão se movendo sob o terreno acidentado perto da Fortaleza de Krol'Dok. Seu aliado diz que os ataques deles causaram grande sofrimento aos seus aliados e que os cultistas estão reivindicando a região. Você deve encontrar o esconderijo deles e trazer de volta quinze orelhas de cultista como mensagem de vingança."}},faq={{q="Quem estou procurando?",a="Você está procurando cultistas do Twilight’s Hammer escondidos em uma rede de cavernas perto da Fortaleza de Krol'Dok.",al={"quem são os cultistas","twilight hammer aqui","orelhas de cultista"}},{q="Por que os cultistas estão sendo caçados?",a="Quem oferece a missão diz que os cultistas causaram sofrimento aos seus aliados e estão reivindicando a região.",al={"por que vingança","por que lutar contra eles","o que eles fizeram"}},{q="O que os batedores sabem?",a="Os batedores relataram movimentação de cultistas sob o terreno acidentado, em uma rede de cavernas escondida ao norte.",al={"relato dos batedores","onde estão os cultistas","movimentação dos cultistas"}},{q="O que devo trazer de volta?",a="Você deve coletar quinze Cultist Ears dos membros do Twilight’s Hammer na Fortaleza de Krol'Dok.",al={"o que devo coletar","missão das orelhas","quantas orelhas"}}},fp="20,158,16.328.0,21.99.0,34.90.0,24.99.0,30.98.0"}
P.entries["quest:94978"] = {n="Taming the Beast",s="Quel'ana Quickgale ensina a você o vínculo entre fera e mestre. Seu primeiro desafio é adestrar um Windsong Crawler perto das águas de Zephras.",h="Quel'ana Quickgale ensina a você o vínculo entre fera e mestre.",kw={"adestramento de feras","quel'ana quickgale","bastão de adestramento","taming the beast","valanaar","windsong crawler","zephras"},sec={{t="Primeiro vínculo",b="Você começa com o Bastão de Adestramento e um Windsong Crawler. Adestre um perto de um corpo d'água, pratique suas habilidades e depois devolva o bastão a Quel'ana Quickgale em Valanaar. Por enquanto, seu caminho rumo à maestria começa com essa criatura."}},faq={{q="O que Quel'ana me pede para adestrar?",a="Quel'ana pede a você que adestre um Windsong Crawler perto de um corpo d'água em Zephras.",al={"qual fera","alvo do adestramento","missão do crawler"}},{q="Para que serve o Bastão de Adestramento?",a="O Bastão de Adestramento é usado para adestrar um Windsong Crawler.",al={"como funciona o bastão","ferramenta de adestramento","missão do bastão"}},{q="Onde encontro um Windsong Crawler?",a="Windsong Crawlers são encontrados perto de corpos d'água em Zephras.",al={"localização do crawler","onde encontrar crawler","fera de zephras"}},{q="Quem me deu o Bastão de Adestramento?",a="Quel'ana Quickgale, em Valanaar, dá a você o Bastão de Adestramento.",al={"doador da missão","quem é quelana","quelana quickgale"}},{q="Por que estou aprendendo a adestrar uma fera?",a="Aprender o vínculo entre fera e mestre é o primeiro passo rumo à maestria da sua classe.",al={"por que adestrar crawler","maestria das feras","primeiro adestramento"}}},fp="16,132,10.215.0,34.77.0,27.50.0,35.55.0,27.56.0,34.90.0"}
P.entries["quest:94979"] = {n="Taming the Beast",s="Quel'ana Quickgale pede que você adestre um galestrider nos Baixios dos Lufopomos. Sua habilidade em terreno aberto vai prepará-lo para as provações que virão.",h="Quel'ana Quickgale pede que você adestre um galestrider nos Baixios dos Lufopomos.",kw={"galestrider","baixios dos lufopomos","ornery galestrider","quel'ana quickgale","bastão de adestramento","taming the beast","valanaar","zephras"},sec={{t="Pelas planícies",b="Você já mostrou que consegue adestrar o rastejante do rio. Quel'ana Quickgale agora lhe entrega um Bastão de Adestramento e pede que procure um galestrider nos baixios de Zephras. A orgulhosa criatura alada corre veloz pelas planícies. Conquiste sua confiança, pratique sua habilidade e devolva o bastão a Quel'ana em Valanaar."}},faq={{q="O que Quel'ana quer que eu adestre?",a="Quel'ana pede que você adestre um Ornery Galestrider nos Baixios dos Lufopomos.",al={"adestrar o quê","adestrar galestrider","que fera"}},{q="Onde encontro o galestrider?",a="O Ornery Galestrider fica nos Baixios dos Lufopomos, nas planícies de Zephras.",al={"onde fica o galestrider","localização do galestrider","onde ficam os baixios"}},{q="Para que serve o Bastão de Adestramento?",a="Quel'ana lhe entrega o Bastão de Adestramento para adestrar um Ornery Galestrider.",al={"uso do bastão de adestramento","para que serve o bastão","como adestrar uma fera"}},{q="Quem me deu esta missão?",a="Quel'ana Quickgale, de Valanaar, pede que você adestre um Ornery Galestrider e devolva o Bastão de Adestramento.",al={"quem me enviou","quem é quel'ana","quickgale"}}},fp="16,138,17.298.0,35.74.0,32.88.0,27.72.0,28.100.0"}
P.entries["quest:94980"] = {n="Krol'dok Moulding",s="O Krol'dok moulding parece ser de uma chave. Alguém na Bastilha de Ermoforte pode saber mais sobre ele.",h="O Krol'dok moulding parece ser de uma chave.",kw={"bastilha de ermoforte","chave","molde de krol'dok","molde"},sec={{t="Molde de chave",b="Você tem um molde que parece ser de uma chave. Alguém na Bastilha de Ermoforte talvez saiba para que serve, e você o leva até lá para descobrir mais."}},faq={{q="O que é o Krol'dok moulding?",a="O Krol'dok moulding parece ser de uma chave.",al={"molde de kroldok","molde de krol'dok","o que é este molde"}},{q="Quem pode saber sobre o molde?",a="Alguém na Bastilha de Ermoforte talvez saiba sobre o molde.",al={"quem sabe sobre o molde","especialista em moldes","perguntar sobre o molde"}},{q="O que acontece quando levo o molde?",a="A pessoa a quem você o leva diz que vai ver o que pode ser feito com ele.",al={"resultado do molde","o que dizem","molde de chave"}}},fp="17,107,13.146.0,30.46.0,31.50.0,39.71.0"}
P.entries["quest:94981"] = {n="Key Ingredients",s="Alphonse Dumas precisa de materiais para fazer uma chave a partir de um molde rudimentar. Você deve levar Thick Leather e Iron Bars para ele.",h="Alphonse Dumas precisa de materiais para fazer uma chave a partir de um molde rudimentar.",kw={"alphonse dumas","brasas","barras de ferro","chave","ingredientes da chave","molde","couro grosso"},sec={{t="Materiais para a Chave",b="Alphonse Dumas mantém as brasas quentes enquanto você reúne o que ele precisa. O molde é rudimentar, mas os materiais certos podem ajudá-lo a fazer uma chave."}},faq={{q="Do que Alphonse precisa?",a="Alphonse Dumas pede que você leve quatro Thick Leather e doze Iron Bars.",al={"materiais necessários","o que levar","ingredientes da chave"}},{q="O que Alphonse está fazendo?",a="Alphonse espera fazer uma chave a partir de um molde rudimentar usando os materiais certos.",al={"o que ele está fabricando","para que serve a chave","molde da chave"}},{q="Onde levo os materiais?",a="Leve Thick Leather e Iron Bars para Alphonse Dumas.",al={"quem recebe os ingredientes","para quem levar os materiais"}}},fp="15,126,21.141.0,24.73.0,24.80.0,30.56.0"}
P.entries["quest:94982"] = {n="Eye of Mugg",s="Commander Brant pede que você encontre a presença do Twilight na Fortaleza de Krol'Dok e traga provas da morte de seu líder. As cavernas representam uma ameaça aos esforços para expulsar o Twilight destas terras.",h="Commander Brant pede que você encontre a presença do Twilight na Fortaleza de Krol'Dok e traga provas da...",kw={"cavernas","commander brant","eye of mugg","fortaleza de krol'dok","batedores desaparecidos","montanhas","twilight"},sec={{t="As cavernas escondidas",b="Commander Brant soube que batedores encontraram cavernas a noroeste, ao longo das montanhas, escondidas pela paisagem natural. Muitos que entraram para descobrir mais não voltaram, e Brant teme que estejam perdidos. Observadores também viram figuras do Twilight entrando e saindo das cavernas durante a noite. Você deve localizar a fortaleza e voltar com provas da morte de seu líder."}},faq={{q="Quem me envia à Fortaleza de Krol'Dok?",a="Commander Brant pede que você localize a fortaleza do Twilight e volte com provas da morte de seu líder.",al={"quem é commander brant","brant me enviou","quem me deu esta missão"}},{q="Onde fica a Fortaleza de Krol'Dok?",a="As cavernas ficam a noroeste, ao longo das montanhas, escondidas pela paisagem natural.",al={"onde fica krol'dok","localização de krol'dok","onde ficam as cavernas"}},{q="Por que Commander Brant está preocupado com as cavernas?",a="Muitos que entraram nas cavernas em busca de informações não voltaram, e Brant teme que estejam perdidos.",al={"por que encontrar as cavernas","o que está acontecendo lá","batedores desaparecidos"}},{q="Quem foi visto perto das cavernas?",a="Observadores relataram uma presença do Twilight entrando e saindo das cavernas, muitas vezes durante a noite.",al={"twilight nas cavernas","quem está em krol'dok","presença do twilight"}},{q="O que Brant me pede para trazer?",a="Brant pede que você volte com provas de que o líder da fortaleza está morto.",al={"que prova preciso trazer","prova sobre o líder","o que trazer de volta"}}},fp="11,196,16.376.0,36.103.0,29.76.0,49.101.0,33.93.0,37.73.0"}
P.entries["quest:94983"] = {n="Twilight Mementos",s="O sargento Riftan envia você ao norte, à Fortaleza de Krol'Dok, após batedores confirmarem um esconderijo do Martelo do Crepúsculo. Ele pede que você traga provas da derrota dos cultistas.",h="O sargento Riftan envia você ao norte, à Fortaleza de Krol'Dok, após batedores confirmarem um esconderijo do...",kw={"caverna","braceletes dos cultistas","esconderijo dos cultistas","fortaleza de krol'dok","batedores","sargento riftan","lembranças do crepúsculo","martelo do crepúsculo"},sec={{t="Relatos dos Batedores",b="Os batedores trouxeram relatos preocupantes ao sargento Riftan sobre um esconderijo de cultistas. Seus relatos confirmam o que outros disseram. Há uma caverna ao norte, escondida pelos arredores, e Riftan acredita que ela serve de base para o culto nas profundezas das montanhas. Ele envia você à Fortaleza de Krol'Dok para trazer provas de que os cultistas do Martelo do Crepúsculo foram derrotados."}},faq={{q="Quem está me enviando ao norte?",a="O sargento Riftan pede que você procure os cultistas do Martelo do Crepúsculo na Fortaleza de Krol'Dok e volte com provas da derrota deles.",al={"quem me enviou","sargento riftan"}},{q="O que os batedores encontraram?",a="Os relatos dos batedores confirmaram as informações sobre um esconderijo de cultistas, com uma caverna escondida ao norte.",al={"relato dos batedores","o que descobriram"}},{q="Onde fica o esconderijo?",a="O esconderijo fica numa caverna ao norte, oculta pelos arredores. Riftan acredita que ela serve de base nas profundezas das montanhas.",al={"caverna dos cultistas","onde estão os cultistas"}},{q="Que provas Riftan quer?",a="Riftan pede que você traga provas de que os cultistas na Fortaleza de Krol'Dok foram derrotados.",al={"quais provas","provas dos cultistas"}},{q="Quem são os cultistas?",a="Eles são membros do Martelo do Crepúsculo, cujo esconderijo foi confirmado pelos relatos dos batedores.",al={"culto do crepúsculo","martelo do crepúsculo"}}},fp="17,161,15.350.0,29.129.0,25.96.0,21.125.0,28.96.0,21.99.0"}
P.entries["quest:94984"] = {n="Tome of Twilight",s="As forças do Crepúsculo persistem, e uma pista aponta para o norte de Solclaro. Pedem que você encontre Nar'gurk e recupere informações da fortaleza dele.",h="As forças do Crepúsculo persistem, e uma pista aponta para o norte de Solclaro.",kw={"fortaleza de krol'dok","nar'gurk","shadow magic","solclaro","tome of twilight","crepúsculo","forças do crepúsculo"},sec={{t="Uma Trilha ao Norte",b="As forças do Crepúsculo ainda vêm de algum lugar desconhecido, então enviam você à Fortaleza de Krol'Dok. Uma criatura do Crepúsculo mencionou Shadow Magic e um ogro chamado Nar'gurk por lá. Pedem que você o mate e recupere qualquer informação valiosa que possa explicar de onde vêm essas forças."}},faq={{q="O que estou procurando?",a="Você está procurando Nar'gurk na Fortaleza de Krol'Dok e qualquer informação valiosa que encontrar por lá.",al={"nar gurk","informações do tomo","fortaleza do crepúsculo"}},{q="Onde fica a Fortaleza de Krol'Dok?",a="A Fortaleza de Krol'Dok fica ao norte de Solclaro.",al={"onde fica a fortaleza","localização da fortaleza de krol'dok"}},{q="Por que estou procurando Nar'gurk?",a="Uma criatura do Crepúsculo mencionou Nar'gurk e Shadow Magic quando perguntaram de onde vinham seus antigos mestres.",al={"por que nar'gurk","pista do crepúsculo"}},{q="Que informações podem estar lá?",a="As informações procuradas podem ajudar a explicar de onde vêm as persistentes forças do Crepúsculo.",al={"quais informações","informações de tome of twilight"}}},fp="16,143,13.279.0,22.87.0,29.43.0,30.109.0,32.93.0"}
P.entries["quest:94992"] = {n="Rescue Roundup",s="Uma égua perdida chamada Biscuit cutuca você, pronta para seguir você de volta a Wheeler's Grange. A volta dela significa que a propriedade voltou a funcionar.",h="Uma égua perdida chamada Biscuit cutuca você, pronta para seguir você de volta a Wheeler's Grange.",kw={"biscuit","demar","égua","égua perdida","resgate em grupo","companheiras de estábulo","wheeler's grange"},sec={{t="Biscuit volta",b="O cavalo perdido de Wheeler se chama Biscuit, e ela abaixa a cabeça antes de cutucar seu braço. Você a leva de volta a Wheeler's Grange. Wheeler agradece por ter Biscuit em casa, embora ela fique sozinha por um tempo. A propriedade voltou a funcionar."}},faq={{q="Quem é Biscuit?",a="Biscuit é a égua de Wheeler, que se perdeu e precisa ser levada de volta a Wheeler's Grange.",al={"égua biscuit","égua perdida","quem é biscuit"}},{q="Para onde Biscuit precisa ir?",a="Biscuit precisa ser levada de volta a Wheeler's Grange.",al={"onde levar a égua","localização de biscuit","destino da égua"}},{q="Por que Wheeler agradece?",a="Wheeler agradece porque você leva Biscuit de volta à fazenda.",al={"por que agradece","biscuit resgatada","agradecimento de wheeler"}},{q="Biscuit está sozinha?",a="Wheeler diz que Biscuit ficará sozinha por um tempo e espera encontrar algumas companheiras de estábulo dela.",al={"biscuit sozinha","onde estão as companheiras de estábulo","outras éguas"}},{q="Wheeler's Grange está aberta?",a="Com Biscuit de volta, Wheeler's Grange voltou a funcionar.",al={"fazenda aberta","negócio de wheeler","fazenda reaberta"}}},fp="14,133,15.248.0,15.95.0,30.53.0,24.65.0,17.90.0,25.56.0"}
P.entries["quest:94997"] = {n="Lingering Essence",s="Riftan pede que você leve uma bolsa de lembranças amaldiçoadas para Ashe Amberhall, na Bastilha de Ermoforte. Ele espera que os estudos dela revelem as energias contidas nos objetos.",h="Riftan pede que você leve uma bolsa de lembranças amaldiçoadas para Ashe Amberhall, na Bastilha de Ermoforte.",kw={"ashe amberhall","cultistas","lembranças amaldiçoadas","energias","bastilha de ermoforte","essência persistente","riftan","satchel of cursed mementos"},sec={{t="Na Bastilha",b="Na Bastilha de Ermoforte, Ashe Amberhall recebe a bolsa e fica sabendo que Riftan a enviou. Ela diz que a longa luta dele contra os cultistas a preocupa, pois o cansaço pode estar afetando seu julgamento. Ainda assim, admite que as preocupações dele podem ter fundamento e volta sua atenção para os objetos."}},faq={{q="Quem me pediu para levar a bolsa?",a="Riftan pede que você leve a Satchel of Cursed Mementos para Ashe Amberhall.",al={"quem me enviou","bolsa de riftan","quem é riftan"}},{q="Quem é Ashe Amberhall?",a="Ashe Amberhall é uma estudiosa respeitada, e sua área de estudo pode ajudá-la a examinar as energias dos objetos.",al={"ashe quem","quem é ashe","amberhall"}},{q="Onde devo levar as lembranças?",a="Leve a Satchel of Cursed Mementos para Ashe Amberhall, na Bastilha de Ermoforte.",al={"onde levar a bolsa","bastilha de ermoforte","destino da bolsa"}},{q="O que há na bolsa?",a="A bolsa contém lembranças amaldiçoadas, e Riftan quer que Ashe examine as energias que elas contêm.",al={"o que tem na bolsa","lembranças amaldiçoadas","conteúdo da bolsa"}},{q="Por que Riftan quer que Ashe as examine?",a="Riftan espera que os estudos de Ashe revelem quais energias estão contidas nos objetos.",al={"por que ashe","para que serve a bolsa","essência persistente"}},{q="O que Ashe pensa da preocupação de Riftan?",a="Ashe teme que o cansaço da longa luta de Riftan contra os cultistas esteja afetando seu julgamento, embora diga que as preocupações dele podem ter fundamento.",al={"ashe confia em riftan","riftan cansado","opinião de ashe"}}},fp="17,153,11.279.0,38.73.0,22.108.0,29.72.0,23.95.0,42.86.0,41.132.0"}
P.entries["quest:94998"] = {n="Curios of Curiosity",s="Você leva uma bolsa com lembranças incomuns para Melanie Sable. O fino trabalho artesanal talvez as torne úteis.",h="Você leva uma bolsa com lembranças incomuns para Melanie Sable.",kw={"trabalho artesanal","curiosidades peculiares","melanie sable","lembranças","vestígios","bolsa com lembranças"},sec={{t="Uma bolsa para Melanie",b="Alguém que examinou as lembranças manda você levar a bolsa para Melanie Sable. A pessoa acredita que os objetos são seguros, embora sua origem continue desconhecida. O trabalho artesanal deles é incomum, e Melanie talvez encontre uma utilidade para eles."}},faq={{q="A quem devo levar as lembranças?",a="Leve a bolsa com as lembranças para Melanie Sable, como pede a pessoa que as examinou.",al={"onde levar a bolsa","quem é melanie sable"}},{q="O que são as lembranças?",a="São vestígios de alguma coisa, mas a pessoa que os examinou não sabe exatamente do quê.",al={"o que há na bolsa","o que são essas curiosidades"}},{q="Por que as lembranças são incomuns?",a="Dizem que o trabalho artesanal delas é bastante singular e intrincado.",al={"o que elas têm de especial","trabalho artesanal das curiosidades"}},{q="As lembranças são seguras?",a="A pessoa que as examinou pede que você diga a Melanie que as lembranças são seguras.",al={"a bolsa é segura","elas são perigosas"}}},fp="19,104,21.217.0,34.68.0,22.76.0,29.63.0,22.65.0"}
P.entries["quest:94999"] = {n="Eyes for the Watchman",s="Eleanor pede que você leve um pacote de cuidados ao Vigia Fredericks, em Southern Watch. Os afazeres no rancho a impedem de entregá-lo pessoalmente.",h="Eleanor pede que você leve um pacote de cuidados ao Vigia Fredericks, em Southern Watch.",kw={"pacote de cuidados","eleanor","patrulha","rancho","southern watch","vigia fredericks"},sec={{t="Um presente para Fredericks",b="O Vigia Fredericks patrulha perto do rancho de Eleanor, e ela preparou um pequeno presente para ele. Como precisa cuidar do irmão mais novo e do rancho, ela pede que você o leve a Southern Watch, a oeste de sua casa."}},faq={{q="Para quem é o pacote?",a="O pacote de cuidados de Eleanor é para o Vigia Fredericks, que está destacado em Southern Watch.",al={"quem recebe","pacote para quem"}},{q="Por que Eleanor não pode entregá-lo pessoalmente?",a="Eleanor precisa cuidar do irmão mais novo e do rancho.",al={"por que eleanor não","por que ela não pode ir"}},{q="Onde está o Vigia Fredericks?",a="O Vigia Fredericks está destacado em Southern Watch, a oeste do rancho de Eleanor.",al={"onde fica fredericks","localização de southern watch"}},{q="Por que Eleanor preparou um presente?",a="Fredericks às vezes patrulha perto do rancho, e Eleanor quer demonstrar sua gratidão.",al={"por que o pacote","para que serve"}},{q="Como Fredericks reage ao pacote?",a="Fredericks agradece a você por entregar o presente de Eleanor e diz que retribuirá o favor algum dia.",al={"reação de fredericks","ele gostou"}}},fp="21,135,21.202.0,23.85.0,37.64.0,28.75.0,31.88.0,41.95.0"}
P.entries["quest:95"] = {n="A vingança de Noel",s="Movido pela dor e pelo desejo de vingança, o eremita Noel pede aos viajantes que retornem à sua fazenda em ruínas, no sul da Floresta do Crepúsculo. Após passar anos perseguindo os cavalgantes sombrios que mataram sua família, ele se lembra de uma figura suspeita que enterrou algo perto do celeiro. Talvez isso traga respostas.",h="Movido pela dor e pelo desejo de vingança, o eremita Noel pede aos viajantes que retornem à sua fazenda em...",kw={"cavalgantes negros","trilha do vento morto","floresta do crepúsculo","monte de terra solta","toco","noel","a vingança de noel","fazenda dos noel"},ang={["class:Paladin"]="O massacre de inocentes por forças sinistras vindas da Trilha do Vento Morto exige justiça e uma punição merecida pelos mortos.",["faction:Alliance"]="O massacre da família Noel é mais um sinal do isolamento da Floresta do Crepúsculo, mostrando até onde as forças sombrias chegam sem patrulhas regulares do exército de Ventobravo."},sec={{t="Tragédia na fazenda",b="Noel era um simples fazendeiro que trabalhava nos campos do sudeste da Floresta do Crepúsculo. Sua vida foi destruída quando cavaleiros encapuzados vindos da Trilha do Vento Morto atacaram sua propriedade e massacraram sua família enquanto ele estava fora. Ao retornar e encontrar todos mortos, Noel avistou uma figura desconhecida rondando o celeiro e enterrando algo às pressas. Tomado pela sede de vingança, partiu imediatamente em busca dos assassinos e deixou para trás o objeto escondido."},{t="Desenterrando segredos",b="Agora acampado nas colinas do oeste e consumido pela ira, Noel precisa que alguém retorne à Fazenda do Noel. Atrás de um velho cepo de árvore, entre a casa e o celeiro arruinado, há um monte de terra solta, amontoada às pressas. Recuperar o que foi enterrado ali é o primeiro passo para descobrir por que os cavalgantes sombrios atacaram um pacato fazendeiro da Floresta do Crepúsculo."}},faq={{q="Quem é Noel?",a="Noel era um fazendeiro comum que vivia no sudeste da Floresta do Crepúsculo, perto da fronteira com o Trilha do Vento Morto. Ao voltar para casa e descobrir que sua família havia sido assassinada por cavaleiros sinistros, abandonou a fazenda e se tornou um recluso obcecado em se vingar dos responsáveis.",al={"quem é noel","história de noel","passado de noel"}},{q="O que aconteceu com a fazenda de Noel?",a="A fazenda de Noel foi atacada pelos misteriosos Cavalgantes Negros vindos da Trilha do Vento Morto. Eles massacraram toda a família e deixaram a propriedade em ruínas antes que Noel pudesse voltar para defendê-los.",al={"tragédia na fazenda dos noel","o que aconteceu na fazenda de noel","por que a fazenda foi destruída"}},{q="Quem enterrou algo atrás do celeiro?",a="Noel viu uma figura sombria perto do celeiro, enterrando um objeto logo após o massacre. Ele partiu em perseguição aos Cavalgantes Negros antes de conseguir capturar o desconhecido ou desenterrar o que havia sido escondido.",al={"quem enterrou o objeto","figura sombria na fazenda de noel","quem cavou o monte de terra"}},{q="Onde fica o monte de terra solta?",a="O monte de terra solta fica na Fazenda do Noel, no sudeste da Floresta do Crepúsculo, atrás de um velho cepo de árvore entre o celeiro e a casa em ruínas.",al={"onde fica o monte de terra","localização da terra solta","onde fica o toco"}},{q="Quem são os Cavalgantes Negros?",a="Os Cavalgantes Negros são cavaleiros encapuzados e ameaçadores que surgem da Trilha do Vento Morto. Pouco se sabe sobre suas origens, mas suas incursões violentas na Floresta do Crepúsculo deixam apenas morte e destruição.",al={"quem são os cavalgantes negros","história dos cavalgantes negros","cavaleiros do trilha do vento morto"}},{q="Por que Noel não desenterrou o objeto?",a="Ao voltar para casa e ver a figura enterrando o objeto, Noel ficou transtornado pela dor e perseguiu imediatamente os Cavalgantes Negros em retirada. Quando estabeleceu seu esconderijo, a fazenda já estava tomada por inimigos, e retornar àquele lugar era doloroso demais.",al={"por que noel não examinou a terra","por que noel foi embora"}}},fx={e064b97c={q="Por que Noel Figueira quer que o objeto enterrado seja recuperado?",a="Noel Figueira busca vingança pelo brutal massacre de sua família pelos misteriosos Cavaleiros Negros da Trilha do Vento Morto. Quando ele descobriu o massacre, testemunhou uma figura sombria enterrando algo apressadamente perto de seu celeiro antes de fugir. Movido pela raiva e pela necessidade de respostas, Noel acredita que o que quer que esteja sob o solo contém a chave para descobrir por que sua fazenda foi alvo e quem ajudou na destruição de sua família.",al={"por que noel quer isso","motivo de noel figueira","motivo da missão de vingança de noel"}}},fp="14,234,24.320.0,18.307.0,19.181.0,29.133.0,37.168.0,41.140.0,24.145.0,47.164.0"}
P.entries["quest:950"] = {n="Retorno a Onu",s="Retorno a Onu é uma missão da Aliança que conclui uma investigação inicial sobre os cultistas acampados ao longo da costa de Costa Negra. Após atacar o acampamento dos cultistas e tentar ler o Twilight Tome, um aventureiro recupera uma única página de rabiscos enlouquecedores para entregar ao Ancient of Lore Onu, no Bosque dos Anciãos.",h="Retorno a Onu é uma missão da Aliança que conclui uma investigação inicial sobre os cultistas acampados ao...",kw={"costa negra","bosque dos ancientes","rabiscos malucos","antigos","onu","twilight tome","martelo do crepúsculo"},ang={["class:Druid"]="A ressonância caótica e antinatural dos rabiscos representa uma afronta à ordem natural que os druidas servem para preservar ao lado de árvores como Onu.",["faction:Alliance"]="Investigar a atividade do culto ao longo da costa de Costa Negra garante que assentamentos de elfos noturnos como Auberdine permaneçam seguros contra ameaças ocultas.",["race:NightElf"]="A profanação das costas de Costa Negra por cultistas sombrios ameaça o equilíbrio guardado pelos Ancients of Lore, tornando os avisos de Onu profundamente pessoais para os kaldorei."},sec={{t="Um Vislumbre da Loucura",b="Ao descobrir o Twilight Tome dentro do acampamento do Martelo do Crepúsculo, qualquer pessoa que espreite suas páginas sofre um ataque imediato aos sentidos. O texto escrito nada e dança pelo pergaminho, e os ornamentos que antes pareciam elaborados transformam-se em figuras grotescas. A tensão mental é tão esmagadora que arrancar uma única página de notas rabiscadas é tudo o que uma mente mortal consegue suportar antes de sucumbir à vertigem."},{t="Suspeitas Ancestrais",b="Ao ser entregue a Onu, o imponente Ancião reconhece a aura antinatural que impregna o fragmento. O pergaminho irradia uma magia caótica e primordial que Onu atribui diretamente ao trabalho das forças antigas e sombrias enterradas sob a terra. Embora os rabiscos sejam difíceis de decifrar, eles confirmam que a presença do Martelo do Crepúsculo em Costa Negra não é mero banditismo, mas parte de um desígnio mais profundo e blasfemo."}},faq={{q="Qual é a página retirada do Twilight Tome?",a="A página, conhecida simplesmente como Rabiscos Malucos, é uma folha arrancada do livro sagrado do culto. Olhar para ela causa grave sofrimento mental, pois a escrita se contorce em padrões grotescos e mutáveis ligados à magia primordial do vazio.",al={"rabiscos malucos","o que são os rabiscos","página do twilight tome"}},{q="Quem é Onu?",a="Onu é um Ancient of Lore enraizado no Bosque dos Anciãos, no sul de Costa Negra. Ele atua como um guardião ancião e estudioso, guiando elfos noturnos e aliados da Aliança contra corrupções emergentes na floresta.",al={"quem é onu","onu costa negra","treant onu"}},{q="O que Onu descobre com os rabiscos?",a="Onu sente energias caóticas e primordiais emanando da página, identificando a influência de entidades antigas e malévolas. Os escritos sugerem que os cultistas do Martelo do Crepúsculo estão buscando ativamente locais com relíquias e poderes enterrados por toda Costa Negra.",al={"o que onu encontrou","significado dos rabiscos"}},{q="Por que o Martelo do Crepúsculo está em Costa Negra?",a="O culto é atraído a Costa Negra para escavar locais élficos arruinados e descobrir vestígios de um poder antigo ligado à escuridão primordial e aos Deuses Antigos, usando o caos da terra para mascarar seus rituais.",al={"cultistas em costa negra","por que o martelo do crepúsculo está aqui"}},{q="Para onde essa investigação segue?",a="Após a descoberta da presença do culto, Onu volta sua atenção para as antigas ruínas élficas de Mathistra, ao norte, orientando os aventureiros a garantir relíquias antigas antes que os cultistas possam tomá-las.",al={"qual é a próxima missão","o que vem depois de return to onu"}},{q="Por que ler o tomo causa tontura?",a="O Twilight Tome está inscrito com magia sombria e enlouquecedora do vazio e do caos. Os glifos confundem ativamente as mentes mortais, causando alucinações e desmaios para impedir que estranhos desvendem seus segredos.",al={"por que o tomo causa tontura","efeitos do twilight tome"}}},fp="13,134,22.216.0,18.276.1,46.130.0,11.190.0,39.209.0,42.194.0,40.157.1,42.166.0"}
P.entries["quest:95033"] = {n="On the Other Side",s="Tan'jani envia você à Aldeia Mojache, em Feralas, para buscar a ajuda do Mandingueiro Uzer'i. Conhecido por sua magia, Uzer'i também é caçador.",h="Tan'jani envia você à Aldeia Mojache, em Feralas, para buscar a ajuda do Mandingueiro Uzer'i.",kw={"aldeia mojache","feralas","caçador","magia","do outro lado","tan'jani","mandingueiro uzer'i"},sec={{t="Amigo de Tan'jani",b="Em Feralas, você encontra o Mandingueiro Uzer'i na Aldeia Mojache. Ele é um velho amigo de Tan'jani. Tan'jani conta que Uzer'i pratica magia, mas também é caçador. Você deve falar com ele e deixar para trás as vastas planícies abertas."}},faq={{q="Quem me enviou até Uzer'i?",a="Tan'jani envia você ao Mandingueiro Uzer'i, um velho amigo.",al={"tan'jani me enviou","quem é o velho tanjani"}},{q="Onde posso encontrar Uzer'i?",a="O Mandingueiro Uzer'i está na Aldeia Mojache, em Feralas.",al={"localização de uzer'i","onde fica o mandingueiro"}},{q="Por que devo ir até Uzer'i?",a="Tan'jani diz que Uzer'i está procurando ajuda e pede que você fale com ele.",al={"por que falar com uzer'i","o que tanjani quer"}},{q="O que Uzer'i faz?",a="O Mandingueiro Uzer'i pratica magia e também é caçador.",al={"profissão de uzer'i","mandingueiro caçador"}}},fp="17,137,17.228.0,22.57.0,24.50.0,30.72.0,20.58.0"}
P.entries["quest:95034"] = {n="The Debt",s="Lumina Windsinger, no Sepulcro, relata o ataque que deixou Banon gravemente ferido. Seu relato aponta um worgen como a criatura que os atacou na estrada.",h="Lumina Windsinger, no Sepulcro, relata o ataque que deixou Banon gravemente ferido.",kw={"banon","gnolls","lumina windsinger","ataque na estrada","o sepulcro","the debt","worgen"},sec={{t="Um ferimento na estrada",b="Lumina Windsinger, no Sepulcro, conta a você o que aconteceu na estrada. Um worgen gigante, semelhante a um lobo, atacou seu grupo e matou os guardas. Banon se colocou entre a criatura e Lumina, que a afugentou com um feitiço. Àquela altura, Banon já havia sofrido mordidas graves. Ele insistiu para que ela o deixasse, mas ela ficou, e os dois seguiram mancando antes que gnolls os encontrassem."},{t="Os últimos momentos de Banon",b="Banon, no Sepulcro, foi perfurado por muitas lâminas de gnolls antes de se voltar contra Lumina. Ela viu que ele ainda a reconhecia, embora não conseguisse se controlar. Lumina acredita que o worgen o condenou e jura matá-lo para que ele não possa infligir o mesmo horror a outro ser vivo."}},faq={{q="Quem atacou Lumina e Banon na estrada?",a="Um worgen gigante, semelhante a um lobo, atacou Lumina e Banon na estrada.",al={"o que os atacou","ataque de worgen","agressor da estrada"}},{q="O que aconteceu com os guardas?",a="O worgen matou os guardas que acompanhavam Lumina e Banon.",al={"destino dos guardas","o que houve com os guardas","guardas da estrada"}},{q="Como Lumina afugentou o worgen?",a="Lumina conseguiu lançar um feitiço que assustou o worgen e o fez fugir.",al={"como o worgen fugiu","feitiço de lumina","o que o assustou"}},{q="Por que Banon foi mordido?",a="Banon se jogou no caminho do worgen para proteger Lumina, e a criatura o feriu gravemente com suas mordidas.",al={"mordida em banon","como banon se feriu","o que aconteceu com banon"}},{q="Onde Lumina conta a você o que aconteceu?",a="Lumina Windsinger conta seu relato a você no Sepulcro.",al={"onde encontrar lumina","localização de lumina","o sepulcro"}}},fp="8,160,19.344.0,20.277.1,42.64.0,28.66.0,36.78.0,21.91.0,41.57.0"}
P.entries["quest:95036"] = {n="A Moon-Kissed Blade",s="Trevan alerta que os worgens ameaçam a Floresta de Pinhaprata e aponta Old Fire-Eye como um inimigo que resiste à morte por meio de magia desconhecida. Ele pede que você descubra o necessário para uma lâmina especial.",h="Trevan alerta que os worgens ameaçam a Floresta de Pinhaprata e aponta Old Fire-Eye como um inimigo que...",kw={"uma lâmina beijada pela lua","materiais da lâmina","old fire-eye","floresta de pinhaprata","arma especial","trevan","worgen"},sec={{t="A lista do ferreiro",b="Old Fire-Eye é o worgen que atacou Trevan e seus companheiros. Trevan lhe dará uma lista dos materiais necessários para forjar uma arma contra ele. Os materiais são reunidos, e Trevan acredita conhecer um ferreiro capaz de fabricar a lâmina."}},faq={{q="Quem é Old Fire-Eye?",a="Old Fire-Eye é o maior e mais cruel dos worgens, e atacou Trevan e seus companheiros.",al={"old fire-eye","worgen fire-eye","worgen grande"}},{q="Por que Old Fire-Eye sempre volta?",a="Uma magia desconhecida impede que Old Fire-Eye permaneça morto.",al={"por que fire-eye não morre","magia de old fire-eye","worgen que não permanece morto"}},{q="O que Trevan precisa de mim?",a="Trevan lhe dará uma lista dos materiais necessários para forjar uma arma especial.",al={"o que trevan quer","lista de trevan","materiais da lâmina"}},{q="Por que é necessária uma lâmina especial?",a="Old Fire-Eye resiste à morte por meio de magia desconhecida, então Trevan diz que é necessária uma arma especial para acabar com ele.",al={"por que lâmina beijada pela lua","arma para old fire-eye","matar fire-eye"}},{q="Quem pode fabricar a lâmina?",a="Trevan acredita conhecer um ferreiro capaz de fabricar a lâmina.",al={"ferreiro para a lâmina","quem faz a lâmina lunar","ferreiro da lâmina"}}},fp="19,185,14.239.0,20.97.0,39.51.0,30.74.0,30.108.0,24.57.0"}
P.entries["quest:95041"] = {n="Acumuladores de dados",s="Acumuladores de dados é uma tarefa concedida por Jemma Quikswitch, uma gnoma exilada que reside em Altaforja. Durante a evacuação desesperada de Gnomeregan, ela copiou os arquivos mais preciosos de sua família em cartões perfurados, apenas para perder vários nos montes de neve congelantes do lado de fora dos portões da cidade. Recuperar esses cartões de dados perdidos significa resgatar desde esquemas avançados de engenharia naval até receitas de família insubstituíveis.",h="Acumuladores de dados é uma tarefa concedida por Jemma Quikswitch, uma gnoma exilada que reside em Altaforja.",kw={"data hoarders","dun morogh","gnomeregan","altaforja","jemma quikswitch","cartões perfurados","segunda guerra","casco de submarino"},ang={["faction:Alliance"]="A Aliança depende muito da engenhosidade dos gnomos; ajudar refugiados deslocados a preservar registros de engenharia dos tempos de guerra garante que o valioso conhecimento técnico da Aliança não se perca para sempre.",["profession:Cooking"]="Guardada ao lado de esquemas de engenharia de primeira linha está a receita pessoal de chili da Vovó Quikswitch, provando que a boa comida possui tanto valor sentimental quanto a ciência militar.",["profession:Engineering"]="Engenheiros conseguem reconhecer o imenso valor escondido nesses cartões, que contêm projetos autênticos de cascos de submarino da Segunda Guerra e equações arcanotécnicas complexas.",["race:Gnome"]="Para aventureiros gnomos, recuperar esses cartões perfurados é uma questão de preservação cultural, garantindo que invenções vitais e memórias de família não se percam nas ruínas radioativas de sua terra natal."},sec={{t="Uma Corrida na Neve",b="Quando a invasão trogg e o subsequente desastre de radiação forçaram os gnomos a saírem de Gnomeregan, milhares fugiram com quaisquer pertences que conseguiram pegar no caos. Jemma Quikswitch tomou a prudente medida de transcrever gerações de conhecimento familiar em arquivos físicos de cartões perfurados. Tragicamente, uma bolsa danificada espalhou vários cartões cruciais pelos campos de neve que cercam a cidade caída. Sem esses cartões perfurados perdidos, os dados restantes constam como jargões indecifráveis, ameaçando apagar o legado intelectual de sua família."},{t="Equações e Chili",b="Os arquivos de dados dos gnomos refletem a amplitude peculiar das prioridades de sua civilização. Os registros da família Quikswitch incluem profundas equações de campo arcanotécnicas, plantas vitais do casco de submarinos da Segunda Guerra e a receita secreta de chili da Vovó Quikswitch. Para quem vê de fora, combinar engenharia militar com culinária caseira pode parecer estranho, mas para os refugiados sobreviventes em Altaforja, preservar os confortos domésticos importa tanto quanto preservar maravilhas tecnológicas."}},faq={{q="Quem é Jemma Quikswitch?",a="Jemma Quikswitch é uma refugiada gnoma que conseguiu escapar da queda de Gnomeregan e agora reside em segurança entre os salões anões de Altaforja.",al={"jemma quikswitch","quem dá data hoarders","concedente da missão data hoarders"}},{q="Quais dados estão armazenados nos cartões perdidos?",a="Os cartões perfurados guardam os arquivos da família Quikswitch, incluindo equações arcanotécnicas, esquemas de cascos de submarino que remontam à Segunda Guerra e a receita de chili da Vovó Quikswitch.",al={"o que são os cartões perfurados","o que havia nos cartões","arquivos dos quikswitch"}},{q="Onde os cartões de dados foram perdidos?",a="Eles escorregaram por um buraco na mochila de Jemma enquanto ela fugia de Gnomeregan, deixando-os enterrados no terreno nevado nos arredores dos portões da cidade subterrânea em Dun Morogh.",al={"onde estão os cartões","localização dos cartões de dados","onde ela os deixou cair"}},{q="Por que Jemma não consegue ler os cartões sobreviventes sem os que estão faltando?",a="Jemma afirma que os dados estão embaralhados demais para serem recuperados sem os cartões perfurados que faltam. A missão não explica como os cartões codificam ou organizam essa informação.",al={"por que precisa de todos os cartões","dados embaralhados","dados dos cartões perfurados"}},{q="Qual papel os gnomos desempenharam na Segunda Guerra em relação aos submarinos?",a="Durante a Segunda Guerra, os gnomos contribuíram fortemente para o esforço militar da Aliança por meio de engenharia avançada, projetando e pilotando especificamente embarcações submersíveis para combater as forças navais da Horda.",al={"submarinos de gnomos na segunda guerra","projetos de casco de submarino"}},{q="Por que os refugiados gnomos estão vivendo em Altaforja?",a="Após a queda repentina de Gnomeregan para invasores troggs e a radiação catastrófica, os gnomos sobreviventes fugiram de seu lar subterrâneo e receberam santuário do Rei Magni Barbabronze na cidade anã vizinha de Altaforja.",al={"por que há gnomos em altaforja","gnomos morando com anões"}}},fp="13,256,22.294.0,19.259.0,24.95.0,38.177.0,34.125.0,66.158.0,65.158.0,45.172.0"}
P.entries["quest:95042"] = {n="Seeking the Kor Gem",s="Ulric Frostveil, um Renegado no Vale Gris, vê sua busca por uma Kor Gem como um trabalho familiar para os conjuradores da Aliança. Ele indica as Profundezas Negras, onde os naga ainda usam as gemas.",h="Ulric Frostveil, um Renegado no Vale Gris, vê sua busca por uma Kor Gem como um trabalho familiar para os...",kw={"vale gris","profundezas negras","renegados","kor gem","naga","ulric frostveil"},sec={{t="Uma gema no Vale Gris",b="Ulric pede que você traga uma Kor Gem das ruínas das Profundezas Negras, ao norte do Vale Gris. Ele diz que os naga lá embaixo ainda usam as gemas, que podem fortalecer armas e instrumentos mágicos. Ele alerta você para não ir sozinho."},{t="O interesse de Ulric",b="Ulric reconhece a corrupção na gema e diz que pode dissipar o mal que as bruxas naga infundiram nela. Ele pergunta se você a venderia para ele, para suas pesquisas acadêmicas."}},faq={{q="Quem é Ulric Frostveil?",a="Ulric Frostveil é um Renegado no Vale Gris que pede que você lhe traga uma Kor Gem.",al={"ulric frostveil","quem é ulric","renegado no vale gris"}},{q="Onde posso encontrar uma Kor Gem?",a="Ulric indica que você siga para o norte, até as Profundezas Negras, onde os naga ainda usam Kor Gems.",al={"localização da kor gem","onde encontrar gema","gema das profundezas negras"}},{q="Para que servem as Kor Gems?",a="Às vezes, as Kor Gems são usadas para fortalecer armas e instrumentos mágicos.",al={"uso da kor gem","magia da gema","o que a kor gem faz"}},{q="Por que Ulric quer uma Kor Gem?",a="Ulric pede que você lhe traga uma Kor Gem e diz que ela pode ser valiosa para suas pesquisas acadêmicas.",al={"ulric quer gema","por que a gema","gema frostveil"}},{q="Quem ainda usa Kor Gems?",a="Os naga das Profundezas Negras ainda usam Kor Gems.",al={"gemas naga","quem usa kor gems","naga das profundezas negras"}}},fp="19,177,18.215.0,16.190.1,23.79.0,27.76.0,27.52.0,30.89.0,24.49.0"}
P.entries["quest:95059"] = {n="Frazzlespark's Crate",s="Um goblin tem uma entrega para Knight Commander Demar Brant na Bastilha de Ermoforte. Pedem a você que leve o caixote de Frazzlespark até ele.",h="Um goblin tem uma entrega para Knight Commander Demar Brant na Bastilha de Ermoforte.",kw={"caixa","demar brant","bastilha de ermoforte","frazzlespark","frazzlespark's crate","entrega do goblin","comandante cavaleiro"},sec={{t="Uma entrega para a Bastilha",b="Frazzlespark envia você para sudoeste, até a Bastilha de Ermoforte, onde Knight Commander Demar Brant está esperando. O caixote é destinado a ele, e o goblin faz questão de usar o nome completo dele. Na bastilha, Demar chama o goblin de mero meio para atingir um fim, parte das negociações que, segundo ele, mantêm seu próprio povo seguro e próspero."}},faq={{q="Quem está esperando pela caixa?",a="O Comandante Cavaleiro Demar Brant está esperando por Frazzlespark's Crate na Bastilha de Ermoforte.",al={"quem quer a caixa","entrega para demar brant"}},{q="Onde devo levar Frazzlespark's Crate?",a="Leve Frazzlespark's Crate ao Comandante Cavaleiro Demar Brant na Bastilha de Ermoforte, a sudoeste de Frazzlespark.",al={"localização da caixa","onde fica a bastilha de ermoforte"}},{q="Por que Demar quer que usem seu nome completo?",a="Frazzlespark comenta que Demar sempre faz o goblin usar seu nome completo, mas não explica o motivo.",al={"nome completo de demar","por que comandante cavaleiro"}},{q="Por que Frazzlespark chama isso de entrega especial?",a="Frazzlespark chama isso de entrega especial e diz que Demar Brant está esperando por ela na Bastilha de Ermoforte.",al={"entrega da caixa","o que há de especial na caixa"}},{q="Por que essa entrega é importante?",a="Demar Brant diz que certas negociações precisam ser feitas para garantir a segurança e o sucesso de seu povo, e chama o goblin de nada além de um meio para atingir um fim.",al={"por que entregar a caixa","segurança dos goblins"}}},fp="20,126,19.303.0,29.82.0,37.102.0,39.95.0,49.98.0,30.152.0"}
P.entries["quest:95062"] = {n="Frazzlespark's Crate",s="Uma entrega de Frazzlespark está a caminho de Old Krom'rosh, em Rog'mar. Leve a caixa até lá com rapidez e cuidado.",h="Uma entrega de Frazzlespark está a caminho de Old Krom'rosh, em Rog'mar.",kw={"caixa","entrega","frazzlespark","caixa de frazzlespark","krom'rosh","old krom'rosh","pacote","rog'mar"},sec={{t="Uma Entrega Cuidadosa",b="Frazzlespark tem um pacote para Old Krom'rosh, que está esperando em Rog'mar, logo a oeste daqui. Pedem que você o leve com rapidez e cuidado, mas não dizem o motivo. Os negócios de Krom'rosh ajudam a alcançar os objetivos do grupo."}},faq={{q="Quem está esperando pela caixa de Frazzlespark?",a="Old Krom'rosh está esperando pela caixa de Frazzlespark em Rog'mar.",al={"quem recebe a caixa","caixa para krom'rosh","pacote para kromrosh"}},{q="Onde fica Rog'mar?",a="Rog'mar fica logo a oeste de Frazzlespark.",al={"onde fica rog'mar","localização de rog'mar","lugar rog'mar"}},{q="O que devo fazer com a caixa?",a="Leve a caixa de Frazzlespark até Old Krom'rosh, em Rog'mar, com rapidez e cuidado.",al={"entregar a caixa","entrega de frazzlespark","o que fazer"}},{q="Por que a caixa precisa ser entregue com cuidado?",a="Frazzlespark aconselha você a fazer a entrega com rapidez e cuidado, mas não explica o motivo.",al={"por que ter cuidado","por que apressar a entrega da caixa","motivo da caixa"}},{q="Por que Krom'rosh faz esse tipo de negócio?",a="Krom'rosh diz que esses negócios ajudam a alcançar seus objetivos.",al={"negócios de krom'rosh","por que as relações","para que servem os negócios"}}},fp="20,112,18.231.0,40.61.0,17.37.0,32.78.0,41.81.0,48.57.0"}
P.entries["quest:95063"] = {n="Bloodmaster's Ring",s="Você irritou Chub'chob no Bloodmaster's Ring de Bolder'ok. A taxa da arena não oferece proteção contra a morte, e você terá de enfrentá-lo sozinho.",h="Você irritou Chub'chob no Bloodmaster's Ring de Bolder'ok.",kw={"arena","bloodmaster","bloodmaster's ring","bolder'ok","chub'chob","clugfist","ogros"},sec={{t="O Desafio da Arena",b="O aviso vem depois das suas lutas no Bloodmaster's Ring de Bolder'ok, onde você já despertou a ira de Chub'chob. O atendente lembra que a taxa de entrada não cobre uma morte acidental. Agora, você enfrenta Chub'chob, Bloodmaster de Bolder'ok, sozinho."},{t="Uma Nova Posição",b="Ao voltar para Clugfist, você conta que se tornou campeão do Bloodmaster's Ring. Sua vitória lhe rende um novo amigo entre o clã. Agora você pode lutar e festejar com os ogros."}},faq={{q="Quem é Chub'chob?",a="Chub'chob é o Bloodmaster de Bolder'ok, e você o irritou na arena.",al={"chub'chob","bloodmaster","quem é chub'chob"}},{q="Onde fica o Bloodmaster's Ring?",a="O Bloodmaster's Ring fica em Bolder'ok.",al={"localização do bloodmaster's ring","arena de bolder'ok","onde lutar"}},{q="A quem conto que me tornei campeão?",a="Você conta a Clugfist, em Bolder'ok, que se tornou campeão do Bloodmaster's Ring.",al={"notícia de campeão","contar para clugfist","quem recebe a notícia"}},{q="A taxa de entrada cobre morte acidental?",a="Não. O atendente avisa que a taxa de entrada não cobre morte acidental.",al={"taxa por morte","taxa da arena","a taxa me protege"}}},fp="18,146,21.260.0,14.196.1,17.80.0,32.39.0,38.102.0,42.75.0"}
P.entries["quest:95064"] = {n="Preventative Measures",s="Watcher Cornelius, em Terral's Watch, teme que os orcs avancem cada vez mais pelas planícies. Ele pede que você contenha a presença crescente deles.",h="Watcher Cornelius, em Terral's Watch, teme que os orcs avancem cada vez mais pelas planícies.",kw={"orcs","planícies","medidas preventivas","recrutas de rog'mar","terral's watch","watcher cornelius"},sec={{t="Orcs nas planícies",b="Em Terral's Watch, Watcher Cornelius vê os orcs ocupando terras às margens do rio e avançando pelas planícies. Ele pede que você mate recrutas de Rog'mar, na esperança de deter o avanço deles."}},faq={{q="Quem pede ajuda?",a="Watcher Cornelius, em Terral's Watch, pede que você detenha a presença crescente dos orcs.",al={"quem precisa de ajuda","pedido de cornelius"}},{q="Por que Cornelius está preocupado com os orcs?",a="Os orcs ocuparam terras às margens do rio, e sua presença está crescendo nas planícies.",al={"por que lutar contra orcs","orcs nas planícies"}},{q="Quais orcs Cornelius quer que você mate?",a="Cornelius pede que você mate recrutas de Rog'mar.",al={"recrutas de rog'mar","quais orcs"}},{q="Onde Cornelius pede ajuda?",a="Cornelius pede ajuda em Terral's Watch.",al={"terral's watch","onde fica cornelius"}}},fp="21,132,18.176.0,18.80.0,42.85.0,38.44.0,34.42.0"}
P.entries["quest:95065"] = {n="Hora da pesca",s="Hora da pesca é um favor simples para Gilbertoo Cinéreo, um pescador idoso que aprecia a paisagem costeira no porto de Ventobravo. Quando a isca acaba justamente na hora em que os peixes começam a morder, ele pede a quem passa que vá aos canais da cidade comprar mais suprimentos de pesca.",h="Hora da pesca é um favor simples para Gilbertoo Cinéreo, um pescador idoso que aprecia a paisagem costeira no...",kw={"canais","catarina gurjão","hora da pesca","gilberto cinéreo","reptantes","miçanga brilhosa","porto de ventobravo","distrito comercial"},ang={["faction:Alliance"]="Reservar um tempo para ajudar um cidadão idoso como Gilbertoo Cinéreo reflete os pequenos afazeres cotidianos que sustentam a vida e o ânimo da população de Ventobravo.",["race:Human"]="Para os humanos que chamam Ventobravo de lar, ajudar um idoso do bairro a desfrutar de uma tarde tranquila de pesca é uma pausa bem-vinda na política do reino."},sec={{t="Um dia à beira d'água",b="Nem todo mundo em Ventobravo está envolvido com política, guerras ou conspirações iminentes. Na beira do porto, Gilbertoo Cinéreo passa seus dias tranquilos aproveitando a brisa do mar e observando a boia dançar sobre as ondas. Mas um pescador entusiasmado pode facilmente perder a conta dos suprimentos, e uma sequência repentina de fisgadas esgota até o pote de iscas mais bem abastecido. Para não abandonar seu lugar favorito, o velho recorre a aventureiros dispostos a repor seus materiais."},{t="Suprimentos nos canais",b="Os pescadores de Ventobravo contam com Catarina Gurjão, que mantém uma conhecida loja de artigos de pesca junto aos canais de pedra, a oeste do movimentado Distrito Comercial. Ao vender anzóis, iscas e outros equipamentos pela cidade, Gurjão garante que clientes antigos como Gilbertoo Cinéreo não precisem recolher as linhas antes da hora por falta de uma isca brilhante ou de uma minhoca."}},faq={{q="Quem é Gilbertoo Cinéreo?",a="Gilbertoo Cinéreo é um pescador idoso que fica à beira d'água no porto de Ventobravo. Feliz em passar os dias lançando a linha ao mar, ele pede aos aventureiros que tragam iscas e materiais de pesca quando seus próprios suprimentos acabam.",al={"gilberto cinéreo","velho cinéreo","quem oferece esta missão"}},{q="Quem é Catarina Gurjão?",a="Catarina Gurjão é uma comerciante de artigos de pesca de Ventobravo. Sua loja fica junto aos canais da cidade, a oeste do Distrito Comercial, onde ela vende equipamentos e iscas aos pescadores do reino.",al={"catarina gurjão","vendedora de pesca em ventobravo","gurjão ventobravo"}},{q="Onde Gilbertoo Cinéreo pesca?",a="Gilbertoo Cinéreo fica perto da água no porto de Ventobravo, de onde aprecia a vista do mar aberto, longe das ruas movimentadas da cidade.",al={"localização de gilberto cinéreo","onde fica gilberto cinéreo","pescador do porto"}},{q="De quais suprimentos Gilbertoo Cinéreo precisa?",a="Gilbertoo Cinéreo precisa de reptantes como isca e de uma miçanga brilhosa para atrair os peixes. Ambos os itens podem ser comprados com Catarina Gurjão, junto aos canais.",al={"itens da missão hora da pesca","que isca cinéreo quer"}},{q="Por que Gilbertoo Cinéreo não busca os suprimentos pessoalmente?",a="Os peixes estão mordendo a isca quando você fala com ele, e o pescador não quer perder seu lugar nem deixar escapar uma boa pescaria para atravessar a cidade em busca de suprimentos.",al={"por que cinéreo não compra iscas","por que cinéreo precisa de ajuda"}},{q="Onde fica a loja de Catarina Gurjão nos canais?",a="A loja fica junto à água, a oeste do Distrito Comercial, com acesso direto pelas passarelas de pedra que cruzam a rede de canais da cidade.",al={"localização de catarina gurjão","onde fica a loja de gurjão","canais do distrito comercial"}}},fp="12,206,18.235.0,25.223.0,20.167.0,24.160.0,29.82.0,37.118.0,52.132.0,58.129.0"}
P.entries["quest:951"] = {n="Relíquias de Mathistra",s="Esta missão envia aventureiros da Aliança para o norte, ao longo da costa de Costa Negra, para vasculhar as tomadas pela vegetação Ruínas de Mathistra. Onu, um Ancião dos Saberes enraizado no Bosque dos Ancientes, busca esses antigos artefatos kaldorei para entender como o Martelo do Crepúsculo está manipulando a feitiçaria dos elfos noturnos em seus ritos sinistros.",h="Esta missão envia aventureiros da Aliança para o norte, ao longo da costa de Costa Negra, para vasculhar as...",kw={"costa negra","bosque dos ancientes","glaive do mestre","mathistra","onu","relíquias","ruínas de mathistra","martelo do crepúsculo"},ang={["class:Druid"]="Ajudar Onu permite que os druidas sirvam a uma das maiores sentinelas anciãs da natureza, protegendo a história ancestral de Costa Negra de ser distorcida por sectários sombrios.",["faction:Alliance"]="Impedir que o Martelo do Crepúsculo use a magia antiga como arma é essencial para proteger o norte de Kalimdor contra forças sombrias e subterrâneas.",["race:NightElf"]="Para os elfos noturnos, ver relíquias de sua glória anterior à Cisão serem desenterradas da terra é uma lembrança sombria da queda de sua civilização — e um aviso alarmante de que as potentes artes de seus ancestrais estão sendo exploradas por loucos apocalípticos."},sec={{t="Uma Descoberta Perturbadora",b="Após aventureiros recuperarem um pergaminho maculado dos sectários que espreitavam ao redor do monumento colossal conhecido como a Glaive do Mestre, Onu decifrou uma revelação perturbadora. O texto não era uma escritura nativa do culto, mas um fragmento amaldiçoado de antigos escritos élficos noturnos. Corrompido pelo Martelo do Crepúsculo, o pergaminho revelou que esses fanáticos apocalípticos estão aproveitando a magia élfica esquecida para despertar ou evocar seus antigos mestres de volta ao mundo mortal."},{t="O Bastião Caído",b="Para combater essa empreitada sombria, Onu direciona os heróis às Ruínas de Mathistra, localizadas ao longo da costa nordeste de Costa Negra. Há muito tempo, Mathistra foi um radiante bastião da civilização altaneira antes de se despedaçar durante a Cisão. Embora a cidade tenha desmoronado em escombros, ervas daninhas e uma infestação de nagas, poderosos resquícios de seus encantamentos arcanos e espirituais originais ainda perduram em urnas despedaçadas e relíquias antigas espalhadas pelas fundações de pedra."},{t="Adivinhando Desígnios Sombrios",b="Ao coletar artefatos sobreviventes dos detritos cobertos de grama das ruínas, os defensores de Costa Negra esperam desvendar as técnicas específicas que os sectários pretendem explorar. Onu estuda a magia residual impregnada nas relíquias, correndo contra o tempo para decifrar os planos do culto antes que o Martelo do Crepúsculo consiga subjugar completamente a antiga feitiçaria kaldorei para libertar seus mestres subterrâneos."}},faq={{q="O que são as Relíquias de Mathistra?",a="São fragmentos de cerâmica encantada, urnas e artefatos deixados para trás nas Ruínas de Mathistra. Criados durante o ápice da antiga civilização dos elfos noturnos antes da Grande Cisão, eles ainda vibram com uma energia mágica persistente.",al={"o que são as relíquias","história das relíquias de mathistra","relíquias élficas mathistra"}},{q="Por que Onu quer essas relíquias?",a="Onu descobriu que o Martelo do Crepúsculo está usando a antiga magia élfica para tentar trazer seus mestres sombrios de volta ao mundo. Ao estudar relíquias intactas de Mathistra, Onu espera compreender como o culto pretende manipular esse poder ancestral.",al={"por que onu quer relíquias","propósito das relíquias de mathistra"}},{q="Onde ficavam as Ruínas de Mathistra?",a="As ruínas ficam ao longo da costa nordeste de Costa Negra, ao norte das ruínas de Ameth'Aran e Bashal'Aran, logo após A Torre de Althalaxx.",al={"onde fica mathistra","localização de mathistra"}},{q="Quem o Martelo do Crepúsculo está tentando trazer de volta?",a="O culto é dedicado a mestres antigos e malévolos; Onu adverte que eles estão usando a antiga magia élfica para trazer esses velhos mestres de volta a Azeroth.",al={"quem são os mestres do martelo do crepúsculo","mestres do culto costa negra"}},{q="O que era Mathistra antes de se tornar uma ruína?",a="Mathistra já foi um grande bastião e cidade dos elfos noturnos há milhares de anos. Ela caiu em ruínas durante a Grande Cisão e, desde então, foi dominada pela natureza selvagem, fantasmas e vis criaturas costeiras, como as nagas.",al={"história de mathistra","o que era mathistra"}},{q="Quem concede a missão 'Relíquias de Mathistra'?",a="A missão é concedida por Onu, um antigo arvoroso enraizado no Bosque dos Ancientes, no centro-sul de Costa Negra, após a investigação da Glaive do Mestre.",al={"quem inicia relíquias de mathistra","doador da missão relíquias de mathistra"}}},fp="16,215,22.360.1,18.296.0,21.293.1,30.220.0,31.222.0,42.138.0,50.154.0,43.204.0,39.177.0"}
P.entries["quest:95111"] = {n="An Underrated Talent",s="Trevan Rol, na Floresta de Pinhaprata, pede que você leve materiais a Ott, na Serraria Tarren, e lhe ofereça uma encomenda personalizada. Suas lâminas simples impressionaram os ferreiros da Cidade Baixa, e essa encomenda lhe dá a chance de mostrar o que sabe fazer.",h="Trevan Rol, na Floresta de Pinhaprata, pede que você leve materiais a Ott, na Serraria Tarren, e lhe ofereça...",kw={"encomenda","lâmina personalizada","ott","ferreiro","serraria tarren","cidade baixa","ferreiro de armas"},sec={{t="Uma Chance para um Ferreiro",b="Trevan Rol pede que você leve materiais a Ott, na Serraria Tarren, e lhe ofereça uma encomenda. Ott é conhecido por vender lâminas simples a viajantes. Trevan comprou uma e depois a levou à Cidade Baixa para manutenção, onde os ferreiros locais se surpreenderam com sua qualidade. Eles acharam que era obra de um mestre famoso, mas foi Ott quem a fez. Agora você lhe oferece a chance de forjar uma lâmina conforme suas especificações."},{t="A Resposta de Ott",b="Ott diz que ninguém nunca lhe pediu uma encomenda personalizada. Ele costuma fabricar armas humildes e funcionais, do seu jeito, e diz que não busca reconhecimento. Está disposto a tentar, embora se pergunte por que você o escolheu, já que os ferreiros da Cidade Baixa também aceitam encomendas personalizadas."}},faq={{q="Quem é Ott?",a="Ott é um ferreiro de armas na Serraria Tarren que vende lâminas simples a viajantes.",al={"ferreiro ott","quem é ott","ferreiro da serraria tarren"}},{q="Por que o ferreiro da Cidade Baixa quer que eu encontre Ott?",a="O ferreiro comprou uma das lâminas de Ott e se surpreendeu quando os ferreiros da Cidade Baixa elogiaram sua qualidade. Ele quer dar a Ott a chance de fazer algo especial.",al={"por que ott","encomenda de ferreiro da cidade baixa","encomenda para ott"}},{q="O que estou levando para Ott?",a="Você está levando materiais para Ott, na Serraria Tarren, e oferecendo a ele uma encomenda para forjar sua lâmina.",al={"materiais para ott","o que levar","materiais de ott"}},{q="Ott faz armas personalizadas?",a="Ott diz que ninguém nunca lhe pediu uma encomenda personalizada, mas ele aceita tentar.",al={"lâmina personalizada de ott","ott pode forjar para mim","encomendas de ott"}},{q="Por que Ott pergunta por que o escolhi?",a="Ott diz que há ferreiros na Cidade Baixa que aceitam encomendas personalizadas e se pergunta por que você procurou justamente por ele.",al={"por que escolher ott","ott se pergunta por quê","por que não um ferreiro da cidade baixa"}}},fp="20,155,16.348.0,12.255.1,11.73.0,49.163.0,26.97.0,29.87.0,33.90.0"}
P.entries["quest:95118"] = {n="Saltwater Savages",s="Um responsável pelo porto pede que você reduza o número de Murlocs ao longo de Eastwind Shore. Eles se tornaram uma reclamação constante entre marinheiros, pescadores e seus filhos.",h="Um responsável pelo porto pede que você reduza o número de Murlocs ao longo de Eastwind Shore.",kw={"eastwind shore","pescadores","murloc","oráculo murloc","guerreiro murloc","responsável pelo porto","marinheiros","saltwater savages"},sec={{t="Reclamações no Porto",b="O responsável pelo porto já ouviu reclamações suficientes de marinheiros, pescadores e até dos próprios filhos. Os Murlocs o incomodam, mas ele ainda precisa cuidar do porto. Ele pede que você mate alguns ao longo de Eastwind Shore, na esperança de ter um pouco de paz em meio a todo aquele barulho."}},faq={{q="Por que o responsável pelo porto quer que os Murlocs sejam mortos?",a="Os marinheiros, pescadores e filhos do responsável pelo porto não param de reclamar deles. Ele os considera uma praga e quer um pouco de paz enquanto cuida do porto.",al={"por que matar murlocs","murlocs incomodam o porto"}},{q="De quais Murlocs ele está falando?",a="Ele pede que você mate Oráculos Murloc e Guerreiros Murloc ao longo de Eastwind Shore.",al={"tipos de murloc","oráculos e guerreiros"}},{q="Onde estão os Murlocs?",a="O responsável pelo porto indica Eastwind Shore.",al={"murlocs de eastwind shore","onde estão os murlocs"}},{q="Matar esses Murlocs resolve o problema?",a="O responsável pelo porto espera que mais Murlocs voltem em breve, mas torce para que as mortes deles lhe deem um pouco de paz até lá.",al={"murlocs voltam","acabou"}}},fp="17,152,22.244.0,49.149.0,33.76.0,22.45.0,45.118.0"}
P.entries["quest:95119"] = {n="Unfriendly Competition",s="Um comerciante do Porto Detonapavio pede que você contenha os ataques da tripulação Eastsea a cargas e navios. Os membros mais próximos estão ao longo da Costa Eastwind.",h="Um comerciante do Porto Detonapavio pede que você contenha os ataques da tripulação Eastsea a cargas e navios.",kw={"roubo de carga","bucaneiros eastsea","tripulação eastsea","mosqueteiros eastsea","costa eastwind","porto detonapavio","navios afundando","concorrência hostil"},sec={{t="Ao longo da costa",b="Navios afundam e cargas desaparecem, prejudicando os negócios do comerciante no Porto Detonapavio. Os bucaneiros e mosqueteiros da tripulação Eastsea são os mais próximos do porto, ao longo da Costa Eastwind, ao norte. O comerciante quer que você cuide deles primeiro; o restante das operações da tripulação continua sendo uma preocupação."}},faq={{q="Quem está pedindo ajuda?",a="Um comerciante do Porto Detonapavio pede que você cuide da tripulação Eastsea.",al={"quem deu isso","dono do porto","sujeito do detonapavio"}},{q="Quem é a tripulação Eastsea?",a="A tripulação Eastsea é descrita como destrutiva e sanguinária, e rouba cargas e afunda navios.",al={"piratas eastsea","sujeitos eastsea","quem é eastsea"}},{q="Por que o comerciante quer que eles sejam detidos?",a="A tripulação rouba cargas e afunda navios, causando prejuízo ao comerciante.",al={"por que lutar contra eastsea","roubo de carga","por que os navios estão afundando"}},{q="Onde os membros da tripulação Eastsea estão mais próximos do porto?",a="Os membros da tripulação mais próximos do Porto Detonapavio estão ao longo da Costa Eastwind, ao norte.",al={"costa eastwind","onde estão os piratas","praia ao norte"}}},fp="22,142,15.313.0,23.71.0,25.100.0,42.68.0,47.86.0"}
P.entries["quest:95120"] = {n="WANTED: Old Rot-Chum",s="O mestre do cais Whizzbuzz oferece uma recompensa por provas da morte de Old Rot-Chum. O murloc agressivo tem atacado pequenas embarcações nas águas do sul.",h="O mestre do cais Whizzbuzz oferece uma recompensa por provas da morte de Old Rot-Chum.",kw={"murloc","ilhas de murlocs","old rot-chum","botes a remo","pequenas embarcações","águas do sul","mestre do cais whizzbuzz"},sec={{t="Uma ameaça no mar",b="Marinheiros e nadadores nas águas ao sul sofrem ataques a botes a remo e outras pequenas embarcações. Os pescadores locais chamam o murloc agressivo por trás dos ataques de Old Rot-Chum. O mestre do cais Whizzbuzz oferece uma recompensa por provas de que a criatura está morta e pede que você a leve até ele."}},faq={{q="Quem é Old Rot-Chum?",a="Old Rot-Chum é o apelido que os pescadores locais dão a um murloc especialmente agressivo.",al={"old rot-chum","rot-chum","quem é rot-chum"}},{q="Onde Old Rot-Chum foi visto?",a="Old Rot-Chum foi visto nas águas ao sul, perto de ilhas infestadas de murlocs.",al={"onde fica old rot-chum","localização de rot-chum","onde está o murloc"}},{q="O que Old Rot-Chum tem atacado?",a="Old Rot-Chum tem atacado botes a remo e outras pequenas embarcações.",al={"o que rot-chum está atacando","ataques a barcos","murloc e botes a remo"}},{q="Quem oferece a recompensa?",a="O mestre do cais Whizzbuzz oferece uma recompensa em troca de provas da morte de Old Rot-Chum.",al={"quem quer provas de rot-chum","recompensa do mestre do cais","quem paga por old rot-chum"}},{q="Que prova Whizzbuzz pede?",a="O mestre do cais Whizzbuzz pede que você leve provas da morte de Old Rot-Chum.",al={"que prova de rot-chum","levar provas","proof of demise"}}},fp="20,154,15.274.0,20.82.0,33.90.0,37.65.0,22.87.0,34.73.0"}
P.entries["quest:95121"] = {n="A Taste of the Sea",s="Fimbo Greasemitz quer frutos do mar frescos para um ensopado novo em seu café à beira-mar. Você reúne ingredientes locais para renovar o cardápio.",h="Fimbo Greasemitz quer frutos do mar frescos para um ensopado novo em seu café à beira-mar.",kw={"praia","café","fimbo greasemitz","peixe","olhos de múrloc","javali assado","carne de sand crawler","ensopado de frutos do mar"},ang={["profession:Cooking"]="Como cozinheiro, você percebe que Fimbo está procurando ingredientes locais frescos para preparar um ensopado de frutos do mar."},sec={{t="Um Prato Novo",b="Fimbo Greasemitz administra um café à beira-mar, onde javali assado e peixe compõem o cardápio diário. Ele quer experimentar um ensopado de frutos do mar e pede que você traga olhos de múrloc e carne de Sand Crawler das praias próximas."}},faq={{q="Quem é Fimbo Greasemitz?",a="Fimbo Greasemitz administra um café à beira-mar e quer acrescentar ensopado de frutos do mar ao cardápio.",al={"quem é fimbo","café do fimbo","fimbo greasemitz"}},{q="De quais ingredientes Fimbo precisa?",a="Fimbo pede olhos de múrloc e carne de Sand Crawler para seu ensopado de frutos do mar.",al={"ingredientes do ensopado","qual carne","olhos de múrloc"}},{q="Por que Fimbo quer frutos do mar?",a="Ele quer uma receita nova de ensopado de frutos do mar para variar o cardápio diário do café, que oferece javali assado e peixe.",al={"por que ensopado","cardápio novo","comida do café"}},{q="Onde você pode encontrar os ingredientes?",a="Fimbo diz que os olhos de múrloc e a carne de Sand Crawler podem ser encontrados nas praias próximas.",al={"onde encontrar carne","onde encontrar ingredientes","coisas da praia"}}},fp="18,129,10.206.0,24.84.0,33.70.0,28.94.0,35.87.0"}
P.entries["quest:95122"] = {n="Unchecked Expansion",s="Wharfmaster Whizzbuzz diz que os piratas Eastsea ao norte daqui são uma ameaça maior que aqueles que você enfrentou antes. O ataque deles deixou Windstead em chamas, e ele quer impedir que avancem para o interior.",h="Wharfmaster Whizzbuzz diz que os piratas Eastsea ao norte daqui são uma ameaça maior que aqueles que você...",kw={"eastsea bombardiers","piratas eastsea","eastsea raiders","pirata","expansão desenfreada","wharfmaster whizzbuzz","windstead"},sec={{t="Windstead em chamas",b="Windstead está em chamas depois que os piratas Eastsea a saquearam e levaram seus espólios. Wharfmaster Whizzbuzz pede que você reduza o número de invasores e bombardeiros ao norte daqui. Ele teme que os piratas avancem ainda mais pelo território para o interior."}},faq={{q="Quem pede ajuda contra os piratas Eastsea?",a="Wharfmaster Whizzbuzz pede que você reduza o número de piratas Eastsea.",al={"quem pede ajuda","tarefa de whizzbuzz","mestre do cais"}},{q="O que aconteceu com Windstead?",a="Os piratas Eastsea saquearam Windstead, levaram seus espólios e a incendiaram por completo.",al={"windstead em chamas","o que aconteceu aqui","por que windstead desapareceu"}},{q="Quais piratas são o alvo?",a="Wharfmaster Whizzbuzz aponta Eastsea Raiders e Eastsea Bombardiers como os piratas cujo número deve ser reduzido.",al={"tipos de piratas","quem devo enfrentar","eastsea raiders"}},{q="Por que Whizzbuzz quer reduzir o número deles?",a="Ele quer impedir que os piratas avancem ainda mais pelo território para o interior.",al={"por que impedir os piratas","piratas no interior","por que enfrentar eastsea"}}},fp="19,188,18.241.0,46.66.0,27.87.0,29.91.0,44.68.0"}
P.entries["quest:95123"] = {n="A Blast Ye Scurvy Dogs!",s="Wharfmaster Whizzbuzz quer pólvora para destruir os navios piratas de Eastsea. Você é enviado para procurar barris de pólvora perto de Winstead, recém-demolida.",h="Wharfmaster Whizzbuzz quer pólvora para destruir os navios piratas de Eastsea.",kw={"piratas de eastsea","pólvora","navios piratas","barris de pólvora","wharfmaster whizzbuzz","winstead"},sec={{t="Pólvora para o mestre do cais",b="Os navios são a próxima preocupação de Whizzbuzz, depois dos próprios piratas de Eastsea. Ele acredita que eles podem ter armazenado pólvora perto de Winstead, recém-demolida, ao norte. Você é enviado para encontrar os barris de pólvora; ele explicará seu plano mais tarde."}},faq={{q="Quem está pedindo a pólvora?",a="Wharfmaster Whizzbuzz quer pólvora para um plano contra os navios de Eastsea.",al={"quem quer os barris","pólvora de whizzbuzz","quem me enviou"}},{q="Por que Whizzbuzz quer pólvora?",a="Ele quer destruir os navios de Eastsea para que não possam fugir em busca de reforços.",al={"por que pólvora","para que serve a pólvora","plano contra os navios de eastsea"}},{q="Onde os piratas podem ter armazenado a pólvora?",a="Whizzbuzz acha que os piratas podem ter armazenado pólvora perto de Winstead, recém-demolida, ao norte.",al={"localização da pólvora","onde estão os barris","pólvora em winstead"}},{q="Qual é o plano de Whizzbuzz?",a="Whizzbuzz diz que explicará o plano mais tarde; por enquanto, quer que você encontre a pólvora.",al={"qual é o plano dele","plano de whizzbuzz","o que vai acontecer"}}},fp="23,137,26.241.0,29.75.0,34.78.0,47.105.0,25.88.0"}
P.entries["quest:95124"] = {n="Admiral Lamora",s="O mestre do cais Whizzbuzz envia você atrás do almirante Lamora, que navega em um barco de Eastsea a nordeste de sua posição. O saque de Lamora pode ajudar Whizzbuzz a recuperar parte do que perdeu com os saques.",h="O mestre do cais Whizzbuzz envia você atrás do almirante Lamora, que navega em um barco de Eastsea a nordeste...",kw={"almirante lamora","eastsea","chave","saque","saques","esconderijo","mestre do cais whizzbuzz"},sec={{t="As perdas de Whizzbuzz",b="O mestre do cais Whizzbuzz quer que o almirante Lamora morra e que seu saque seja recuperado. Lamora está a bordo de um dos barcos de Eastsea, a nordeste de Whizzbuzz. Você deve descobrir em qual barco ele está e onde guarda o saque. Se estiver trancado, Whizzbuzz suspeita que Lamora esteja com a chave."}},faq={{q="Quem está me enviando atrás do almirante Lamora?",a="O mestre do cais Whizzbuzz envia você atrás do almirante Lamora e pede que traga o saque de Lamora.",al={"quem quer que lamora morra","pedido de whizzbuzz","missão do almirante lamora"}},{q="Onde está o almirante Lamora?",a="Lamora está a bordo de um dos barcos de Eastsea, a nordeste do mestre do cais Whizzbuzz.",al={"onde está lamora","localização de lamora","qual barco de eastsea"}},{q="Por que Whizzbuzz quer que Lamora morra?",a="Whizzbuzz diz que os saques de Lamora lhe custaram uma fortuna e que quer recuperar parte do que perdeu.",al={"por que matar lamora","vingança de whizzbuzz","lamora e whizzbuzz"}},{q="O que Whizzbuzz quer de Lamora?",a="Whizzbuzz quer que Lamora morra e que seu saque seja trazido de volta. Ele suspeita que Lamora esteja com a chave, caso o esconderijo esteja trancado.",al={"o que pegar de lamora","saque de lamora","o que é o esconderijo"}},{q="O que acontece depois que eu voltar?",a="Whizzbuzz diz que não tinha certeza de que você sobreviveria ao encontro com Lamora. Em seguida, oferece fazer um favor para você e diz que talvez volte a chamá-lo.",al={"o que whizzbuzz diz","voltar para whizzbuzz","agradecimento de whizzbuzz"}}},fp="14,192,18.272.0,39.96.0,24.81.0,36.104.0,37.113.0,28.127.0"}
P.entries["quest:95125"] = {n="Ott's Masterwork",s="Ott está pronto para forjar uma lâmina para você com materiais de qualidade. Você está convidado a acompanhar o trabalho dele.",h="Ott está pronto para forjar uma lâmina para você com materiais de qualidade.",kw={"ferreiro","lâmina","forja","obra-prima","materiais","ott"},sec={{t="Na forja",b="Ott considera os materiais excelentes e espera que o trabalho dele atenda às suas expectativas. Ele forja a lâmina para você e, em seguida, a oferece para suas viagens."}},faq={{q="Quem está fazendo minha lâmina?",a="Ott está forjando sua lâmina com os materiais de qualidade que você forneceu.",al={"quem forja","lâmina de ott","ott ferreiro"}},{q="Posso assistir Ott forjá-la?",a="Ott pede que você fique afastado enquanto começa a forjar, e a etapa solicitada é observá-lo trabalhar.",al={"assistir ott forjar","ver a lâmina sendo feita","processo de forja"}},{q="O que Ott diz quando a lâmina fica pronta?",a="Ott chama a lâmina de sua melhor obra e espera que ela seja útil em suas viagens.",al={"conclusão de ott","o que ott diz","lâmina pronta"}}},fp="16,85,12.137.0,23.63.0,25.81.0,45.81.0"}
P.entries["quest:95126"] = {n="The Moonsilver Blade",s="Trevan Rol pede que você leve a Obra-prima de Ott até ele, na Floresta de Pinhaprata. A lâmina é a última parte do trabalho dele antes de enfrentar uma fera.",h="Trevan Rol pede que você leve a Obra-prima de Ott até ele, na Floresta de Pinhaprata.",kw={"fera","lumina","lâmina de luaprata","ott","obra-prima de ott","floresta de pinhaprata","trevan rol"},sec={{t="A lâmina",b="Ott agradece pela oportunidade e pede que você transmita sua gratidão a Trevan. Você leva a Obra-prima de Ott de volta para Trevan Rol, na Floresta de Pinhaprata."},{t="A aprovação de Trevan",b="Trevan examina a lâmina e aprova o trabalho de Ott. Ele diz que só falta matar a fera e orienta você a falar com Lumina quando estiver pronto."}},faq={{q="Quem fez a Obra-prima de Ott?",a="Ott fez a lâmina e a enviou com você para Trevan Rol.",al={"quem fez a lâmina","lâmina de ott","criador da obra-prima"}},{q="Quem é Trevan Rol?",a="Trevan Rol é quem recebe e examina a Obra-prima de Ott na Floresta de Pinhaprata.",al={"quem é trevan","lâmina de trevan","trevan rol"}},{q="Onde devo levar a lâmina?",a="Leve a Obra-prima de Ott até Trevan Rol, na Floresta de Pinhaprata.",al={"para onde levar a lâmina","onde levar a obra-prima de ott","destino da lâmina"}},{q="O que Trevan acha da lâmina?",a="Trevan examina a lâmina e diz que ela servirá muito bem.",al={"trevan gostou da lâmina","a lâmina de ott é boa","aprovação de trevan"}},{q="Com quem devo falar depois de Trevan?",a="Trevan orienta você a falar com Lumina quando estiver pronto.",al={"o que fazer em seguida","quem é lumina","falar com lumina"}}},fp="20,102,9.152.0,17.138.1,26.61.0,18.71.0,27.58.0,36.57.0,37.64.0"}
P.entries["quest:95140"] = {n="Old Fire-Eye",s="Lumina Windsinger pede que você cace Old Fire-Eye na Floresta de Pinhaprata com a Lâmina de Luaprata. Os Moldavento aguardam sua morte, e Lumina espera que a lâmina lhe seja útil.",h="Lumina Windsinger pede que você cace Old Fire-Eye na Floresta de Pinhaprata com a Lâmina de Luaprata.",kw={"banon","guilnéas","lumina windsinger","lâmina de luaprata","old fire-eye","floresta de pinhaprata","moldavento"},sec={{t="O Propósito de uma Lâmina",b="Você recebeu a Lâmina de Luaprata dos Moldavento. Os moradores dizem que Old Fire-Eye caça por uma vasta área ao sul daqui, geralmente perto dos portões de Guilnéas. Lumina pede que você o encontre e use a lâmina para acabar com ele. A gratidão dos Moldavento depende disso."},{t="Depois da Caçada",b="Quando você retorna, Lumina agradece e diz que Banon pode descansar em paz. Então, ela imbui a lâmina ensanguentada com uma pequena parcela da magia de seu povo, na esperança de que os ventos a guiem bem."}},faq={{q="Quem está me pedindo para caçar Old Fire-Eye?",a="Lumina Windsinger pede que você cace Old Fire-Eye com a Lâmina de Luaprata.",al={"quem me enviou","tarefa de lumina","windsinger"}},{q="Onde posso encontrar Old Fire-Eye?",a="Os moradores dizem que Old Fire-Eye caça por uma vasta área ao sul de Lumina e costuma ficar perto dos portões de Guilnéas.",al={"localização de fire-eye","onde está old fire-eye","portões de guilnéas"}},{q="O que devo usar contra Old Fire-Eye?",a="Lumina pede que você use a Lâmina de Luaprata para acabar com Old Fire-Eye.",al={"lâmina contra fire-eye","arma de luaprata","qual arma"}},{q="Por que Lumina quer que Old Fire-Eye seja morto?",a="Lumina diz que os Moldavento ficarão gratos quando Old Fire-Eye estiver morto.",al={"por que matar fire-eye","por que caçá-lo","motivo de fire-eye"}},{q="Quem é Banon?",a="Lumina diz que Banon poderá descansar em paz depois que Old Fire-Eye for morto.",al={"quem é banon","banon em paz"}},{q="O que Lumina faz com a lâmina?",a="Lumina imbui a Lâmina de Luaprata ensanguentada com uma pequena parcela da magia de seu povo.",al={"magia da lâmina","lumina encanta a lâmina","magia dos ventos"}}},fp="12,175,17.261.0,14.186.1,38.74.0,30.100.0,39.64.0,40.71.0,13.64.0,35.89.0"}
P.entries["quest:95141"] = {n="Report to Rog'mar",s="Um Orc envia você a Rog'mar, um posto avançado nas disputadas Sendas do Rio. Apresente-se a Krom'rosh, cuja experiência tem ajudado o posto a resistir a repetidos ataques.",h="Um Orc envia você a Rog'mar, um posto avançado nas disputadas Sendas do Rio.",kw={"ataques","costa leste","krom'rosh","posto avançado","sendas do rio","rog'mar","pedregal"},sec={{t="Um posto resiste",b="As Sendas do Rio ficam a nordeste de Pedregal, ao longo da costa leste. Muitos tentaram conquistar essas terras, mas poucos conseguiram. Rog'mar é um pequeno posto avançado que sobreviveu a incontáveis ataques. Você é enviado para lá para se apresentar a Krom'rosh, um antigo aliado cuja experiência em batalha tem ajudado o posto a resistir."}},faq={{q="Onde fica Rog'mar?",a="Rog'mar fica nas Sendas do Rio, a nordeste de Pedregal, ao longo da costa leste.",al={"localização de rog'mar","onde fica rogmar","posto avançado de rog'mar"}},{q="A quem devo me apresentar?",a="Você deve se apresentar a Krom'rosh no posto avançado de Rog'mar.",al={"a quem se apresentar","quem é krom'rosh","kromrosh"}},{q="O que é Rog'mar?",a="Rog'mar é um pequeno posto avançado nas Sendas do Rio que tem resistido a incontáveis ataques.",al={"o que é rogmar","posto avançado das sendas do rio","pequeno posto avançado"}},{q="Por que Krom'rosh está em Rog'mar?",a="A experiência de Krom'rosh no combate a inimigos tem ajudado o posto avançado a resistir.",al={"por que kromrosh está lá","função de krom'rosh","quem comanda rogmar"}},{q="Como são as terras das Sendas do Rio?",a="As Sendas do Rio são terras disputadas ao longo da costa leste, a nordeste de Pedregal.",al={"sendas do rio","como são as sendas do rio","terras disputadas"}}},fp="17,157,18.302.0,17.78.0,22.54.0,16.81.0,28.70.0,38.84.0"}
P.entries["quest:95143"] = {n="Finding Tan'jani",s="Um viajante pede que você encontre seu irmão Tan'jani. As mensagens o situam ao sul de Loch Modan, e a mais recente aponta para Rog'mar, nas Sendas do Rio.",h="Um viajante pede que você encontre seu irmão Tan'jani.",kw={"carta manchada de sangue","loch modan","irmão desaparecido","sendas do rio","rog'mar","tan jani","tan'jani"},sec={{t="Um Irmão Desaparecido",b="O irmão de um viajante, Tan'jani, partiu em busca de algo desconhecido. Uma mensagem o situa em algum lugar ao sul de Loch Modan. Uma carta manchada de sangue menciona as Sendas do Rio e Rog'mar, mais ao sul, e o viajante pede que você o encontre lá."}},faq={{q="Quem é Tan'jani?",a="Tan'jani é o irmão do viajante que pede que você o encontre.",al={"tan'jani","tan jani","irmão desaparecido"}},{q="Onde Tan'jani foi mencionado pela última vez?",a="Uma carta manchada de sangue menciona as Sendas do Rio e Rog'mar, mais ao sul de Loch Modan.",al={"onde está tan'jani","localização de tan'jani","rog'mar"}},{q="O que Tan'jani estava procurando?",a="Tan'jani estava sempre à procura de algo, mas seu irmão não sabe o quê.",al={"o que ele procurava","tan'jani procurando","por que ele partiu"}},{q="O que dizem as mensagens?",a="Um viajante contou que encontrou Tan'jani em algum lugar ao sul de Loch Modan. Uma carta manchada de sangue menciona as Sendas do Rio e Rog'mar, mas quase toda ela está ilegível.",al={"mensagens de tan'jani","carta manchada de sangue","o que aconteceu com a carta"}}},fp="16,147,17.242.0,16.63.0,34.86.0,32.80.0,25.156.0"}
P.entries["quest:95144"] = {n="Overseas Delivery",s="Fizzgrimble pede que você leve uma caixa lacrada pelo mar até Friz Frazzlespark, nas Sendas do Rio. O conteúdo deve continuar sendo uma surpresa até chegar ao Porto Detonapavio.",h="Fizzgrimble pede que você leve uma caixa lacrada pelo mar até Friz Frazzlespark, nas Sendas do Rio.",kw={"fizzgrimble","friz frazzlespark","caixa misteriosa","entrega além-mar","porto detonapavio","sendas do rio","porto de bondebico"},sec={{t="Uma travessia cuidadosa",b="Fizzgrimble envia você para leste, em direção ao Porto de Bondebico, de onde um navio costuma atravessar o mar. A caixa vai para Friz Frazzlespark, no Porto Detonapavio, nas Sendas do Rio. Manuseie-a com cuidado; Fizzgrimble avisa para não abri-la nem sacudi-la."}},faq={{q="Para quem é a encomenda?",a="Friz Frazzlespark está esperando a caixa no Porto Detonapavio, nas Sendas do Rio.",al={"quem recebe a caixa","encomenda para friz frazzlespark"}},{q="Onde devo levar a caixa?",a="Leve-a até Friz Frazzlespark, no Porto Detonapavio, nas Sendas do Rio.",al={"destino da caixa","onde fica o porto detonavapio"}},{q="Onde posso encontrar uma passagem pelo mar?",a="Fizzgrimble recomenda seguir para leste até o Porto de Bondebico, de onde um navio costuma oferecer uma travessia segura.",al={"como atravessar","navio no porto de bondebico"}},{q="O que devo fazer com a caixa no caminho?",a="Mantenha a caixa fechada e evite incliná-la, sacudi-la ou fazer movimentos bruscos com ela.",al={"como carregar a caixa","posso abrir a encomenda"}},{q="O que tem dentro da caixa?",a="Friz Frazzlespark pede que você se vire enquanto abre a caixa, para manter o conteúdo em segredo.",al={"conteúdo da caixa","qual é a surpresa"}}},fp="17,178,18.262.0,23.81.0,30.67.0,40.101.0,43.85.0,25.98.0"}
P.entries["quest:95156"] = {n="Stuff 'Em and Stick 'Em",s="Ember precisa de feno da propriedade de Wheeler para consertar bonecos de treinamento desgastados. Os recrutas precisam de alvos resistentes para treinar para a batalha.",h="Ember precisa de feno da propriedade de Wheeler para consertar bonecos de treinamento desgastados.",kw={"ember","propriedade","feno","recrutas","stuff 'em and stick 'em","bonecos de treinamento","campo de treinamento","wheeler"},sec={{t="Alvos Desgastados",b="No campo de treinamento, Ember precisa de feno para consertar os bonecos usados pelos recrutas. O desgaste deles pode deixar os recrutas despreparados para a batalha. Há uma propriedade fora da fortaleza que pertence a Wheeler, e talvez ele tenha feno sobrando. Ember se oferece para compensá-lo pelos suprimentos que ele puder fornecer."},{t="Alvos Novos",b="Ember espera consertar vários alvos assim que o feno chegar. O treinamento dos recrutas depende de bonecos que resistam à prática."}},faq={{q="Por que Ember precisa de feno?",a="Ember precisa de feno para consertar bonecos de treinamento desgastados no campo de treinamento.",al={"feno para ember","por que feno","feno para bonecos de treinamento"}},{q="Quem é Wheeler?",a="Wheeler é o homem que administra a pequena propriedade fora da fortaleza, onde Ember espera conseguir feno sobrando.",al={"propriedade de wheeler","quem tem feno","homem da propriedade"}},{q="Por que os bonecos estão sendo consertados?",a="Os bonecos estão desgastados, e Ember teme que os recrutas fiquem despreparados para a batalha se eles não forem consertados.",al={"bonecos desgastados","alvos de treinamento quebrados","por que consertar os alvos"}},{q="Wheeler será pago pelo feno?",a="Ember diz que Wheeler será compensado se puder ceder alguns suprimentos.",al={"wheeler será pago","compensação pelo feno","pagamento pelos fardos"}},{q="O que Ember fará com o feno?",a="Ember planeja usar o feno para consertar vários alvos de treinamento imediatamente.",al={"para que serve o feno","consertar alvos","uso do feno"}}},fp="23,134,12.279.0,13.157.1,24.72.0,15.102.0,35.106.0,33.64.0,32.73.0"}
P.entries["quest:95161"] = {n="Lembre-se de que eu te amo",s="Lembre-se de que eu te amo é uma missão da Aliança que começa no Orfanato de Ventobravo e envia viajantes para as florestas sombrias da Floresta do Crepúsculo. Com a tarefa de entregar uma sombria Carta Manchada de Sangue, os aventureiros devem rastrear um órfão recém-adotado chamado Jeremy Tececórdio e sua mãe adotiva, Avette Fellwood.",h="Lembre-se de que eu te amo é uma missão da Aliança que começa no Orfanato de Ventobravo e envia viajantes...",kw={"avette fellwood","carta manchada de sangue","floresta do crepúsculo","jeremy tececórdio","remember that i love you","ventobravo","orfanato de ventobravo"},ang={["faction:Alliance"]="Levar lembranças de parentes caídos ou desaparecidos a órfãos adotados evidencia os contínuos custos pessoais do estado turbulento do reino.",["race:Human"]="Para os humanos de Ventobravo, essa tarefa une o coração relativamente seguro do reino aos assentamentos assombrados e esquecidos da Floresta do Crepúsculo."},sec={{t="Uma Mensagem para um Órfão",b="As crianças do Orfanato de Ventobravo carregam fardos pesados, tendo perdido suas famílias para guerras, dificuldades e o caos que assola o reino. Jeremy Tececórdio era um desses tutelados até ser adotado recentemente por uma mulher chamada Avette Fellwood. Embora a vida nas matas sombrias da Floresta do Crepúsculo seja repleta de perigos e trabalho árduo, as cuidadoras do orfanato acreditavam que isso lhe oferecia a chance de ter uma família em vez de continuar trancado na cidade."},{t="Uma Lembrança Sombria",b="A missão gira em torno de transportar uma Carta Manchada de Sangue destinada a Jeremy, enviada aos cuidados de Avette Fellwood. As informações conduzem os viajantes para o sul, passando pela segurança da Floresta de Elwynn e adentrando as sombras da Floresta do Crepúsculo. A natureza lúgubre do pacote sugere uma tragédia passada que perseguiu o jovem Jeremy para muito além dos portões de Ventobravo."}},faq={{q="Quem é Jeremy Tececórdio?",a="Jeremy Tececórdio é um jovem rapaz criado anteriormente no Orfanato de Ventobravo. Ele foi adotado recentemente por Avette Fellwood, deixando a cidade para viver e trabalhar nas terras sombrias da Floresta do Crepúsculo.",al={"jeremy","quem é jeremy","órfão jeremy"}},{q="Quem é Avette Fellwood?",a="Avette Fellwood é a recém-adotiva mãe de Jeremy, que reside na Floresta do Crepúsculo. As matronas de Ventobravo a consideram uma mulher doce, que provavelmente acolheu Jeremy para conseguir um par extra de mãos em suas tarefas diárias.",al={"avette","quem é avette","mãe adotiva"}},{q="O que é a Carta Manchada de Sangue?",a="A Carta Manchada de Sangue é um item de entrega sombrio destinado a Jeremy Tececórdio e entregue diretamente nas mãos de sua guardiã adotiva, Avette Fellwood, carregando ecos de violência ou tragédia.",al={"carta manchada de sangue","a carta","o que é a carta"}},{q="Onde encontro Avette Fellwood?",a="Avette Fellwood reside na Floresta do Crepúsculo, o território florestal escuro localizado diretamente ao sul da Floresta de Elwynn, do outro lado do rio.",al={"localização de avette fellwood","onde está avette","encontrar avette"}},{q="Por que Jeremy foi enviado para a Floresta do Crepúsculo?",a="Jeremy foi adotado no Orfanato de Ventobravo. Embora a Floresta do Crepúsculo seja uma terra perigosa e ameaçadora, suas cuidadoras acreditavam que viver com uma família e ajudar no trabalho honesto era melhor do que continuar sendo um órfão institucionalizado.",al={"por que floresta do crepúsculo","por que jeremy saiu de ventobravo","orfanato floresta do crepúsculo"}},{q="Qual facção pode fazer esta missão?",a="Esta missão é exclusiva da Aliança, originando-se na capital humana de Ventobravo e seguindo para o território controlado pela Aliança na Floresta do Crepúsculo.",al={"é da aliança","apenas aliança","missão da horda"}}},fp="24,136,23.349.0,12.253.1,26.146.0,23.196.0,33.150.0,32.101.0,32.173.0,34.125.0"}
P.entries["quest:95162"] = {n="Paletusk Harvesting",s="Na'zok pede que você reúna carne de paletusk perto de Bolder'ok. O rancho alimenta os ogros próximos e abastece Rog'mar enquanto a guerra avança.",h="Na'zok pede que você reúna carne de paletusk perto de Bolder'ok.",kw={"carne de javali","bolder'ok","na'zok","ogros","paletusk","coleta de paletusk","rancho","rog'mar"},sec={{t="Carne para o rancho",b="Na'zok precisa de mais carne no rancho perto de Bolder'ok, onde os ogros deixam Na'zok ficar enquanto a carne continuar chegando. Com o avanço da guerra, a necessidade de comida aumenta, e os ogros começam a ver Na'zok como a próxima refeição. Você deve reunir pedaços de carne de javali para os ogros famintos e Rog'mar."}},faq={{q="Quem está pedindo carne?",a="Na'zok pede que você reúna carne de javali perto de Bolder'ok para os ogros e Rog'mar.",al={"quem precisa de carne","pedido de na'zok","quem é na'zok"}},{q="Por que Na'zok precisa da carne?",a="O rancho é uma das poucas fontes de alimento de Na'zok, e os ogros deixam Na'zok ficar enquanto a carne continuar chegando.",al={"por que carne","por que reunir carne de javali","ogros famintos"}},{q="Quem é Rog'mar?",a="Rog'mar é um povoado, não uma pessoa. Na'zok quer que sobre carne suficiente para abastecê-lo.",al={"carne para rog'mar"}},{q="Onde está Na'zok?",a="Na'zok está perto de Bolder'ok.",al={"localização de na'zok","onde fica o rancho"}},{q="Que carne é necessária?",a="Na'zok pede pedaços de carne de javali de paletusk.",al={"carne de javali","carne de paletusk","pedaços de carne"}}},fp="19,126,18.294.0,23.77.0,30.106.0,15.87.0,16.25.0,20.50.0"}
P.entries["quest:95163"] = {n="Drive Them Back",s="Na'zok pede que você leve os Young Paletusks fugidos de volta à fazenda dele, perto de Bolder'ok. Os filhotes cruzaram o rio, e precisam voltar aos chiqueiros.",h="Na'zok pede que você leve os Young Paletusks fugidos de volta à fazenda dele, perto de Bolder'ok.",kw={"bolder'ok","filhotes fugidos","fazenda","gorgegut","na'zok","paletusk","porcos","young paletusks"},sec={{t="Os filhotes fugidos",b="A fazenda de Na'zok, perto de Bolder'ok, tem mais porcos soltos pelo vale do que nos chiqueiros. Gorgegut não tem sido um trabalhador rural ideal, embora mantenha os humanos afastados. Alguns Young Paletusks cruzaram o rio, e são pequenos demais para serem colhidos no campo. Na'zok lhe dá um pedaço de pau para levá-los de volta aos chiqueiros."}},faq={{q="Por que os filhotes saíram dos chiqueiros?",a="Alguns Young Paletusks fugiram da fazenda de Na'zok e cruzaram o rio.",al={"filhotes fugidos","porcos soltos","por que os porcos estão fora"}},{q="Quem é Gorgegut?",a="Gorgegut é trabalhador rural de Na'zok, embora Na'zok diga que ele deixa a desejar.",al={"gorgegut trabalhador rural","quem é gorgegut","homem da fazenda de porcos"}},{q="Por que levar os Young Paletusks de volta?",a="Os Young Paletusks são pequenos demais para serem colhidos no campo, então Na'zok quer que voltem à fazenda.",al={"devolver os filhotes","por que trazer os porcos de volta","young paletusk"}},{q="Onde fica a fazenda de Na'zok?",a="A fazenda de Na'zok fica perto de Bolder'ok.",al={"localização da fazenda de na'zok","fazenda perto de bolder'ok","onde fica a fazenda de porcos"}}},fp="15,148,19.313.0,38.70.0,16.78.0,35.106.0,23.32.0"}
P.entries["quest:95165"] = {n="See Ya, Scallywags!",s="Um mestre do cais tem um plano para os três barcos do Eastsea. Você deve instalar cargas temporizadas nos cascos e deixá-lo detoná-las.",h="Um mestre do cais tem um plano para os três barcos do Eastsea.",kw={"barcos","canhões","eastsea","pólvora","carga explosiva remota","até mais, patifes","cargas temporizadas","mestre do cais"},sec={{t="Cargas a Bordo",b="O mestre do cais aproveita a pólvora que você roubou para preparar cargas temporizadas para os barcos do Eastsea. Você deve colocar uma no casco de cada embarcação, perto dos canhões. Depois de instalá-las, afaste-se para que ele possa detonar os explosivos."}},faq={{q="O que o mestre do cais quer que eu faça?",a="Instale uma carga explosiva remota no casco de cada um dos três barcos do Eastsea, perto dos canhões.",al={"o que devo fazer","tarefa dos barcos do eastsea"}},{q="Por que usar a pólvora que roubei?",a="O mestre do cais usa a pólvora para preparar cargas temporizadas para os barcos.",al={"pólvora roubada","para que serve a pólvora"}},{q="Por que instalar as cargas perto dos canhões?",a="O mestre do cais diz que a pólvora deixará os explosivos mais potentes perto dos canhões.",al={"carga perto dos canhões","onde colocar as cargas"}},{q="Quantos barcos estão envolvidos?",a="Você deve colocar cargas em cada um dos três barcos do Eastsea.",al={"quantos barcos","três barcos"}},{q="O que o mestre do cais sabe sobre explosivos?",a="Ele diz que costumava ganhar a vida de um jeito menos honesto.",al={"explosivos do mestre do cais","por que ele sabe fazer bombas"}}},fp="19,136,14.230.0,40.101.0,30.71.0,39.91.0,28.64.0,48.45.0"}
P.entries["quest:95183"] = {n="Step One: Rock",s="Hamur, em Bolder'ok, quer pedras boas do rio próximo. Leve-as até ele para que possa fazer uma arma minúscula para uma criaturinha.",h="Hamur, em Bolder'ok, quer pedras boas do rio próximo.",kw={"bolder'ok","pedras boas","hamur","arma ogra","rio","arma minúscula"},sec={{t="O pedido de Hamur",b="Hamur, em Bolder'ok, diz que você é pequeno demais para empunhar uma boa arma ogra. Ele se oferece para fazer uma arma minúscula para você se trouxer pedras boas. Ele quer pedras do rio que fica fora de Bolder'ok, onde só as melhores servem."}},faq={{q="Quem é Hamur?",a="Hamur fica em Bolder'ok e se oferece para fazer uma arma minúscula para você se trouxer pedras boas.",al={"quem é hamur","quem quer pedras"}},{q="Onde encontro as pedras?",a="Hamur pede pedras boas do rio que fica fora de Bolder'ok.",al={"local das pedras","onde ficam as pedras"}},{q="Por que Hamur quer pedras?",a="Hamur diz que usará as pedras boas para fazer uma arma minúscula para uma criaturinha.",al={"por que pedras","para que servem as pedras"}},{q="Que tipo de pedras Hamur quer?",a="Hamur quer pedras boas do rio que fica fora de Bolder'ok; ele diz que nem toda pedra serve.",al={"pedras boas","quais pedras"}}},fp="14,119,15.217.0,13.87.0,26.59.0,26.80.0,35.92.0"}
P.entries["quest:95184"] = {n="The Sharpest of Blades",s="Ember Bladewhisper quer pedras de amolar para os recrutas de Farholde. Uma lâmina experiente pode fazer a diferença entre a vitória e a morte.",h="Ember Bladewhisper quer pedras de amolar para os recrutas de Farholde.",kw={"ember bladewhisper","farholde","recrutas","pedras de amolar","solid sharpening stones","campos de treinamento"},sec={{t="Lâminas para recrutas",b="Nos campos de treinamento de Farholde, Ember Bladewhisper percebe que os recrutas pouco sabem sobre a diferença entre uma espada de treino e uma lâmina de veterano bem cuidada. Pedem a você que leve pedras de amolar para ela, para que os recrutas aprendam o que significa ter um fio afiado."}},faq={{q="Quem precisa de pedras de amolar?",a="Ember Bladewhisper pede pedras de amolar nos campos de treinamento de Farholde.",al={"quem quer pedras","pedras de ember bladewhisper"}},{q="Por que Ember quer as pedras?",a="Ela quer que os recrutas entendam a diferença entre uma lâmina afiada e uma espada de treino.",al={"por que pedras de amolar","para que servem as pedras"}},{q="Onde devo levar as pedras?",a="Leve as pedras de amolar para Ember Bladewhisper nos campos de treinamento de Farholde.",al={"onde levar as pedras","pedras de farholde"}},{q="De que tipo de pedras Ember precisa?",a="Ember pede Solid Sharpening Stones.",al={"quais pedras","tipo de pedra"}}},fp="22,137,19.258.0,28.79.0,31.89.0,32.83.0,36.39.0"}
P.entries["quest:95189"] = {n="Brasão de Lordaeron",s="O Brasão de Lordaeron é uma relíquia desgastada que ostenta a marca régia do reino caído do norte. Encontradas em meio às ruínas desoladas de Capital City, tais relíquias tornaram-se escassas desde a queda do reino, e alguém em Ventobravo estaria muito interessado em pôr as mãos nesta.",h="O Brasão de Lordaeron é uma relíquia desgastada que ostenta a marca régia do reino caído do norte.",kw={"crest of lordaeron","heraldica","lady dena kennedy","lordaeron","reliquia","ruínas de lordaeron","ventobravo","clareiras de tirisfal"},ang={["faction:Alliance"]="O emblema de Lordaeron representa o pilar fundador da Aliança original, tornando sua recuperação uma vitória simbólica contra o apagamento total causado pelo Flagelo e pelos Renegados.",["race:Human"]="Para os humanos, em particular aqueles cujas famílias antes chamavam o norte de lar, o brasão é uma lembrança tocante do grandioso reino que outrora liderou a Aliança."},sec={{t="Uma Herança Despedaçada",b="Quando o Flagelo assolou o reino de Lordaeron, seus palácios, arquivos e orgulhosas insígnias foram em grande parte obliterados ou deixados para definhar sob a sombra de Cidade Baixa. Artefatos físicos sobreviventes que exibem o brasão real são extremamente raros. Recuperar um brasão intacto ou desgastado das ruínas do norte representa um pedaço tangível da história humana resgatado do esquecimento."},{t="Refúgio no Sul",b="Após a Terceira Guerra, milhares de refugiados do norte fugiram para o sul em direção ao Reino de Ventobravo, levando consigo apenas lembranças de sua terra natal. Em Ventobravo, Lady Dena Kennedy tem grande interesse em adquirir tais vestígios de Lordaeron, tornando relíquias como este brasão profundamente estimadas na capital do sul."}},faq={{q="O que é o Brasão de Lordaeron?",a="É um emblema heráldico desgastado que exibe a marca oficial de Lordaeron. Deixado para trás após o reino cair perante o Flagelo, é uma relíquia histórica valiosa para os sobreviventes humanos.",al={"crest of lordaeron","o que e crest of lordaeron","item crest of lordaeron"}},{q="Quem deseja o Brasão de Lordaeron?",a="O brasão é entregue a Lady Dena Kennedy, uma patrona aristocrática em Ventobravo que busca colecionar e preservar artefatos raros do reino caído do norte.",al={"quem recebe o brasao","onde levar crest of lordaeron","entregar brasao"}},{q="Onde o brasão foi encontrado?",a="Ele foi recuperado das Ruínas de Lordaeron em Clareiras de Tirisfal, a capital arruinada que hoje fica diretamente acima da fortaleza dos Renegados, Cidade Baixa.",al={"localizacao do brasao","brasao das ruinas","onde conseguir o brasao"}},{q="Por que os artefatos de Lordaeron são tão raros?",a="A queda rápida e catastrófica do reino durante a Terceira Guerra resultou no massacre sistemático de seu povo e na ruína de suas propriedades. Raríssimas relíquias de família sobreviveram ao Flagelo e à subsequente ascensão dos Renegados.",al={"por que reliquias de lordaeron sao raras","raridade de artefatos de lordaeron"}},{q="Por que Ventobravo se importa com as relíquias de Lordaeron?",a="Ventobravo acolheu levas de refugiados, cavaleiros e nobres que fugiram da devastação do norte. Preservar relíquias homenageia o reino irmão caído da Aliança e mantém viva a herança dos humanos do norte.",al={"por que ventobravo se importa","reliquias de lordaeron em ventobravo"}},{q="Quem é Lady Dena Kennedy?",a="Lady Dena Kennedy é uma nobre residente em Ventobravo que tem um interesse ativo em resgatar vestígios históricos e relíquias de família originárias de Lordaeron.",al={"lady dena kennedy","quem e dena kennedy"}}},fp="18,193,20.268.0,19.292.0,31.177.0,33.110.0,26.141.0,41.176.0,50.174.0,25.126.0"}
P.entries["quest:95194"] = {n="Our Man in Theramore",s="A AVIN busca sua ajuda após um homem levado à costa da Ilha Theramore afirmar ser Varian Wrynn. Encontre o agente Sully na estalagem para saber o que vem a seguir.",h="A AVIN busca sua ajuda após um homem levado à costa da Ilha Theramore afirmar ser Varian Wrynn.",kw={"jaina proudmore","nosso homem em theramore","avin","rei de ventobravo","sully","ilha theramore","varian wrynn","washed ashore"},sec={{t="Uma alegação em Theramore",b="A AVIN soube que os fuzileiros navais de Jaina Proudmore levaram um homem à costa da Ilha Theramore. Ele diz ser Varian Wrynn, o rei desaparecido de Ventobravo. O agente Sully espera na estalagem, e a AVIN quer que você descubra o que está acontecendo."}},faq={{q="Por que a AVIN me quer em Theramore?",a="Um homem encontrado na costa da Ilha Theramore afirma ser Varian Wrynn. A AVIN quer que você encontre seu agente Sully e descubra o que está acontecendo.",al={"por que theramore","avin theramore","o que a avin precisa"}},{q="Quem é Sully?",a="Sully é um anão e agente da AVIN lotado na Ilha Theramore. Ele espera por você na estalagem.",al={"quem é sully","sully theramore","agente anão"}},{q="Quem levou o homem à costa?",a="Os fuzileiros navais de Jaina Proudmore levaram o homem a Theramore depois de encontrá-lo na praia.",al={"homem levado à costa","quem encontrou varian","fuzileiros navais de theramore"}},{q="O que o homem levado à costa afirma?",a="Ele afirma ser Varian Wrynn, o rei de Ventobravo.",al={"homem na praia","alegação de varian","é mesmo varian"}},{q="Onde posso encontrar Sully?",a="Sully espera na estalagem da Ilha Theramore.",al={"localização de sully","onde está o agente","estalagem de theramore"}}},fp="20,151,20.235.0,35.141.0,13.97.0,27.99.0,34.52.0,23.46.0"}
P.entries["quest:95195"] = {n="Insígnia ensanguentada",s="As Insígnia ensanguentadas são vestígios trágicos dos defensores caídos de Lordaeron, espalhadas entre as ruínas assoladas do reino. Ostentando os antigos brasões da Aliança, esses distintivos desgastados representam soldados cujas famílias fugiram para o sul, rumo a Ventobravo, durante a Terceira Guerra.",h="As Insígnia ensanguentadas são vestígios trágicos dos defensores caídos de Lordaeron, espalhadas entre as...",kw={"aliança","bloodied insignia","lordaeron","marcus jonas","refugiados","ruínas de lordaeron","ventobravo","terceira guerra"},ang={["class:Paladin"]="Muitos dos caídos na capital lutaram ao lado dos Cavaleiros do Punho de Prata; recuperar suas medalhas honra os irmãos e irmãs perdidos da sagrada ordem.",["faction:Alliance"]="Entregar essas insígnias ao General Marcus Jonas serve como um ato de dever e lembrança para com os soldados que deram suas vidas defendendo a Aliança original.",["race:Human"]="Para os humanos da Aliança, esses distintivos são lembranças solenes da queda do maior reino humano, conectando os refugiados que vivem em Ventobravo aos seus parentes caídos no norte."},sec={{t="Símbolos dos Caídos",b="Quando o Príncipe Arthas retornou para assolar Lordaeron com o Flagelo, suas grandiosas forças militares foram subjugadas e massacradas. Inúmeros soldados pereceram defendendo a Capital e as terras ao redor, deixando para trás poucos vestígios físicos além de armaduras enferrujadas e latão manchado de sangue. Essas antigas insígnias da Aliança pertenciam aos homens e mulheres que resistiram ao avanço dos mortos-vivos. Pisoteada no solo e nos escombros das ruínas, cada medalha é uma relíquia da última e desesperada resistência do reino."},{t="Um Mensageiro para os Exilados",b="Muitos sobreviventes de Lordaeron fugiram para o sul através do mar, estabelecendo-se como refugiados em Ventobravo. Décadas de aliança e laços de parentesco unem os dois reinos humanos, fazendo com que muitos no sul anseiem por respostas sobre seus entes queridos desaparecidos. O General Marcus Jonas, comandante da guarda da cidade de Ventobravo, recebe a custódia dessas insígnias ensanguentadas para que a memória dos defensores do norte seja preservada e suas famílias sobreviventes possam finalmente conhecer seu destino."}},faq={{q="O que são as Insígnia ensanguentadas?",a="São medalhas militares usadas por soldados do Reino de Lordaeron que lutaram e morreram sob o estandarte da Aliança durante a Terceira Guerra.",al={"item bloodied insignia","o que é esta insígnia","história da insígnia"}},{q="Onde essas insígnias são encontradas?",a="Elas são recuperadas por todas as Ruínas de Lordaeron, em Clareiras de Tirisfal, onde os defensores do reino fizeram sua última resistência contra o Flagelo.",al={"onde caem as insígnias","localização da insígnia","distintivos das ruínas de lordaeron"}},{q="Por que o General Marcus Jonas quer essas insígnias?",a="O General Marcus Jonas supervisiona a defesa em Ventobravo, onde inúmeros refugiados do norte agora habitam. Ele reúne esses vestígios para que os sacrifícios dos guerreiros de Lordaeron sejam honrados e seus parentes vivos no sul possam encontrar paz.",al={"quem é marcus jonas","por que entregar para ventobravo","insígnia de marcus jonas"}},{q="Por que os soldados de Lordaeron usavam insígnias da Aliança?",a="A Aliança original foi forjada em Lordaeron sob o comando do Rei Terenas Menethil II para derrotar a Horda Antiga. Lordaeron foi o coração e líder da Aliança de Lordaeron durante toda a Segunda e a Terceira Guerra.",al={"brasão da aliança de lordaeron","distintivo da aliança de lordaeron"}},{q="O que aconteceu com os soldados que usavam essas medalhas?",a="Eles foram mortos durante a Terceira Guerra, quando o Príncipe Arthas Menethil traiu o reino, assassinou seu pai e libertou o Flagelo dos mortos-vivos sobre a capital.",al={"o que matou os soldados","destino dos soldados de lordaeron"}},{q="Ainda existem parentes vivos desses soldados?",a="Sim. Milhares de cidadãos e soldados evacuaram Lordaeron durante a peste e as invasões do Flagelo, encontrando por fim santuário no Reino de Ventobravo.",al={"refugiados de lordaeron em ventobravo","quem sente falta destes soldados"}}},fp="17,169,20.402.0,26.384.0,32.119.0,32.141.0,43.191.0,55.176.0,52.147.0,51.144.0"}
P.entries["quest:95196"] = {n="Watch Yer Back",s="Sully McCleary pede que você o encontre perto de um cemitério fora da cidade. Ele quer contar mais sobre sua missão sem que alguém o siga.",h="Sully McCleary pede que você o encontre perto de um cemitério fora da cidade.",kw={"pântano vadeoso","cemitério","missão","sully mccleary","torre","olhe para trás"},sec={{t="Um Encontro Discreto",b="Sully McCleary planeja sair pela porta atrás de você. Depois que ele partir, encontre-o atrás do cemitério fora da cidade e certifique-se de que ninguém o siga."},{t="A Próxima Informação",b="No Pântano Vadeoso, Sully McCleary pede que você investigue uma torre e descubra o que puder. Agora, o trabalho depende do que você encontrar lá."}},faq={{q="Quem está me pedindo para encontrá-lo?",a="Sully McCleary pede que você o encontre atrás do cemitério fora da cidade.",al={"quem é sully","sully mccleary","encontrar sully"}},{q="Onde encontro Sully?",a="Encontre Sully atrás do cemitério fora da cidade, depois que ele sair pela porta atrás de você.",al={"localização de sully","onde encontrá-lo","encontro no cemitério"}},{q="Por que devo garantir que ninguém me siga?",a="Sully pede que você se certifique de que ninguém o siga antes de encontrá-lo.",al={"evitar que alguém siga","por que não ser seguido","ficar de olho nas minhas costas"}},{q="O que Sully quer que eu faça agora?",a="Sully pede que você entre sorrateiramente em uma torre e descubra o que puder.",al={"trabalho na torre","qual é a missão","o que sully pede"}}},fp="14,132,15.159.0,13.135.1,29.70.0,22.91.0,38.66.0,35.63.0"}
P.entries["quest:95198"] = {n="The Return of the King?",s="Um contato envia você disfarçado à Torre dos Magos de Theramore para ouvir notícias sobre o homem encontrado na praia. O que você descobre põe em dúvida um possível resgate do rei.",h="Um contato envia você disfarçado à Torre dos Magos de Theramore para ouvir notícias sobre o homem encontrado...",kw={"alcaz","defias","disfarce","encantamento","jaina","rei","fuzileiro naval de kul tiraz","torre dos magos","theramore"},sec={{t="Na Torre dos Magos",b="Um contato entrega a você um disfarce mágico preparado por magos em casa, para que pareça um fuzileiro naval de Kul Tiraz. Na Torre dos Magos de Theramore, você escuta Jaina e seu círculo íntimo em busca de menções ao homem encontrado na praia. Jaina consegue enxergar através do disfarce, então mantenha distância."},{t="Uma prisão em Alcaz",b="O humano encontrado na praia não é o homem que procuram. Ainda assim, notícias sobre uma prisão em Alcaz e o envolvimento dos Defias dão ao contato motivos para suspeitar que o rei possa ter ficado preso lá. O contato pretende agir e trazer o rei de volta a Ventobravo."}},faq={{q="Quem me dá o disfarce?",a="Um contato entrega a você um disfarce preparado por magos em casa para fazer você parecer um fuzileiro naval de Kul Tiraz.",al={"quem dá o disfarce","quem fornece o disfarce"}},{q="Onde devo escutar?",a="Você é enviado à Torre dos Magos de Theramore para escutar Jaina e seu círculo íntimo.",al={"onde escutar","torre dos magos"}},{q="De quem devo manter distância?",a="Mantenha distância de Jaina, que consegue enxergar através do disfarce.",al={"evitar jaina","disfarce de jaina"}},{q="Com que aparência devo ficar disfarçado?",a="O disfarce deve fazer você parecer um fuzileiro naval de Kul Tiraz.",al={"disfarce de fuzileiro naval","disfarce de kul tiraz"}}},fp="23,172,17.269.0,17.241.1,26.97.0,30.81.0,36.64.0,40.62.0"}
P.entries["quest:952"] = {n="Bosque dos Ancientes",s="Bosque dos Ancientes é uma missão de entrega da Aliança que leva aventureiros de Darnassus até Costa Negra, do outro lado do mar. Encarregado pelo Arquidruida Fandral Guenelmo, o mensageiro leva uma carta a Onu, um venerável Anciente da Tradição que vive ao sul de Auberdine.",h="Bosque dos Ancientes é uma missão de entrega da Aliança que leva aventureiros de Darnassus até Costa Negra...",kw={"anciente da tradição","auberdine","círculo cenariano","costa negra","darnassus","fandral guenelmo","bosque dos ancientes","onu","clareira do oráculo"},ang={["class:Druid"]="Levar mensagens entre o Arquidruida de Darnassus e Onu apresenta aos jovens druidas as diferenças de temperamento entre os anciãos do Círculo Cenariano, contrastando a determinação de Guenelmo com a paciência serena de um Anciente da Tradição.",["faction:Alliance"]="Para os campeões da Aliança que concluem suas tarefas em Darnassus, essa entrega oferece um motivo para conhecer as rotas de hipogrifos e explorar o território costeiro de Costa Negra.",["race:NightElf"]="Essa tarefa marca a transição natural do abrigo de Teldrassil para as terras selvagens do continente de Kalimdor, destacando o contraste filosófico entre Fandral Guenelmo e os ensinamentos de Malfurion Tempesfúria."},sec={{t="Deixando os galhos para trás",b="Depois de ajudar a resolver questões relativas à Clareira do Oráculo, no alto de Teldrassil, os aventureiros são convocados de forma brusca para outra tarefa pelo Arquidruida Fandral Guenelmo. Sem tolerar a ociosidade, Guenelmo encarrega o mensageiro de levar um comunicado urgente pelo mar até as florestas ancestrais de Costa Negra, instruindo-o a embarcar em um hipogrifo na cidade."},{t="Uma diferença de paciência",b="Ao chegar a Costa Negra e viajar para o sul de Auberdine, até o Bosque dos Ancientes, o mensageiro entrega a carta a Onu. O imponente Anciente da Tradição recebe a correspondência com serena reflexão, observando discretamente a impaciência incessante de Guenelmo. Para Onu e os antigos guardiões da floresta, tudo acontece em seu devido tempo: uma sabedoria tranquila e duradoura que Shan'do Malfurion Tempesfúria compreendia, mas que falta claramente a Guenelmo."}},faq={{q="Quem inicia a missão Bosque dos Ancientes?",a="O Arquidruida Fandral Guenelmo oferece a missão no Enclave Cenariano, em Darnassus, depois que você conclui sua tarefa anterior relativa à Clareira do Oráculo.",al={"quem oferece bosque dos ancientes","quem dá a missão bosque dos ancientes","missão de fandral guenelmo"}},{q="Onde fica o Bosque dos Ancientes?",a="O Bosque dos Ancientes fica no continente, em Costa Negra, diretamente ao sul do porto costeiro de Auberdine.",al={"localização do bosque dos ancientes","onde fica o bosque dos ancientes","localização de onu"}},{q="Quem é Onu?",a="Onu é um sábio e venerável Anciente da Tradição que vive em Costa Negra. Como protetor e guardião da sabedoria da natureza, recebe correspondência da liderança druídica de Darnassus.",al={"quem é onu","onu costa negra","onu anciente da tradição"}},{q="Como chegar a Costa Negra saindo de Teldrassil?",a="Os viajantes costumam descer de Darnassus até a Aldeia de Rut'theran e pegar um hipogrifo pelo mar até o porto de Auberdine, em Costa Negra.",al={"como chegar a costa negra","viajar para auberdine","hipogrifo para costa negra"}},{q="Por que Onu menciona Shan'do Tempesfúria?",a="Ao receber a carta, Onu comenta a pressa inquieta do Arquidruida Guenelmo. Ele observa que a floresta segue seu próprio ritmo, uma paciência atemporal que Shan'do Malfurion Tempesfúria compreendia e respeitava.",al={"comentário de onu sobre malfurion","referência a shan'do tempesfúria","por que mencionar shan'do"}},{q="Quais missões vêm antes desta?",a="Esta missão é a etapa final de uma sequência curta de três partes que começa com A Clareira Encantada, segue com Teldrassil e termina enviando você para Costa Negra.",al={"pré-requisitos de bosque dos ancientes","série de missões do bosque dos ancientes","missões anteriores a onu"}}},fx={["00893f03"]={q="Por que o Arquidruida Fandral Guenelmo quer que esta mensagem seja entregue a Onu?",a="Fandral Guenelmo está ansioso para manter uma comunicação estreita com os protetores antigos do outro lado do mar, em Kalimdor. Onu, um Ancestral do Saber enraizado em Costa Negra, estava aguardando notícias do Arquidruida sobre os assuntos em Teldrassil. Agora que Fandral recebeu os últimos relatórios da Clareira do Oráculo, ele está impaciente para transmitir suas descobertas e instruções sem demora, avançando com seus planos para os elfos noturnos.",al={"por que enviar mensagem a onu","motivo de fandral sobre o bosque dos ancientes","por que fandral precisa disso entregue"}},["658e120a"]={q="Por que Fandral Guenelmo escolhe você para entregar sua mensagem?",a="Tendo visto você levar notícias da Clareira do Oráculo para Darnassus, Fandral imagina que você já é capaz de realizar recados delicados através de distâncias. Em vez de desviar emissários Cenarianos experientes ou Sentinelas de seus deveres, ele simplesmente coloca um mensageiro comprovado em serviço para levar sua missiva para Costa Negra.",al={"por que eu, mensagem de fandral","por que enviar o jogador a onu","por que não enviar uma sentinela"}}},fp="21,226,18.230.0,22.341.0,43.135.0,43.109.0,11.160.0,43.126.0,39.192.0,33.143.0"}
P.entries["quest:95204"] = {n="Crest of Lordaeron",s="O Crest of Lordaeron é um artefato histórico desgastado que traz o emblema do reino caído. Como poucos tesouros desse tipo sobreviveram à destruição causada pelo Flagelo, ele é entregue a Urraca Convulserpe na Cidade Baixa para ajudar a preservar o passado dos Renegados.",h="O Crest of Lordaeron é um artefato histórico desgastado que traz o emblema do reino caído.",kw={"crest of lordaeron","renegados","lordaeron","urraca convulserpe","relíquia","cidade baixa"},ang={["faction:Horde"]="Ajudar arquivistas dos Renegados na Cidade Baixa ajuda a preservar o legado material de Lordaeron em meio às ruínas deixadas pelo Flagelo.",["race:Undead"]="Como antigos cidadãos de Lordaeron, os Renegados valorizam as relíquias sobreviventes de seu reino caído como raros remanescentes de suas vidas passadas e de seu patrimônio."},sec={{t="Um Símbolo Sobrevivente do Reino Caído",b="O reino de Lordaeron foi despedaçado durante a Terceira Guerra, deixando pouco para trás além de cinzas, ruínas e a desolação do Flagelo. Como grande parte da cultura material do reino foi aniquilada, insígnias e emblemas sobreviventes como o Crest of Lordaeron são excepcionalmente raros. Para os Renegados que habitam sob as ruínas da Capital City, esses objetos sobreviventes são elos físicos preciosos com a civilização à qual outrora pertenceram."},{t="Preservando o Patrimônio dos Renegados",b="Quando recuperado em outras partes do mundo, o brasão desgastado é entregue a Urraca Convulserpe na Cidade Baixa. Urraca verifica sua autenticidade — chegando a testar o metal com uma mordida — antes de confirmá-lo como uma relíquia autêntica e quase intacta de sua terra natal. Para Urraca e os arquivistas Renegados, cada peça resgatada ajuda a recompor uma história que o Flagelo tentou apagar por completo."}},faq={{q="O que é o Crest of Lordaeron?",a="O Crest of Lordaeron é um emblema desgastado que traz a marca do reino humano caído. Como pouquíssimas relíquias físicas sobreviveram à destruição do Flagelo, é uma peça de história inestimável para aqueles que tentam preservar o legado de Lordaeron.",al={"o que é crest of lordaeron","missão crest of lordaeron","item brasão"}},{q="Quem quer o brasão na Cidade Baixa?",a="O brasão é levado a Urraca Convulserpe, que vive na Cidade Baixa. Urraca inspeciona cuidadosamente e protege os artefatos recuperados ligados ao antigo reino.",al={"quem recebe o brasão","onde entregar o brasão","entrega do brasão cidade baixa"}},{q="Por que Urraca Convulserpe morde o brasão?",a="Ao receber o brasão, Urraca Convulserpe o morde para verificar sua autenticidade e composição material antes de declará-lo uma relíquia genuína e quase intacta de Lordaeron.",al={"por que morder o brasão","oran morde brasão"}},{q="Por que os Renegados valorizam relíquias de Lordaeron?",a="Os Renegados são os remanescentes mortos-vivos da antiga população de Lordaeron. Apesar da condição de mortos-vivos e de sua nova lealdade, relíquias de sua terra natal destruída representam elos tangíveis com sua história e identidade.",al={"por que renegados se importam com lordaeron","relíquias dos renegados"}},{q="O que acontecerá com o brasão após ele ser entregue?",a="Urraca Convulserpe fica responsável pelo brasão para garantir que ele seja mantido em segurança, tratando-o como um precioso tesouro histórico que ajuda a restaurar e recordar o legado de seu reino.",al={"o que acontece com o brasão","preservação do brasão"}},{q="Quão raras são as relíquias sobreviventes de Lordaeron?",a="Emblemas e relíquias físicas anteriores à Terceira Guerra são excepcionalmente escassos. A maioria dos símbolos de Lordaeron foi destruída, saqueada ou corrompida quando Arthas e o Flagelo assolaram o reino.",al={"o brasão é raro","quantos brasões restam"}}},fp="18,148,40.264.0,28.278.0,31.183.0,33.113.0,41.137.0,46.153.0,52.134.0,45.150.0"}
P.entries["quest:95212"] = {n="Never Saddle on Quality",s="Never Saddle on Quality é uma tarefa da Aliança centrada no Rancho Ambarmanso, em Dun Morogh. Tratadores precisam de peles pristinas de leopardo-das-montanhas para confeccionar selas quentes para carneiros de montaria destinados a reforçar a expedição de Alterac. O esforço garante que montarias e cavaleiros possam suportar o frio congelante das montanhas do norte.",h="Never Saddle on Quality é uma tarefa da Aliança centrada no Rancho Ambarmanso, em Dun Morogh.",kw={"alterac","expedição de alterac","rancho ambarmanso","dun morogh","peles de leopardo","never saddle on quality","peles pristinas de leopardo","carneiros","selas"},ang={["class:Hunter"]="A tarefa convoca rastreadores e caçadores habilidosos a buscarem os leopardos-das-montanhas mais ferozes de Dun Morogh para garantir peles pristinas.",["faction:Alliance"]="Os esforços de criação de carneiros do Rancho Ambarmanso fornecem diretamente reforços de montarias para as forças da Aliança que operam nas alturas congelantes de Alterac.",["race:Dwarf"]="Os resistentes carneiros-das-montanhas de Dun Morogh são montarias anãs emblemáticas, e os criadores do Rancho Ambarmanso se recusam a equipá-los com equipamento inferior."},sec={{t="Montando a Expedição",b="No Rancho Ambarmanso, em Dun Morogh, tratadores estão preparando um novo grupo de robustos carneiros-das-montanhas para reforçar a expedição da Aliança que opera em Alterac. No entanto, os preparativos foram interrompidos devido à escassez de material adequado necessário para confeccionar selas duráveis e resistentes ao frio para as feras."},{t="Calor para as Passagens Altas",b="Para suportar o congelamento implacável das Montanhas de Alterac, as montarias da expedição exigem um isolamento espesso e de alta qualidade. Caçadores são enviados aos despenhadeiros orientais para rastrear os maiores e mais ferozes leopardos-das-montanhas de Dun Morogh e recuperar suas peles pristinas, garantindo que as forças da Aliança recebam equipamentos feitos para sobreviver às passagens altas."}},faq={{q="O que é Never Saddle on Quality?",a="Never Saddle on Quality é uma tarefa baseada no Rancho Ambarmanso, em Dun Morogh. Um criador precisa de peles de leopardo de alta qualidade para confeccionar selas resistentes e quentes para um grupo de carneiros que estão sendo preparados como reforços para a expedição de Alterac.",al={"o que é esta missão","missão never saddle on quality","o que é never saddle on quality"}},{q="Por que peles de leopardo são necessárias?",a="As peles são necessárias para confeccionar selas duráveis e quentes para as montarias da expedição. Os leopardos-das-montanhas de Dun Morogh fornecem uma pelagem espessa e isolante, adequada para proteger cavaleiros e feras contra o frio cortante das montanhas de Alterac.",al={"por que peles de leopardo","para que servem as peles","por que peles pristinas"}},{q="Para onde os carneiros estão sendo enviados?",a="As montarias estão destinadas às forças da Aliança envolvidas na expedição de Alterac. Com o clima severo e as operações em andamento nas passagens altas, carneiros de montaria bem equipados são um apoio essencial.",al={"para onde vão os carneiros","quem recebe os carneiros","reforços de alterac"}},{q="Qual é o papel do Rancho Ambarmanso nisso?",a="O Rancho Ambarmanso está localizado nas colinas nevadas de Dun Morogh, a leste de Kharanos. Ele serve como o principal local de criação e treinamento para os carneiros-das-montanhas dos anões.",al={"onde fica o rancho ambarmanso","localização do rancho ambarmanso"}},{q="Onde os leopardos habitam?",a="Os ferozes leopardos-das-neves habitam as cristas e despenhadeiros nevados a leste do Rancho Ambarmanso, em Dun Morogh, onde os caçadores devem rastrear as maiores feras para recuperar couros pristinos.",al={"onde encontrar leopardos","onde estão os leopardos dun morogh"}},{q="Por que a proteção contra o clima frio é tão importante para a expedição?",a="O reino e os picos de Alterac são notoriamente congelantes e açoitados pelo vento. Sem material grosso e de alta qualidade para as selas, montarias e cavaleiros correm risco de congelamento e exaustão no terreno montanhoso.",al={"alterac é frio","por que selas quentes"}}},fp="23,229,23.201.0,26.290.0,32.198.0,29.181.0,30.175.0,37.125.0,27.157.0,63.166.0"}
P.entries["quest:95213"] = {n="Stolen Blasting Powder",s="Stolen Blasting Powder trata de um barril de explosivo perigoso e vazio descoberto entre troggs perto da Pedreira Gol'Bolar. Levar o recipiente desaparecido ao Mestre da Pedreira Thesten expõe uma perigosa falha na segurança da pedreira e nos depósitos de explosivos.",h="Stolen Blasting Powder trata de um barril de explosivo perigoso e vazio descoberto entre troggs perto da...",kw={"pólvora de detonação","dun morogh","barril de pólvora vazio","pedreira gol'bolar","barril de pólvora","mestre da pedreira thesten","stolen blasting powder","thesten","troggs"},ang={["faction:Alliance"]="Proteger as linhas de suprimento e postos avançados de mineração de Dun Morogh contra incursões de troggs é essencial para as operações da Aliança por toda Khaz Modan.",["profession:Engineering"]="Pólvora de detonação é um material volátil perigoso; engenheiros entendem melhor do que ninguém a destruição que troggs poderiam causar com explosivos não autorizados.",["profession:Mining"]="As operações da pedreira dependem de demolições controladas para extrair pedra, mas barris de pólvora desaparecidos sinalizam grave perigo dentro dos fossos de escavação.",["race:Dwarf"]="A Pedreira Gol'Bolar fornece pedras e recursos vitais para Altaforja, tornando a segurança de seus explosivos de mineração uma preocupação urgente para qualquer anão."},sec={{t="Uma Descoberta Perigosa",b="Um barril vazio estampado com avisos de perigo grave revela que pólvora de detonação perigosa escapou de mãos autorizadas na Pedreira Gol'Bolar. Tais explosivos são estritamente reservados para detonações controladas na pedreira sob a autorização direta do mestre da pedreira. Encontrar o barril entre troggs hostis indica que o local de escavação enfrenta uma ameaça muito mais volátil do que interrupções rotineiras de trabalho."},{t="O Alarme do Mestre da Pedreira",b="Devolver o recipiente vazio ao Mestre da Pedreira Thesten confirma os piores temores dos feitores anões. Thesten fica pálido ao ver o barril, percebendo que a pólvora de detonação desaparecida já foi esvaziada e manuseada pelos troggs subterrâneos que infestam a área. A descoberta deixa a liderança da pedreira correndo para avaliar o que as criaturas pretendem explodir a seguir."}},faq={{q="O que é Stolen Blasting Powder?",a="Stolen Blasting Powder é uma missão iniciada ao descobrir um barril de pólvora de detonação vazio estampado com avisos de perigo nas mãos de troggs perto da Pedreira Gol'Bolar. Ela alerta o Mestre da Pedreira Thesten sobre o roubo de suprimentos de mineração voláteis.",al={"o que é stolen blasting powder","missão barril de pólvora","história do barril de pólvora vazio"}},{q="Quem deve receber o barril de pólvora vazio?",a="O barril de pólvora vazio deve ser levado diretamente ao Mestre da Pedreira Thesten, que supervisiona as operações na Pedreira Gol'Bolar em Dun Morogh.",al={"onde levar o barril","quem é thesten","localização do mestre da pedreira"}},{q="Por que a pólvora de detonação roubada é perigosa?",a="O barril traz claramente avisos de autorização do mestre da pedreira e continha pólvora de detonação perigosa. Troggs possuindo ou detonando explosivos pesados ameaçam toda a escavação da pedreira e os assentamentos próximos.",al={"por que a pólvora é perigosa","troggs com explosivos","por que troggs têm pólvora"}},{q="O que é a Pedreira Gol'Bolar?",a="A Pedreira Gol'Bolar é um local de escavação dos anões situado em Dun Morogh, responsável pela extração de pedras e minerais para Altaforja.",al={"onde fica gol bolar","localização da pedreira","gol bolar dun morogh"}},{q="Por que o Mestre da Pedreira Thesten fica pálido?",a="Ao ver o barril vazio, o Mestre da Pedreira Thesten fica visivelmente pálido e pergunta onde ele foi encontrado, reconhecendo imediatamente que o conteúdo perigoso já caiu em mãos de troggs hostis.",al={"por que thesten fica pálido","reação de thesten","o que thesten diz"}},{q="O que os troggs estão fazendo perto da Pedreira Gol'Bolar?",a="Troggs infestaram as partes inferiores e os arredores da Pedreira Gol'Bolar, perturbando os mineradores anões e saqueando equipamentos e pólvora explosiva do local de escavação.",al={"há troggs na pedreira","infestação de troggs em dun morogh","por que troggs estão pegando pólvora"}}},fp="22,191,21.331.0,24.279.1,31.192.0,40.119.0,44.169.0,25.107.0,40.168.0,44.164.0"}
P.entries["quest:95214"] = {n="Stolen Blasting Powder",s="Stolen Blasting Powder é uma missão na Pedreira Gol'Bolar, em Dun Morogh, onde os aventureiros devem recuperar munições desaparecidas. Troggs primitivos fugiram com pólvora explosiva suficiente para nivelar uma ala inteira de uma fortaleza, forçando o Quarrymaster Thesten a recrutar ajuda discreta antes que ocorra uma catástrofe.",h="Stolen Blasting Powder é uma missão na Pedreira Gol'Bolar, em Dun Morogh, onde os aventureiros devem...",kw={"pólvora de detonação","dun morogh","explosivos","pedreira gol'bolar","altaforja","rei magni","mestre de pedreira thesten","thesten","troggs"},ang={["faction:Alliance"]="As rotas de suprimentos e as obras de pedra de Dun Morogh são vitais para o reduto montanhoso da Aliança. Manter a paz e vigiar munições perigosas garante a segurança da Sala do Trono na vizinha Altaforja.",["profession:Mining"]="A pólvora de detonação é uma ferramenta indispensável para desbastar rochas e abrir veios em escavações profundas, mas manuseá-la exige disciplina — perder barris inteiros para habitantes selvagens das cavernas é o pesadelo de qualquer mestre de pedreira.",["race:Dwarf"]="A Pedreira Gol'Bolar abastece o trabalho em pedra e os esforços de escavação de Altaforja. Permitir que troggs subterrâneos transformem explosivos de mineração em armas bem diante da porta do Rei Magni é uma falha de segurança humilhante para qualquer supervisor anão."},sec={{t="Um carregamento desaparecido",b="Na Pedreira Gol'Bolar, em Dun Morogh, as operações dos anões dependem fortemente de pesadas cargas de detonação para quebrar pedras e abrir veios profundos. No entanto, a segurança falhou quando troggs primitivos à espreita nos penhascos próximos conseguiram fugir com uma remessa inteira de pólvora de detonação de alta qualidade. O Quarrymaster Thesten viu-se obrigado a correr para encontrar mãos capazes antes que o bando de ladrões provocasse uma detonação acidental."},{t="Um barril de pólvora nos penhascos",b="O volume total do material desaparecido é estarrecedor: Thesten observa que o barril continha força explosiva suficiente para transformar a grandiosa sala do trono do Rei Magni Barbabronze em um pátio a céu aberto. Os troggs levaram o saque volátil para o leste, em direção aos seus acampamentos rudimentares nas colinas. Deixados por conta própria, seria apenas uma questão de tempo até que os brutos descobrissem o fogo ou batessem pedra contra pedra gerando faíscas."},{t="Resolução silenciosa",b="Assim que as cargas roubadas são arrancadas dos troggs e devolvidas em segurança ao depósito da pedreira, Thesten solta um profundo suspiro de alívio. O mestre da pedreira recompensa The Adventurer com um pedido discreto para não mencionar o pequeno incidente a ninguém."}},faq={{q="Quem é o Quarrymaster Thesten?",a="O Quarrymaster Thesten supervisiona as operações de escavação na Pedreira Gol'Bolar, em Dun Morogh. Responsável pela segurança e produtividade do local de escavação, ele se vê em uma situação embaraçosa depois que um enorme estoque de pólvora de detonação industrial desaparece sob sua supervisão.",al={"quem é thesten","mestre de pedreira thesten","quem dá esta missão"}},{q="Onde a pólvora de detonação roubada pode ser encontrada?",a="A pólvora foi levada pelos troggs que infestam os penhascos e tocas imediatamente a leste da Pedreira Gol'Bolar. Os aventureiros são enviados a esses afloramentos rochosos para recuperar os barris e sacos voláteis das criaturas antes que ocorra um desastre.",al={"onde fica stolen blasting powder","localização dos troggs","localização da pólvora"}},{q="Por que os troggs roubaram a pólvora de detonação?",a="Os troggs são criaturas primitivas e subterrâneas, movidas por astúcia básica e agressividade territorial. Embora tenham saqueado os barris de pólvora dos trabalhadores da pedreira, o Quarrymaster Thesten teme que até mesmo experimentos desajeitados possam levá-los a acidentalmente detonar os explosivos.",al={"por que troggs roubam pólvora","o que troggs querem com pólvora"}},{q="Quão perigosa é a pólvora de detonação roubada?",a="De acordo com o Quarrymaster Thesten, o barril desaparecido continha pólvora explosiva volátil suficiente para transformar a sala do trono do Rei Magni em um pátio a céu aberto. Se detonada de uma só vez na pedreira fechada ou nas cavernas, a força seria devastadora.",al={"quão poderosa é a pólvora","pólvora na sala do trono de magni","a pólvora é perigosa"}},{q="Por que o Quarrymaster Thesten quer que o incidente seja mantido em segredo?",a="Quando você devolve a pólvora, Thesten paga você e pede que não mencione este pequeno incidente a ninguém. Ele não diz o motivo, mas perder tanto explosivo para os troggs é claramente algo que ele prefere manter em segredo.",al={"por que manter em segredo","segredo de thesten","não mencione o incidente"}},{q="O que é a Pedreira Gol'Bolar?",a="A Pedreira Gol'Bolar é um proeminente local de escavação dos anões no leste de Dun Morogh, responsável pela extração de pedra para projetos de construção e engenharia em todo o reino. Seus poços profundos enfrentam regularmente pragas subterrâneas, como troggs que emergem da rocha.",al={"o que é gol bolar","pedreira gol'bolar","onde fica golbolar"}}},fp="22,183,19.282.0,25.250.0,16.202.1,28.188.0,46.166.0,45.194.0,44.189.0,59.199.0,25.191.0"}
P.entries["quest:95216"] = {n="The New Plague",s="The New Plague é uma iniciativa de pesquisa realizada por Theodore Griffs no Boticarium da Cidade Baixa. Investigando relatos de um artrópode letal nas ruínas acima, cujo veneno consome até mesmo carne de morto-vivo, Griffs busca analisar e fazer engenharia reversa das toxinas mortais do organismo.",h="The New Plague é uma iniciativa de pesquisa realizada por Theodore Griffs no Boticarium da Cidade Baixa.",kw={"boticarium","icor","ruínas de lordaeron","the new plague","theodore griffs","cepa tóxica","cidade baixa","witherfang"},ang={["faction:Horde"]="Embora a Horda tolere os Renegados como aliados táticos nos Reinos do Leste, os sinistros experimentos biológicos preparados no Boticarium frequentemente causam inquietação entre os membros mais honrados.",["race:Undead"]="A Real Sociedade de Boticários busca incessantemente toxinas capazes de ferir tanto os vivos quanto os mortos para assegurar a supremacia dos Renegados e proteger sua jovem nação."},sec={{t="A Ambição do Boticário",b="Nos recessos úmidos do Boticarium, a Real Sociedade de Boticários reúne continuamente agentes virulentos de toda Azeroth. Theodore Griffs, um de seus dedicados pesquisadores, rastreia feras exóticas e contaminantes mortais para abastecer a inovação alquímica dos Renegados. Ouvindo rumores de uma criatura peçonhenta rondando a pedra despedaçada acima, Griffs envia aventureiros para adquirir uma amostra viável antes que a oportunidade escape."},{t="Uma Toxina que Dissolve Carne",b="O alvo da pesquisa é Witherfang, um artrópode peçonhento que espreita as ruínas da superfície de Lordaeron. Seu veneno possui a rara e aterrorizante qualidade de decompor não apenas tecido vivo, mas também carne morta e preservada. Para um boticário trabalhando para aprimorar a guerra biológica e proteger o reino dos Renegados, descobrir como tal toxina ignora a resistência necrótica oferece um conhecimento químico inestimável."},{t="Engenharia Reversa do Icor",b="Embora Griffs expresse frustração quando os aventureiros destroem Witherfang em vez de capturá-lo vivo, o icor coletado fornece material suficiente para análise. Ao decompor os fluidos corporais da criatura, o boticário pretende fazer engenharia reversa dos mecanismos virulentos do veneno, garantindo que até mesmo um artrópode esmagado contribua para a crescente destreza química da Cidade Baixa."}},faq={{q="Quem é Theodore Griffs?",a="Theodore Griffs é um pesquisador boticário que atua no Boticarium na Cidade Baixa. Ele investiga toxinas potentes e espécimes exóticos para sintetizar compostos para os Renegados, demonstrando pouca consideração por qualquer um que não saiba apreciar o delicado ofício alquímico.",al={"quem dá the new plague","theodore griffs","quem é theodore griffs"}},{q="O que é Witherfang?",a="Witherfang é um artrópode letal e peçonhento encontrado à espreita nas Ruínas de Lordaeron, acima da Cidade Baixa. Ele produz uma toxina extraordinariamente corrosiva, capaz de dissolver até mesmo a resistente carne de morto-vivo.",al={"o que é witherfang","onde fica witherfang","artrópode das ruínas de lordaeron"}},{q="Por que Theodore Griffs quer o veneno de Witherfang?",a="Theodore Griffs busca estudar o veneno de Witherfang para determinar como suas toxinas corroem a carne de morto-vivo, esperando fazer engenharia reversa da substância em cepas potentes para o arsenal alquímico dos Renegados.",al={"o que theodore quer com witherfang","por que coletar a cepa altamente tóxica"}},{q="Por que Theodore Griffs fica chateado quando você retorna?",a="Theodore Griffs esperava que o espécime fosse mantido intacto ou cuidadosamente extraído, em vez de morto sumariamente. Embora irritado com a morte de Witherfang, ele ainda conseguiu recuperar icor residual suficiente dos restos mortais para estudar suas propriedades.",al={"por que theodore ficou zangado","estraguei a amostra"}},{q="Qual é o propósito do Boticarium?",a="O Boticarium serve como o centro de pesquisas da Real Sociedade de Boticários sob Lordaeron. Descrito como o bairro mais vital da Cidade Baixa, ele é dedicado a testar cepas virulentas, preparar armas alquímicas e fazer experimentos em criaturas exóticas.",al={"propósito do boticarium","por que o boticarium é importante"}},{q="Como Theodore acredita que as cepas virulentas são melhor transmitidas?",a="Segundo Theodore Griffs, o vetor mais potente e confiável para a transmissão virulenta é sempre através da introdução direta na corrente sanguínea.",al={"como o veneno é transmitido","método de transmissão"}}},fp="14,171,25.338.0,24.301.0,29.280.1,23.260.0,19.139.0,49.156.0,45.172.0,40.236.0,64.109.0"}
P.entries["quest:95217"] = {n="The Quarry's Smith",s="The Quarry's Smith é um acordo oferecido por Frast Dokner, um artesão em atividade estabelecido em um acampamento de pedreira. Isolado sem a entrega de suprimentos prevista, o ferreiro recorre a viajantes dispostos a reunir metal bruto e couro resistente para reparos essenciais no acampamento. Em troca dos materiais necessários, Dokner compartilha técnicas práticas de ferraria com aspirantes a metalúrgicos.",h="The Quarry's Smith é um acordo oferecido por Frast Dokner, um artesão em atividade estabelecido em um...",kw={"ferraria","barras de cobre","dun morogh","anão","frast dokner","pedreira gol'bolar","altaforja","the quarry's smith","couros de javali reforçados"},ang={["faction:Alliance"]="Ajudar Dokner garante que a remota pedreira dos anões permaneça operacional, reforçando a infraestrutura local e a prontidão dos equipamentos na região montanhosa e nevada.",["profession:Blacksmithing"]="Frast Dokner atua como um mentor de campo para aprendizes de ferreiro, negociando suas suadas técnicas de forja com qualquer pessoa disposta a fornecer o metal bruto e o couro necessários para manter sua bigorna aquecida.",["profession:Mining"]="Os mineradores que trabalham nas jazidas ao redor encontrarão um consumidor local imediato para suas barras de cobre fundidas, transformando minério bruto em treinamento prático e reparos no acampamento.",["race:Dwarf"]="A Pedreira Gol'Bolar representa o empreendimento e a indústria dos Barbabronze em Dun Morogh, onde a determinação dos anões mantém as forjas acesas mesmo quando as caravanas de suprimentos atrasam."},sec={{t="Escassez na Pedreira",b="A vida em uma escavação ativa exige manutenção constante, desde afiar picaretas e substituir suportes desgastados até reforçar os equipamentos do acampamento. Quando uma remessa vital de suprimentos não chega no prazo previsto, o trabalho diário quase para por completo. Sem novos estoques vindos das principais rotas comerciais, os artesãos no local são forçados a improvisar e recorrer a aventureiros de passagem para manter o acampamento em funcionamento. Frast Dokner, trabalhando na forja em meio a esses atrasos contínuos, depende de qualquer pessoa disposta a conseguir metais básicos e couros, em vez de esperar inutilmente por carroças de transporte que podem estar irremediavelmente atrasadas."},{t="O Acordo de um Aprendiz",b="As guildas tradicionais de ferraria dos anões valorizam a disciplina e métodos rigorosamente guardados, raramente transmitindo segredos de ofício a andarilhos casuais. Dokner, no entanto, equilibra a necessidade local com a etiqueta formal da guilda. Enfrentando uma escassez imediata de cobre maleável e couro durável necessários para consertar ferramentas e equipamentos do acampamento, ele oferece uma troca pragmática: traga os materiais brutos diretamente à sua bigorna, e ele ensinará você suas técnicas pessoais de ferraria. É um acordo mutuamente vantajoso nascido da necessidade da fronteira, trocando valioso conhecimento vocacional por sobrevivência e manutenção imediatas."}},faq={{q="Quem é Frast Dokner?",a="Frast Dokner é um ferreiro experiente estabelecido em um acampamento de pedreira, responsável por manter ferramentas, encaixes estruturais e equipamentos para os trabalhadores no local. Quando atrasos logísticos cortam sua linha de suprimentos habitual, ele toma a iniciativa ao recrutar aventureiros de passagem para obter os materiais brutos de que necessita desesperadamente.",al={"história de frast dokner","quem é o ferreiro da pedreira","ferreiro da pedreira"}},{q="Por que a pedreira precisa de barras de cobre e couros de javali?",a="A escavação e a manutenção do acampamento consomem quantidades enormes de material resistente. O cobre fornece um metal acessível e maleável, adequado para forjar encaixes de reposição, pregos, fechos e tiras de reforço para Ferramentas Quebradas. Os couros de javali reforçados fornecem um couro resistente necessário para foles, coberturas de ferramentas, correias e aventais de proteção que suportam as faíscas severas e o desgaste pesado do trabalho diário na pedreira.",al={"por que barras de cobre e couros de javali","materiais necessários ferreiro da pedreira","materiais de reparo da pedreira"}},{q="Por que o carregamento de suprimentos está atrasado?",a="Embora Frast Dokner não detalhe o motivo específico do atraso, as rotas terrestres de suprimentos através dos penhascos nevados e passagens montanhosas são frequentemente assoladas por nevascas rigorosas, animais selvagens errantes e emboscadas hostis de troggs ou bandidos. Acampamentos de mineração e pedreiras isolados são frequentemente os primeiros assentamentos a sentir o impacto sempre que as carroças de transporte atrasam.",al={"carregamento de suprimentos atrasado","o que aconteceu com os suprimentos","por que os suprimentos estão atrasados"}},{q="O que Frast Dokner oferece em troca dos materiais?",a="Em vez de oferecer apenas moedas, Frast Dokner promete compartilhar suas técnicas pessoais de ferraria com quem reunir os suprimentos necessários. Para um aspirante a artesão, aprender diretamente com um artífice experiente estabelecido em campo oferece percepções práticas sobre metalurgia e manutenção de equipamentos que os salões formais de guilda nas cidades raramente ensinam a novatos.",al={"história da recompensa do ferreiro da pedreira","o que frast ensina","técnicas de ferraria de frast"}},{q="Onde fica esta pedreira?",a="Frast Dokner trabalha em Dun Morogh na Pedreira Gol'Bolar, um local de escavação dos anões situado no sopé nevado ao sul de Kharanos. A pedreira enfrenta pressões operacionais constantes decorrentes do rigoroso clima de inverno e de troggs subterrâneos agressivos que rotineiramente atacam os mineradores e perturbam os comboios de comércio que viajam a partir de Altaforja.",al={"qual pedreira é esta","onde fica frast dokner","localização do ferreiro da pedreira"}},{q="Frast Dokner é afiliado a Altaforja?",a="Sim, Frast Dokner e o acampamento da pedreira operam sob o domínio do clã Barbabronze e do Reino de Altaforja. A extração de pedra e minério das montanhas de Dun Morogh é vital para os projetos de construção e fortificações defensivas do reino dos anões, tornando ferreiros locais como Dokner essenciais para a força industrial de Altaforja.",al={"frast dokner altaforja","a pedreira faz parte de altaforja","lealdade dos anões da pedreira"}}},fp="18,217,23.504.0,23.468.0,20.252.0,52.315.0,32.278.0,59.287.0,29.246.0,42.258.0"}
P.entries["quest:95219"] = {n="From Port to Port",s="Um vendedor do porto envia você com um barril cuidadosamente embalado ao Domínio de Plumaluna. A longa jornada exige cuidado.",h="Um vendedor do porto envia você com um barril cuidadosamente embalado ao Domínio de Plumaluna.",kw={"barril","entrega","domínio de plumaluna","feralas","de porto em porto","mardrack greenwell","porto detonapavio"},sec={{t="Um cliente distante",b="Um vendedor tem um cliente no Domínio de Plumaluna, em Feralas, e você leva até lá um barril do Porto Detonapavio. O vendedor diz que ele está embalado hermeticamente, mas alerta que algo pode fazê-lo explodir. Manuseie o barril com cuidado no caminho até Mardrack Greenwell."}},faq={{q="O que estou entregando?",a="Você está levando um barril do Porto Detonapavio para Mardrack Greenwell, no Domínio de Plumaluna.",al={"o que há no barril","entrega do porto detonapavio","barril do porto"}},{q="Para onde devo levar o barril?",a="O barril deve ser entregue a Mardrack Greenwell, no Domínio de Plumaluna, em Feralas.",al={"onde entregar","entrega em plumaluna","barril em feralas"}},{q="Por que devo manuseá-lo com cuidado?",a="O vendedor alerta que algo pode fazer o barril embalado hermeticamente explodir.",al={"o barril é perigoso","por que ter cuidado","o que pode fazê-lo explodir"}},{q="Quem embalou o barril?",a="Um dos homens do vendedor embalou o barril hermeticamente.",al={"quem embalou o produto do porto","embalagem hermética","homem do vendedor"}}},fp="17,112,18.250.0,21.91.0,27.78.0,33.71.0,20.49.0"}
P.entries["quest:95248"] = {n="To the Summit of Eternity",s="Depois de proteger a aldeia dos sobreviventes contra o Flagelo, pedem que você suba até Summit of Eternity. Os aldeões querem respostas dos druidas que protegem a grande árvore e o poço. Eles se perguntam por que nenhum auxílio ou mensagem chegou em cinco anos.",h="Depois de proteger a aldeia dos sobreviventes contra o Flagelo, pedem que você suba até Summit of Eternity.",kw={"druidas","grande árvore","flagelo","summit of eternity","sobreviventes","aldeia","poço"},ang={["class:Druid"]="Como druida, os sobreviventes esperam que você explique por que sua ordem no pico nunca entrou em contato com eles durante os cinco anos de isolamento."},sec={{t="Perguntas para Summit of Eternity",b="Depois de afastar o Flagelo o bastante para tornar o assentamento seguro, você vê os aldeões voltarem o olhar para o alto pico. Eles sabem que druidas vivem no topo de Summit of Eternity, vigiando a grande árvore e o poço.\n\nMas cinco anos de isolamento os deixaram amargurados e perplexos. Eles querem que você suba até o alto e pergunte por que esses guardiões nunca enviaram auxílio nem avisaram o mundo de que sobreviveram."}},faq={{q="Por que você foi enviado a Summit of Eternity?",a="Os sobreviventes da aldeia querem saber por que os druidas que protegem o pico nunca ofereceram ajuda nem avisaram que seu povo ainda estava vivo.",al={"por que ir ao pico","druidas de summit of eternity","por que falar com os druidas"}},{q="Há quanto tempo os sobreviventes estão presos aqui?",a="Os aldeões passaram cinco anos suportando o Flagelo ao redor do assentamento.",al={"há quanto tempo a aldeia está presa","tempo na aldeia dos sobreviventes","há quanto tempo os sobreviventes resistem"}},{q="Quem vive em Summit of Eternity?",a="Druidas vivem no pico, onde vigiam a grande árvore e o poço.",al={"o que os druidas protegem","druidas no pico","quem está no pico"}},{q="Os druidas chegaram a entrar em contato com a aldeia dos sobreviventes?",a="Durante os cinco anos de isolamento dos sobreviventes, os druidas nunca enviaram uma mensagem nem entraram em contato com ninguém em nome deles.",al={"os druidas enviaram ajuda","silêncio dos druidas","por que os druidas não ajudaram"}}},fp="25,249,24.421.0,43.143.0,47.84.0,38.78.0,49.116.0"}
P.entries["quest:95250"] = {n="Abominable Creatures",s="Abominable Creatures é uma missão concedida pelo Captain Truman, um lealista humano que aguarda desesperadamente por reforços nos arredores da capital caída de Lordaeron. Acreditando que seu comandante — um reverenciado Grand Marshal — ainda luta bravamente nas Ruínas de Lordaeron próximas, Truman implora a um aventureiro capaz que o encontre. A missão expõe o destino sombrio dos defensores perdidos do reino e a hostilidade amarga que arde entre os lealistas sobreviventes.",h="Abominable Creatures é uma missão concedida pelo Captain Truman, um lealista humano que aguarda...",kw={"abominable creatures","captain truman","grand marshal","head of the baron","lordaeron","ruínas de lordaeron","the baron","true sons of lordaeron"},ang={["faction:Alliance"]="A missão destaca a situação perigosa e isolada dos remanescentes alinhados à Aliança tentando operar dentro das ruínas assoladas do norte de Lordaeron. Ela enfatiza como os destacamentos lealistas remanescentes lutam contra o declínio da esperança e o desgaste psicológico de combater monstruosidades avassaladoras.",["race:Human"]="Aventureiros humanos testemunham o destino desolador da liderança caída de Lordaeron, já que até mesmo um estimado Grand Marshal foi transformado em um grotesco horror morto-vivo. O luto amargo e o fervor nacionalista do Captain Truman refletem o trauma recente carregado pelos sobreviventes humanos desesperados para recuperar seu lar ancestral.",["race:Undead"]="Para os Renegados, a transformação grotesca de the Baron é uma lembrança sombria de como o Flagelo mutilou os melhores defensores de Lordaeron em abominações monstruosas. O juramento do Captain Truman de purgar as ruínas de todas as feras e mortos-vivos reflete a hostilidade implacável que os lealistas vivos guardam contra o povo da Cidade Baixa."},sec={{t="Uma Vigília Desesperada",b="Captain Truman permanece vigilante em seu posto, aguardando ansiosamente por reforços há muito esperados para apoiar a defesa de Lordaeron. Confiante na proeza marcial de seu superior — um renomado Grand Marshal a quem descreve como um herói alto e escultural —, Truman continua preso ao dever após receber ordens de manter a posição enquanto seu comandante avançava para o combate em andamento. Nutrindo profunda desconfiança em relação a forasteiros e desprezando abertamente aqueles que considera raças inferiores, o capitão se recusa a confiar em irregulares locais. Quando um viajante capaz se aproxima, Truman aproveita a oportunidade para pedir ajuda, implorando para que alguém se aventure no território arruinado a fim de verificar o bem-estar de seu mestre e avaliar a batalha."},{t="As Ruínas de Lordaeron",b="A busca direciona os aventureiros diretamente para as perigosas Ruínas de Lordaeron, a capital destruída que caiu para o Flagelo durante a Terceira Guerra. Embora Captain Truman espere que seu glorioso líder esteja triunfante sobre os caídos, a realidade dentro da cidade assolada é muito mais sombria. As ruínas estão tomadas por horrores, remanescentes mortos-vivos e abominações vagando pelas praças de pedra quebradas. Percorrer essas ruas devastadas exige confrontar a verdade brutal do que aconteceu com os defensores que se aventuraram na cidade. Em vez de encontrar um cavaleiro impecável mantendo a posição, os viajantes descobrem que o comandante teve um fim trágico e distorcido entre as monstruosidades que ocupam os pátios."},{t="Uma Revelação Horripilante",b="Ao localizar o comandante desaparecido, designado como the Baron, os aventureiros fazem uma descoberta estarrecedora: o herói outrora escultural foi transformado em uma grotesca monstruosidade morta-viva. Cumprir a sombria tarefa exige matar a criatura e levar a Head of the Baron de volta ao Captain Truman. Ao ser apresentado à cabeça decepada de seu antigo senhor, Truman reage com choque, horror e profunda repulsa. Incapaz de aceitar o terrível destino de seu comandante, o capitão explode em amarga indignação, acusando o aventureiro de estar aliado a monstros e jurando que os verdadeiros filhos de Lordaeron um dia recuperarão sua terra e purgarão todas as feras."}},faq={{q="Quem dá a missão Abominable Creatures?",a="A missão é oferecida pelo Captain Truman, um lealista humano estacionado na região ao redor do reino caído. Mantendo ansiosamente seu posto enquanto aguarda reforços, Truman busca desesperadamente notícias de seu comandante, um reverenciado Grand Marshal que avançou para as Ruínas de Lordaeron próximas.",al={"quem dá abominable creatures","doador da missão abominable creatures","onde começar abominable creatures"}},{q="Onde ocorre a missão Abominable Creatures?",a="A missão direciona os aventureiros para as Ruínas de Lordaeron, a capital devastada e tomada por horrores do Flagelo e remanescentes mortos-vivos. Captain Truman mantém um posto fora da capital assolada, pedindo a viajantes corajosos que se aventurem diretamente nas ruínas perigosas para localizar seu superior desaparecido.",al={"local de abominable creatures","onde abominable creatures é concluída","zona de abominable creatures"}},{q="Quem é o mestre do Captain Truman?",a="Captain Truman refere-se ao seu mestre como o Grand Marshal, elogiando-o como um herói militar alto e escultural. No entanto, os objetivos da missão referem-se a este nobre desaparecido como the Baron, indicando que ele era um aristocrata de alto escalão e comandante militar liderando a defesa do reino.",al={"quem é o comandante de truman","identidade do grand marshal truman","quem é the baron"}},{q="O que aconteceu com o Grand Marshal nas Ruínas de Lordaeron?",a="Em vez de resistir vitoriosamente, o Grand Marshal foi morto e transformado em uma monstruosa criatura morta-viva dentro das Ruínas de Lordaeron. Quando os aventureiros o localizam, encontram uma abominação designada como the Baron, forçando-os a destruí-lo e pegar sua cabeça decepada.",al={"o que aconteceu com the baron","destino do grand marshal","o grand marshal está morto"}},{q="Por que o Captain Truman fica com raiva quando você entrega a missão?",a="Captain Truman esperava que seu comandante escultural estivesse vivo e vitorioso. Quando apresentado à cabeça grotesca e mutante de the Baron, Truman é tomado por horror e repulsa, acusando furiosamente o aventureiro de pregar uma piada de mau gosto e de se associar a feras vis.",al={"por que truman está bravo","reação de truman abominable creatures","por que truman grita com você"}},{q="O que Captain Truman quer dizer com os 'true sons of Lordaeron'?",a="Captain Truman usa o termo para descrever patriotas humanos fervorosos dedicados a recuperar sua terra natal destruída. Suas palavras expressam uma visão feroz e intolerante na qual os legítimos sobreviventes humanos purgarão o reino de todos os mortos-vivos, feras e qualquer um visto como associado a eles.",al={"significado de true sons of lordaeron","quem são os true sons of lordaeron","truman true sons"}},{q="Por que Captain Truman se recusa a confiar em 'half breeds'?",a="Captain Truman demonstra profundo desdém por raças não humanas e aliados irregulares, descartando-os como mestiços não confiáveis e escória. Sua intensa xenofobia o impede de confiar em qualquer um que não considere representantes dignos do reino.",al={"truman half breeds","por que captain truman é racista","xenofobia de truman"}}},fp="20,312,17.524.0,22.516.0,23.483.1,41.230.0,53.227.0,31.222.0,61.182.0,61.234.0,62.233.0,54.218.0"}
P.entries["quest:95254"] = {n="WANTED: Trapclaw",s="Fimbo Greasemitz quer a pinça de Trapclaw depois que o enorme caranguejo rouba iscas e corta linhas de pesca sob as docas. Traga-a para ele, e ele promete uma refeição feita com sua mistura secreta de temperos.",h="Fimbo Greasemitz quer a pinça de Trapclaw depois que o enorme caranguejo rouba iscas e corta linhas de pesca...",kw={"isca","caranguejo","carne de caranguejo","docas","fimbo greasemitz","linhas de pesca","pinça","trapclaw"},sec={{t="Sob as docas",b="Fimbo Greasemitz quer carne de caranguejo, e Trapclaw tem rastejado sob as docas. O grande caranguejo rouba iscas e corta linhas de pesca. Fimbo pede que você traga a pinça de Trapclaw, que pretende usar em uma refeição."}},faq={{q="Quem está pedindo a pinça de Trapclaw?",a="Fimbo Greasemitz quer a pinça de Trapclaw para conseguir carne de caranguejo.",al={"quem quer a pinça","pedido de fimbo greasemitz"}},{q="O que Trapclaw está fazendo?",a="Trapclaw rasteja sob as docas, roubando iscas e cortando linhas de pesca.",al={"por que trapclaw","caranguejo sob as docas"}},{q="Por que Fimbo quer a pinça?",a="Fimbo quer carne de caranguejo e pede a pinça de Trapclaw.",al={"para que serve a pinça","pedido de carne de caranguejo"}},{q="O que Fimbo promete preparar?",a="Fimbo diz que vai preparar um prato com manteiga e sua mistura secreta de temperos.",al={"qual refeição","prato de fimbo"}}},fp="16,188,15.218.0,36.59.0,23.75.0,31.54.0,32.68.0"}
P.entries["quest:95260"] = {n="Terrors From the Deep",s="No Porto Detonapavio, você procura um marinheiro capaz de identificar um monstro marinho pintado em um couro. A imagem estranha pode indicar uma criatura nestas águas.",h="No Porto Detonapavio, você procura um marinheiro capaz de identificar um monstro marinho pintado em um couro.",kw={"tripas de peixe","couro pintado","porto detonapavio","marinheiro","monstro marinho","tinta de lula","terrors from the deep"},sec={{t="Uma criatura pintada",b="Um couro pintado leva você ao Porto Detonapavio, onde um marinheiro talvez reconheça a criatura. Tripas de peixe e tinta de lula formam a figura de algo de pescoço longo que emerge das ondas. Se ela pertence a um monstro real destas águas, alguém que navega por aqui talvez o conheça."}},faq={{q="O que está pintado no couro?",a="O couro mostra um monstro marinho de pescoço longo emergindo das ondas, pintado com tripas de peixe e tinta de lula.",al={"o que há no couro","imagem de monstro marinho"}},{q="Onde alguém pode identificar o monstro?",a="O Porto Detonapavio é o porto mais próximo, e um marinheiro de lá talvez reconheça a criatura.",al={"para onde devo ir","marinheiro do porto detonapavio"}},{q="O monstro marinho é real?",a="A pintura levanta a possibilidade de que um monstro marinho espreite nestas águas, mas você procura um marinheiro capaz de identificá-lo.",al={"criatura marinha real","monstro real?"}}},fp="21,143,15.242.0,28.101.0,39.83.0,24.131.0"}
P.entries["quest:95261"] = {n="It Takes Guts",s="Argo Brinewhistle pede vísceras de feras e cogumelos Rotflesh como isca para uma criatura de pescoço comprido que viu perto das ilhas. Ele espera que a captura faça os outros acreditarem em sua história.",h="Argo Brinewhistle pede vísceras de feras e cogumelos Rotflesh como isca para uma criatura de pescoço comprido...",kw={"argo brinewhistle","isca","vísceras de feras","ilhas","é preciso coragem","monstro de pescoço comprido","cogumelos rotflesh","windstead"},sec={{t="A isca de Argo",b="Argo Brinewhistle diz que viu um monstro de pescoço comprido perto das ilhas, quando estava em seu barco. Ele quer que você reúna vísceras de feras e cogumelos Rotflesh para usar como isca. Os cogumelos crescem em uma caverna perto de Windstead, e Argo espera capturar a criatura."}},faq={{q="Quem é Argo Brinewhistle?",a="Argo Brinewhistle é um pescador que diz ter visto um monstro de pescoço comprido perto das ilhas.",al={"quem é argo","argo pescador","história de argo"}},{q="O que Argo quer para usar como isca?",a="Argo pede que você traga vísceras de feras e cogumelos Rotflesh.",al={"qual isca argo precisa","vísceras para argo","isca fedorenta"}},{q="Onde crescem os cogumelos Rotflesh?",a="Os cogumelos Rotflesh crescem em uma caverna perto de Windstead.",al={"local dos rotflesh","onde crescem os cogumelos","caverna de windstead"}},{q="Por que Argo precisa da isca?",a="Argo quer a isca para capturar a criatura de pescoço comprido que diz ter visto perto das ilhas.",al={"por que precisa de isca","o que argo está tentando capturar","monstro de pescoço comprido"}},{q="Por que ninguém acredita em Argo?",a="Argo diz que as pessoas desprezam sua história porque o veem como um pescador bêbado.",al={"por que duvidam de argo","argo bêbado","quem acredita em argo"}}},fp="13,187,11.250.0,25.95.0,29.65.0,33.47.0,28.94.0,32.80.0"}
P.entries["quest:95262"] = {n="The Secret Prison",s="Sully pede que você entre em Alcaz Prison e descubra o que aconteceu com o Rei de Ventobravo. O destino do rei pesa muito sobre Ventobravo.",h="Sully pede que você entre em Alcaz Prison e descubra o que aconteceu com o Rei de Ventobravo.",kw={"alcaz","alcaz prison","rei de ventobravo","ventobravo","sully","the secret prison"},sec={{t="Uma busca em Alcaz",b="Sully envia você a Alcaz, um posto avançado que se acredita abandonado desde a Terceira Guerra. Ninguém que ele conhece falou de uma prisão por lá. Ainda assim, talvez o Rei de Ventobravo esteja lá dentro, e Sully precisa que você descubra o que aconteceu com ele."},{t="O que você encontra",b="Em Alcaz Prison, você descobre que o Rei de Ventobravo está morto. Você também descobre que uma força maior está manipulando os acontecimentos por trás do dragão menor que você matou. Sully precisa ouvir o que você descobriu."}},faq={{q="Para onde Sully me envia?",a="Sully envia você a Alcaz Prison, em um posto avançado que se acredita abandonado desde a Terceira Guerra.",al={"para onde devo ir","alcaz prison","onde fica a prisão"}},{q="O que Sully quer que eu descubra?",a="Sully quer que você descubra o que aconteceu com o Rei de Ventobravo.",al={"o que estou procurando","rei de ventobravo","encontrar o rei"}},{q="O que se acredita que seja Alcaz?",a="Acredita-se que Alcaz seja um posto avançado abandonado desde a Terceira Guerra.",al={"o que é alcaz","posto avançado de alcaz","lugar abandonado"}},{q="Por que Sully me envia a Alcaz?",a="Sully envia você porque talvez o Rei de Ventobravo esteja lá.",al={"por que alcaz","por que ir até lá","motivo de sully"}}},fp="17,130,17.235.0,13.198.2,25.91.0,33.62.0,29.63.0,32.77.0"}
P.entries["quest:95263"] = {n="Somber News",s="Sully McCleary espera por você no Pântano Vadeoso com notícias sobre o rei. A morte dele abalou Ventobravo, e Sully precisa saber o que você descobriu.",h="Sully McCleary espera por você no Pântano Vadeoso com notícias sobre o rei.",kw={"pântano vadeoso","tentativa de fuga","rei","naga","bilhete","notícia sombria","ventobravo","sully mccleary"},sec={{t="Notícias para Sully",b="No Pântano Vadeoso, Sully McCleary espera para saber o que você descobriu. O rei está morto, e Ventobravo enfrenta uma notícia devastadora. Você entrega um bilhete a Sully; enquanto ele o lê, sua expressão fica sombria."}},faq={{q="Quem está me esperando?",a="Sully McCleary espera no Pântano Vadeoso para saber o que você descobriu.",al={"quem quer notícias","quem é sully","para onde devo ir"}},{q="O que aconteceu com o rei?",a="O rei morreu durante uma tentativa de fuga, pouco antes do ataque dos naga.",al={"rei morto","o que aconteceu com o rei","quem matou o rei"}},{q="O que devo levar a Sully?",a="Você leva a Sully um bilhete com o que descobriu.",al={"bilhete para sully","o que estou entregando a ele","entregar bilhete"}},{q="Como Sully reage?",a="A expressão de Sully fica sombria enquanto ele lê o bilhete, e ele chama a notícia de terrível.",al={"reação de sully","sully está chateado","o que ele diz"}}},fp="11,141,14.188.0,22.71.0,26.73.0,22.45.0,21.80.0"}
P.entries["quest:95264"] = {n="Shaw Needs To Know",s="Matthias Shaw precisa que você leve notícias urgentes a ele em Ventobravo. Ele alerta que a forma como forem tratadas pode afetar a população da cidade.",h="Matthias Shaw precisa que você leve notícias urgentes a ele em Ventobravo.",kw={"matthias shaw","mensagem","segredo","avin","ventobravo","notícias urgentes"},sec={{t="De volta a Shaw",b="Em Ventobravo, Matthias Shaw lê as palavras que você traz e pede que mantenha a notícia em segredo. Ele diz que ela precisa ser tratada com cuidado pelo bem da população da cidade."}},faq={{q="Quem precisa saber da notícia?",a="Matthias Shaw, em Ventobravo, precisa que você leve a notícia até ele.",al={"para quem devo contar","notícia de shaw","quem é shaw"}},{q="Por que devo manter isso em segredo?",a="Shaw diz que, se a notícia se espalhar antes de estarem prontos, as coisas acabarão mal para a população de Ventobravo.",al={"por que manter em segredo","manter em segredo","para quem posso contar"}},{q="O que Shaw fará com a notícia?",a="Shaw lê as palavras na página e diz que cuidará do resto.",al={"o que acontece com a mensagem","shaw lê a mensagem","o que ele diz"}},{q="Sobre o que é a notícia?",a="A notícia é descrita como potencialmente desastrosa para Ventobravo, mas seu conteúdo não é revelado aqui.",al={"qual é a notícia","o que aconteceu","qual é o desastre"}}},fp="18,123,12.170.0,19.59.0,29.100.0,32.69.0,23.100.0"}
P.entries["quest:95267"] = {n="The Monster Surfaces",s="Argo Brinewhistle quer que você use uma bola de isca para atrair um monstro marinho das águas perto das murloc islands. Ele pede que você traga a cabeça da criatura de volta para o barco.",h="Argo Brinewhistle quer que você use uma bola de isca para atrair um monstro marinho das águas perto das...",kw={"argo brinewhistle","big ball o' bait","decoração para o barco","cabeça do monstro","murloc islands","monstro marinho","destroços"},sec={{t="Destroços na água",b="Argo Brinewhistle indica as murloc islands, onde você encontrou um desenho. Lá, destroços recentes marcam o ponto da água onde a isca deve ser lançada. O monstro marinho é o perigo que Argo quer atrair, e a cabeça dele será usada no barco."}},faq={{q="O que Argo quer que eu faça?",a="Argo quer que você use a Big Ball o' Bait perto de destroços recentes na água junto às murloc islands e depois leve a cabeça do monstro até ele.",al={"missão da isca de argo","isca para monstro marinho","missão do monstro à tona"}},{q="Onde devo jogar a isca?",a="Argo indica destroços recentes na água perto das murloc islands, onde você encontrou um desenho.",al={"onde jogar a isca","isca nas murloc islands","destroços recentes"}},{q="Por que Argo quer a cabeça do monstro?",a="Argo quer fazer uma decoração para o barco com a cabeça da criatura.",al={"por que a cabeça do monstro","decoração para o barco","cabeça para o barco"}},{q="Como se chama a isca?",a="Ela se chama Big Ball o' Bait.",al={"big ball bait","bola de tripas","nome da isca"}}},fp="20,161,21.241.0,29.136.0,26.98.0,38.68.0,24.34.0"}
P.entries["quest:95278"] = {n="It Is Time, Brother...",s="Uma mensagem precisa chegar a Krom'rosh em Rog'mar enquanto o perigo aumenta. O aviso de Da'grosh lembra uma antiga esperança para a aldeia e a Horda.",h="Uma mensagem precisa chegar a Krom'rosh em Rog'mar enquanto o perigo aumenta.",kw={"da'grosh","horda","krom'rosh","mensagem","rog'mar","aldeia","aviso","guerreiros"},ang={["class:Warrior"]="Como guerreiro, você é mencionado na esperança de Da'grosh de que os parentes da aldeia se tornem grandes guerreiros da Horda.",["faction:Horde"]="Como membro da Horda, você ouve a esperança de infância de Da'grosh de que os parentes da aldeia se tornem guerreiros capazes de salvar seu povo."},sec={{t="Um Aviso para Rog'mar",b="A ameaça cresceu além do que se imaginava, e Rog'mar precisa ser avisada. Você leva uma mensagem a Krom'rosh, sem tempo para parar por ninguém no caminho."},{t="Uma Antiga Esperança",b="Da'grosh certa vez incentivou os parentes da aldeia a se tornarem grandes guerreiros da Horda e protegerem seu povo do perigo. Krom'rosh agora vê uma chance de pôr essa esperança à prova."}},faq={{q="Quem precisa ser avisado?",a="Rog'mar precisa ser avisada porque a ameaça é maior do que se imaginava.",al={"quem precisa ser avisado","avisar quem"}},{q="Quem recebe a mensagem?",a="Krom'rosh, em Rog'mar, recebe a mensagem.",al={"entregar mensagem para quem","quem recebe a carta"}},{q="Por que não posso parar no caminho?",a="A mensagem precisa chegar a Krom'rosh, e o aviso diz para não parar por ninguém no caminho.",al={"por que não parar","não posso parar"}},{q="O que Da'grosh contou à aldeia quando era criança?",a="Da'grosh incentivou os parentes da aldeia a se tornarem grandes guerreiros da Horda e salvarem seu povo do perigo.",al={"infância de dagrosh","o que dagrosh disse"}}},fp="22,132,21.159.0,11.169.1,23.72.0,25.42.0,31.90.0,46.105.0"}
P.entries["quest:95283"] = {n="The Missing Kor'kron",s="Um contingente de elite Kor'kron enviado ao Pântano Vadeoso não fez contato. Você vai à Aldeia Muralha Verde perguntar a Nazeer Bloodspike o que ele sabe.",h="Um contingente de elite Kor'kron enviado ao Pântano Vadeoso não fez contato.",kw={"aldeia muralha verde","contato programado","pântano vadeoso","kor'kron elite","kor'kron desaparecidos","nazeer bloodspike","missão especial"},sec={{t="Notícias do Pântano Vadeoso",b="O silêncio do contingente deixa sua missão sem notícias. Na Aldeia Muralha Verde, Nazeer Bloodspike conhece a situação do Pântano Vadeoso melhor do que ninguém. Você vai descobrir o que ele pode contar sobre os Kor'kron Elite desaparecidos."}},faq={{q="Quem enviou os Kor'kron Elite ao Pântano Vadeoso?",a="Eitrigg, que envia você até Nazeer, diz que seu grupo os despachou para uma missão especial há algum tempo.",al={"quem enviou os kor'kron","quem os enviou"}},{q="Por que os Kor'kron Elite estão desaparecidos?",a="O prazo para o contato programado já passou, e não chegaram notícias deles.",al={"por que os kor'kron desapareceram","o que aconteceu com eles"}},{q="Para onde os Kor'kron foram enviados?",a="Um contingente de Kor'kron Elite foi enviado ao Pântano Vadeoso em uma missão especial.",al={"onde estão os kor'kron","localização dos kor'kron"}},{q="Com quem devo falar na Aldeia Muralha Verde?",a="Fale com Nazeer Bloodspike, um orc que conhece a situação do Pântano Vadeoso.",al={"quem é nazeer","nazeer bloodspike"}}},fp="20,153,20.230.0,48.99.0,35.68.0,29.81.0,47.77.0"}
P.entries["quest:95284"] = {n="The Elite of the Elite",s="Um fornecedor perto da costa pede que você encontre uma força desaparecida de elite Kor’kron. O rastro leva à Ilha Alcaz, onde algo pode ter dado errado.",h="Um fornecedor perto da costa pede que você encontre uma força desaparecida de elite Kor’kron.",kw={"ilha alcaz","costa","soldados de elite","ilha","kor'kron","kor'kron desaparecidos","fornecedor"},ang={["faction:Horde"]="Como membro da Horda, você recebeu o pedido de encontrar uma força desaparecida de soldados Kor’kron."},sec={{t="Uma trilha preocupante",b="Há alguns dias, soldados Kor’kron pararam aqui para comprar suprimentos e descansar antes de seguir viagem. O fornecedor ouviu um deles falar de uma ilha, e a Ilha Alcaz fica logo ali, perto da costa. Agora, pedem que você encontre os elites desaparecidos e descubra o que aconteceu com eles."}},faq={{q="Quem são os Kor’kron desaparecidos?",a="São uma pequena força de soldados Kor’kron que parou aqui para buscar suprimentos e descansar antes de seguir viagem.",al={"elites kor'kron","soldados desaparecidos","kor kron desaparecidos"}},{q="Para onde os Kor’kron podem ter ido?",a="Um dos soldados mencionou uma ilha, e o fornecedor suspeita que seja a Ilha Alcaz, perto da costa.",al={"qual ilha","ilha kor'kron","para onde eles foram"}},{q="Por que o fornecedor está preocupado?",a="Os Kor’kron seguiram viagem depois de descansar, mas o fornecedor sente que algo deu errado.",al={"o que deu errado","por que procurar os kor'kron","soldados de elite desaparecidos"}},{q="Como é a Ilha Alcaz?",a="O fornecedor descreve a Ilha Alcaz como um lugar muito desagradável.",al={"ilha alcaz","alcaz é perigosa","ilha desagradável"}}},fp="22,157,16.250.0,31.102.0,37.94.0,28.83.0,26.53.0"}
P.entries["quest:95285"] = {n="Right Place, Wrong Time",s="A sargento Ulka pede que você se informe sobre a situação em Alcaz Isle. Os demais detalhes da missão são reservados a quem precisa conhecê-los.",h="A sargento Ulka pede que você se informe sobre a situação em Alcaz Isle.",kw={"alcaz isle","instruções","missão","lugar certo, hora errada","sargento ulka","chefe guerreiro"},ang={["faction:Horde"]="Como integrante da Horda, a sargento Ulka pergunta se você está pronto para cumprir seu dever para com o Chefe Guerreiro."},sec={{t="Instruções de Ulka",b="A sargento Ulka se esforça para se sentar quando fala com você em Alcaz Isle. Você oferece ajuda, mas ela afasta sua mão. Ela diz que vai atualizá-lo sobre a situação, mas mantém em sigilo os demais detalhes da missão. Seu dever para com o Chefe Guerreiro espera por você."}},faq={{q="Quem quer me atualizar?",a="A sargento Ulka se esforça para se sentar enquanto fala com você.",al={"quem é ulka","sargento ulka"}},{q="O que está acontecendo em Alcaz Isle?",a="A sargento Ulka diz que vai atualizá-lo sobre a situação em Alcaz Isle.",al={"situação em alcaz","o que está acontecendo aqui"}},{q="Por que Ulka não compartilha todos os detalhes da missão?",a="A sargento Ulka diz que os detalhes restantes da missão só devem ser conhecidos por quem precisa.",al={"por que só quem precisa saber","quais são os detalhes"}},{q="O que Ulka me pede?",a="Fale com a sargento Ulka para saber mais sobre a situação em Alcaz Isle.",al={"o que devo fazer","falar com ulka"}},{q="O que Ulka pergunta sobre meu dever?",a="A sargento Ulka pergunta se você está pronto para cumprir seu dever para com o Chefe Guerreiro.",al={"pronto para o chefe guerreiro","pergunta sobre o dever"}}},fp="23,138,15.245.0,29.57.0,32.72.0,45.66.0,25.73.0,33.73.0"}
P.entries["quest:95288"] = {n="Smuggler's Paradise",s="No Porto Detonapavio, Friz Frazzlespark manda você atrás dos piratas Eastsea que levaram as mercadorias que ela roubou. Ela chama isso de sua primeira lição sobre lidar com traidores.",h="No Porto Detonapavio, Friz Frazzlespark manda você atrás dos piratas Eastsea que levaram as mercadorias que...",kw={"piratas eastsea","friz frazzlespark","goblin","porto detonapavio","bens contrabandeados","paraíso dos contrabandistas","bens roubados"},sec={{t="A lição de Friz",b="Friz Frazzlespark, no Porto Detonapavio, quer que você recupere mercadorias levadas pelos piratas Eastsea. Ela diz que as roubou primeiro e chama recuperá-las de sua primeira lição como seu capanga."},{t="Uma primeira lição",b="Friz diz que você aprendeu bem sua primeira lição. Ela oferece sua sabedoria de graça e depois indica outra tarefa para você."}},faq={{q="Quem é Friz Frazzlespark?",a="Friz Frazzlespark é a goblin que pede que você recupere suas mercadorias roubadas pelos piratas Eastsea.",al={"friz","quem é friz","goblin no porto detonapavio"}},{q="O que os piratas Eastsea levaram?",a="Os piratas Eastsea levaram uma remessa de mercadorias que Friz diz ter roubado primeiro.",al={"bens dos piratas","o que foi roubado","bens contrabandeados"}},{q="Para onde Friz quer que os bens sejam devolvidos?",a="Friz pede que você recolha as mercadorias para ela no Porto Detonapavio.",al={"onde fica friz","porto detonapavio","onde levar os bens"}},{q="Por que Friz quer os bens de volta?",a="Friz diz que os piratas levaram mercadorias que ela roubou primeiro e chama recuperá-las de uma lição sobre lidar com traidores.",al={"por que recuperar os bens","por que friz se importa","motivo da traição"}}},fp="19,157,13.180.0,14.131.1,25.94.0,34.81.0,40.62.0,34.120.0"}
P.entries["quest:95293"] = {n="Smuggler's Special",s="Friz manda você levar ao capitão Bentcoin, em Eastwind Shore, uma caixa chamada The Friz Special. A entrega é a resposta dela à tentativa dele de invadir seu território.",h="Friz manda você levar ao capitão Bentcoin, em Eastwind Shore, uma caixa chamada The Friz Special.",kw={"capitão bentcoin","caixa","piratas de eastsea","eastwind shore","friz","especial do contrabandista","the friz special","guerra comercial"},sec={{t="A resposta de Friz",b="O capitão Bentcoin ameaça você quando pisa no navio dele. Friz enviou você com uma caixa chamada The Friz Special, destinada ao capitão em Eastwind Shore. As mercadorias dela deveriam ter sido entregues diretamente a ela, e Friz acredita que Bentcoin está tentando invadir seu território. Ela chama isso de segunda lição e apresenta a caixa como uma resposta à altura da negociação dele."},{t="A caixa",b="Quando Bentcoin recebe a caixa de Friz, ele entende isso como um sinal de que ela sabe que foi derrotada. Então, ouve um ruído de algo contando os segundos."}},faq={{q="Quem é Friz?",a="Friz enviou você até o capitão Bentcoin com uma caixa chamada The Friz Special, depois que mercadorias destinadas a ela foram desviadas.",al={"friz","quem me enviou","quem dá the friz special"}},{q="Quem é o capitão Bentcoin?",a="O capitão Bentcoin é o capitão que Friz manda você encontrar no navio dele, em Eastwind Shore.",al={"bentcoin","quem é o capitão","capitão de eastwind"}},{q="O que estou entregando?",a="Você está levando The Friz Special, uma caixa que Friz preparou para o capitão Bentcoin.",al={"the friz special","a caixa","o que devo levar"}},{q="Por que Friz está enviando um presente?",a="Friz diz que as mercadorias que você conseguiu com os piratas de Eastsea deveriam ser enviadas diretamente a ela, e acredita que Bentcoin está tentando invadir seu território.",al={"por que dar um presente a bentcoin","entrega de friz","guerra comercial"}},{q="Onde encontro o capitão Bentcoin?",a="O capitão Bentcoin está no navio dele, em Eastwind Shore.",al={"localização de bentcoin","onde está o capitão","eastwind shore"}},{q="O que Bentcoin diz quando chego?",a="Bentcoin ameaça fazer você andar na prancha por subir a bordo do navio dele e exige saber por que deveria poupar você.",al={"reação de bentcoin","o que o capitão diz","subir no navio"}}},fp="18,158,13.362.0,9.132.1,12.111.0,24.88.0,21.74.0,27.157.0,33.53.0,37.98.0"}
P.entries["quest:95294"] = {n="Smuggler's Bargain",s="Um pirata Eastsea oferece a Friz Frazzlespark um acordo para deixá-la cuidar dos negócios em paz. Você leva a mensagem dele até ela no Porto Detonapavio.",h="Um pirata Eastsea oferece a Friz Frazzlespark um acordo para deixá-la cuidar dos negócios em paz.",kw={"capitão","piratas eastsea","friz frazzlespark","goblin","pirata","porto detonapavio","acordo do contrabandista"},sec={{t="A oferta de um capitão",b="Friz Frazzlespark chamou a atenção dos piratas Eastsea, e um deles se oferece para impedir que sua tripulação interfira nos negócios dela. Em troca, propõe um acordo lucrativo. Você leva a mensagem dele até Friz no Porto Detonapavio, onde ela saberá quem alega estar no comando."},{t="A lição de Friz",b="Friz responde à oferta do pirata com um aviso sobre o preço de cruzar seu caminho. As palavras dela deixam os termos do acordo em dúvida."}},faq={{q="O que o pirata oferece a Friz?",a="Um pirata Eastsea se oferece para impedir que sua tripulação interfira nos negócios de Friz e propõe um acordo lucrativo.",al={"oferta do pirata eastsea","acordo com friz"}},{q="Para quem devo voltar para relatar?",a="Você volta para Friz Frazzlespark no Porto Detonapavio.",al={"onde voltar","quem recebe a mensagem"}},{q="Que mensagem o capitão envia?",a="Ele quer que Friz saiba que um novo capitão está no comando e prevê uma relação lucrativa.",al={"mensagem do capitão","o que dizer a friz"}},{q="Quem é o novo capitão?",a="Friz questiona quem é o capitão, mas a mensagem não o identifica.",al={"quem é o capitão","chefe dos piratas"}}},fp="18,135,17.279.0,13.124.1,32.118.0,24.51.0,35.93.0,23.69.0"}
P.entries["quest:95295"] = {n="I Know a Guy",s="Friz manda você à Angra do Butim para encontrar seu contato. Ruzzgot consegue mercadorias com os bucaneiros locais e explicará o que vem a seguir.",h="Friz manda você à Angra do Butim para encontrar seu contato.",kw={"angra do butim","contato","bucaneiros","friz","mercadorias","conheço alguém","piratas","ruzzgot"},sec={{t="Um contato em Angra do Butim",b="Friz diz que seu contato é Ruzzgot. Ele espera na Angra do Butim. Consegue mercadorias com os piratas de lá, que Friz chama de bucaneiros. Encontre Ruzzgot, e ele explicará o restante."}},faq={{q="Quem é o contato de Friz?",a="Friz indica Ruzzgot como seu contato na Angra do Butim.",al={"contato de friz","quem é ruzzgot","contato na angra do butim"}},{q="Para onde Friz me envia?",a="Friz envia você à Angra do Butim para encontrar Ruzzgot.",al={"para onde ir","onde está ruzzgot","angra do butim"}},{q="O que Ruzzgot faz?",a="Ruzzgot consegue mercadorias com os piratas locais da Angra do Butim.",al={"o que o contato faz","mercadorias de ruzzgot","mercadorias piratas"}},{q="Por que Friz chama os piratas de bucaneiros?",a="Friz diz que algumas pessoas chamam piratas de bucaneiros e brinca que a palavra contém “saque grátis”.",al={"significado de bucaneiro","piratas ou bucaneiros","por que bucaneiros"}}},fp="12,141,22.166.0,22.47.0,24.44.0,21.55.0,43.98.0"}
P.entries["quest:95296"] = {n="Shipping and Handling",s="Seu empregador pede que você leve uma caixa ao Porto de Bondebico. Espera-se que um goblin de lá pague o que deve.",h="Seu empregador pede que você leve uma caixa ao Porto de Bondebico.",kw={"caixa","entrega","dívidas","goblin","transporte e entrega","porto de bondebico","tanaris","wharfmaster steamfizzle"},sec={{t="Uma Caixa para Entregar",b="Sua empregadora está ocupada negociando na cidade, então lhe entrega uma caixa para o associado dela. Ela espera que você pegue um navio nas docas até o Porto de Bondebico, em Tanaris. Lá, você deve falar com Wharfmaster Steamfizzle, e as taxas de um goblin estão em jogo."}},faq={{q="Quem me deu a caixa?",a="Sua empregadora lhe entrega a caixa enquanto cuida das negociações na cidade.",al={"entrega de caixa","quem me enviou","trabalho de transporte"}},{q="Para onde vai a caixa?",a="A caixa deve ser entregue ao associado do seu empregador no Porto de Bondebico, em Tanaris.",al={"destino da caixa","onde entregar","entrega no porto de bondebico"}},{q="Com quem devo falar no Porto de Bondebico?",a="No Porto de Bondebico, o contato indicado é Wharfmaster Steamfizzle.",al={"mestre do cais","steamfizzle","contato no porto"}},{q="Por que estou levando uma caixa?",a="Sua empregadora pede que você entregue a caixa porque está ocupada negociando na cidade.",al={"por que a caixa","o que há na caixa","motivo da entrega"}},{q="O que o goblin deve fazer?",a="Seu empregador espera que um goblin no Porto de Bondebico pague o que deve.",al={"dívidas do goblin","pagar o que deve","por que o goblin"}}},fp="21,105,18.256.0,22.73.0,24.81.0,41.67.0,26.84.0,34.68.0"}
P.entries["quest:953"] = {n="A queda de Ameth'Aran",s="A Sentinela Tysha Lamiluna incumbe os aventureiros de explorar as assombrosas ruínas de Ameth'Aran em Costa Negra para decifrar antigas tabuletas de pedra. Essas inscrições registram a tragédia e a ruína que atingiram a cidade dos Altaneiros durante a Cisão. O conhecimento reunido destina-se ao Círculo dos Anciãos em Auberdine, recuperando uma história amplamente perdida durante a Guerra dos Antigos.",h="A Sentinela Tysha Lamiluna incumbe os aventureiros de explorar as assombrosas ruínas de Ameth'Aran em Costa...",kw={"ameth'aran","auberdine","azshara","círculo dos anciãos","costa negra","altaneiros","cisão","tabuletas","tysha lamiluna"},ang={["class:Mage"]="As tabuletas oferecem um vislumbre sóbrio do ápice da magia élfica antes da Cisão e da terrível ruína causada quando esse poder saiu do controle.",["faction:Alliance"]="Ajudar as Sentinelas a resguardar a história de Costa Negra contribui para preservar um conhecimento crucial para os líderes elfos noturnos que guiam a Aliança em Kalimdor.",["race:NightElf"]="As ruínas de Ameth'Aran são uma lembrança sombria da soberba dos seus ancestrais sob o reinado da Rainha Azshara e das consequências catastróficas da feitiçaria arcana desregulada."},sec={{t="Ecos dos Altaneiros",b="Muito antes de a costa se fragmentar na extensão enevoada de Costa Negra, Ameth'Aran erguia-se como um assentamento próspero onde os feiticeiros de elite da Rainha Azshara praticavam uma poderosa magia arcana. Após a destruição cataclísmica da Nascente da Eternidade, dez mil anos atrás, a cidade foi reduzida a mármore quebrado e pilares rachados. Hoje, permanece assombrada pelos espíritos inquietos e angustiados dos Altaneiros que pereceram quando sua era de ouro ruiu."},{t="Revelando Crônicas Perdidas",b="Como a Guerra dos Antigos mergulhou a civilização dos elfos noturnos em uma luta caótica pela sobrevivência, raríssimos relatos escritos sobreviveram intactos à Grande Cisão. A Sentinela Tysha Lamiluna tentou inspecionar as ruínas pessoalmente, descobrindo duas grandes tabuletas gravadas — Lay of Ameth'Aran e A queda de Ameth'Aran — antes que espectros fantasmagóricos de Altaneiros a forçassem a recuar. Recuperar esses registros garante que as verdades históricas do antigo desastre cheguem aos eruditos do Círculo dos Anciãos em Auberdine."}},faq={{q="O que é Ameth'Aran?",a="Ameth'Aran é uma antiga ruína de elfos noturnos localizada na região central de Costa Negra. Dez mil anos atrás, era uma cidade onde a nobreza dos Altaneiros da Rainha Azshara manipulava e estudava abertamente a grandiosa magia arcana, antes de sucumbir durante a Grande Cisão.",al={"história de ameth'aran","o que era ameth'aran","quem vivia em ameth'aran"}},{q="Por que há fantasmas em Ameth'Aran?",a="Os fantasmas inquietos que assombram as ruínas são os espíritos dos Altaneiros que ali viveram e morreram. Apanhados na catástrofe repentina e violenta que despedaçou a Nascente da Eternidade e fragmentou Kalimdor, seus espíritos permanecem atados às ruínas em tormento eterno.",al={"por que há espíritos em ameth'aran","fantasmas de ameth'aran","altaneiros inquietos"}},{q="Quem é a Sentinela Tysha Lamiluna?",a="A Sentinela Tysha Lamiluna é uma sentinela elfa noturna posicionada ao longo da estrada em Costa Negra. Ela recebeu a missão de explorar sítios antigos e recuperar registros históricos perdidos para o Círculo dos Anciãos em Auberdine.",al={"sentinela tysha lamiluna","quem dá a queda de ameth'aran"}},{q="Por que o Círculo dos Anciãos quer a leitura dessas tabuletas?",a="A destruição da Nascente da Eternidade mergulhou Kalimdor em um imenso caos, obliterando incontáveis bibliotecas e monumentos. Como tão poucos registros escritos sobreviveram à Guerra dos Antigos, as tabuletas fornecem relatos raros e em primeira mão sobre a Cisão sob a perspectiva dos Altaneiros.",al={"por que ler as tabuletas","tabuletas do círculo dos anciãos","significado de lay of ameth'aran"}},{q="Onde as tabuletas estão localizadas?",a="As duas grandes tabuletas — Lay of Ameth'Aran e A queda de Ameth'Aran — estão gravadas em monumentos de pedra erguidos entre os pátios arruinados de Ameth'Aran, cercadas pelos fantasmas errantes dos antigos habitantes da cidade.",al={"onde ficam as tabuletas de ameth'aran","localização das tabuletas","como ler ameth'aran"}},{q="O que aconteceu com os Altaneiros de Ameth'Aran durante a Cisão?",a="Quando a Nascente da Eternidade implodiu no clímax da Guerra dos Antigos, tremores colossais e o ricochete arcano despedaçaram Kalimdor. Ameth'Aran desabou em ruínas, soterrando seus cidadãos e deixando seus fantasmas a vagar pelos escombros.",al={"como ameth'aran caiu","destruição de ameth'aran"}}},fx={["4f4506ec"]={q="Por que a Sentinela Tysha Lamiluna quer que isso seja feito?",a="A Sentinela Tysha Lamiluna foi despachada em nome do Círculo dos Ancestrais para pesquisar as ruínas antigas. Registros da era da Guerra dos Ancestrais e da Ruptura são extremamente raros devido aos cataclismos daquela época. Reunir a história esculpida nas tábuas permite que ela forneça uma contabilidade completa aos druidas e anciãos em Auberdine.",al={"motivo de tysha lamiluna","por que tysha precisa disso","por que estudar as tábuas de ameth'aran"}},["2329a43d"]={q="Por que a Sentinela Tysha Lamiluna precisa da sua ajuda?",a="Tysha aventurou-se anteriormente em Ameth'Aran para examinar as tábuas ela mesma, mas foi emboscada e expulsa pelos espíritos vingativos dos Altaneiros que assombram as ruínas. Incapaz de transcrever as inscrições com segurança por conta própria enquanto sob constante ataque espectral, ela precisa de um aventureiro capaz para invadir as ruínas e decifrar o texto em seu lugar.",al={"por que tysha não consegue ler as tábuas","por que tysha precisa de mim","por que tysha não vai ela mesma"}}},fp="22,278,23.289.0,26.458.0,19.221.0,35.199.0,32.190.0,56.311.0,30.204.0,66.216.0"}
P.entries["quest:95309"] = {n="No Orc Left Behind",s="Sua missão é entrar em Alcaz Prison para encontrar Commander Folkar e descobrir o que está acontecendo sob a fortaleza. Um exército aguarda nas masmorras, e você foi avisado para não ir sozinho.",h="Sua missão é entrar em Alcaz Prison para encontrar Commander Folkar e descobrir o que está acontecendo sob a...",kw={"alcaz prison","commander folkar","masmorras","fortaleza","kor'kron","nenhum orc fica para trás","ulka"},sec={{t="Sob a Fortaleza",b="Commander Folkar está em algum lugar nas masmorras sob a fortaleza, e você é enviado a Alcaz Prison para encontrá-lo. Se ele estiver vivo, você deve libertá-lo e descobrir o que está acontecendo por lá. Um exército aguarda abaixo, então você foi avisado de que precisará de aliados para sobreviver."},{t="A Busca",b="Ulka enviou você para encontrar Commander Folkar depois de sobreviver a um encontro mortal. Folkar elogia o serviço dela à Kor’kron e diz que vai garantir uma promoção em campo para ela. Ainda assim, ele afirma que a missão não terminou, e você não pode sair de Alcaz Prison."}},faq={{q="Para onde estou sendo enviado?",a="Você deve entrar em Alcaz Prison, nas masmorras sob a fortaleza.",al={"para onde ir","localização de alcaz prison","sob a fortaleza"}},{q="Quem estou procurando?",a="Você está procurando Commander Folkar em Alcaz Prison.",al={"quem encontrar","commander folkar","paradeiro de folkar"}},{q="O que devo descobrir?",a="Você deve descobrir o que está acontecendo nas masmorras sob a fortaleza.",al={"o que está acontecendo","descobrir o que aconteceu","situação na prisão"}},{q="Por que fui avisado para trazer aliados?",a="Um exército aguarda nas masmorras, e você foi avisado de que não sobreviverá lá sozinho.",al={"preciso de aliados","ir sozinho?","exército abaixo"}}},fp="18,166,14.259.0,10.253.1,22.65.0,21.53.0,28.74.0,32.88.0"}
P.entries["quest:95312"] = {n="Coming to Collect",s="Quem deve dinheiro a Friz apostou o dinheiro dela em Slugjaw na arena de Geringontzan e diz que os ganhos estão prontos para serem recolhidos. Você deve falar com Fizbuz Mithril.",h="Quem deve dinheiro a Friz apostou o dinheiro dela em Slugjaw na arena de Geringontzan e diz que os ganhos...",kw={"arena","vindo buscar","fizbuz mithril","friz","geringontzan","jogos de azar","slugjaw","ganhos"},sec={{t="O dinheiro de Friz",b="O jogador que deve dinheiro a Friz diz que apostou o dinheiro dela em Slugjaw, na arena de Fizbuz, em Geringontzan. Ele afirma que ganhou a aposta, mas diz que ainda não recebeu os ganhos. Como você já está cumprindo uma tarefa para Friz, ele pede que você fale com Fizbuz Mithril em Geringontzan."}},faq={{q="Quem deve dinheiro a Friz?",a="Um jogador deve dinheiro a Friz depois de apostar o dinheiro dela em Slugjaw, na arena de Fizbuz.",al={"dinheiro de friz","devedor de friz","quem deve a friz"}},{q="Por que ele apostou o dinheiro de Friz?",a="Ele diz que achou que apostar em Slugjaw era um investimento seguro.",al={"por que apostar o dinheiro dela","aposta em slugjaw","aposta do jogador"}},{q="Quem é Slugjaw?",a="Slugjaw é o lutador da arena em quem o jogador apostou em Geringontzan.",al={"slugjaw","arena de slugjaw","quem é slugjaw"}},{q="Onde estão os ganhos?",a="O jogador diz que ainda não recebeu os ganhos e manda você falar com Fizbuz Mithril em Geringontzan.",al={"ganhos de friz","recolher dinheiro","onde está o dinheiro"}},{q="Com quem devo falar em Geringontzan?",a="Fale com Fizbuz Mithril em Geringontzan sobre os ganhos.",al={"fizbuz","arena de geringontzan","tarefa de friz"}}},fp="17,158,14.268.0,20.74.0,30.61.0,15.61.0,23.107.0,35.58.0"}
P.entries["quest:95314"] = {n="O elixir verde do Vale das Sombras",s="Carolai Anise em Montalvo busca itens a serem resgatados do povoado abandonado do Vale das Sombras, escondido nas profundezas da isolada Floresta do Sussurro. Antes da queda do reino, a aldeia era famosa por destilar o Whispering Elixir a partir de estranhas ervas locais — um potente preparado que permaneceu valorizado no mercado negro mesmo após ser proibido em Lordaeron.",h="Carolai Anise em Montalvo busca itens a serem resgatados do povoado abandonado do Vale das Sombras, escondido...",kw={"boticário","montalvo","carolai anise","veneno","vale das sombras","tirisfal","whispering elixir","floresta do sussurro"},ang={["class:Rogue"]="O Whispering Elixir foi muito valorizado por envenenadores clandestinos e patifes que agiam longe dos olhos dos antigos magistrados de Lordaeron.",["profession:Herbalism"]="O elixir obtém sua potência a partir de ervas singulares que só vicejam sob a copa sinistra da isolada Floresta do Sussurro.",["race:Undead"]="Para os Renegados, recuperar as destilações esquecidas de Lordaeron serve tanto a um comércio lucrativo quanto aos experimentos de boticários na recém-criada Cidade Baixa."},sec={{t="Uma infusão banida",b="Muito antes da Terceira Guerra e da chegada do Flagelo, os habitantes reclusos do Vale das Sombras preparavam uma mistura peculiar conhecida como Whispering Elixir. Destilada a partir de ervas raras exclusivas das Clareiras de Tirisfal, a poção ganhou notoriedade por todo o norte de Lordaeron. Apesar de ter sido oficialmente banida dentro de Capital City, suas propriedades incomuns faziam com que fosse avidamente procurada por místicos, envenenadores e boticários praticantes dispostos a burlar os decretos reais."},{t="Ruínas na Floresta do Sussurro",b="O Vale das Sombras fica escondido nas profundezas da Floresta do Sussurro, a oeste de Tirisfal. Historicamente, os aldeões eram um povo isolacionista e desconfiado que raramente acolhia forasteiros. Após a invasão do Flagelo, o povoado ruiu, mas estoques esquecidos do antigo elixir verde continuam em meio aos destroços. Carolai Anise opera a partir de Montalvo, aproveitando a persistente demanda do submundo para pagar aventureiros dispostos a encarar o silêncio perturbador da floresta."},{t="A maldição do sussurro",b="Embora Carolai prefira descartar os boatos como mera superstição, a Floresta do Sussurro carrega uma reputação sombria. As lendas locais sugerem que o próprio solo e as raízes da floresta estão contaminados por uma maldição antiga, algo que penetra diretamente na flora colhida pelos destiladores do Vale das Sombras. Seja qual for a malevolência persistente que assombra o vilarejo abandonado, isso pouco fez para diminuir o apetite de compradores distantes em busca de seus frascos restantes."}},faq={{q="O que é o Vale das Sombras?",a="O Vale das Sombras era uma aldeia isolada, oculta na Floresta do Sussurro, a oeste das Clareiras de Tirisfal. Seu povo era formado por isolacionistas sigilosos conhecidos principalmente por destilar misturas raras a partir da vegetação selvagem local antes de o Flagelo assolar a região.",al={"onde fica o vale das sombras","quem vivia no vale das sombras","aldeia vale das sombras"}},{q="O que é o Whispering Elixir?",a="É uma potente poção verde destilada a partir de ervas exclusivas encontradas em Tirisfal. Muito cobiçada por místicos, envenenadores e boticários, a bebida foi banida em Capital City antes da queda de Lordaeron.",al={"o que o elixir faz","história o elixir verde do vale das sombras","whispering elixir"}},{q="Quem é Carolai Anise?",a="Carolai Anise é uma engenhosa Renegada que reside em Montalvo. Ela atua como intermediária de curiosidades valiosas e proibidas, obtendo reagentes ilícitos como o elixir do Vale das Sombras para vender a compradores interessados por todo o reino.",al={"carolai anise","quem dá a missão o elixir verde do vale das sombras","doador de missão montalvo"}},{q="Por que o elixir foi banido em Capital City?",a="Nenhum motivo é apresentado. Carolai diz apenas que o elixir foi proibido na cidade, e que boticários, místicos e envenenadores o procuravam mesmo assim. Alguns acreditam que a Floresta do Sussurro seja amaldiçoada e que o elixir destilado de suas raízes carregue a mesma maldição, mas Carolai rejeita isso como superstição e nunca associa isso à proibição.",al={"por que o whispering elixir era ilegal","o elixir é veneno"}},{q="Por que a Floresta do Sussurro é considerada perigosa?",a="Os bosques isolados a oeste de Plangemortis são amplamente considerados sinistros e amaldiçoados. Aqueles que se aventuram por lá relatam uma profunda malevolência e estranhos fenômenos florestais, que, segundo boatos, contaminaram as ervas que brotam de seu solo.",al={"a floresta do sussurro é amaldiçoada","história da floresta do sussurro"}},{q="Quem são os compradores que querem este elixir?",a="De acordo com Carolai Anise, vários compradores estão ansiosos para obter frascos remanescentes anteriores à guerra, embora ela não revele quem são.",al={"quem compra o elixir","compradores de carolai anise"}}},fx={["4d019fa8"]={q="Por que Carolai Anise quer que o Elixir Sussurrante seja coletado?",a="Carolai Anise trabalha como procuradora de artigos raros em Montalvo, e a demanda pela bebida ilícita nunca morreu de verdade. Com vários compradores ávidos pressionando-a por carregamentos, há um lucro considerável a ser obtido de quaisquer garrafas que restaram intactas entre as ruínas.",al={"por que carolai quer o elixir","motivação de carolai anise","por que coletar elixir sussurrante"}}},fp="28,195,13.300.0,30.405.0,20.331.1,19.190.0,26.192.0,21.142.0,46.280.0,50.204.0,39.105.0"}
P.entries["quest:95315"] = {n="The Riverglades Report",s="A Capitã Nélia envia você ao sul com correspondência para Demar Brant, na Bastilha de Ermoforte. Um batedor relata que uma força inimiga se reúne além do Pantanal, perto de um povoado chamado Farholde.",h="A Capitã Nélia envia você ao sul com correspondência para Demar Brant, na Bastilha de Ermoforte.",kw={"capitã nélia","correspondência","demar brant","farholde","bastilha de ermoforte","relato das sendas do rio","batedor","pantanal"},sec={{t="Relato de um batedor",b="A Capitã Nélia soube que uma grande força inimiga está se reunindo bem ao sul do Pantanal. Talvez haja ali um povoado chamado Farholde, embora ela só conheça esse nome. Ela entrega a você uma correspondência para Demar Brant, que lidera o destacamento na Bastilha de Ermoforte, na costa sudeste das Sendas do Rio."}},faq={{q="O que o batedor relatou?",a="O batedor relatou que uma grande força inimiga está se reunindo bem ao sul, além do Pantanal.",al={"relato do batedor","o que acontece ao sul"}},{q="Para quem a Capitã Nélia está me enviando?",a="Você deve entregar a correspondência da Capitã Nélia a Demar Brant, na Bastilha de Ermoforte.",al={"quem recebe a carta","demar brant"}},{q="Onde fica a Bastilha de Ermoforte?",a="A Bastilha de Ermoforte fica na costa sudeste das Sendas do Rio.",al={"onde fica farholde","localização da bastilha"}},{q="O que é Farholde?",a="A Capitã Nélia ouviu falar de um povoado chamado Farholde perto do local onde a força está se reunindo.",al={"povoado farholde","o que é farholde"}}},fp="22,180,16.302.0,26.80.0,35.83.0,23.67.0,17.81.0"}
P.entries["quest:95321"] = {n="Tazzik's Dues",s="Tazzik mandou você buscar seus ganhos em Geringontzan, mas o campeão da arena dele não ganhou nada. Você precisa confrontar Tazzik sobre a dívida não paga.",h="Tazzik mandou você buscar seus ganhos em Geringontzan, mas o campeão da arena dele não ganhou nada.",kw={"arena","friz","porto de bondebico","tanaris","tazzik","dívidas de tazzik","ganhos"},sec={{t="De volta ao porto",b="O Collector manda você voltar ao Porto de Bondebico, em Tanaris. O campeão de Tazzik perdeu rápido na arena, então não há ganhos para buscar. Tazzik pode estar tentando pegar um navio para sair do porto enquanto você conversa com o Collector."},{t="A resposta de Tazzik",b="Tazzik admite que apostou tudo o que tinha nas lutas para pagar Friz e perdeu tudo. Ele diz que não pode devolver os pertences dela e pede sua ajuda."}},faq={{q="O que aconteceu com os ganhos de Tazzik?",a="O campeão de Tazzik perdeu na arena, e o Collector diz que a luta não rendeu nenhuma moeda de cobre.",al={"ganhos de tazzik","onde está o dinheiro de tazzik"}},{q="Aonde Tazzik quer que eu vá?",a="O Collector manda você voltar ao Porto de Bondebico, em Tanaris, para confrontar Tazzik.",al={"onde encontrar tazzik","localização de tazzik"}},{q="Por que devo voltar correndo ao porto?",a="O Collector acha que Tazzik pode estar tentando pegar o próximo navio para sair do Porto de Bondebico.",al={"tazzik fugindo","tazzik está indo embora"}},{q="Quem é Friz?",a="Friz é quem Tazzik deve. Ele apostou o dinheiro dela em uma luta na arena de Geringontzan, e o campeão dele perdeu.",al={"friz tazzik","tazzik friz"}}},fp="13,143,16.233.0,15.152.1,35.87.0,32.80.0,36.90.0,12.103.0"}
P.entries["quest:95322"] = {n="Get the Goods",s="Em Angra do Butim, Friz, um caravaneiro, combinou comprar mercadorias dos Bucaneiros da Vela Sangrenta. Embora diga que os piratas são amigos, ele quer que você o acompanhe como reforço enquanto procura o baú escondido na colina fora da cidade.",h="Em Angra do Butim, Friz, um caravaneiro, combinou comprar mercadorias dos Bucaneiros da Vela Sangrenta.",kw={"bucaneiros da vela sangrenta","baú dos bucaneiros da vela sangrenta","angra do butim","friz","remessa","selva do espinhaço"},sec={{t="Um acordo com piratas",b="Friz tem uma remessa à espera na Selva do Espinhaço, comprada dos Bucaneiros da Vela Sangrenta. Os piratas dizem que esconderam o baú na colina com vista para Angra do Butim, para mantê-lo em segurança. Friz insiste que eles são parceiros de confiança, mas quer um companheiro armado para evitar qualquer traição. Você sai pelos portões para inspecionar o baú dos piratas."}},faq={{q="Quem é Friz?",a="Friz é um caravaneiro de Angra do Butim que faz negócios com os Bucaneiros da Vela Sangrenta.",al={"quem oferece get the goods","quem é friz","quem quer a remessa"}},{q="Onde os Bucaneiros deixaram as mercadorias?",a="Os piratas esconderam a remessa em um baú na colina, logo fora de Angra do Butim.",al={"localização do baú dos bucaneiros da vela sangrenta","onde está a remessa","onde está o baú"}},{q="Por que Friz negocia com os Bucaneiros da Vela Sangrenta?",a="Friz afirma que os Bucaneiros da Vela Sangrenta são bons amigos e fornecem tudo pelo que ele paga, embora ainda prefira ter alguém junto para intimidá-los.",al={"por que os piratas são de confiança","os piratas são amigáveis com friz"}},{q="Por que Friz pede que você vá?",a="Friz quer um companheiro armado para fazer uma demonstração de força, caso as negociações com os piratas deem errado.",al={"por que precisa de reforço","por que friz quer um acompanhante"}}},fp="13,248,21.384.0,13.95.0,43.82.0,57.158.0,32.122.0"}
P.entries["quest:95325"] = {n="We've Been Robbed!",s="Um carregamento já pago foi roubado na Selva do Espinhaço, e os ladrões se refugiaram num acampamento dos Empreendimentos S.A. perto do Lago Nezferiti. Recuperar o livro-caixa da empresa é a única forma de descobrir quem encomendou o roubo e acertar as contas.",h="Um carregamento já pago foi roubado na Selva do Espinhaço, e os ladrões se refugiaram num acampamento dos...",kw={"lago nezferiti","carregamento","selva do espinhaço","empreendimentos s.a.","livro-caixa dos empreendimentos s.a.","fomos roubados!"},sec={{t="Carregamentos Desaparecidos",b="Uma caixa já paga desapareceu na Selva do Espinhaço, e os ladrões não vão ficar com ela. Os Empreendimentos S.A. mantêm um acampamento ao norte, perto do Lago Nezferiti, e seus registros guardam os nomes por trás da traição. Você precisa vasculhar o local e garantir o livro-caixa da empresa antes que as pistas esfriem."},{t="A Carga Roubada",b="Dentro do acampamento está o livro-caixa dos Empreendimentos S.A., um volume manchado de graxa que cataloga negócios escusos e contatos comerciais por toda a selva. Os registros provam que a empresa levou a carga e mostram até onde se estendem seus negócios desonestos."}},faq={{q="Onde fica o acampamento dos Empreendimentos S.A.?",a="O acampamento fica perto do Lago Nezferiti, no norte da Selva do Espinhaço, onde os Empreendimentos S.A. supervisionam suas operações locais.",al={"local do acampamento dos empreendimentos s.a.","onde fica o livro-caixa dos empreendimentos s.a.","onde fica o lago nezferiti"}},{q="O que é o livro-caixa dos Empreendimentos S.A.?",a="É um livro coberto de graxa que registra transações comerciais entre os Empreendimentos S.A. e seus parceiros comerciais.",al={"o que é o livro-caixa dos empreendimentos s.a.","o que o livro-caixa contém"}},{q="Por que estão procurando o livro-caixa?",a="Uma caixa já paga foi levada, e rastrear os registros escritos da operação é a única forma de descobrir quem encomendou o roubo.",al={"por que pegar o livro-caixa","quem levou o carregamento"}}},fp="18,240,17.314.0,16.233.1,34.122.0,35.113.0,31.123.0"}
P.entries["quest:95326"] = {n="The Big Payback",s="Um livro-caixa roubado revela que um agente dos Empreendimentos S.A. tomou os bens de Russote. Os produtos continuam nas mãos do ladrão, e Russote precisa recuperar sua carga para proteger seu comércio em Angra do Butim.",h="Um livro-caixa roubado revela que um agente dos Empreendimentos S.A.",kw={"angra do butim","caravaneiro","livro-caixa","porto detonapavio","russote","carregamento","the big payback","empreendimentos s.a."},sec={{t="Um Carregamento Roubado",b="Um livro-caixa recuperado detalha cada viagem feita pelo Caravaneiro Russote, até chegar a um amargo registro de roubo. Um agente próximo dos Empreendimentos S.A. apreendeu sua carga, e os bens roubados continuam nas mãos do agente. Russote espera em Angra do Butim que alguém acerte as contas e devolva o que foi levado antes que seu sustento seja arruinado."},{t="De Volta aos Negócios",b="Recuperar a carga restaura a confiança de Russote em sua reputação como comerciante. Com seus produtos de volta, ele retoma os negócios imediatamente e se oferece para ajudar a organizar o transporte até o Porto Detonapavio."}},faq={{q="Quem é Russote?",a="Russote é um caravaneiro que trabalha em Angra do Butim e depende de entregar produtos pela região com confiabilidade para manter seu negócio.",al={"quem é russote","russote angra do butim","o que russote faz"}},{q="Quem roubou a carga de Russote?",a="Um agente próximo dos Empreendimentos S.A. roubou os bens de Russote, como registra um livro-caixa de entregas recuperado que relata o roubo.",al={"quem roubou os produtos de russote","roubo dos empreendimentos s.a. contra russote","quem levou a carga"}},{q="Por que recuperar a carga é importante para Russote?",a="A vida de um caravaneiro depende da confiança e da confiabilidade, e perder sua carga ameaça sua reputação em Angra do Butim.",al={"por que russote se importa com sua carga","por que a carga é importante","o que acontece se russote perder sua entrega"}},{q="Para onde a carga deveria ir?",a="Russote se oferece para ajudar a organizar o envio dos bens recuperados até o Porto Detonapavio.",al={"para onde ia a carga de russote","entrega no porto detonapavio","destino da carga"}}},fp="15,200,17.327.0,16.196.1,15.119.0,29.114.0,51.111.0,38.94.0"}
P.entries["quest:95327"] = {n="All's Well That Ends Well",s="Ruzzgot diz que a Empreendimentos S.A. pagou sua parte no acordo e que Friz recebeu seu saque. Você volta para Friz Frazzlespark no Porto Detonapavio enquanto Ruzzgot aguarda outra remessa.",h="Ruzzgot diz que a Empreendimentos S.A.",kw={"acordo","friz frazzlespark","porto detonapavio","sendas do rio","remessa","southsea pirates","empreendimentos s.a."},sec={{t="Outra remessa",b="Uma nova remessa está a caminho de Ruzzgot, e Friz Frazzlespark espera no Porto Detonapavio. Você volta até ela nas Sendas do Rio depois que a Empreendimentos S.A. recebeu o que merecia e Friz recebeu seu saque. Ruzzgot diz que a transação foi tranquila. Agora, os Southsea Pirates devem trazer a próxima remessa para ele."}},faq={{q="Quem é Friz Frazzlespark?",a="Friz Frazzlespark está esperando por você no Porto Detonapavio, nas Sendas do Rio.",al={"quem é friz","friz frazzlespark"}},{q="O que aconteceu com a Empreendimentos S.A.?",a="Ruzzgot diz que a Empreendimentos S.A. recebeu o que merecia.",al={"acordo com a empreendimentos s.a.","e a empreendimentos s.a."}},{q="Friz recebeu seu saque?",a="Sim. Ruzzgot diz que Friz fica com o saque dela.",al={"saque de friz","ela recebeu?"}},{q="O que vem a seguir?",a="Ruzzgot espera outra remessa dos Southsea Pirates.",al={"próxima remessa","southsea pirates"}}},fp="25,185,16.312.0,25.75.0,33.49.0,22.37.0,20.59.0"}
P.entries["quest:95328"] = {n="Whispering Horror Residue",s="O Whispering Horror Residue é o resto contorcido de uma estranha fera recuperado de sob a Floresta do Sussurro. Coletados por aventureiros intrépidos, esses restos tocados pelo Vazio são levados a Father Lankester no War Quarter da Cidade Baixa para pesquisas sobre a sombra.",h="O Whispering Horror Residue é o resto contorcido de uma estranha fera recuperado de sob a Floresta do...",kw={"father lankester","sombra","tirisfal","cidade baixa","vazio","war quarter","floresta do sussurro","whispering horror residue"},ang={["class:Priest"]="Sacerdotes das sombras dos Renegados como Father Lankester mantêm um intenso interesse acadêmico e teológico em espécimes do Vazio, considerando restos planares estranhos como objetos de estudo em vez de meras abominações.",["faction:Horde"]="Aventureiros a serviço da Horda recuperam espécimes perturbadores dos ermos ocultos das Clareiras de Tirisfal para abastecer os esforços de pesquisa sob as ruínas de Capital City.",["race:Undead"]="Os Renegados da Cidade Baixa estudam ativamente magias proibidas e corrupções antinaturais por toda Lordaeron, buscando controlar fenômenos sombrios para fortalecer seu domínio precário sobre o reino."},sec={{t="Uma Colheita Perturbadora",b="O Whispering Horror Residue representa os restos bizarros e contorcidos recolhidos de uma fera derrotada que habitava sob a Floresta do Sussurro. Em vez de abandonar tamanha curiosidade antinatural, aventureiros engenhosos recolhem o material palpitante na esperança de que pesquisadores da Cidade Baixa possam fazer bom uso dele."},{t="Estudos na Sombra",b="Os restos da criatura encontram um destinatário ávido em Father Lankester, localizado no War Quarter da Cidade Baixa. Lankester observa que a Floresta do Sussurro há muito tempo é tocada pelo Vazio, acolhendo a oportunidade de examinar vestígios físicos dessa corrupção sombria à medida que se aprofunda nos mistérios da sombra."}},faq={{q="O que é o Whispering Horror Residue?",a="O Whispering Horror Residue consiste nos restos corporais contorcidos colhidos de uma estranha fera derrotada sob a Floresta do Sussurro. Apesar de sua natureza perturbadora, estudiosos de Shadow Magic o consideram valioso para pesquisas arcanas e ocultas.",al={"o que é o resíduo","o que é whispering horror residue","item de resíduo"}},{q="Quem quer o Whispering Horror Residue?",a="O resíduo é entregue a Father Lankester, uma figura dos Renegados localizada no War Quarter da Cidade Baixa. Ele acolhe a oportunidade de explorar os mistérios da sombra e de fenômenos tocados pelo Vazio.",al={"quem recebe o resíduo","quem é father lankester","onde entregar o resíduo"}},{q="De onde veio este espécime?",a="O espécime origina-se de sob a Floresta do Sussurro, uma floresta sinistra localizada a oeste de Plangemortis, nas Clareiras de Tirisfal. Como Father Lankester observa, a área infecta é conhecida por ser tocada pelo Vazio.",al={"de onde vem o horror","história da floresta do sussurro","sob a floresta do sussurro"}},{q="Por que Father Lankester quer o resíduo?",a="Father Lankester busca estudar os mistérios da sombra e do Vazio. Para os praticantes dos Renegados que investigam artes proibidas, restos físicos de criaturas corrompidas pelo Vazio oferecem percepções raras e material de pesquisa.",al={"por que lankester quer isso","pesquisa de sombras cidade baixa","por que estudar o resíduo"}},{q="Onde Father Lankester pode ser encontrado?",a="Father Lankester reside no War Quarter da Cidade Baixa. O War Quarter serve como um centro movimentado para guerreiros, eruditos e estrategistas militares dos Renegados sob as ruínas da capital de Lordaeron.",al={"onde fica o war quarter","onde lankester está localizado","localização de lankester na cidade baixa"}},{q="A Floresta do Sussurro é tocada pelo Vazio?",a="A Floresta do Sussurro há muito mantém uma reputação sinistra entre os habitantes de Tirisfal. Father Lankester observa que não é segredo para ninguém que os bosques infectos e os espaços subterrâneos sob eles são tocados pelo Vazio.",al={"a floresta do sussurro é amaldiçoada","corrupção do vazio floresta do sussurro","o que toca a floresta do sussurro"}}},fp="25,138,21.162.0,17.197.0,38.149.0,40.151.0,34.147.0,43.154.0,36.168.0,45.147.0"}
P.entries["quest:95329"] = {n="Out in the Field",s="Um vigia em Terral's Watch observa as planícies em busca de movimentos da Horda. Você deve buscar o relatório de situação dele.",h="Um vigia em Terral's Watch observa as planícies em busca de movimentos da Horda.",kw={"cornelius","horda","torre de observação","no campo","relatório de situação","terral's watch","vigia"},sec={{t="Uma Vigília Remota",b="Uma torre vigia as planícies do norte a partir de Terral's Watch. O Vigia Cornelius está sozinho no posto, monitorando os movimentos das forças da Horda. Seu posto é isolado, e ele é conhecido por falar pouco. Você deve conversar com ele e trazer um relatório de situação."}},faq={{q="Quem é Cornelius?",a="Cornelius é o vigia que está sozinho em Terral's Watch, onde observa as planícies em busca de movimentos da Horda.",al={"vigia cornelius","quem é o vigia","relatório de cornelius"}},{q="O que é Terral's Watch?",a="Terral's Watch é um posto de observação com vista para as planícies do norte, usado para monitorar os movimentos das forças da Horda.",al={"terral watch","torre de vigia","torre no norte"}},{q="Que relatório devo buscar?",a="Você deve conversar com o Vigia Cornelius em Terral's Watch e buscar um relatório de situação.",al={"relatório de situação","o que cornelius precisa","tarefa de cornelius"}},{q="Por que Cornelius está sozinho?",a="Cornelius está sozinho no posto de vigia isolado. Ele é conhecido por ser taciturno, e esse é o motivo dado para sua designação para lá.",al={"por que ele está sozinho","posto de cornelius","por que foi designado para lá"}}},fp="16,115,14.265.0,17.115.0,23.116.0,30.88.0,33.140.0"}
P.entries["quest:95330"] = {n="Love Thy Neighbor",s="Cassandra Wheeler pede que você leve o excedente da fazenda dela a Halligan Turner, no Turner's Logging Camp. Ela espera que os trabalhadores tenham mais variedade nas refeições.",h="Cassandra Wheeler pede que você leve o excedente da fazenda dela a Halligan Turner, no Turner's Logging Camp.",kw={"cassandra wheeler","farholde","produtos da fazenda","frutas","halligan turner","ame o próximo","turner's logging camp","verduras"},sec={{t="Presente de uma vizinha",b="Cassandra Wheeler cultiva a terra ao norte de Farholde e leva a colheita até lá para vender. Ela separa o que sobra para pessoas que precisam de um incentivo. O acampamento madeireiro fica ao norte da fazenda dela, às margens do rio, e ela acha que os trabalhadores poderiam aproveitar frutas e verduras. Você leva o excedente a Halligan Turner, o capataz do acampamento."},{t="No acampamento",b="Halligan Turner recebe os produtos com gratidão. Os trabalhadores têm pouco além de carne e pão, então ele planeja repartir os produtos entre eles. Ele espera retribuir a gentileza de Cassandra quando puder."}},faq={{q="Quem pediu a entrega?",a="Cassandra Wheeler pede que você leve o excedente da fazenda dela a Halligan Turner.",al={"quem pediu isso","pedido de cassandra","missão dos produtos da fazenda"}},{q="Quem é Halligan Turner?",a="Halligan Turner é o capataz do Turner's Logging Camp.",al={"quem é halligan","capataz do acampamento madeireiro","sujeito turner"}},{q="Onde fica o acampamento madeireiro?",a="O Turner's Logging Camp fica ao norte da fazenda de Cassandra, às margens do rio.",al={"onde fica o acampamento de turner","localização do acampamento","acampamento madeireiro"}},{q="Que produtos Cassandra está enviando?",a="Ela envia frutas e verduras excedentes da fazenda dela.",al={"o que devo entregar","produtos da fazenda","produtos de cassandra"}},{q="Por que Cassandra separa produtos da fazenda?",a="Depois da colheita, Cassandra guarda o que não vende para dar a pessoas que precisam de um incentivo.",al={"por que dar comida","motivo de cassandra","ajudar os vizinhos"}},{q="O que os trabalhadores do acampamento madeireiro costumam comer?",a="Halligan diz que os trabalhadores comem pouco além de carne e pão.",al={"o que os madeireiros comem","comida dos trabalhadores do acampamento","carne e pão"}}},fp="17,168,17.318.0,11.191.1,31.82.0,23.56.0,26.69.0,31.53.0,40.93.0,45.60.0"}
P.entries["quest:95349"] = {n="The Earthen Ring",s="Esta jornada marca a chegada dos Moldavento de Zephras a Azeroth como uma vanguarda avançada após atrasos causados por atividades de sectários em Valanaar. Embarcando em um navio skycutter do lado de fora do pavilhão, os viajantes desembarcam em Mulgore para encontrar Alaana Stormwalker e começar a se aclimatar a um novo mundo vasto e perigoso.",h="Esta jornada marca a chegada dos Moldavento de Zephras a Azeroth como uma vanguarda avançada após atrasos...",kw={"alaana stormwalker","banu-alah","seita","mulgore","skycutter","harmonia telúrica","valanaar","moldavento","zephras"},ang={["class:Shaman"]="Os Moldavento e os Xamãs compartilham uma profunda reverência pelos elementos, confiando no favor dos ventos para guiar sua travessia aérea. Chegar sob o estandarte da Harmonia Telúrica os conecta diretamente às tradições elementais que criam raízes em Mulgore.",["race:Skyborne"]="Para os aventureiros Skyborne que partem de Valanaar, esta jornada marca sua chegada histórica a Azeroth como uma vanguarda avançada. Deixando para trás os problemas causados pela seita em sua terra natal, eles dão seus primeiros passos nos Morros Ondulantes de Mulgore.",["race:Tauren"]="Como zeladores nativos de Mulgore, os Tauren testemunham a chegada de novos viajantes de Zephras descendo sobre suas planícies ancestrais. Acolher esses visitantes vindos dos céus proporciona uma conexão inicial com aliados que estabelecem uma presença em suas terras."},sec={{t="Partida de Valanaar",b="Os viajantes que partem para Azeroth devem ajustar seus planos devido a perturbações recentes causadas por atividades de uma seita em Valanaar. Enquanto os líderes seniores permanecem no pavilhão para concluir assuntos urgentes e conter a ameaça dos sectários, uma pequena vanguarda de Moldavento é enviada à frente. Viajando até as docas do lado de fora do pavilhão, esses pioneiros embarcam em uma embarcação skycutter rumo aos céus. Embora seus comandantes prometam se juntar a eles em breve, a expedição inicial repousa inteiramente sobre os ombros desse grupo avançado, enviado à frente para estabelecer uma presença antes que o restante possa segui-los."},{t="Chegada a Mulgore",b="Ao pousar nos Morros Ondulantes de Mulgore, os aventureiros que chegam de Zephras são recebidos por Alaana Stormwalker. Estabelecer uma presença em Azeroth levará tempo e esforços cuidadosos, incentivando os recém-chegados a fazer o reconhecimento do território ao redor e a se aclimatar ao novo ambiente. Embora os ventos favoreçam a expedição que chega, Azeroth continua sendo um reino desconhecido e perigoso. Familiarizar-se com o terreno local, a vida selvagem e os habitantes vizinhos é um primeiro passo essencial antes que os demais viajantes de Valanaar cheguem para se juntar ao esforço."}},faq={{q="Por que os Moldavento estão viajando para Azeroth?",a="Uma vanguarda de Moldavento é enviada à frente para estabelecer uma presença em Azeroth enquanto seus líderes permanecem em Valanaar. Problemas recentes envolvendo uma seita local desorganizaram os planos originais de viagem, atrasando o restante do grupo. Como resultado, este grupo avançado viaja sozinho para desembarcar e garantir uma posição até que reforços possam segui-los.",al={"por que ir para azeroth","missão dos moldavento","por que os moldavento estão em mulgore"}},{q="Quem é Alaana Stormwalker?",a="Alaana Stormwalker é o contato que aguarda para receber os Moldavento que chegam após o pouso em Mulgore. Ela dá as boas-vindas aos viajantes que chegam de Zephras, observando que estabelecer uma presença segura nestas novas terras exigirá tempo. Enquanto os preparativos começam, ela aconselha os aventureiros recém-chegados a explorar a região ao redor e a se preparar para os perigos de Azeroth.",al={"quem é alaana","papel de alaana stormwalker","onde está alaana stormwalker"}},{q="Por que a partida principal foi adiada?",a="A viagem principal de Valanaar foi adiada devido a eventos preocupantes recentes envolvendo uma seita local. Lidar com essas complicações causadas pelos sectários forçou os líderes da expedição a permanecerem no pavilhão para concluir seus negócios. Em vez de interromper a missão por completo, eles enviaram uma pequena vanguarda de Moldavento a bordo de um skycutter para liderar o caminho até Azeroth.",al={"por que o atraso","qual seita atrasou a viagem","por que ficar em valanaar"}},{q="Como os viajantes vão de Valanaar até Mulgore?",a="Os viajantes fazem a jornada embarcando em um navio skycutter ancorado do lado de fora do pavilhão em Valanaar. Esta embarcação transporta a vanguarda pelos céus até as planícies de Mulgore, servindo como o principal transporte que liga Zephras às terras de Azeroth durante a expedição inicial.",al={"como chegar a mulgore","onde está o navio","como você viaja para azeroth"}},{q="O que é Zephras?",a="Zephras é o lar ou a origem dos aventureiros que chegam a bordo do skycutter. Quando os viajantes chegam a Mulgore, Alaana Stormwalker os identifica como recém-chegados vindos de Zephras, observando que ventos favoráveis guiaram sua travessia para o território desconhecido e perigoso de Azeroth.",al={"onde fica zephras","o que é zephras","história de zephras"}},{q="O que os aventureiros devem fazer ao chegar a Mulgore?",a="Os aventureiros recém-chegados são incentivados a fazer o reconhecimento e explorar as terras ao redor de Mulgore. Como estabelecer uma presença definitiva leva tempo, familiarizar-se com o terreno próximo, as criaturas e as ameaças locais é uma preparação essencial para desbravar este novo mundo empolgante, porém perigoso.",al={"o que fazer em mulgore","próximos passos após chegar","o que fazer a seguir"}}},fp="16,272,23.440.0,18.424.0,45.264.0,26.240.0,35.192.0,50.190.0,16.215.0,52.209.0"}
P.entries["quest:95350"] = {n="Welcome to Azeroth",s="'Boas-vindas a Azeroth' é uma missão introdutória que envia um viajante do Penhasco do Trovão para Orgrimmar em nome dos Moldavento. Guiado pelos laços espirituais da Harmonia Telúrica, o emissário se encontra com o Chefe de Guerra Thrall para forjar laços de sobrevivência e aliança com a Horda.",h="'Boas-vindas a Azeroth' é uma missão introdutória que envia um viajante do Penhasco do Trovão para Orgrimmar...",kw={"harmonia telúrica","horda","orgrimmar","thrall","penhasco do trovão","vale da sabedoria","boas-vindas a azeroth","moldavento"},ang={["class:Shaman"]="Com orientação invocando a Harmonia Telúrica e a bênção dos ventos, esta jornada conecta diretamente parentes espirituais ao coração da liderança xamânica no Vale da Sabedoria.",["faction:Horde"]="Esta missão diplomática oficializa os laços com a Horda, apresentando os recém-chegados diretamente ao Chefe de Guerra Thrall como aliados essenciais para a sobrevivência em Kalimdor.",["race:Skyborne"]="Deixando as grandes altitudes para o mundo da superfície abaixo, os Skyborne Moldavento estendem a mão para o Penhasco do Trovão e Orgrimmar a fim de garantir seu lugar entre novos aliados."},sec={{t="Aliados em um Mundo Mais Amplo",b="Aventureiros que desbravam a vasta extensão de Kalimdor logo descobrem que a sobrevivência depende da fraternidade. Os Moldavento olham além de suas origens isoladas para os povos que caminham abaixo, reconhecendo que o isolamento não oferece defesa contra as ameaças de Azeroth. Ao estender a mão para a cidade tauren vizinha do Penhasco do Trovão e olhar para os bastiões orcs a leste, eles buscam companheiros leais para enfrentar a natureza selvagem juntos."},{t="Uma Audiência com o Chefe de Guerra",b="A jornada conduz os enviados às torres imponentes do Penhasco do Trovão antes de direcioná-los através dos Sertões até Orgrimmar, a poderosa capital da Horda. Aguardando no tranquilo Vale da Sabedoria está o Chefe de Guerra Thrall, o coração que guia a coalizão. Apresentar-se diante de Thrall marca a entrada oficial dos Moldavento no tecido político e espiritual de Kalimdor, unidos por um propósito comum e pelo respeito mútuo pelos elementos."}},faq={{q="Qual é o objetivo da missão Boas-vindas a Azeroth?",a="'Boas-vindas a Azeroth' é uma missão introdutória diplomática que envia um emissário em nome dos Moldavento para se encontrar com o Chefe de Guerra Thrall em Orgrimmar. Ela serve como uma introdução oficial à Horda em geral e ao mundo da superfície de Kalimdor.",al={"o que é esta missão","missão boas-vindas a azeroth","objetivo de boas-vindas a azeroth"}},{q="Quem são os Moldavento?",a="Os Moldavento são um grupo que busca alcançar aliados da superfície a partir de cima, procurando a sobrevivência por meio da irmandade com a Harmonia Telúrica e a Horda. Eles enviam viajantes para falar diretamente com a liderança da Horda em Durotar.",al={"quem são os moldavento","o que são os moldavento"}},{q="Por que você é enviado para falar com Thrall?",a="Como Chefe de Guerra da Horda e um reverenciado líder xamânico, Thrall supervisiona as principais alianças da coalizão a partir do Vale da Sabedoria. Fazer contato com ele oficializa as relações entre os Moldavento e a Horda.",al={"por que visitar thrall","falar com thrall em orgrimmar","por que ir para orgrimmar"}},{q="Como você viaja do Penhasco do Trovão para Orgrimmar?",a="Os viajantes alçam voo a partir do mestre de voo localizado no poleiro central do Penhasco do Trovão, sobrevoando as planícies de Kalimdor para o leste até a fortaleza do desfiladeiro de Orgrimmar.",al={"como chegar a orgrimmar","mestre de voo do penhasco do trovão","como ir do penhasco do trovão a orgrimmar"}},{q="Como a Harmonia Telúrica se encaixa nesta missão?",a="Neste encontro, a Harmonia Telúrica é descrita como alinhada com a coalizão de povos afins da Horda, ajudando a facilitar laços entre facções xamânicas e as nações de Kalimdor.",al={"papel da harmonia telúrica na horda","a harmonia telúrica é da horda"}},{q="Onde Thrall está localizado em Orgrimmar?",a="O Chefe de Guerra Thrall reside no Vale da Sabedoria, um santuário espiritual tranquilo nos limites ocidentais de Orgrimmar onde xamãs e conselheiros tribais se reúnem.",al={"onde está thrall","localização de thrall no vale da sabedoria"}}},fp="18,196,25.303.0,29.350.0,52.156.0,24.200.0,38.208.0,50.154.0,48.142.0,37.139.0"}
P.entries["quest:95383"] = {n="Shipping and Handling",s="O Mestre do Cais Steamfizzle indica Tazzik para você entregar o Esconderijo Secreto de Friz. A remessa levanta dúvidas sobre sua passagem pela alfândega.",h="O Mestre do Cais Steamfizzle indica Tazzik para você entregar o Esconderijo Secreto de Friz.",kw={"alfândega","friz","esconderijo secreto de friz","porto detonapavio","envio e manuseio","porto de bondebico","tazzik","mestre do cais steamfizzle"},sec={{t="No cais",b="Tazzik espera no cais do Porto de Bondebico pela caixa que você carrega. O Mestre do Cais Steamfizzle indica que você a entregue a ele, embora afirme não saber nada sobre a entrega. Ele pede pressa e alerta você para não chamar a atenção errada. A remessa vem do Porto Detonapavio, e há dúvidas sobre sua passagem pela alfândega."}},faq={{q="Quem está me pedindo para entregar a caixa?",a="O Mestre do Cais Steamfizzle indica que você entregue o Esconderijo Secreto de Friz a Tazzik.",al={"quem me enviou","quem me deu o pacote"}},{q="Para quem devo entregar o Esconderijo Secreto de Friz?",a="Você deve entregar o Esconderijo Secreto de Friz a Tazzik, no Porto de Bondebico.",al={"para onde vai a caixa","para quem entregar o esconderijo"}},{q="O que é o Esconderijo Secreto de Friz?",a="É uma remessa que Friz enviou para Tazzik. O texto de conclusão elogia sua qualidade.",al={"o que tem na caixa","pacote de friz"}},{q="De onde veio a remessa?",a="Tazzik diz que consegue sentir o cheiro do Porto Detonapavio em você.",al={"origem da caixa","pacote do porto detonapavio"}},{q="Por que Steamfizzle me manda correr?",a="Steamfizzle alerta você para não chamar a atenção errada.",al={"por que se apressar","ideia errada"}},{q="A remessa foi liberada pela alfândega?",a="Tazzik diz que a remessa foi liberada pela alfândega, mas sugere que o dinheiro de Friz pode ser um problema.",al={"liberado pela alfândega","isso é legal"}}},fp="21,141,11.327.0,38.73.0,45.72.0,30.79.0,33.48.0,38.54.0,36.99.0"}
P.entries["quest:95384"] = {n="Partial Mystical Notes",s="Um estranho pergaminho mágico traz símbolos que você não consegue ler, mas não contém nenhuma força que pareça volátil. Você o leva a Dudd Fizzlescroll, na Angra do Butim, onde ele vê potencial em sua magia.",h="Um estranho pergaminho mágico traz símbolos que você não consegue ler, mas não contém nenhuma força que...",kw={"angra do butim","dudd fizzlescroll","pergaminho mágico","magia mística","anotações místicas incompletas","pergaminho incompleto","símbolos estranhos"},sec={{t="Símbolos indecifráveis",b="Você encontra um pergaminho mágico coberto de símbolos estranhos, mas não conhece o idioma. A magia parece inofensiva, então você leva o pergaminho incompleto a Dudd Fizzlescroll, na Angra do Butim. Ele reconhece que se trata de uma magia poderosa e planeja traduzi-la para seus registros."}},faq={{q="O que há no pergaminho?",a="O pergaminho mágico traz símbolos estranhos em um idioma que você não fala.",al={"quais símbolos","escrita do pergaminho","anotações místicas"}},{q="O pergaminho parece perigoso?",a="Você não percebe nenhuma força particularmente volátil no pergaminho.",al={"é volátil","o pergaminho é perigoso","magia segura"}},{q="Quem quer o pergaminho?",a="Dudd Fizzlescroll, na Angra do Butim, reconhece a magia do pergaminho e pretende traduzi-lo para seus registros.",al={"quem fica com ele","dudd fizzlescroll","colecionador de pergaminhos"}},{q="Onde devo levar o pergaminho incompleto?",a="Você leva o pergaminho incompleto a Dudd Fizzlescroll, na Angra do Butim.",al={"onde levar o pergaminho","pergaminho da angra do butim","destino do pergaminho"}}},fp="22,180,14.261.0,22.72.0,31.60.0,21.105.0,36.63.0"}
P.entries["quest:95385"] = {n="Torn Mystical Scroll",s="Um pergaminho rasgado traz uma magia tênue e runas desconhecidas. Você o leva a Dudd Fizzlescroll, em Angra do Butim, onde ele vê potencial em sua escrita.",h="Um pergaminho rasgado traz uma magia tênue e runas desconhecidas.",kw={"angra do butim","dudd fizzlescroll","engenharia","magia tênue","pergaminho incompleto","runas","pergaminho místico rasgado"},ang={["profession:Engineering"]="Dudd Fizzlescroll planeja copiar as runas em seu trabalho e fala em se tornar um engenheiro lendário."},sec={{t="Um Fragmento Curioso",b="Uma magia tênue envolve o pergaminho rasgado, e suas runas são estranhas para você. Você não sente perigo nele, embora a maioria chamasse o pergaminho de inútil. Dudd Fizzlescroll, em Angra do Butim, talvez encontre uma utilidade para o fragmento."},{t="O Trabalho de Dudd",b="Dudd Fizzlescroll está ansioso para copiar as runas em seu trabalho. Ele fala em se tornar um engenheiro lendário, depois avisa você para manter distância, para não se machucar."}},faq={{q="O que é o pergaminho rasgado?",a="É um fragmento de pergaminho com magia tênue e runas desconhecidas. Você sente que ele não é perigoso.",al={"pergaminho rasgado","pergaminho místico","o que é este pergaminho"}},{q="Quem quer o pergaminho?",a="Dudd Fizzlescroll, em Angra do Butim, está interessado no pergaminho incompleto.",al={"quem quer o pergaminho","colecionador de pergaminhos","dudd scroll"}},{q="Por que levá-lo a Dudd?",a="Dudd talvez encontre uma utilidade para as runas desconhecidas no pergaminho.",al={"por que dudd","para onde vai o pergaminho","finalidade do pergaminho"}},{q="O pergaminho é perigoso?",a="O pergaminho emana uma magia tênue, mas você intui que ele não é perigoso.",al={"pergaminho seguro","pergaminho perigoso","é mágico"}}},fp="20,139,15.208.0,11.157.1,24.104.0,21.67.0,21.62.0,24.74.0"}
P.entries["quest:954"] = {n="Bashal'Aran",s="Os sátiros demoníacos e os duendes cruéis que infestam a antiga cidade élfica de Bashal'Aran não se aproximam de um santuário banhado por uma aura azul sobrenatural. Trovejius Tecevento, ancião de Auberdine, envia aventureiros para investigar a origem desse refúgio intocado.",h="Os sátiros demoníacos e os duendes cruéis que infestam a antiga cidade élfica de Bashal'Aran não se aproximam...",kw={"astérion","bashal'aran","aura azul","costa negra","duende","ruínas kaldorei","sátiro","trovejius tecevento"},ang={["faction:Alliance"]="Os batedores de Auberdine dependem de aventureiros da Aliança para avançar pelas ruínas disputadas de Costa Negra e neutralizar as ameaças demoníacas antes que cheguem ao litoral.",["race:NightElf"]="Bashal'Aran é um lembrete sombrio das perdas causadas pela Cisão, onde os espíritos remanescentes de seus ancestrais ainda mantêm vigílias solitárias contra a corrupção demoníaca crescente."},sec={{t="Um farol entre as ruínas",b="Bashal'Aran já foi um povoado glorioso do antigo império kaldorei, mas seus mármores despedaçados e arcos cobertos de vegetação agora fervilham de corrupção demoníaca. Sátiros deformados e duendes corrompidos se alimentam avidamente das energias mágicas remanescentes, tornando-se cada vez mais malignos. Apesar do domínio dessas criaturas, Trovejius Tecevento notou algo curioso: no alto de uma elevação a oeste das ruínas, uma aura azul etérea envolve um santuário do qual nenhum demônio se aproxima."},{t="O espectro atormentado",b="Atravessar as patrulhas demoníacas até o santuário elevado revela que a luz azul não é um fenômeno natural. Ela emana de Astérion, um espírito antigo cuja vigília já dura séculos de solidão. Cercado por feras uivantes e demônios vis, o espectro cansado vê até mesmo um viajante desconhecido como um alívio bem-vindo após décadas de isolamento."}},faq={{q="Onde fica a aura azul?",a="A aura azul brilha no topo de uma pequena elevação a oeste das ruínas de Bashal'Aran, a leste de Auberdine, em Costa Negra. O santuário fica um pouco acima das muralhas em ruínas.",al={"encontrar aura azul","onde fica astérion","localização do santuário de bashal'aran"}},{q="Por que os sátiros evitam o santuário?",a="Ninguém sabe ao certo. Uma estranha aura azul envolve o santuário, e os sátiros e duendes demoníacos que infestam as ruínas se recusam a se aproximar. Trovejius Tecevento envia você para descobrir a origem dessa aura.",al={"por que os demônios têm medo","por que os sátiros não se aproximam"}},{q="Quem oferece esta missão?",a="Trovejius Tecevento, um druida elfo noturno e ancião de Auberdine, oferece a missão após observar os movimentos estranhos dos demônios nas ruínas a leste.",al={"quem oferece a missão","quem dá a missão","localização de trovejius tecevento"}},{q="O que é Bashal'Aran?",a="Bashal'Aran é uma antiga ruína kaldorei nas florestas de Costa Negra. Devastada durante a Cisão, ela foi infestada por parasitas mágicos, duendes e sátiros que procuram se alimentar do poder adormecido de seus meridianos mágicos.",al={"o que aconteceu com bashal'aran","história de bashal'aran"}}},fx={["2cba9e48"]={q="Por que Trovejius Tecevento quer que eu investigue Bashal'Aran?",a="Trovejius Tecevento observa as antigas ruínas de Bashal'Aran com um pavor crescente. Espritais e sátiros corrompidos infestam o local, atraindo energias arcanas persistentes para ampliar seu poder demoníaco. No entanto, entre essa infestação, um único santuário envolvido por uma curiosa aura azul permanece totalmente intocado pelos demônios. Trovejius precisa entender qual poder os mantém afastados — e se isso pode ser a chave para repelir a corrupção que avança sobre a Costa Negra.",al={"por que investigar bashal'aran","motivação de thundris","por que me enviar a bashal'aran"}}},fp="11,161,21.382.0,17.245.1,31.192.0,35.147.0,28.136.0,20.171.0"}
P.entries["quest:95417"] = {n="The Purple Ones",s="Clubtoe pede que você procure ogros desaparecidos nas cavernas sob Solclaro. Alguns que voltam estão mudados, e ele quer entender por quê.",h="Clubtoe pede que você procure ogros desaparecidos nas cavernas sob Solclaro.",kw={"cavernas","clubtoe","runas sombrias","ogros desaparecidos","ogros","roxo","solclaro","os roxos","twilight hammer"},sec={{t="A preocupação de Clubtoe",b="Clubtoe viu amigos entrarem nas cavernas sob Solclaro e não voltarem. Alguns retornam roxos e já não agem como seus amigos. Ele pede que você procure os ogros desaparecidos nas cavernas, embora tema que você também volte mudado."},{t="Nas cavernas",b="Sob Solclaro, você encontra um ogro morto entre runas sombrias. Os poderes do ritual do Twilight Hammer o dominaram."}},faq={{q="Quem é Clubtoe?",a="Clubtoe é um ogro cujos amigos desapareceram nas cavernas sob Solclaro.",al={"clubtoe","quem é clubtoe"}},{q="Por que Clubtoe pede que eu procure nas cavernas?",a="Alguns amigos de Clubtoe não voltam das cavernas, e alguns que retornam estão roxos e agem de forma diferente.",al={"ogros desaparecidos","encontrar amigos de clubtoe","ogros das cavernas"}},{q="Onde estão os ogros desaparecidos?",a="Clubtoe pede que você procure os ogros desaparecidos nas cavernas sob Solclaro.",al={"para onde vão os ogros","caverna de solclaro","ogros desaparecidos"}},{q="O que há de estranho nos ogros que voltam?",a="Alguns retornam roxos e já não agem como os amigos de Clubtoe.",al={"ogros roxos","por que roxos","ogros agem estranho"}}},fp="15,138,17.245.0,12.124.1,15.83.0,44.110.0,28.79.0,43.60.0"}
P.entries["quest:95418"] = {n="Spread the Word",s="Clubtoe pede que você leve a cabeça de Chogg'Zac para Tran'gul, em Rog'mar, depois que ele deixar a Twilight's Hammer. A notícia da deserção pode levar mais ogros do culto a se libertarem.",h="Clubtoe pede que você leve a cabeça de Chogg'Zac para Tran'gul, em Rog'mar, depois que ele deixar a...",kw={"chogg'zac","clubtoe","clugfist","deserção de ogro","rog'mar","espalhe a notícia","tran'gul","martelo do crepúsculo"},sec={{t="Uma mensagem para Tran'gul",b="A cabeça de Chogg'Zac deve voltar para seus amigos, e Tran'gul, em Rog'mar, é quem deve recebê-la. Clubtoe diz que rompeu com a Twilight's Hammer e planeja se juntar a Clugfist, o maior ogro que conhece, junto com muitos outros. Clubtoe pretende ficar onde está até que o caminho esteja livre. Agora, Tran'gul precisa saber o que Clubtoe decidiu."},{t="Notícias da caverna",b="Tran'gul fica sabendo que a caverna guardava outra surpresa. Você convenceu um dos ogros do Martelo do Crepúsculo a desertar, e ele falou de outros da sua espécie. Tran'gul diz que precisam agir imediatamente com base nessa notícia."}},faq={{q="Quem é Clubtoe?",a="Clubtoe é um ogro que diz que já cansou do Martelo do Crepúsculo e planeja se juntar aos ogros livres.",al={"clubtoe","ogro clubtoe","quem é clubtoe"}},{q="Quem é Clugfist?",a="Clugfist é o maior ogro que Clubtoe conhece, e Clubtoe diz que ele deixou o Martelo do Crepúsculo com muitos amigos.",al={"clugfist","ogro clugfist","maior ogro"}},{q="O que Clubtoe me pede para levar?",a="Clubtoe pede que você leve a cabeça de Chogg'Zac de volta aos amigos dele.",al={"cabeça de chogg","cabeça de chogg'zac","o que levar"}},{q="Onde devo levar a cabeça de Chogg'Zac?",a="Você deve entregar a cabeça de Chogg'Zac a Tran'gul, em Rog'mar.",al={"onde levar a cabeça","tran'gul","rog'mar"}},{q="Por que Tran'gul está preocupado?",a="Tran'gul fica sabendo que um ogro do Martelo do Crepúsculo desertou e mencionou outros da sua espécie.",al={"reação de tran'gul","caverna do crepúsculo","por que agir agora"}}},fp="15,178,22.329.0,18.202.1,15.99.0,16.109.0,34.62.0,33.59.0,26.94.0"}
P.entries["quest:95420"] = {n="Land of Giants",s="Um orc pede que você leve a cabeça de Chogg a uma cidade ogra nas colinas do norte. A oferenda pode abrir caminho para renovar um antigo vínculo com os ogros.",h="Um orc pede que você leve a cabeça de Chogg a uma cidade ogra nas colinas do norte.",kw={"chogg","chogg’zac","clugfist","terra dos gigantes","colinas do norte","cidade ogra","ogros","aliança orc"},ang={["race:Orc"]="Como orc, você leva uma oferta enraizada na honrada história de orcs lutando ao lado dos ogros."},sec={{t="Um vínculo antigo",b="Os orcs veem uma chance de renovar sua antiga aliança com os ogros. Relatos situam o lar do clã em uma fortaleza entre as colinas do norte, e a cabeça de Chogg deve falar por você. Leve-a à cidade ogra e ofereça-a como símbolo de amizade. O clã talvez ouça sua proposta, se não pisoteá-lo antes."},{t="À porta de Clugfist",b="Na cidade ogra, você apresenta a cabeça de Chogg a Clugfist. Ele reconhece que você derrotou Chogg’Zac e pergunta o que você quer com ele. A oferta de amizade abriu uma oportunidade para falar com o líder do clã."}},faq={{q="Por que estou levando a cabeça de Chogg aos ogros?",a="Os orcs esperam que a cabeça de Chogg sirva como símbolo de amizade e ajude a renovar sua antiga aliança com os ogros.",al={"cabeça de chogg","por que levar a cabeça de chogg","oferenda da cabeça de ogro"}},{q="Onde fica o lar do clã ogro?",a="Relatos situam a fortaleza do clã nas colinas, bem ao norte.",al={"localização da cidade ogra","onde ficam os ogros","ogros das colinas do norte"}},{q="Quem é Clugfist?",a="Clugfist é o enorme ogro que você encontra na cidade ogra. Ele pergunta o que você quer com ele.",al={"quem é clugfist","líder ogro","clug fist"}},{q="Quem é Chogg’Zac?",a="Chogg’Zac é o ogro que Clugfist diz que você derrotou.",al={"chogg zac","história de chogg","quem é chogg"}},{q="O que os orcs querem dos ogros?",a="Os orcs esperam recorrer à sua antiga aliança com os ogros e apresentar uma proposta ao clã.",al={"aliança entre orcs e ogros","o que os orcs querem","amizade com ogros"}}},fp="14,143,11.313.0,20.218.1,46.114.0,32.68.0,16.87.0,19.56.0,37.92.0"}
